//! Build-time wikitext presentation compiler. No HTML strings are executed and no network is required.
//! Reuses the portable document IR tokenizer, adding block layout, HTML, references,
//! entities, and a deliberately bounded set of Wiktionary template presentations.
const missing_dependency = @import("missing_dependency");
pub const generated_link = missing_dependency.generated_link;
pub const MissingText = missing_dependency.Text;
const std = @import("std");
const relative_font = @import("font_scale.zig");
pub const FontScaleBasis = @import("blob_encoder").presentation_types.FontScaleBasis;
const ir = @import("blob_encoder").document_ir;
const entities = @import("shared_xml_decode").html_entities;
const syntax = @import("blob_encoder").wikitext_syntax;
const templates = @import("presentation_templates.zig");
const diagnostics = @import("build_diagnostics");
const hieroglyphs = @import("hieroglyph_unicode.zig");
const A = std.mem.Allocator;
const table_style_profile = @import("table_style_profile.zig");
const presentation_types = @import("blob_encoder").presentation_types;
pub const citation_state = @import("presentation_citations.zig");
pub const CitationPlan = citation_state.Plan;

// Build-only evidence copied before compiler scratch buffers unwind.
// Offsets name this exact input fragment, never an inferred page coordinate.
pub const RejectedCompilerCapture = struct {
    pub const Snapshot = struct {
        scope: []const u8 = "first instrumented compiler rejection; offset is local to the captured fragment, page offset unknown",
        operation: []const u8,
        reason: []const u8,
        error_name: []const u8,
        reason_bits: u64,
        fragment_bytes: usize,
        local_offset: usize,
        window_offset: usize,
        window_hex: []const u8,
        window_truncated: bool,
        labels_truncated: bool,
    };
    failure: ?anyerror = null,
    operation: [64]u8 = undefined,
    reason: [96]u8 = undefined,
    operation_len: usize = 0,
    reason_len: usize = 0,
    labels_truncated: bool = false,
    reason_bits: u64 = 0,
    fragment_bytes: usize = 0,
    local_offset: usize = 0,
    window_offset: usize = 0,
    window_len: usize = 0,
    window_hex: [512]u8 = undefined,

    fn record(self: *@This(), operation: []const u8, reason: []const u8, fragment: []const u8, offset: usize, bits: u64, failure: anyerror) void {
        if (self.failure != null) return;
        self.operation_len = @min(operation.len, self.operation.len);
        self.reason_len = @min(reason.len, self.reason.len);
        @memcpy(self.operation[0..self.operation_len], operation[0..self.operation_len]);
        @memcpy(self.reason[0..self.reason_len], reason[0..self.reason_len]);
        self.labels_truncated = operation.len != self.operation_len or reason.len != self.reason_len;
        self.reason_bits = bits;
        self.fragment_bytes = fragment.len;
        self.local_offset = @min(offset, fragment.len);
        self.window_offset = self.local_offset -| 64;
        const end = self.window_offset + @min(@as(usize, 256), fragment.len - self.window_offset);
        self.window_len = boundedTraceHex(&self.window_hex, fragment[self.window_offset..end]).len;
        self.failure = failure;
    }
    pub fn snapshot(self: *const @This(), failure: anyerror) ?Snapshot {
        if (self.failure == null or self.failure.? != failure) return null;
        return .{ .operation = self.operation[0..self.operation_len], .reason = self.reason[0..self.reason_len],
            .error_name = @errorName(failure), .reason_bits = self.reason_bits,
            .fragment_bytes = self.fragment_bytes, .local_offset = self.local_offset, .window_offset = self.window_offset,
            .window_hex = self.window_hex[0..self.window_len],
            .window_truncated = self.window_offset != 0 or self.window_len / 2 != self.fragment_bytes,
            .labels_truncated = self.labels_truncated };
    }
    pub const Scope = struct {
        previous: ?*RejectedCompilerCapture,
        pub fn deinit(self: @This()) void { rejected_compiler_capture = self.previous; }
    };
    pub fn suspendCapture() Scope {
        const previous = rejected_compiler_capture;
        rejected_compiler_capture = null;
        return .{ .previous = previous };
    }
    pub fn resumeCapture(self: *@This()) Scope {
        const previous = rejected_compiler_capture;
        rejected_compiler_capture = self;
        return .{ .previous = previous };
    }
    pub fn begin(self: *@This()) Scope {
        self.* = .{};
        return self.resumeCapture();
    }
};
threadlocal var rejected_compiler_capture: ?*RejectedCompilerCapture = null;
pub fn rejectedCompilerSnapshot(failure: anyerror) ?RejectedCompilerCapture.Snapshot {
    return if (rejected_compiler_capture) |capture| capture.snapshot(failure) else null;
}


fn optionalParagraphEnd(input: []const u8, opening: syntax.Tag, matcher: ?syntax.ControlMatcher) syntax.Pair {
    var scan: syntax.OpaqueScan = .{};
    var at = opening.end;
    while (at < input.len) {
        if (at > opening.end and input[at - 1] == '\n') {
            const end = std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len;
            const line = std.mem.trimEnd(u8, input[at..end], "\r");
            const controlled = line[syntax.leadingBehaviorControlOffset(line, matcher)..];
            if (headingLineControlled(line, matcher) != null or Renderer.wikiTableIndent(line) != null or
                starts(line, "----") or (controlled.len != 0 and std.mem.indexOfScalar(u8, "*#;:", controlled[0]) != null))
                return .{ .inner_end = at, .end = at };
        }
        if (scan.tagAt(input, at, null)) |tag| {
            if (tag.is("p") and tag.closing) return .{ .inner_end = at, .end = tag.end };
            // Unsupported tag spellings remain escaped text, not block owners.
            if (!tag.closing and oneOf(tag.name, &.{ "blockquote", "center", "div", "dl", "h1", "h2", "h3", "h4", "h5", "h6", "hr", "ol", "p", "pre", "source", "syntaxhighlight", "table", "ul" }))
                return .{ .inner_end = at, .end = at };
        }
        if (scan.protectedEnd(input, at, null)) |end| {
            at = end;
            continue;
        }
        if (starts(input[at..], "[[") or starts(input[at..], "{{")) {
            if (syntax.balancedWithOpaqueScan(input, at, &scan)) |pair| {
                at = pair.end;
                continue;
            }
        } else if (input[at] == '[' and ir.hasExternalProtocol(input[at + 1 ..])) {
            var links: ir.InlineIterator = .{ .input = input[at..], .renderer_boundaries = true };
            if (links.next()) |token| if (token.kind == .external_link) {
                at += links.cursor;
                continue;
            };
        }
        if (scan.tagAt(input, at, null)) |tag| {
            at = tag.end;
        } else at += 1;
    }
    return .{ .inner_end = input.len, .end = input.len };
}

// Ordinary HTML wrappers cannot cut a physical wiki table at an inner HTML
// closer. Keep the original pair unless a real table close and later explicit
// wrapper close prove the wider scope; genuinely unclosed tables stay unchanged.
fn blockWrapperPair(input: []const u8, opening: syntax.Tag, matcher: ?syntax.ControlMatcher) ?syntax.Pair {
    if (opening.is("p") and !opening.closing and !opening.self_closing) return optionalParagraphEnd(input, opening, matcher);
    const original = syntax.matchingTag(input, opening) orelse return null;
    if (!opening.is("div") or std.mem.indexOf(u8, input[opening.end..original.inner_end], "{|") == null) return original;
    var scan: syntax.OpaqueScan = .{};
    var no_more_nowiki_close = false;
    var depth: usize = 1;
    var tables: usize = 0;
    var table_owner_depths: [max_depth]usize = undefined;
    var crossed = false;
    var at = opening.end;
    while (at < input.len) {
        if (at == 0 or input[at - 1] == '\n') {
            const end = std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len;
            const line = trim(input[at..end]);
            // Share the renderer's opener grammar; closers accept whitespace
            // trimming only, never a colon-prefixed literal such as :|}.
            if (Renderer.wikiTableIndent(line) != null) {
                if (tables >= max_depth) return original;
                table_owner_depths[tables] = depth;
                tables += 1;
            } else if (starts(line, "|}") and tables != 0) {
                tables -= 1;
                // The generated table end pops its still-open descendants.
                // Only discard DIVs opened after this table; its outside
                // wrapper still requires an explicit closing DIV below.
                if (depth > table_owner_depths[tables]) {
                    depth = table_owner_depths[tables];
                    crossed = true;
                }
            }
        }
        if (scan.protectedEnd(input, at, &no_more_nowiki_close)) |end| {
            at = end;
            continue;
        }
        if (starts(input[at..], "{{") or starts(input[at..], "[[")) {
            if (syntax.balancedWithOpaqueScan(input, at, &scan)) |pair| {
                at = pair.end;
                continue;
            }
        }
        if (scan.tagAt(input, at, &no_more_nowiki_close)) |tag| {
            if (tag.is("div")) {
                if (tag.closing) {
                    // A cell cannot close any DIV opened before its table.
                    // DIVs opened inside that cell retain ordinary nesting.
                    if (tables != 0 and depth <= table_owner_depths[tables - 1]) {
                        crossed = true;
                    } else {
                        depth -= 1;
                        if (depth == 0) return if (crossed) .{ .inner_end = at, .end = tag.end } else original;
                    }
                } else if (!tag.self_closing) {
                    if (depth >= max_depth) return original;
                    depth += 1;
                }
            }
            at = tag.end;
        } else at += 1;
    }
    return original;
}

// Scope observation must validate the same physical-table-aware DIV boundary
// that ordinary body rendering emitted. This does not admit other HTML kinds.
pub fn cssBlockScopePair(input: []const u8, opening: syntax.Tag) ?syntax.Pair {
    if (!opening.is("div") or opening.closing or opening.self_closing) return null;
    return blockWrapperPair(input, opening, null);
}

fn optionalTableEnd(input: []const u8, opening: syntax.Tag) syntax.Pair {
    return optionalTableEndFrom(input, opening.name, opening.end, false);
}
fn optionalTableEndFrom(input: []const u8, name: []const u8, start: usize, implicit_row: bool) syntax.Pair {
    var cursor = start;
    while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |at| {
        if (syntax.protectedEnd(input, at)) |end| {
            cursor = end;
            continue;
        }
        const tag = syntax.tagAt(input, at) orelse {
            cursor = at + 1;
            continue;
        };
        cursor = tag.end;
        if (!tag.closing and tag.is("table")) {
            if (syntax.matchingTag(input, tag)) |pair| {
                cursor = pair.end;
                continue;
            }
        }
        if (tag.closing and tag.is(name)) return .{ .inner_end = at, .end = tag.end };
        const row = std.ascii.eqlIgnoreCase(name, "tr");
        const sibling = !tag.closing and (if (row) tag.is("tr") else tag.is("td") or tag.is("th") or tag.is("tr"));
        // Authored row-group tags are escaped by the sanitizer. Their closing
        // spelling is visible text, not an optional row or cell boundary.
        const parent = tag.closing and (tag.is("table") or (!row and tag.is("tr")));
        // Omitted tr starts at the first actual cell. A caption belongs to
        // the surrounding table; authored group tags do not split this row.
        const implicit_boundary = implicit_row and !tag.closing and tag.is("caption");
        if (sibling or parent or implicit_boundary) return .{ .inner_end = at, .end = at };
    }
    return .{ .inner_end = input.len, .end = input.len };
}
// Raw unsupported group spellings must reach the ordinary HTML table path,
// where existing foster parenting and literal compilation retain their order.
// This admission scan uses the same tag/protected-scope rules as table parsing.
fn hasAuthoredTableGroup(input: []const u8) bool {
    var scan: syntax.OpaqueScan = .{};
    var no_more_nowiki_close = false;
    var cursor: usize = 0;
    while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |at| {
        if (scan.protectedEnd(input, at, &no_more_nowiki_close)) |end| {
            cursor = end;
            continue;
        }
        const tag = scan.tagAt(input, at, &no_more_nowiki_close) orelse {
            cursor = at + 1;
            continue;
        };
        if (tag.is("tbody") or tag.is("thead") or tag.is("tfoot")) return true;
        cursor = tag.end;
    }
    return false;
}

fn optionalListItemEnd(input: []const u8, opening: syntax.Tag) syntax.Pair {
    if (opening.self_closing) return .{ .inner_end = opening.end, .end = opening.end };
    var cursor = opening.end;
    while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |at| {
        if (syntax.protectedEnd(input, at)) |end| {
            cursor = end;
            continue;
        }
        const tag = syntax.tagAt(input, at) orelse {
            cursor = at + 1;
            continue;
        };
        cursor = tag.end;
        if (!tag.closing and (tag.is("ul") or tag.is("ol") or tag.is("dl") or tag.is("table"))) {
            if (syntax.matchingTag(input, tag)) |pair| {
                cursor = pair.end;
                continue;
            }
        }
        if (tag.closing and tag.is(opening.name)) return .{ .inner_end = at, .end = tag.end };
        const sibling = !tag.closing and (if (opening.is("li")) tag.is("li") else tag.is("dt") or tag.is("dd"));
        const parent = tag.closing and (tag.is("ul") or tag.is("ol") or tag.is("dl"));
        if (sibling or parent) return .{ .inner_end = at, .end = at };
    }
    return .{ .inner_end = input.len, .end = input.len };
}
// Explicit ruby fallback punctuation belongs to this ruby, not nested ruby or
// protected literal markup. Existing rp text must pass through unchanged.
fn rubyHasFallback(input: []const u8) bool {
    var cursor: usize = 0;
    while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |at| {
        if (syntax.protectedEnd(input, at)) |end| {
            cursor = end;
            continue;
        }
        const tag = syntax.tagAt(input, at) orelse {
            cursor = at + 1;
            continue;
        };
        cursor = tag.end;
        if (tag.closing) continue;
        if (tag.is("rp")) return true;
        if (tag.is("ruby")) {
            if (syntax.matchingTag(input, tag)) |pair| cursor = pair.end;
        }
    }
    return false;
}

// WikiHiero's parserHook ignores its attribute map and renders unlinked glyph
// images. Support only the attested boolean link spelling as that same no-op;
// other attributes retain the native compiler's explicit unsupported fallback.
fn supportedHieroAttributes(raw: []const u8) bool {
    const attrs = trim(raw);
    if (attrs.len == 0) return true;
    const equal = std.mem.indexOfScalar(u8, attrs, '=') orelse return false;
    if (!std.ascii.eqlIgnoreCase(trim(attrs[0..equal]), "link")) return false;
    var value = trim(attrs[equal + 1 ..]);
    if (value.len == 0) return false;
    if (value[0] == '\'' or value[0] == '"') {
        if (value.len < 2 or value[value.len - 1] != value[0]) return false;
        value = value[1 .. value.len - 1];
    }
    return std.ascii.eqlIgnoreCase(value, "true") or std.ascii.eqlIgnoreCase(value, "false");
}

fn htmlAttributePresent(tag: syntax.Tag, key: []const u8) bool {
    var at: usize = 0;
    while (at < tag.attrs.len) {
        while (at < tag.attrs.len and (std.ascii.isWhitespace(tag.attrs[at]) or tag.attrs[at] == '/')) : (at += 1) {}
        const begin = at;
        while (at < tag.attrs.len and !std.ascii.isWhitespace(tag.attrs[at]) and tag.attrs[at] != '=' and tag.attrs[at] != '/') : (at += 1) {}
        if (at == begin) {
            at += 1;
            continue;
        }
        if (std.ascii.eqlIgnoreCase(tag.attrs[begin..at], key)) return true;
        while (at < tag.attrs.len and std.ascii.isWhitespace(tag.attrs[at])) : (at += 1) {}
        if (at == tag.attrs.len or tag.attrs[at] != '=') continue;
        at += 1;
        while (at < tag.attrs.len and std.ascii.isWhitespace(tag.attrs[at])) : (at += 1) {}
        if (at == tag.attrs.len) break;
        const quote = tag.attrs[at];
        const quoted = quote == '\'' or quote == '"';
        if (quoted) at += 1;
        while (at < tag.attrs.len and (if (quoted) tag.attrs[at] != quote else !std.ascii.isWhitespace(tag.attrs[at]))) : (at += 1) {}
        if (quoted and at < tag.attrs.len) at += 1;
    }
    return false;
}
// Tag.attr extracts values and therefore cannot distinguish a boolean
// attribute from absence. Certify the whole attribute token sequence first;
// malformed/duplicate/overflow input supplies no absence authority.
fn htmlOwnAttributePresence(raw: ?*const anyopaque, key: []const u8) table_style_profile.AttributePresence {
    const tag: *const syntax.Tag = @ptrCast(@alignCast(raw orelse return .unknown));
    if (tag.closing or tag.self_closing or tag.isOpaque() or tag.html_pre or std.mem.indexOfAny(u8, tag.attrs, "<>\x00") != null) return .unknown;
    var names: [32][]const u8 = undefined;
    var count: usize = 0;
    var at: usize = 0;
    while (at < tag.attrs.len) {
        while (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\r\n\x0c", tag.attrs[at]) != null) : (at += 1) {}
        if (at == tag.attrs.len) break;
        const begin = at;
        if (!(std.ascii.isAlphabetic(tag.attrs[at]) or tag.attrs[at] == '_' or tag.attrs[at] == ':')) return .unknown;
        at += 1;
        while (at < tag.attrs.len and (std.ascii.isAlphanumeric(tag.attrs[at]) or std.mem.indexOfScalar(u8, "_:-", tag.attrs[at]) != null)) : (at += 1) {}
        const name = tag.attrs[begin..at];
        if (count == names.len) return .unknown;
        for (names[0..count]) |previous| if (std.ascii.eqlIgnoreCase(previous, name)) return .unknown;
        names[count] = name;
        count += 1;
        const name_end = at;
        while (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\r\n\x0c", tag.attrs[at]) != null) : (at += 1) {}
        if (at < tag.attrs.len and tag.attrs[at] == '=') {
            at += 1;
            while (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\r\n\x0c", tag.attrs[at]) != null) : (at += 1) {}
            if (at == tag.attrs.len) return .unknown;
            const quote = tag.attrs[at];
            if (quote == '\'' or quote == '"') {
                at += 1;
                while (at < tag.attrs.len and tag.attrs[at] != quote) : (at += 1) {
                    const byte = tag.attrs[at];
                    if ((byte < 32 and std.mem.indexOfScalar(u8, "\t\r\n\x0c", byte) == null) or byte == 127) return .unknown;
                }
                if (at == tag.attrs.len) return .unknown;
                at += 1;
                if (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\r\n\x0c", tag.attrs[at]) == null) return .unknown;
            } else {
                const value_start = at;
                while (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\r\n\x0c", tag.attrs[at]) == null) : (at += 1)
                    if (tag.attrs[at] < 32 or tag.attrs[at] == 127 or std.mem.indexOfScalar(u8, "\"'`=<>", tag.attrs[at]) != null) return .unknown;
                if (at == value_start) return .unknown;
            }
        } else if (at == name_end and at < tag.attrs.len) return .unknown;
    }
    return if (htmlAttributePresent(tag.*, key)) .present else .absent;
}
const HtmlListNumberStyle = enum { decimal, lower_alpha, upper_alpha, lower_roman, upper_roman };
fn htmlListNumberStyle(value: []const u8) ?HtmlListNumberStyle {
    if (std.mem.eql(u8, value, "1")) return .decimal;
    if (std.mem.eql(u8, value, "a")) return .lower_alpha;
    if (std.mem.eql(u8, value, "A")) return .upper_alpha;
    if (std.mem.eql(u8, value, "i")) return .lower_roman;
    if (std.mem.eql(u8, value, "I")) return .upper_roman;
    return null;
}
fn htmlListItemCount(input: []const u8) i32 {
    var count: i32 = 0;
    var cursor: usize = 0;
    while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |at| {
        if (syntax.protectedEnd(input, at)) |end| {
            cursor = end;
            continue;
        }
        const tag = syntax.tagAt(input, at) orelse {
            cursor = at + 1;
            continue;
        };
        cursor = tag.end;
        if (tag.closing) continue;
        if (tag.is("li")) {
            count +|= 1;
            cursor = optionalListItemEnd(input, tag).end;
        } else if (tag.is("ul") or tag.is("ol") or tag.is("dl") or tag.is("table")) {
            if (syntax.matchingTag(input, tag)) |pair| cursor = pair.end;
        }
    }
    return count;
}
pub const media_types = @import("presentation_media.zig");
pub const Error = A.Error || error{ InvalidFontScale, UncompiledPresentation, RenderLimit, InvalidPreContext, UncompiledTemplate, InvalidMissingDependencyCopy, InvalidLiteralProvenance, LiteralProvenanceLimit };

// Build-only coordinates in an already page-TOC-prepared owner fragment.
// The source owner map, rather than a new tag search here, proves these scopes.
pub const FormattingAttributes = struct {
    text_element: ?*const table_style_profile.TextElement = null,
    custom_properties: ?table_style_profile.CustomEnvironment = null,
    relative_context_policy_present: bool = false,
    // Producer-only conservative inherited policy; never a reader field.
    column_fragmentation_policy_present: bool = false,
    table_collapse: ?table_style_profile.BorderCollapseState = null,
    table_inheritance_scoped: bool = false,
    text_align: ?presentation_types.CellTextAlign = null,
    classes: []const u8 = "",
    // Build-only ancestor source tokens, never serialized into Stored styles.
    css_ancestor_classes: []const u8 = "",
    role: Role = .normal,
    relation_note: bool = false,
    language: []const u8 = "",
    direction: []const u8 = "",
    // Effective metadata saved before legacy Unicode isolation clears direction.
    // Consumed only when this exact captured interval becomes a typed scope.
    captured_direction: ?[]const u8 = null,
    explanation: []const u8 = "",
    tooltip: ?[]const u8 = null,
    tooltip_set: bool = false,
    explanation_set: bool = false,
    foreground: ?[]const u8 = null,
    foreground_set: bool = false,
    font_scale: ?f32 = null,
    font_scale_basis: FontScaleBasis = .context,
    font_scale_set: bool = false,
    // Build-only completeness; never serialized as span style or identity.
    font_size_unknown: bool = false,
};
pub const FragmentPreContext = struct {
    pub const Kind = enum { pre, formatting, layout_div, link, refused_link, hidden, css_block };
    pub const Initial = struct { body_end: usize, resume_at: usize, kind: FragmentPreContext.Kind = .pre, formatting: SpanFlags = .{}, target: []const u8 = "", tag_name: []const u8 = "", attributes: FormattingAttributes = .{}, quote: ?QuoteSeed = null, resume_quote: ?QuoteSeed = null };
    pub const Trailing = struct { opening_start: usize, body_start: usize, kind: FragmentPreContext.Kind = .pre, formatting: SpanFlags = .{}, target: []const u8 = "", tag_name: []const u8 = "", attributes: FormattingAttributes = .{}, quote: ?QuoteSeed = null };
    initial: []const Initial = &.{},
    trailing: []const Trailing = &.{},
    initial_block_pre: bool = false,
    quote: ?QuoteSeed = null,
};

// Sparse gate for the existing full-page observer. Complete single-line
// roots are skipped once; malformed overlap is bounded by the shared stack.
// This is only an observation hint. The existing renderer decides whether a
// matched formatting wrapper owns a body scope, and which headings it crosses.
pub fn mayHaveFormattingScopes(input: []const u8) bool {
    var opaque_scan: syntax.OpaqueScan = .{};
    var cursor: usize = 0;
    while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |opening| {
        if (opaque_scan.protectedEnd(input, opening, null)) |end| {
            cursor = end;
            continue;
        }
        if (opaque_scan.tagAt(input, opening, null)) |tag| {
            cursor = tag.end;
            if (tag.closing or tag.self_closing) continue;
            if (Renderer.blockFormattingFlags(tag) != null) return true;
            if (tag.is("div") and trim(tag.attrs).len == 0) return true;
            if (tag.is("div") and (tag.attr("class") != null or tag.attr("style") != null)) return true;
            if (Renderer.knownInlineHtmlName(tag.name) and (tag.attr("style") != null or std.mem.indexOfScalar(u8, tag.attrs, '<') != null)) return true;
        } else cursor = opening + 1;
    }
    return false;
}

pub fn mayHaveMultilineLinks(source: []const u8) bool {
    var scan: syntax.OpaqueScan = .{};
    var at: usize = 0;
    while (at < source.len) {
        if (source[at] == '<') {
            if (scan.protectedEnd(source, at, null)) |end| {
                at = end;
                continue;
            }
            if (scan.tagAt(source, at, null)) |tag| {
                at = tag.end;
                continue;
            }
        }
        if (starts(source[at..], "{{") or starts(source[at..], "[[")) {
            if (syntax.balancedWithOpaqueScan(source, at, &scan)) |pair| {
                if (starts(source[at..], "[[") and std.mem.indexOfScalar(u8, source[at..pair.end], '\n') != null) return true;
                at = pair.end;
                continue;
            }
        }
        at += 1;
    }
    return false;
}

pub const PreScopeObserver = struct {
    ctx: ?*anyopaque,
    enter: *const fn (?*anyopaque, []const u8, ?usize, usize, usize, usize, usize, bool, FragmentPreContext.Kind, SpanFlags, []const u8, FormattingAttributes) Error!void,
};

// Optional build-only native extension provenance. A phase is validated once
// against the complete wire output/title before language regrouping. Renderers
// own copies of referenced strings, not pointers into the page transport arena.
pub const PoemPhaseItem = struct {
    token: []const u8,
    kind: enum { br, space, indent, scope, literal },
    depth: ?u8 = null,
    tag: ?[]const u8 = null,
    body: ?[]const u8 = null,
    generated_links: []const generated_link.WireRange = &.{},
};
const PoemPhaseWire = struct {
    schema: []const u8,
    handled: bool,
    output_sha256: []const u8,
    display_title_sha256: []const u8,
    items: []const PoemPhaseItem,
    output_links: []const generated_link.WireRange = &.{},
    display_title_links: []const generated_link.WireRange = &.{},
};
pub const PoemPhase = struct {
    items: []const PoemPhaseItem,
    // Borrowed only during this page's synchronous Writer compilation. JSON
    // values and Renderer-owned strings have their separate allocator lifetimes.
    full_output: []const u8,
    display_title_source: []const u8 = "",
    output_links: []const generated_link.Range = &.{},
    display_title_links: []const generated_link.Range = &.{},
    numbered_links: []const generated_link.Range = &.{},
    body_links: []const []const generated_link.Range = &.{},
    numbered_body_links: []const []const generated_link.Range = &.{},
    // Encoder-only semantic preparation; never part of PoemPhaseWire.
    numbered_bodies: []const ?[]const u8 = &.{},
    // Build-only whole-page root, borrowed from PreparedExternalLinks.source.
    // Rewritten bytes and this overlay share its caller page-allocator lifetime;
    // unchanged roots retain the existing borrowed full_output lifetime.
    numbered_source: ?[]const u8 = null,
    // The numbered root and its immutable Cite registry share page lifetime.
    numbered_citations: ?*const CitationPlan = null,
};
const native_poem_prefix = "\x7fWDPOEM:";
const max_poem_metadata_bytes = 16 * 1024 * 1024;
fn nativePoemLooking(value: []const u8) bool {
    var cursor: usize = 0;
    while (std.mem.indexOfScalarPos(u8, value, cursor, '<')) |lt| {
        cursor = lt + 1;
        if (cursor < value.len and value[cursor] == '/') cursor += 1;
        if (value.len - cursor < 4 or !std.ascii.eqlIgnoreCase(value[cursor..][0..4], "poem")) continue;
        if (value.len == cursor + 4 or value[cursor + 4] == '>' or value[cursor + 4] == '/' or std.ascii.isWhitespace(value[cursor + 4])) return true;
    }
    return false;
}
fn nativePoemIndex(value: []const u8) ?usize {
    if (!std.mem.startsWith(u8, value, native_poem_prefix)) return null;
    const rest = value[native_poem_prefix.len..];
    const colon = std.mem.indexOfScalar(u8, rest[0..@min(rest.len, 21)], ':') orelse return null;
    if (colon == 0 or (colon > 1 and rest[0] == '0')) return null;
    for (rest[0..colon]) |ch| if (!std.ascii.isDigit(ch)) return null;
    return std.fmt.parseInt(usize, rest[0..colon], 10) catch null;
}
const PoemReferenceMetrics = struct { bytes: usize, depth: usize };
fn poemReferenceMetrics(value: []const u8, items: []const PoemPhaseItem, before: usize, costs: []const usize, depths: []const usize) !PoemReferenceMetrics {
    var pos: usize = 0;
    var bytes: usize = 0;
    var depth: usize = 0;
    while (std.mem.indexOfPos(u8, value, pos, native_poem_prefix)) |found| {
        const index = nativePoemIndex(value[found..]) orelse return error.OrphanPoemMarker;
        if (index >= items.len or index >= before or !std.mem.startsWith(u8, value[found..], items[index].token)) return error.OrphanPoemMarker;
        bytes = std.math.add(usize, bytes, found - pos) catch return error.FrameTooLarge;
        bytes = std.math.add(usize, bytes, costs[index]) catch return error.FrameTooLarge;
        if (bytes > max_poem_metadata_bytes) return error.FrameTooLarge;
        depth = @max(depth, depths[index] + 1);
        if (depth > max_depth) return error.InvalidPoemMetadata;
        pos = found + items[index].token.len;
    }
    bytes = std.math.add(usize, bytes, value.len - pos) catch return error.FrameTooLarge;
    if (bytes > max_poem_metadata_bytes) return error.FrameTooLarge;
    return .{ .bytes = bytes, .depth = depth };
}
pub fn parsePoemPhaseAlloc(a: A, full_output: []const u8, display_title: ?[]const u8, metadata: ?[]const u8) !?*const PoemPhase {
    const title = display_title orelse "";
    if (full_output.len > max_poem_metadata_bytes or title.len > 64 * 1024) return error.FrameTooLarge;
    const encoded = metadata orelse {
        if (std.mem.indexOf(u8, full_output, native_poem_prefix) != null or std.mem.indexOf(u8, title, native_poem_prefix) != null) return error.OrphanPoemMarker;
        if (std.mem.indexOf(u8, full_output, generated_link.prefix) != null or std.mem.indexOf(u8, title, generated_link.prefix) != null) return error.InvalidPoemMetadata;
        if (nativePoemLooking(full_output) or nativePoemLooking(title)) return error.MissingPoemMetadata;
        return null;
    };
    if (encoded.len > max_poem_metadata_bytes) return error.FrameTooLarge;
    const phase = try a.create(PoemPhaseWire);
    phase.* = std.json.parseFromSliceLeaky(PoemPhaseWire, a, encoded, .{ .allocate = .alloc_always, .ignore_unknown_fields = false, .duplicate_field_behavior = .@"error" }) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return error.InvalidPoemMetadata,
    };
    const generated = std.mem.eql(u8, phase.schema, "wikidict.presentation-phase.v2");
    if (!phase.handled or (!generated and !std.mem.eql(u8, phase.schema, "wikidict.poem-phase.v1")) or phase.items.len > 100_000) return error.InvalidPoemMetadata;
    if (!generated and (phase.output_links.len != 0 or phase.display_title_links.len != 0)) return error.InvalidPoemMetadata;
    var output_hash: [32]u8 = undefined;
    var title_hash: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(full_output, &output_hash, .{});
    std.crypto.hash.sha2.Sha256.hash(title, &title_hash, .{});
    const output_hex = std.fmt.bytesToHex(output_hash, .lower);
    const title_hex = std.fmt.bytesToHex(title_hash, .lower);
    if (!std.mem.eql(u8, phase.output_sha256, &output_hex) or !std.mem.eql(u8, phase.display_title_sha256, &title_hex)) return error.InvalidPoemMetadata;
    const costs = try a.alloc(usize, phase.items.len);
    const depths = try a.alloc(usize, phase.items.len);
    var literal_bytes: usize = 0;
    var link_count = generated_link.checkedCount(phase.output_links.len, phase.display_title_links.len) catch return error.InvalidPoemMetadata;
    const body_links = try a.alloc([]const generated_link.Range, phase.items.len);
    @memset(body_links, &.{});
    for (phase.items, 0..) |item, index| {
        if (!generated and item.generated_links.len != 0) return error.InvalidPoemMetadata;
        link_count = generated_link.checkedCount(link_count, item.generated_links.len) catch return error.InvalidPoemMetadata;
        if (item.token.len > 128 or nativePoemIndex(item.token) != index) return error.InvalidPoemMetadata;
        const rest = item.token[native_poem_prefix.len..];
        const colon = native_poem_prefix.len + (std.mem.indexOfScalar(u8, rest, ':') orelse return error.InvalidPoemMetadata);
        const tail = item.token[colon + 1 ..];
        if (tail.len != 65 or tail[64] != 0x7f) return error.InvalidPoemMetadata;
        for (tail[0..64]) |ch| if (!std.ascii.isDigit(ch) and (ch < 'a' or ch > 'f')) return error.InvalidPoemMetadata;
        if (item.kind == .indent) {
            const depth = item.depth orelse return error.InvalidPoemMetadata;
            if (depth == 0 or depth > 32) return error.InvalidPoemMetadata;
        } else if (item.depth != null) return error.InvalidPoemMetadata;
        costs[index] = if (item.kind == .br or item.kind == .space) 1 else 0;
        depths[index] = 0;
        if (item.kind == .literal) {
            const tag = item.tag orelse return error.InvalidPoemMetadata;
            const body = item.body orelse return error.InvalidPoemMetadata;
            if (!oneOf(tag, &.{ "text", "nowiki", "pre", "source", "syntaxhighlight", "poem" })) return error.InvalidPoemMetadata;
            if (body.len > max_poem_metadata_bytes -| literal_bytes) return error.FrameTooLarge;
            literal_bytes += body.len;
            var body_hash: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(body, &body_hash, .{});
            const body_hex = std.fmt.bytesToHex(body_hash, .lower);
            if (!std.mem.eql(u8, tail[0..64], &body_hex)) return error.InvalidPoemMetadata;
            if (std.mem.eql(u8, tag, "text")) {
                if (item.generated_links.len != 0) return error.InvalidPoemMetadata;
                costs[index] = body.len;
                depths[index] = 1;
            } else {
                body_links[index] = generated_link.bindAlloc(a, body, item.generated_links) catch |err| switch (err) { error.OutOfMemory => return err, else => return error.InvalidPoemMetadata };
                generated_link.validateCoverage(body, body_links[index]) catch return error.InvalidPoemMetadata;
                const metrics = try poemReferenceMetrics(body, phase.items, index, costs, depths);
                costs[index] = metrics.bytes;
                depths[index] = metrics.depth;
            }
        } else if (item.tag != null or item.body != null or item.generated_links.len != 0) return error.InvalidPoemMetadata;
    }
    _ = try poemReferenceMetrics(full_output, phase.items, phase.items.len, costs, depths);
    const title_metrics = try poemReferenceMetrics(title, phase.items, phase.items.len, costs, depths);
    if (title_metrics.bytes > 64 * 1024) return error.FrameTooLarge;
    const result = try a.create(PoemPhase);
    const output_links = generated_link.bindAlloc(a, full_output, phase.output_links) catch |err| switch (err) { error.OutOfMemory => return err, else => return error.InvalidPoemMetadata };
    const title_links = generated_link.bindAlloc(a, title, phase.display_title_links) catch |err| switch (err) { error.OutOfMemory => return err, else => return error.InvalidPoemMetadata };
    generated_link.validateCoverage(full_output, output_links) catch return error.InvalidPoemMetadata;
    generated_link.validateCoverage(title, title_links) catch return error.InvalidPoemMetadata;
    result.* = .{ .items = phase.items, .full_output = full_output, .display_title_source = title, .output_links = output_links, .display_title_links = title_links, .body_links = body_links };
    return result;
}

fn missingSlice(a: A, parent: MissingText, child: []const u8) Error!MissingText {
    const base = @intFromPtr(parent.bytes.ptr);
    const at = @intFromPtr(child.ptr);
    if (at < base or at - base > parent.bytes.len or child.len > parent.bytes.len - (at - base))
        return MissingText.transformedFrom(parent, child);
    if (parent.ranges.len == 0 and parent.literal_curly_ranges.len == 0 and parent.generated_links.len == 0) return .{ .bytes = child, .unknown = parent.unknown, .lost_missing_range = parent.lost_missing_range };
    return missing_dependency.slice(a, parent, at - base, at - base + child.len);
}
fn missingEdit(source: MissingText, start: usize, end: usize, bytes: []const u8) MissingText {
    var unknown = source.unknown;
    var lost_missing_range = source.lost_missing_range;
    for (source.ranges) |r| if (r.start < end and r.end > start) {
        unknown = true;
        lost_missing_range = true;
        break;
    };
    return .{ .bytes = bytes, .unknown = unknown, .lost_missing_range = lost_missing_range };
}

fn bindGeneratedSlice(a: A, source: MissingText, root: []const u8, links: []const generated_link.Range) Error!?MissingText {
    if (try generated_link.borrowedSliceAlloc(a, source.bytes, root, links)) |slice| {
        if (slice.len == 0) return null;
        try generated_link.validateCoverage(source.bytes, slice);
        var result = source;
        result.generated_links = slice;
        result.generated_source = source.bytes;
        return result;
    }
    return null;
}
fn bindGeneratedSource(a: A, source: MissingText, phase: ?*const PoemPhase) Error!MissingText {
    try generated_link.validateRanges(source.bytes, source.generated_source, source.generated_links);
    if (source.generated_links.len != 0) return source;
    if (std.mem.indexOf(u8, source.bytes, generated_link.prefix) == null) return source;
    const known = phase orelse return error.InvalidLiteralProvenance;
    const roots = [_][]const u8{ known.full_output, known.display_title_source, known.numbered_source orelse "" };
    const ranges = [_][]const generated_link.Range{ known.output_links, known.display_title_links, known.numbered_links };
    for (roots, ranges) |root, links| if (try bindGeneratedSlice(a, source, root, links)) |result| return result;
    for (known.items, 0..) |item, index| {
        if (item.body) |body| if (index < known.body_links.len) {
            if (try bindGeneratedSlice(a, source, body, known.body_links[index])) |result| return result;
        };
        if (index < known.numbered_bodies.len and index < known.numbered_body_links.len) if (known.numbered_bodies[index]) |body| {
            if (try bindGeneratedSlice(a, source, body, known.numbered_body_links[index])) |result| return result;
        };
    }
    return error.InvalidLiteralProvenance;
}

pub const GeneratedLinkProof = struct {
    bound: *const generated_link.Bound,
    display: []const u8,
    preserve_whitespace: bool,
    display_slice: ?[]const u8 = null,
};
pub fn hasCompiledGeneratedLinkTarget(span: Span) bool {
    if (span.kind != .link or span.self_link or span.provenance != .protected_literal) return false;
    const proof = span.generated_link orelse return false;
    const value = proof.bound.value;
    const needs_component = std.mem.indexOfScalar(u8, value.target, '#') != null;
    if (needs_component) {
        if (span.target_fragment == null or span.target_fragment.?.len != 0) return false;
    } else if (span.target_fragment != null) return false;
    const display = proof.display_slice orelse proof.display;
    const base = @intFromPtr(proof.display.ptr);
    const at = @intFromPtr(display.ptr);
    if (at < base or at - base > proof.display.len or display.len > proof.display.len - (at - base)) return false;
    return generated_link.validBound(proof.bound) and span.target.ptr == value.target.ptr and span.target.len == value.target.len and
        span.text.ptr == display.ptr and span.text.len == display.len and generated_link.displayMatches(proof.display, value.label, proof.preserve_whitespace);
}

fn generatedLabelSlice(original: Span, text: []const u8) Error!Span {
    if (!hasCompiledGeneratedLinkTarget(original)) return error.InvalidLiteralProvenance;
    const base = @intFromPtr(original.text.ptr);
    const at = @intFromPtr(text.ptr);
    if (at < base or at - base > original.text.len or text.len > original.text.len - (at - base)) return error.InvalidLiteralProvenance;
    var result = original;
    result.text = text;
    var proof = original.generated_link.?;
    proof.display_slice = text;
    result.generated_link = proof;
    return result;
}

// Build-only immutable authority. Loading validates IO/source identities; a
// lookup retains no request bytes and has only allocation failure to propagate.
pub const MissingFigureObservation = struct {
    label: []const u8,
    href: []const u8,
    data_width: u32,
    link_paint: ?presentation_types.MissingLinkPaint = null,
    anchor_attributes: table_style_profile.AttributePresenceSource,
    element_attributes: table_style_profile.AttributePresenceSource,
};
// Full original expansion and a selected observed parser-root class inventory.
// Build-only absence proof. The optional complete superset additionally needs
// authenticated outer context; neither form supplies positive CSS matches.
pub const ObservedSvgLanguage = struct { language: []const u8, policy: presentation_types.FigureSizingPolicy };

pub const ObservedTextClassScope = struct {
    source: []const u8,
    scope: *const table_style_profile.BoundedTextClassScope,
};
// Shared producer-side validation: the existing MediaWiki language-tag grammar
// plus the canonical raster-key subset representable by the current model.
pub fn validSvgRasterLanguage(language: []const u8) bool {
    return presentation_types.validSvgLanguageIdentity(language) and Renderer.mediaLanguageTag(language);
}


// Build-only recognition of the narrow source branch whose complete rendered
// result can be supplied by a selected normal page observation. This does not
// establish header success or itself authorize an error result.
pub const ImageMapNoLinkSource = struct { file: []const u8, line: usize };
pub fn imageMapNoLinkSource(input: []const u8) ?ImageMapNoLinkSource {
    if (input.len == 0 or input.len > 256 * 1024 or std.mem.indexOfScalar(u8, input, 0) != null) return null;
    var lines = std.mem.splitScalar(u8, input, '\n');
    var physical_line: usize = 0;
    var file: ?[]const u8 = null;
    while (lines.next()) |raw_line| {
        physical_line += 1;
        const line = std.mem.trim(u8, raw_line, " \t\r");
        if (line.len == 0 or line[0] == '#') continue;
        if (file == null) {
            if (std.mem.indexOfAny(u8, line, "<>{}[]") != null) return null;
            const pipe = std.mem.indexOfScalar(u8, line, '|') orelse return null;
            const name = std.mem.trim(u8, line[0..pipe], " \t\r");
            if (name.len == 0) return null;
            var size = std.mem.trim(u8, line[pipe + 1 ..], " \t\r");
            if (std.mem.endsWith(u8, size, "|")) size = std.mem.trim(u8, size[0 .. size.len - 1], " \t\r");
            if (!std.mem.endsWith(u8, size, "px")) return null;
            size = size[0 .. size.len - 2];
            var dimensions = std.mem.splitScalar(u8, size, 'x');
            var count: usize = 0;
            while (dimensions.next()) |dimension| {
                if (dimension.len == 0 or count == 2) return null;
                for (dimension) |byte| if (!std.ascii.isDigit(byte)) return null;
                const value = std.fmt.parseInt(u16, dimension, 10) catch return null;
                if (value == 0) return null;
                count += 1;
            }
            if (count == 0) return null;
            file = name;
            continue;
        }
        // Earlier desc/region/unknown commands remain on the strict ordinary
        // path. An observation never reorders an earlier potential error.
        const space = std.mem.indexOfAny(u8, line, " \t") orelse return null;
        if (!std.mem.eql(u8, line[0..space], "default") or std.mem.indexOfScalar(u8, line, '[') != null) return null;
        return .{ .file = file.?, .line = physical_line };
    }
    return null;
}

pub const FigureSizingSource = struct {
    // Build-only validated file alias identity; source/Book lookups keep authored names.
    resolve_canonical_file_fn: ?*const fn (?*const anyopaque, A, []const u8) A.Error!?[]const u8 = null,
    ctx: ?*const anyopaque = null,
    // Page-owned observation capabilities never replace the shared sizing context.
    page_observation_ctx: ?*const anyopaque = null,
    text_class_scope: ?ObservedTextClassScope = null,
    resolve_fn: *const fn (?*const anyopaque, A, []const u8, presentation_types.FigureFormat, ?u32, ?u32) A.Error!?presentation_types.FigureSizingPolicy,
    // Explicit SVG raster language requires an exact selected page observation;
    // ordinary sizing cannot silently supply a different image variant.
    // Only an exact selected occurrence may supply a resolved raster language
    // when the source contains no authored language option.
    resolve_observed_svg_language_fn: ?*const fn (?*const anyopaque, A, []const u8, presentation_types.FigureFormat, []const u8, ?u32, ?u32) A.Error!?ObservedSvgLanguage = null,
    resolve_svg_language_fn: ?*const fn (?*const anyopaque, A, []const u8, presentation_types.FigureFormat, []const u8, []const u8, ?u32, ?u32) A.Error!?presentation_types.FigureSizingPolicy = null,
    // Separate default-first-page TIFF authority; generic sizing never grants it.
    resolve_default_tiff_page_fn: ?*const fn (?*const anyopaque, A, []const u8, presentation_types.FigureFormat, ?u32, ?u32) A.Error!?presentation_types.FigureSizingPolicy = null,
    // Optional exact page/occurrence observation; never a general upright factor.
    // The immutable callback owner binds source/title/site/core/file/options.
    resolve_observed_width_fn: ?*const fn (?*const anyopaque, A, []const u8, presentation_types.FigureFormat, []const u8, u32) A.Error!?u32 = null,
    // Exact selected bare-upright SVG raster/geometry proof. This fallback
    // cannot supply other widths or replace ordinary file sizing authority.
    resolve_observed_svg_upright_fit_fn: ?*const fn (?*const anyopaque, A, []const u8, presentation_types.FigureFormat, []const u8, ?u32, ?u32) A.Error!?presentation_types.FigureSizingPolicy = null,
    // Complete final-anchor inventory for one selected page and occurrence.
    // Missing page context or a mismatched lookup leaves attributes unknown.
    resolve_anchor_attributes_fn: ?*const fn (?*const anyopaque, A, []const u8, presentation_types.FigureFormat, []const u8) A.Error!?table_style_profile.AttributePresenceSource = null,
    // Selected full-page markup plus independently authenticated missing=true.
    // This supplies no successful image, sizing policy, or computed CSS.
    resolve_missing_content_fn: ?*const fn (?*const anyopaque, A, []const u8, presentation_types.FigureFormat, []const u8) A.Error!?MissingFigureObservation = null,
    // Exact complete supplied-page wrapper + served CSS + retained file/message
    // proof. No ordinary handler or filename-only eligibility is implied.
    resolve_static_poster_fn: ?*const fn (?*const anyopaque, A, []const u8, presentation_types.FigureFormat, []const u8, ?u32, ?u32) A.Error!?presentation_types.StaticPoster = null,
    // Authenticated non-vector file basis for a height-only thumbnail. The
    // returned original width is paired with the authored height bound.
    resolve_height_only_width_fn: ?*const fn (?*const anyopaque, A, []const u8, presentation_types.FigureFormat, u32) A.Error!?u32 = null,
    resolve_width_limit_fn: ?*const fn (?*const anyopaque, A, []const u8, presentation_types.FigureFormat) A.Error!?u32 = null,
    // Exact observed occurrence: wiki, original page title, file, and all raw
    // options participate. This does not attest a deployed parser core or cap.
    resolve_height_occurrence_fn: ?*const fn (?*const anyopaque, A, []const u8, []const u8, []const u8, presentation_types.FigureFormat, []const u8, u32) A.Error!?u32 = null,
    // Independent full-page height evidence uses only the selected page context.
    resolve_observed_page_height_fn: ?*const fn (?*const anyopaque, A, []const u8, []const u8, []const u8, presentation_types.FigureFormat, []const u8, u32) A.Error!?u32 = null,
    // Exact selected page observation; returns a plain localized error sentence.
    // No callback means no header-success or error-recovery authority.
    resolve_image_map_no_link_fn: ?*const fn (?*const anyopaque, A, []const u8, usize) A.Error!?[]const u8 = null,
    // Authenticated SVG handler model for an authored width AND height pair.
    // It must never supply the width of an observed height-only occurrence.
    resolve_svg_explicit_box_fn: ?*const fn (?*const anyopaque, A, []const u8, presentation_types.FigureFormat, ?u32, ?u32) A.Error!?presentation_types.FigureSizingPolicy = null,
    source_context: ?FigureSourceContext = null,
    page_language: ?FigurePageLanguageContext = null,
};
// Loader-selected current observation for one exact page/revision/source pair.
