                        } else {
                            try sink.append(a, try normalizeHtmlWithMissing(a, try normalizeWikiQuotesWithMissing(a, try missing_dependency.slice(a, source, cursor + 2 + pipe + 1, skip - 2), depth + 1, true, context, null), depth + 1, false));
                        }
