    return result;
}

pub const Reference = struct { kind: citation_state.Kind = .note, number: usize, group_number: ?u32, name: []const u8 = "", group: []const u8 = "", body: []const u8 = "", missing: ?MissingText = null, spans: []const Span = &.{}, blocks: ?[]const Block = null, poem: bool = false, poem_direction: []const u8 = "", citation_plan: ?*const CitationPlan = null, citation_item: ?usize = null };
pub const ReferenceDefinition = struct { name: []const u8, group: []const u8 = "", body: []const u8 = "", missing: ?MissingText = null, list_defined: bool = false };
pub const ReferenceDefinitions = struct { content_conversion: ?bool = null, items: []const ReferenceDefinition = &.{}, fallbacks: @import("presentation_fallback.zig").Report = .{}, citations: ?*const CitationPlan = null };

/// Collect names once without rendering reference bodies or creating citations.
pub fn referenceDefinitionsAlloc(a: std.mem.Allocator, source: []const u8) Error!ReferenceDefinitions {
    var renderer: Renderer = .{ .a = a, .context = .{} };
    try renderer.referenceDefinitions(source, "");
    return .{ .items = try renderer.ref_defs.toOwnedSlice(a), .fallbacks = renderer.fallbacks };
}

pub fn referenceDefinitionsWithMissingAlloc(a: A, source: MissingText) Error!ReferenceDefinitions {
    var renderer: Renderer = .{ .a = a, .context = .{}, .body_missing = source };
    try renderer.referenceDefinitions(source.bytes, "");
    return .{ .items = try renderer.ref_defs.toOwnedSlice(a), .fallbacks = renderer.fallbacks };
}

const max_nodes = 100_000;
const max_depth = 48;
fn starts(text: []const u8, prefix: []const u8) bool {
    return syntax.starts(text, prefix);
}
fn trim(text: []const u8) []const u8 {
    return syntax.trim(text);
}
fn listRoot(mark: u8) u8 {
    return if (mark == ';' or mark == ':') ';' else mark;
}
fn resetChangedListCounters(counts: []usize, previous: []const u8, current: []const u8) void {
    const limit = @min(counts.len, @min(previous.len, current.len));
    var common: usize = 0;
    while (common < limit and listRoot(previous[common]) == listRoot(current[common])) : (common += 1) {}
    // A different nested list family closes that list, but keeps common parents.
    @memset(counts[common..], 0);
}
// MediaWiki chooses definition separators after quote/link rendering, outside
// accepted HTML nesting. Keep the shared template delimiter rules unchanged.
const DefinitionColonScanner = struct {
    input: []const u8,
    cursor: usize = 0,
    html_depth: usize = 0,

    fn next(self: *DefinitionColonScanner, after: usize) ?usize {
        const text = self.input;
        while (self.cursor < text.len) {
            const colon = syntax.delimiter(text, ":", self.cursor) orelse return null;
            while (self.cursor < colon) {
                if (text[self.cursor] == '<') {
                    if (syntax.protectedEnd(text, self.cursor)) |end| {
                        self.cursor = end;
                        continue;
                    }
                    if (syntax.tagAt(text, self.cursor)) |tag| {
                        if (normalizableHtmlTag(tag.name) or oneOf(tag.name, &.{ "table", "tr", "td", "th", "caption" })) {
                            if (tag.closing) {
                                self.html_depth -|= 1;
                            } else {
                                // A slash does not close a non-void HTML container.
                                self.html_depth += 1;
                            }
                        }
                        self.cursor = tag.end;
                        continue;
                    }
                }
                if (starts(text[self.cursor..], "[[") or starts(text[self.cursor..], "{{")) {
                    if (syntax.balanced(text, self.cursor)) |pair| {
                        self.cursor = pair.end;
                        continue;
                    }
                }
                self.cursor += 1;
            }
            self.cursor = colon + 1;
            // A link-label opener can scope later text beyond the link itself.
            // Advance through it once; rejecting a link's colon must not reset depth.
            if (self.html_depth == 0 and colon >= after) return colon;
        }
        return null;
    }
};
pub fn inlineDefinitionSplit(text: []const u8) ?struct { term: []const u8, definition: []const u8 } {
    var scanner: DefinitionColonScanner = .{ .input = text };
    var colon = scanner.next(0) orelse return null;
    // Links become anchors before MediaWiki's definition-list pass. Reuse the
    // accepted bracketed/free-link extents without changing template delimiters.
    var tokens: ir.InlineIterator = .{ .input = text };
    while (true) {
        const before = tokens.cursor;
        const token = tokens.next() orelse break;
        if (tokens.cursor <= before) break;
        if (tokens.cursor <= colon) continue;
        if (token.kind == .external_link and before <= colon) {
            colon = scanner.next(tokens.cursor) orelse return null;
            continue;
        }
        break;
    }
    const term = std.mem.trim(u8, text[0..colon], " \t");
    const definition = std.mem.trim(u8, text[colon + 1 ..], " \t");
    return .{ .term = term, .definition = definition };
}
fn oneOf(name: []const u8, names: []const []const u8) bool {
    for (names) |n| if (std.ascii.eqlIgnoreCase(name, n)) return true;
    return false;
}

fn adoptionFormattingTag(name: []const u8) bool {
    return oneOf(name, &.{ "b", "big", "code", "em", "font", "i", "s", "small", "strike", "strong", "tt", "u" });
}

fn normalizableHtmlTag(name: []const u8) bool {
    return oneOf(name, &.{
        "b",    "strong", "i",    "em",   "u",    "s",   "del",        "strike", "ins",  "sup",  "sub",  "small",
        "big",  "span",   "font", "code", "tt",   "kbd", "samp",       "var",    "cite", "dfn",  "abbr", "q",
        "time", "mark",   "bdi",  "bdo",  "ruby", "rb",  "rt",         "rtc",    "rp",   "data", "h1",   "h2",
        "h3",   "h4",     "h5",   "h6",   "div",  "p",   "blockquote", "center", "ul",   "ol",   "li",   "dl",
        "dt",   "dd",
    });
}

// Recognition is earned once from the complete ordinary source token. The
// immutable borrowed proof survives only within one normalization/emission call.
const ReopenedExternalParent = struct {
    source: MissingText,
    start: usize,
    end: usize,
    target: []const u8,
    fn init(source: MissingText, start: usize, end: usize, target: []const u8) ?ReopenedExternalParent {
        if (!ordinaryNormalizationRange(source, start, end) or
            !ir.bracketedAngleProtocolTarget(source.bytes[start..end], target)) return null;
        return .{ .source = source, .start = start, .end = end, .target = target };
    }
    fn borrowedOriginal(self: ReopenedExternalParent) ?[]const u8 {
        if (!ordinaryNormalizationRange(self.source, self.start, self.end)) return null;
        const original = self.source.bytes[self.start..self.end];
        if (original.len < 3 or original[0] != '[' or original[original.len - 1] != ']' or
            self.target.len == 0 or self.target.len >= original.len - 1 or
            self.target.ptr != original[1..].ptr) return null;
        return original;
    }
};
const ReopenedExternalLink = struct {
    start: usize,
    label_start: usize,
    end: usize,
    parent: ReopenedExternalParent,
    fn lessThan(_: void, lhs: ReopenedExternalLink, rhs: ReopenedExternalLink) bool {
        return lhs.start < rhs.start;
    }
};
const ReopenedExternalDomain = struct {
    source: []const u8,
    // Sorted once after normalization, before this immutable domain is exposed.
    links: []const ReopenedExternalLink,
    parent: ?*const ReopenedExternalDomain,
};
fn reopenedExternalLowerBound(links: []const ReopenedExternalLink, at: usize) usize {
    var first: usize = 0;
    var last = links.len;
    while (first < last) {
        const middle = first + (last - first) / 2;
        if (links[middle].start < at) first = middle + 1 else last = middle;
    }
    return first;
}
fn ordinaryNormalizationRange(source: MissingText, start: usize, end: usize) bool {
    if (source.unknown or start >= end or end > source.bytes.len) return false;
    for (source.ranges) |range| if (range.start < end and range.end > start) return false;
    for (source.literal_curly_ranges) |range| if (range.start < end and range.end > start) return false;
    for (source.generated_links) |range| if (range.start < end and range.end > start) return false;
    return true;
}
fn recordReopenedExternal(a: A, links: ?*std.ArrayList(ReopenedExternalLink), frame: HtmlNormalizationFrame, end: usize) Error!void {
    const sink = links orelse return;
    const parent = frame.angle_parent orelse return;
    if (!frame.repair_generated) return;
    try sink.append(a, .{ .start = frame.output_start, .label_start = frame.label_output_start, .end = end, .parent = parent });
}

const HtmlNormalizationFrame = struct {
    name: []const u8,
    opener: []const u8,
    formatting: bool,
    external_close_at: ?usize = null,
    label_output_start: usize = 0,
    repair_generated: bool = false,
    output_start: usize = 0,
    angle_parent: ?ReopenedExternalParent = null,
};
const HtmlNormalizationToken = struct { frame: HtmlNormalizationFrame, closing: bool, end: usize };
const max_html_normalization_frames = max_depth * 4;

// External links are parsed after quotes upstream. Their brackets therefore
// participate in formatting repair, while authored HTML anchors remain literal.
fn htmlNormalizationToken(input: []const u8, at: usize, recognize_external_links: bool) ?HtmlNormalizationToken {
    if (recognize_external_links and input[at] == ']') return .{ .frame = .{ .name = "!external", .opener = "", .formatting = true }, .closing = true, .end = at + 1 };
    if (recognize_external_links and input[at] == '[') {
        if (at + 1 >= input.len or input[at + 1] == '[' or !ir.hasExternalProtocol(input[at + 1 ..])) return null;
        var iterator: ir.InlineIterator = .{ .input = input[at..], .renderer_boundaries = true };
        const token = iterator.next() orelse return null;
        if (token.kind != .external_link) return null;
        const target_end = @intFromPtr(token.target.ptr) - @intFromPtr(input.ptr) + token.target.len;
        return .{ .frame = .{ .name = "!external", .opener = input[at..target_end], .formatting = true, .external_close_at = at + iterator.cursor - 1 }, .closing = false, .end = target_end };
    }
    const tag = syntax.tagAt(input, at) orelse return null;
    if (!normalizableHtmlTag(tag.name) or tag.self_closing) return null;
    return .{ .frame = .{ .name = tag.name, .opener = input[at..tag.end], .formatting = adoptionFormattingTag(tag.name) }, .closing = tag.closing, .end = tag.end };
}
fn htmlNormalizationMatch(frames: []const HtmlNormalizationFrame, token: HtmlNormalizationToken, at: usize) ?usize {
    var index = frames.len;
    while (index != 0) {
        index -= 1;
        if (std.ascii.eqlIgnoreCase(frames[index].name, token.frame.name)) {
            if (frames[index].external_close_at) |close_at| {
                if (close_at != at) continue;
            }
            return index;
        }
    }
    return null;
}
fn hasMisnestedHtml(input: []const u8, depth: usize, recognize_external_links: bool) bool {
    var no_more_nowiki_close = false;
    var opaque_scan: syntax.OpaqueScan = .{};
    if (depth >= max_depth) return false;
    const boundaries = QuoteBoundaries.init(input);
    if (std.mem.indexOfScalar(u8, input, '<') == null) return false;
    var frames: [max_html_normalization_frames]HtmlNormalizationFrame = undefined;
    var frame_count: usize = 0;
    var pos: usize = 0;
    while (std.mem.indexOfAnyPos(u8, input, pos, "<[]")) |at| {
        if (input[at] == '<') if (opaque_scan.protectedEnd(input, at, &no_more_nowiki_close)) |end| {
            pos = end;
            continue;
        };
        if (starts(input[at..], "[[") and !ir.doubleOpeningExternalToken(input, at)) {
            if (boundaries.canClose(input, at)) if (syntax.balancedWithOpaqueScan(input, at, &opaque_scan)) |pair| {
                const inner = input[at + 2 .. pair.inner_end];
                if (syntax.delimiter(inner, "|", 0)) |pipe| {
                    if (hasMisnestedHtml(inner[pipe + 1 ..], depth + 1, false)) return true;
                }
                pos = pair.end;
                continue;
            };
            pos = at + 2;
            continue;
        }
        if (input[at] == '<') if (opaque_scan.tagAt(input, at, &no_more_nowiki_close)) |tag| {
            if (!normalizableHtmlTag(tag.name) or tag.self_closing) {
                pos = tag.end;
                continue;
            }
        };
        const token = htmlNormalizationToken(input, at, recognize_external_links) orelse {
            pos = at + 1;
            continue;
        };
        pos = token.end;
        if (!token.closing) {
            if (frame_count == frames.len) return false;
            frames[frame_count] = token.frame;
            frame_count += 1;
        } else if (htmlNormalizationMatch(frames[0..frame_count], token, at)) |index| {
            if (index + 1 != frame_count) return true;
            frame_count = index;
        }
    }
    return false;
}
fn appendHtmlFrameClose(a: A, out: *std.ArrayList(u8), frame: HtmlNormalizationFrame) Error!void {
    if (frame.external_close_at != null) {
        // Only an empty repair-generated fragment needs a transparent label.
        if (std.mem.trim(u8, out.items[frame.label_output_start..], " \t\r\n").len == 0)
            try out.appendSlice(a, "<span></span>");
        return out.append(a, ']');
    }
    try out.appendSlice(a, "</");
    try out.appendSlice(a, frame.name);
    try out.append(a, '>');
}
fn normalizeMisnestedHtml(a: A, input: []const u8) Error![]const u8 {
    return normalizeMisnestedHtmlDepth(a, input, 0, true);
}
fn normalizeMisnestedHtmlDepth(a: A, input: []const u8, depth: usize, recognize_external_links: bool) Error![]const u8 {
    var no_more_nowiki_close = false;
    var opaque_scan: syntax.OpaqueScan = .{};
    if (!hasMisnestedHtml(input, depth, recognize_external_links)) return input;
    const boundaries = QuoteBoundaries.init(input);
    var out: std.ArrayList(u8) = .empty;
    var frames: [max_html_normalization_frames]HtmlNormalizationFrame = undefined;
    var frame_count: usize = 0;
    var pos: usize = 0;
    while (std.mem.indexOfAnyPos(u8, input, pos, "<[]")) |at| {
        try out.appendSlice(a, input[pos..at]);
        if (input[at] == '<') if (opaque_scan.protectedEnd(input, at, &no_more_nowiki_close)) |end| {
            try out.appendSlice(a, input[at..end]);
            pos = end;
            continue;
        };
        if (starts(input[at..], "[[") and !ir.doubleOpeningExternalToken(input, at)) {
            if (boundaries.canClose(input, at)) if (syntax.balancedWithOpaqueScan(input, at, &opaque_scan)) |pair| {
                const inner = input[at + 2 .. pair.inner_end];
                if (syntax.delimiter(inner, "|", 0)) |pipe| {
                    try out.appendSlice(a, input[at .. at + 2 + pipe + 1]);
                    try out.appendSlice(a, try normalizeMisnestedHtmlDepth(a, inner[pipe + 1 ..], depth + 1, false));
                    try out.appendSlice(a, "]]");
                } else try out.appendSlice(a, input[at..pair.end]);
                pos = pair.end;
                continue;
            };
            try out.appendSlice(a, input[at .. at + 2]);
            pos = at + 2;
            continue;
        }
        if (input[at] == '<') if (opaque_scan.tagAt(input, at, &no_more_nowiki_close)) |tag| {
            if (!normalizableHtmlTag(tag.name) or tag.self_closing) {
                try out.appendSlice(a, input[at..tag.end]);
                pos = tag.end;
                continue;
            }
        };
        const token = htmlNormalizationToken(input, at, recognize_external_links) orelse {
            try out.append(a, input[at]);
            pos = at + 1;
            continue;
        };
        const raw = input[at..token.end];
        if (!token.closing) {
            try out.appendSlice(a, raw);
            if (frame_count == frames.len) return input;
            var frame = token.frame;
            if (frame.external_close_at != null) frame.label_output_start = out.items.len;
            frames[frame_count] = frame;
            frame_count += 1;
            pos = token.end;
            continue;
        }
        const index = htmlNormalizationMatch(frames[0..frame_count], token, at) orelse {
            try out.appendSlice(a, raw);
            pos = token.end;
            continue;
        };
        const above = frames[index + 1 .. frame_count];
        var close_index = above.len;
        while (close_index != 0) {
            close_index -= 1;
            try appendHtmlFrameClose(a, &out, above[close_index]);
        }
        const closed = frames[index];
        if (closed.external_close_at != null and closed.repair_generated and
            std.mem.trim(u8, out.items[closed.label_output_start..], " \t\r\n").len == 0)
            try out.appendSlice(a, "<span></span>");
        try out.appendSlice(a, raw);
        var retained: [max_html_normalization_frames]HtmlNormalizationFrame = undefined;
        var retained_len: usize = 0;
        for (above) |frame| if (frame.formatting) {
            retained[retained_len] = frame;
            retained_len += 1;
        };
        frame_count = index;
        for (retained[0..retained_len]) |frame| {
            try out.appendSlice(a, frame.opener);
            var reopened = frame;
            if (frame.external_close_at != null) {
                try out.append(a, ' ');
                reopened.label_output_start = out.items.len;
                reopened.repair_generated = true;
            }
            frames[frame_count] = reopened;
            frame_count += 1;
        }
        pos = token.end;
    }
    try out.appendSlice(a, input[pos..]);
    return out.toOwnedSlice(a);
}

fn appendHtmlFrameCloseMissing(a: A, out: *missing_dependency.Builder, frame: HtmlNormalizationFrame, links: ?*std.ArrayList(ReopenedExternalLink)) Error!void {
    if (frame.external_close_at != null) {
        if (std.mem.trim(u8, out.bytes.items[frame.label_output_start..], " \t\r\n").len == 0)
            try out.append(a, MissingText.untracked("<span></span>"));
        try out.append(a, MissingText.untracked("]"));
        return recordReopenedExternal(a, links, frame, out.bytes.items.len);
    }
    try out.append(a, MissingText.untracked("</"));
    try out.append(a, MissingText.untracked(frame.name));
    try out.append(a, MissingText.untracked(">"));
}
fn normalizeMisnestedHtmlWithMissing(a: A, source: MissingText, depth: usize, recognize_external_links: bool) Error!MissingText {
    return normalizeMisnestedHtmlWithReopened(a, source, depth, recognize_external_links, null);
}
fn normalizeMisnestedHtmlWithReopened(a: A, source: MissingText, depth: usize, recognize_external_links: bool, links: ?*std.ArrayList(ReopenedExternalLink)) Error!MissingText {
    const input = source.bytes;
    var no_more_nowiki_close = false;
    var opaque_scan: syntax.OpaqueScan = .{};
    if (!hasMisnestedHtml(input, depth, recognize_external_links)) return source;
    const boundaries = QuoteBoundaries.init(input);
    var out: missing_dependency.Builder = .{};
    var frames: [max_html_normalization_frames]HtmlNormalizationFrame = undefined;
    var frame_count: usize = 0;
    var pos: usize = 0;
    while (std.mem.indexOfAnyPos(u8, input, pos, "<[]")) |at| {
        try out.appendSlice(a, source, pos, at);
        if (input[at] == '<') if (opaque_scan.protectedEnd(input, at, &no_more_nowiki_close)) |end| {
            try out.appendSlice(a, source, at, end);
            pos = end;
            continue;
        };
        if (starts(input[at..], "[[") and !ir.doubleOpeningExternalToken(input, at)) {
            if (boundaries.canClose(input, at)) if (syntax.balancedWithOpaqueScan(input, at, &opaque_scan)) |pair| {
                const inner = input[at + 2 .. pair.inner_end];
                if (syntax.delimiter(inner, "|", 0)) |pipe| {
                    try out.appendSlice(a, source, at, at + 2 + pipe + 1);
                    try out.append(a, try normalizeMisnestedHtmlWithMissing(a, try missing_dependency.slice(a, source, at + 2 + pipe + 1, pair.inner_end), depth + 1, false));
                    try out.appendSlice(a, source, pair.inner_end, pair.end);
                } else try out.appendSlice(a, source, at, pair.end);
                pos = pair.end;
                continue;
            };
            try out.appendSlice(a, source, at, at + 2);
            pos = at + 2;
            continue;
        }
        if (input[at] == '<') if (opaque_scan.tagAt(input, at, &no_more_nowiki_close)) |tag| {
            if (!normalizableHtmlTag(tag.name) or tag.self_closing) {
                try out.appendSlice(a, source, at, tag.end);
                pos = tag.end;
                continue;
            }
        };
        const token = htmlNormalizationToken(input, at, recognize_external_links) orelse {
            try out.appendSlice(a, source, at, at + 1);
            pos = at + 1;
            continue;
        };
        if (!token.closing) {
            const output_start = out.bytes.items.len;
            try out.appendSlice(a, source, at, token.end);
            if (frame_count == frames.len) {
                if (links) |sink| sink.clearRetainingCapacity();
                return source;
            }
            var frame = token.frame;
            frame.output_start = output_start;
            if (frame.external_close_at) |close_at| {
                frame.label_output_start = out.bytes.items.len;
                const target = input[at + 1 .. token.end];
                if (links != null) frame.angle_parent = ReopenedExternalParent.init(source, at, close_at + 1, target);
            }
            frames[frame_count] = frame;
            frame_count += 1;
            pos = token.end;
            continue;
        }
        const index = htmlNormalizationMatch(frames[0..frame_count], token, at) orelse {
            try out.appendSlice(a, source, at, token.end);
            pos = token.end;
            continue;
        };
        const above = frames[index + 1 .. frame_count];
        var close_index = above.len;
        while (close_index != 0) {
            close_index -= 1;
            try appendHtmlFrameCloseMissing(a, &out, above[close_index], links);
        }
        const closed = frames[index];
        if (closed.external_close_at != null and closed.repair_generated and
            std.mem.trim(u8, out.bytes.items[closed.label_output_start..], " \t\r\n").len == 0)
            try out.append(a, MissingText.untracked("<span></span>"));
        try out.appendSlice(a, source, at, token.end);
        if (closed.external_close_at != null) try recordReopenedExternal(a, links, closed, out.bytes.items.len);
        var retained: [max_html_normalization_frames]HtmlNormalizationFrame = undefined;
        var retained_len: usize = 0;
        for (above) |frame| if (frame.formatting) {
            retained[retained_len] = frame;
            retained_len += 1;
        };
        frame_count = index;
        for (retained[0..retained_len]) |frame| {
            const output_start = out.bytes.items.len;
            try out.append(a, try missingSlice(a, source, frame.opener));
            var reopened = frame;
            reopened.output_start = output_start;
            if (frame.external_close_at != null) {
                try out.append(a, MissingText.untracked(" "));
                reopened.label_output_start = out.bytes.items.len;
                reopened.repair_generated = true;
            }
            frames[frame_count] = reopened;
            frame_count += 1;
        }
        pos = token.end;
    }
    try out.appendSlice(a, source, pos, input.len);
    if (links) |sink| std.mem.sort(ReopenedExternalLink, sink.items, {}, ReopenedExternalLink.lessThan);
    return out.finish(a);
}
inline fn referenceStringEqual(a: []const u8, b: []const u8) bool {
    if (a.len != b.len) return false;
    if (a.len == 0) return true;
    if (a.len < 4) {
        const middle = a.len / 2;
        return ((a[0] ^ b[0]) | (a[a.len - 1] ^ b[b.len - 1]) | (a[middle] ^ b[middle])) == 0;
    }
    if (a.len <= 8) {
        return std.mem.readInt(u32, a[0..4], .little) == std.mem.readInt(u32, b[0..4], .little) and
            std.mem.readInt(u32, a[a.len - 4 ..][0..4], .little) == std.mem.readInt(u32, b[b.len - 4 ..][0..4], .little);
    }
    if (a.len <= 16) {
        return std.mem.readInt(u64, a[0..8], .little) == std.mem.readInt(u64, b[0..8], .little) and
            std.mem.readInt(u64, a[a.len - 8 ..][0..8], .little) == std.mem.readInt(u64, b[b.len - 8 ..][0..8], .little);
    }
    return std.mem.eql(u8, a, b);
}

fn pipeTrickLabel(target: []const u8) []const u8 {
    // MediaWiki's pre-save pipe trick is intentionally syntactic: the first
    // colon prefix is removed even when it is not a registered namespace. It
    // does not apply to section/anchor links.
    if (std.mem.indexOfScalar(u8, target, '#') != null) return target;
    var label = target;
    if (std.mem.indexOfScalar(u8, label, ':')) |colon| label = std.mem.trimStart(u8, label[colon + 1 ..], " \t");
    if (label.len != 0 and label[label.len - 1] == ')') {
        if (std.mem.lastIndexOf(u8, label, " (")) |paren| label = label[0..paren];
    } else if (std.mem.indexOf(u8, label, ", ")) |comma| {
        label = label[0..comma];
    }
    return label;
}

// Action destinations are semantic data, never a deferred template input.
// Inspect decoded targets only; percent-encoded braces and single braces stay literal.
pub fn unresolvedActionTarget(target: []const u8) bool {
    return std.mem.indexOf(u8, target, "{{") != null or std.mem.indexOf(u8, target, "}}") != null;
}

// Closing braces alone are literal URL characters in MediaWiki. Opening
// template markers remain forbidden, and non-URL action targets stay strict.
pub fn unresolvedExternalActionTarget(target: []const u8) bool {
    return std.mem.indexOf(u8, target, "{{") != null or
        (std.mem.indexOf(u8, target, "}}") != null and !safeUrl(target));
}

pub fn safeUrl(url: []const u8) bool {
    if (!ir.validExternalUrl(url)) return false;
    for (url) |ch| if (ch <= 32 or ch == 127) return false;
    return true;
}

const MagicLinkKind = enum { rfc, pmid, isbn };
const MagicLink = struct {
    kind: MagicLinkKind,
    end: usize,
    text: []const u8,
    payload: []const u8,
};

fn magicSpace(ch: u8) bool {
    return ch == ' ' or ch == '\t';
}

// MediaWiki Parser::SPACE_NOT_NL, on authored source. Do not decode arbitrary
// entities here: encoded prefixes and double-encoded spaces remain literal.
fn isbnSpaceLen(input: []const u8) usize {
    if (input.len == 0) return 0;
    if (magicSpace(input[0])) return 1;
    if (std.mem.startsWith(u8, input, "&nbsp;")) return 6;
    if (std.mem.startsWith(u8, input, "&#")) {
        var pos: usize = 2;
        const hex = pos < input.len and (input[pos] == 'x' or input[pos] == 'X');
        if (hex) pos += 1;
        while (pos < input.len and input[pos] == '0') : (pos += 1) {}
        if (hex) {
            if (pos + 3 <= input.len and (input[pos] == 'a' or input[pos] == 'A') and
                input[pos + 1] == '0' and input[pos + 2] == ';') return pos + 3;
        } else if (std.mem.startsWith(u8, input[pos..], "160;")) return pos + 4;
        return 0;
    }
    if (input[0] < 0x80) return 0;
    const len = std.unicode.utf8ByteSequenceLength(input[0]) catch return 0;
    if (len > input.len) return 0;
    const cp = std.unicode.utf8Decode(input[0..len]) catch return 0;
    return if (cp == 0xa0 or cp == 0x1680 or (cp >= 0x2000 and cp <= 0x200a) or
        cp == 0x202f or cp == 0x205f or cp == 0x3000) len else 0;
}

fn isbnDelimiterLen(input: []const u8) usize {
    return if (input.len != 0 and input[0] == '-') 1 else isbnSpaceLen(input);
}

// The optional second slice starts at an entity boundary in ordinary text.
// Matching this view avoids copying or decoding the unconsumed page suffix.
const MagicSource = struct {
    first: []const u8,
    tail: []const u8 = "",

    fn remaining(self: MagicSource, pos: usize) []const u8 {
        return if (pos < self.first.len) self.first[pos..] else self.tail[pos - self.first.len ..];
    }
    fn byte(self: MagicSource, pos: usize) ?u8 {
        const rest = self.remaining(pos);
        return if (rest.len == 0) null else rest[0];
    }
    fn boundaryAfter(self: MagicSource, pos: usize) bool {
        return if (pos < self.first.len)
            ir.linkBoundaryAfter(self.first, pos)
        else
            ir.linkBoundaryAfter(self.tail, pos - self.first.len);
    }
};

const MagicMatch = struct { kind: MagicLinkKind, end: usize, payload_start: usize };

fn isbnPayloadEnd(input: MagicSource, start: usize, thirteen: bool) ?usize {
    var pos = start;
    if (thirteen) {
        const rest = input.remaining(pos);
        if (!std.mem.startsWith(u8, rest, "978") and !std.mem.startsWith(u8, rest, "979")) return null;
        pos += 3;
        pos += isbnDelimiterLen(input.remaining(pos));
    }
    for (0..9) |_| {
        const ch = input.byte(pos) orelse return null;
        if (!std.ascii.isDigit(ch)) return null;
        pos += 1;
        pos += isbnDelimiterLen(input.remaining(pos));
    }
    const check = input.byte(pos) orelse return null;
    if (!std.ascii.isDigit(check) and check != 'X' and check != 'x') return null;
    pos += 1;
    return if (input.boundaryAfter(pos)) pos else null;
}

fn magicMatchAt(input: MagicSource, start: usize) ?MagicMatch {
    if (!ir.linkBoundaryBefore(input.first, start)) return null;
    const Prefix = struct { kind: MagicLinkKind, len: usize };
    const prefix: Prefix = if (std.mem.startsWith(u8, input.first[start..], "RFC"))
        .{ .kind = .rfc, .len = 3 }
    else if (std.mem.startsWith(u8, input.first[start..], "PMID"))
        .{ .kind = .pmid, .len = 4 }
    else if (std.mem.startsWith(u8, input.first[start..], "ISBN"))
        .{ .kind = .isbn, .len = 4 }
    else
        return null;

    var pos = start + prefix.len;
    const spaces_start = pos;
    while (true) {
        const rest = input.remaining(pos);
        const len = if (prefix.kind == .isbn)
            isbnSpaceLen(rest)
        else if (rest.len != 0 and magicSpace(rest[0]))
            @as(usize, 1)
        else
            0;
        if (len == 0) break;
        pos += len;
    }
    if (pos == spaces_start) return null;
    const payload_start = pos;
    if (prefix.kind == .rfc or prefix.kind == .pmid) {
        while (input.byte(pos)) |ch| {
            if (!std.ascii.isDigit(ch)) break;
            pos += 1;
        }
        if (pos == payload_start or !input.boundaryAfter(pos)) return null;
        return .{ .kind = prefix.kind, .end = pos, .payload_start = payload_start };
    }
    // The upstream optional 97[89] prefix is greedy, but may backtrack to the
    // ten-digit alternative. Each digit position allows only one delimiter.
    const end = isbnPayloadEnd(input, payload_start, true) orelse
        isbnPayloadEnd(input, payload_start, false) orelse return null;
    return .{ .kind = .isbn, .end = end, .payload_start = payload_start };
}

fn magicLinkAt(input: []const u8, start: usize) ?MagicLink {
    const matched = magicMatchAt(.{ .first = input }, start) orelse return null;
    return .{
        .kind = matched.kind,
        .end = matched.end,
        .text = input[start..matched.end],
        .payload = input[matched.payload_start..matched.end],
    };
}

fn isbnCandidateStart(value: []const u8) ?usize {
    var cursor: usize = 0;
    while (std.mem.indexOfPos(u8, value, cursor, "ISBN")) |at| {
        const after = at + 4;
        if (ir.linkBoundaryBefore(value, at) and
            (after == value.len or isbnSpaceLen(value[after..]) != 0)) return at;
        cursor = after;
    }
    return null;
}

fn magicLinkStart(input: []const u8, start: usize) ?usize {
    var pos = start;
    while (pos < input.len) {
        const relative = std.mem.indexOfAny(u8, input[pos..], "RPI") orelse return null;
        pos += relative;
        if (magicLinkAt(input, pos) != null) return pos;
        pos += 1;
    }
    return null;
}
// Strip only complete active comments before decoding title entities. Keep
// protected bodies intact. Ordinary attribute quotes do not protect comments.
fn internalTargetWithoutCommentsAlloc(a: A, value: []const u8) ![]const u8 {
    if (std.mem.indexOf(u8, value, "<!--") == null) return value;
    var result: std.ArrayList(u8) = .empty;
    errdefer result.deinit(a);
    var scan: syntax.OpaqueScan = .{};
    var cursor: usize = 0;
    var copied: usize = 0;
    var changed = false;
    while (cursor < value.len) {
        if (starts(value[cursor..], "<!--")) {
            const close = std.mem.indexOfPos(u8, value, cursor + 4, "-->") orelse break;
            try result.appendSlice(a, value[copied..cursor]);
            cursor = close + 3;
            copied = cursor;
            changed = true;
            continue;
        }
        if (scan.protectedEnd(value, cursor, null)) |end| {
            cursor = end;
            continue;
        }
        if (scan.tagAt(value, cursor, null)) |tag| {
            cursor = tag.end;
            continue;
        }
        cursor += 1;
    }
    if (!changed) {
        result.deinit(a);
        return value;
    }
    try result.appendSlice(a, value[copied..]);
    return try result.toOwnedSlice(a);
}

fn internalTargetHasNowikiRegion(target: []const u8) bool {
    var cursor: usize = 0;
    var no_more_close = false;
    while (std.mem.indexOfScalarPos(u8, target, cursor, '<')) |open| {
        if (syntax.nowikiRegionAtCached(target, open, &no_more_close) != null) return true;
        cursor = open + 1;
    }
    return false;
}

// The tokenizer normalizes target edges. Recover only authored final ASCII
// spaces for an unpiped visible label; never change the canonical target or
// treat tabs/entities/invalid title source as a newly supported label grammar.
fn unpipedLinkLabelSpaces(input: []const u8, token: ir.InlineSpan, end: usize) []const u8 {
    if (token.link_has_pipe or end > input.len or end < token.trail.len + 2) return "";
    const input_at = @intFromPtr(input.ptr);
    const target_at = @intFromPtr(token.target.ptr);
    if (target_at < input_at or target_at - input_at > input.len) return "";
    const offset = target_at - input_at;
    if (token.target.len > input.len - offset) return "";
    const first = offset + token.target.len;
    const last = end - token.trail.len - 2;
    if (first > last or !std.mem.eql(u8, input[last .. last + 2], "]]")) return "";
    const suffix = input[first..last];
    for (suffix) |ch| if (ch != ' ') return "";
    return suffix;
}

// Source syntax eligibility precedes literal invalid-title body recovery.
// Replacement characters may render there but never grant navigation authority.
fn internalTargetSyntaxAllowed(target: []const u8, comptime allow_replacement: bool) bool {
    var has_non_ascii = false;
    for (target) |ch| {
        if (ch < 32 or ch == 127 or std.mem.indexOfScalar(u8, "[]{}", ch) != null) return false;
        has_non_ascii = has_non_ascii or ch >= 128;
    }
    if (!has_non_ascii) return true;
    if (!std.unicode.utf8ValidateSlice(target)) return false;
    var view = std.unicode.Utf8View.initUnchecked(target);
    var it = view.iterator();
    while (it.nextCodepoint()) |cp| if ((cp >= 0x80 and cp <= 0x9f) or (!allow_replacement and cp == 0xfffd)) return false;
    return true;
}
// Match the renderer's earlier label-only recovery before considering a
// rejected target's complete visible body during citation preparation.
fn internalTargetHasMissingOccurrence(source: MissingText, target: []const u8) bool {
    const base = @intFromPtr(source.bytes.ptr);
    const at = @intFromPtr(target.ptr);
    if (at < base or at - base > source.bytes.len or target.len > source.bytes.len - (at - base)) return false;
    const first = at - base;
    const last = first + target.len;
    for (source.ranges) |occurrence| if (occurrence.start >= first and occurrence.end <= last) return true;
    return false;
}
fn safeInternalTarget(target: []const u8) bool {
    return internalTargetSyntaxAllowed(target, false);
}
fn internalTargetNeedsLiteralBody(target: []const u8) bool {
    return std.mem.indexOfAny(u8, target, "<>") != null or
        std.mem.indexOf(u8, target, "\u{fffd}") != null;
}
test "safe internal target ASCII fast path preserves Unicode and control checks" {
    try std.testing.expect(safeInternalTarget("cat#section"));
    try std.testing.expect(safeInternalTarget("caf\xc3\xa9"));
    try std.testing.expect(safeInternalTarget("cat \xf0\x9f\x90\x88"));
    try std.testing.expect(!safeInternalTarget("cat\x7f"));
    try std.testing.expect(!safeInternalTarget("cat\xc2\x85"));
    try std.testing.expect(!safeInternalTarget("cat\xff"));
    try std.testing.expect(!safeInternalTarget("antiquit\u{fffd}"));
    try std.testing.expect(!safeInternalTarget("Good#\u{fffd}"));
    try std.testing.expect(safeInternalTarget("Tom''s"));
    try std.testing.expect(!safeInternalTarget("[[taking]]"));
    try std.testing.expect(!safeInternalTarget("{{{7}}}"));
    try std.testing.expect(!safeInternalTarget("taking#x[y]"));
}

/// The caller uses an arena for a page; returned arrays/text share its lifetime.
pub fn unclosedFragmentTraceEnabled(value: ?[]const u8) !bool {
    const raw = value orelse return false;
    if (std.mem.eql(u8, raw, "0")) return false;
    if (std.mem.eql(u8, raw, "1")) return true;
    return error.InvalidUnclosedFragmentTrace;
}
fn boundedTraceHex(buffer: []u8, bytes: []const u8) []const u8 {
    const count = @min(bytes.len, buffer.len / 2);
    const digits = "0123456789abcdef";
    for (bytes[0..count], 0..) |byte, i| {
        buffer[2 * i] = digits[byte >> 4];
        buffer[2 * i + 1] = digits[byte & 15];
    }
    return buffer[0 .. count * 2];
}

/// Preserve only the first active page-body TOC boundary before owner regrouping.
/// Returns input when unchanged; otherwise the caller owns the allocated slice.
/// Reference/list bodies retain the existing deferred-reference policy, not Cite parity.
// Resolve this before behavior-switch removal and before language-owner slicing.
// Unknown capture state is distinct from an explicit page-global suppression.
pub fn pageContentConversion(a: A, input: []const u8, context: Context) Error!?bool {
    if (context.content_conversion) |enabled| return enabled;
    const namespaces = context.namespace_catalog orelse return null;
    _ = namespaces.language_conversion orelse return null;
    const registry = context.behavior_switches orelse return null;
    var scan: usize = 0;
    var no_more_nowiki_close = false;
    var opaque_scan: syntax.OpaqueScan = .{};
    while (scan < input.len) {
        if (input[scan] == '<') {
            const tag = opaque_scan.tagAt(input, scan, &no_more_nowiki_close);
            if (opaque_scan.protectedEnd(input, scan, &no_more_nowiki_close)) |end| {
                scan = end;
                continue;
            }
            if (tag) |opening| {
                scan = if (opening.is("includeonly") and !opening.closing and !opening.self_closing)
                    if (syntax.matchingTag(input, opening)) |pair| pair.end else input.len
                else
                    opening.end;
                continue;
            }
        }
        if (try registry.noContentConvertMatchAt(a, input, scan)) |end| {
            if ((try registry.matchAt(a, input, scan)) == end) return false;
        }
        scan += 1;
    }
    return true;
}

pub fn preparePageTocSourceAlloc(a: A, input: []const u8, registry: ?*const @import("namespace_registry").behavior_switches.Registry) Error![]const u8 {
    return (try preparePageTocSourceWithMissingAlloc(a, MissingText.untracked(input), registry)).bytes;
}
pub fn preparePageTocSourceWithMissingAlloc(a: A, source: MissingText, registry: ?*const @import("namespace_registry").behavior_switches.Registry) Error!MissingText {
    const input = source.bytes;
    var out: missing_dependency.Builder = .{};
    errdefer out.deinit(a);
    var emitted: usize = 0;
    var scan: usize = 0;
    var first_toc = false;
    // Track the copied output line once, so TOC elision cannot create or
    // extend an earlier-phase horizontal-rule prefix.
    var hyphen_line = true;
    var no_more_nowiki_close = false;
    var opaque_scan: syntax.OpaqueScan = .{};
    while (scan < input.len) {
        if (input[scan] == '<') {
            const tag = opaque_scan.tagAt(input, scan, &no_more_nowiki_close);
            if (opaque_scan.protectedEnd(input, scan, &no_more_nowiki_close)) |end| {
                scan = end;
                continue;
            }
            if (tag) |opening| {
                // Hidden includeonly bodies cannot consume the page's first TOC.
                // Match the renderer's complete, self-closing and unclosed scopes.
                scan = if (opening.is("includeonly") and !opening.closing and !opening.self_closing)
                    if (syntax.matchingTag(input, opening)) |pair| pair.end else input.len
                else
                    opening.end;
                continue;
            }
        }
        const matched = if (registry) |captured| try captured.matchAt(a, input, scan) else syntax.behaviorSwitchEnd(input, scan);
        if (matched) |end| {
            const toc_end = if (registry) |captured| try captured.tocMatchAt(a, input, scan) else if (std.ascii.eqlIgnoreCase(input[scan..end], "__TOC__")) end else null;
            if (toc_end != null and toc_end.? == end) {
                if (first_toc) {
                    const copied = input[emitted..scan];
                    try out.appendSlice(a, source, emitted, scan);
                    for (copied) |ch| {
                        if (ch == '\n') hyphen_line = true else if (ch != '-') hyphen_line = false;
                    }
                    emitted = end;
                    if (hyphen_line and end < input.len and input[end] == '-') {
                        // Preserve this existing suffix byte without joining it
                        // to an authored hyphen run across the removed control.
                        try out.append(a, missingEdit(source, end, end + 1, "&#45;"));
                        emitted = end + 1;
                        hyphen_line = false;
                    }
                } else first_toc = true;
            }
            scan = @max(end, emitted);
        } else scan += 1;
    }
    if (emitted == 0) return source;
    try out.appendSlice(a, source, emitted, input.len);
    return try out.finish(a);
}

// Build-only preparation. Numeric labels are resolved before language-owner
// regrouping, while the original Poem transport and its authenticated items stay
// immutable. All returned strings/overlays belong to the supplied page allocator.
const MissingBuffer = struct {
    builder: missing_dependency.Builder = .{},
    items: []const u8 = &.{},
    const empty: @This() = .{};
    fn append(self: *@This(), a: A, byte: u8) Error!void {
        try self.builder.append(a, MissingText.untracked(&.{byte}));
        self.items = self.builder.bytes.items;
    }
    fn appendCopied(self: *@This(), a: A, parent: MissingText, bytes: []const u8) Error!void {
        try self.builder.append(a, try missingSlice(a, parent, bytes));
        self.items = self.builder.bytes.items;
    }
    fn view(self: *const @This()) MissingText {
        return .{ .bytes = self.items, .ranges = self.builder.ranges.items, .literal_curly_ranges = self.builder.literal_curly_ranges.items, .generated_links = self.builder.generated_links.items, .generated_source = if (self.builder.generated_links.items.len == 0) null else self.items, .unknown = self.builder.unknown, .lost_missing_range = self.builder.lost_missing_range };
    }
    fn take(self: *@This(), a: A) Error!MissingText {
        const value = try self.builder.finish(a);
        self.* = .empty;
        return value;
    }
    fn deinit(self: *@This(), a: A) void {
        self.builder.deinit(a);
        self.* = .empty;
    }
};

// Issued only by the existing complete-root numbering pass when its sole
// changes are validated ordinary numeric labels, never arbitrary replacements.
pub const ClassScopeSourceTransition = struct { original: []const u8, prepared: []const u8 };
// Coordinates issued by the page preparation operation, not DOM authority.
// The ranges and their backing source live in the supplied page allocator.
pub const SourceElementProjection = struct {
    pub const Copy = struct { original_start: usize, prepared_start: usize, len: usize };
    original: MissingText,
    prepared: []const u8,
    copies: []const Copy,

    pub fn originalRange(self: *const @This(), start: usize, len: usize) ?usize {
        if (start > self.prepared.len or len > self.prepared.len - start) return null;
        for (self.copies) |copy| {
            if (copy.prepared_start > self.prepared.len or copy.len > self.prepared.len - copy.prepared_start or
                copy.original_start > self.original.bytes.len or copy.len > self.original.bytes.len - copy.original_start) return null;
            if (start < copy.prepared_start or start - copy.prepared_start > copy.len or len > copy.len - (start - copy.prepared_start)) continue;
            const original_start = copy.original_start + start - copy.prepared_start;
            if (!std.mem.eql(u8, self.prepared[start..][0..len], self.original.bytes[original_start..][0..len])) return null;
            if (self.original.lost_missing_range or self.original.generated_source != null or
                !ordinaryNormalizationRange(self.original, original_start, original_start + len)) return null;
            return original_start;
        }
        return null;
    }

    pub fn preparedRange(self: *const @This(), start: usize, len: usize) ?usize {
        if (start > self.original.bytes.len or len > self.original.bytes.len - start) return null;
        for (self.copies) |copy| {
            if (start < copy.original_start or start - copy.original_start > copy.len or len > copy.len - (start - copy.original_start)) continue;
            const prepared_start = copy.prepared_start + start - copy.original_start;
            if (self.originalRange(prepared_start, len) == start) return prepared_start;
        }
        return null;
    }

    fn compose(a: A, first: @This(), second: @This()) Error!?@This() {
        if (first.prepared.ptr != second.original.bytes.ptr or first.prepared.len != second.original.bytes.len) return null;
        var copies: std.ArrayList(Copy) = .empty;
        errdefer copies.deinit(a);
        for (second.copies) |next| for (first.copies) |previous| {
            const start = @max(next.original_start, previous.prepared_start);
            const end = @min(next.original_start + next.len, previous.prepared_start + previous.len);
            if (start >= end) continue;
            try copies.append(a, .{ .original_start = previous.original_start + start - previous.prepared_start,
                .prepared_start = next.prepared_start + start - next.original_start, .len = end - start });
        };
        return .{ .original = first.original, .prepared = second.prepared, .copies = try copies.toOwnedSlice(a) };
    }
};

// Document binds this view only after its normal parser-output range checks.
// It cannot expose the original page's ancestor-class inventory.
pub const SourceElementBinding = struct {
    scope: *const table_style_profile.BoundedTextClassScope,
    projection: *const SourceElementProjection,
    owner: MissingText,
    page_start: usize,

    fn ownerOffset(self: @This(), part: []const u8) ?usize {
        const first = @intFromPtr(self.owner.bytes.ptr);
        const pointer = @intFromPtr(part.ptr);
        if (pointer < first or pointer - first > self.owner.bytes.len or part.len > self.owner.bytes.len - (pointer - first)) return null;
        const start = pointer - first;
        if (self.page_start > self.projection.prepared.len or self.owner.bytes.len > self.projection.prepared.len - self.page_start or
            !std.mem.eql(u8, part, self.projection.prepared[self.page_start + start..][0..part.len]) or
            self.owner.lost_missing_range or self.owner.generated_source != null or
            !ordinaryNormalizationRange(self.owner, start, start + part.len)) return null;
        return start;
    }

    fn originalRange(self: @This(), part: []const u8) ?usize {
        const start = self.ownerOffset(part) orelse return null;
        return self.projection.originalRange(self.page_start + start, part.len);
    }

    fn ownerRange(self: @This(), original_start: usize, len: usize) ?[]const u8 {
        const prepared_start = self.projection.preparedRange(original_start, len) orelse return null;
        if (prepared_start < self.page_start or prepared_start - self.page_start > self.owner.bytes.len or
            len > self.owner.bytes.len - (prepared_start - self.page_start)) return null;
        const part = self.owner.bytes[prepared_start - self.page_start..][0..len];
        if (self.originalRange(part) != original_start) return null;
        return part;
    }
};

pub const PreparedExternalLinks = struct {
    source_element_projection: ?SourceElementProjection = null,
    class_scope_transition: ?ClassScopeSourceTransition = null,
    fallbacks: @import("presentation_fallback.zig").Report = .{},
    content_conversion: ?bool = null,
    citations: ?*const CitationPlan = null,
    source: []const u8,
    missing: MissingText,
    poem_phase: ?*const PoemPhase,
};
const PageExternalNumbering = struct {
    const Phase = enum { extensions, interlanguage, media, ordinary };
    const Edit = struct { start: usize, end: usize, value: []const u8, tracked: ?MissingText = null, numbered_label_only: bool = false, citation_attribute_only: bool = false };
    a: A,
    renderer: Renderer,
    phase: ?*const PoemPhase,
    number: usize = 0,
    edits: std.ArrayList(Edit) = .empty,
    seen_references: std.ArrayList(usize) = .empty,
    seen_reference_sites: std.ArrayList(usize) = .empty,
    seen_extensions: std.ArrayList(usize) = .empty,
    seen_poem: []bool,
    citations: ?*CitationPlan = null,
    collecting_citations: bool = false,
    root_missing: MissingText = MissingText.untracked(""),
    numbered_batches: std.ArrayList(usize) = .empty,
    tracked_domains: std.ArrayList(MissingText) = .empty,
    native_domain_depth: usize = 0,

    fn containsFolded(bytes: []const u8, needle: []const u8) bool {
        if (needle.len > bytes.len) return false;
        for (0..bytes.len - needle.len + 1) |at| if (std.ascii.eqlIgnoreCase(bytes[at..][0..needle.len], needle)) return true;
        return false;
    }
    fn citationPossible(source: []const u8) bool {
        // Entity-bearing attributes can expose tags only after their own decode.
        // Keep those conservative positives; plain no-ref pages need no collector.
        return containsFolded(source, "<ref") or std.mem.indexOfScalar(u8, source, '&') != null;
    }
    fn citationPossibleInContext(source: []const u8, context: Context) bool {
        if (citationPossible(source)) return true;
        if (context.poem_phase) |phase| for (phase.items, 0..) |item, index| {
            if (item.body) |body_value| if (citationPossible(body_value)) return true;
            if (index < phase.numbered_bodies.len) if (phase.numbered_bodies[index]) |body_value| if (citationPossible(body_value)) return true;
        };
        for (context.citation_definitions) |definition| if (citationPossible(definition.body)) return true;
        return false;
    }
    fn collisionDomains(renderer: *Renderer, domains: *std.ArrayList([]const u8), source: []const u8) Error!void {
        try domains.append(renderer.a, source);
        const controlled = try renderer.withoutBehaviorControls(source);
        try domains.append(renderer.a, controlled);
        const decoded = try renderer.entityText(controlled);
        try domains.append(renderer.a, decoded);
        // Media title destinations decode percent escapes after entity decoding.
        try domains.append(renderer.a, std.Uri.percentDecodeInPlace(try renderer.a.dupe(u8, decoded)));
        // Visible text accepts longer numeric references than attribute fields.
        var visible: std.ArrayList(u8) = .empty;
        var at: usize = 0;
        while (at < controlled.len) {
            var scratch: [4]u8 = undefined;
            if (controlled[at] == '&') if (Renderer.decodeEntity(controlled[at..], &scratch, true)) |entity_value| {
                try visible.appendSlice(renderer.a, entity_value.bytes);
                at += entity_value.consumed;
                continue;
            };
            try visible.append(renderer.a, controlled[at]);
            at += 1;
        }
        try domains.append(renderer.a, visible.items);
    }
    fn citationAttributeAlloc(a: A, root: []const u8, context: Context) Error![]const u8 {
        var scratch = std.heap.ArenaAllocator.init(a);
        defer scratch.deinit();
        var renderer: Renderer = .{ .a = scratch.allocator(), .context = context };
        var domains: std.ArrayList([]const u8) = .empty;
        try collisionDomains(&renderer, &domains, root);
        if (context.poem_phase) |phase| for (phase.items, 0..) |item, index| {
            if (item.body) |body_value| try collisionDomains(&renderer, &domains, body_value);
            if (index < phase.numbered_bodies.len) if (phase.numbered_bodies[index]) |body_value| try collisionDomains(&renderer, &domains, body_value);
        };
        for (context.citation_definitions) |definition| try collisionDomains(&renderer, &domains, definition.body);
        var serial: usize = 0;
        while (true) : (serial += 1) {
            const candidate = try std.fmt.allocPrint(a, "data-wikidict-cite-{d}", .{serial});
            var collision = false;
            for (domains.items) |domain_value| collision = collision or containsFolded(domain_value, candidate);
            if (!collision) return candidate;
            a.free(candidate);
        }
    }
    // Keep exact whole-domain identity while retaining the existing metadata
    // validation and allocation-error contract. A full copy may deliberately
    // decline excessive ordinary ranges; preserve that result rather than
    // restoring the original evidence after its limit was exceeded.
    fn wholeTrackedCitationBody(self: *@This(), source: MissingText) Error!MissingText {
        const checked = try missingSlice(self.a, source, source.bytes);
        if (checked.bytes.ptr == source.bytes.ptr) return checked;
        if (checked.unknown != source.unknown or checked.ranges.len != source.ranges.len or
            checked.literal_curly_ranges.len != source.literal_curly_ranges.len or
            checked.generated_links.len != source.generated_links.len) return checked;
        // Full-slice validation retained every channel. Only this exact parent,
        // never an equal-byte or detached value, supplies its original identity.
        self.a.free(checked.bytes);
        self.a.free(checked.ranges);
        self.a.free(checked.literal_curly_ranges);
        self.a.free(checked.generated_links);
        return source;
    }
    fn trackedCitationBody(self: *@This(), body_text: []const u8) Error!MissingText {
        // Generated projection/control domains retain their exact tracked slices.
        // Native originals have no source-range manifest and remain explicitly unknown.
        const pointer = @intFromPtr(body_text.ptr);
        var index = self.tracked_domains.items.len;
        while (index != 0) {
            index -= 1;
            const source = self.tracked_domains.items[index];
            const begin = @intFromPtr(source.bytes.ptr);
            if (pointer >= begin and pointer - begin <= source.bytes.len and body_text.len <= source.bytes.len - (pointer - begin)) {
                if (pointer == begin and body_text.len == source.bytes.len)
                    return self.wholeTrackedCitationBody(source);
                return missingSlice(self.a, source, body_text);
            }
        }
        if (body_text.ptr == self.root_missing.bytes.ptr and body_text.len == self.root_missing.bytes.len)
            return self.wholeTrackedCitationBody(self.root_missing);
        return missingSlice(self.a, self.root_missing, body_text);
    }
    fn capturedCitationBody(self: *@This(), body_text: []const u8) Error!MissingText {
        const value = try self.trackedCitationBody(body_text);
        var closing: usize = 0;
        var at: usize = 0;
        while (std.mem.indexOfPos(u8, body_text, at, native_poem_prefix)) |found| {
            const item = self.renderer.poemItemAt(body_text[found..]) orelse {
                at = found + native_poem_prefix.len;
                continue;
            };
            at = found + item.token.len;
            if (item.kind != .indent) continue;
            const generated_tag = syntax.tagAt(body_text, at) orelse continue;
            if (!generated_tag.is("span") or generated_tag.closing or generated_tag.self_closing) continue;
            if (syntax.matchingTag(body_text, generated_tag) == null) closing += 1;
        }
        if (closing == 0) return value;
        var out: missing_dependency.Builder = .{};
        defer out.deinit(self.a);
        try out.append(self.a, value);
        for (0..closing) |_| try out.append(self.a, MissingText.untracked("</span>"));
        return out.finish(self.a);
    }
    fn annotateCitation(self: *@This(), input: []const u8, tag: syntax.Tag, event: usize) Error!void {
        // An authored dangling assignment must not consume our generated
        // attribute as its value. Tag normalization keeps the original name
        // slice, so insert before all authored attributes without rewriting them.
        const first = @intFromPtr(input.ptr);
        const name = @intFromPtr(tag.name.ptr);
        if (tag.closing or tag.name.len == 0 or name < first or name - first > input.len or
            tag.name.len > input.len - (name - first) or tag.end > input.len) return error.InvalidPreContext;
        const end = name - first + tag.name.len;
        if (end >= tag.end) return error.InvalidPreContext;
        const attribute_text = try std.fmt.allocPrint(self.a, " {s}=\"{d}\"", .{ self.citations.?.attribute, event });
        try self.replace(input, end, end, attribute_text);
        const position = self.address(input, end);
        for (self.edits.items) |*edit| if (edit.start == position and edit.end == position and
            edit.tracked == null and std.mem.eql(u8, edit.value, attribute_text)) {
            edit.citation_attribute_only = true;
            break;
        };
    }
    fn citationEvent(self: *@This(), tag: syntax.Tag) Error!citation_state.Event {
        const plan = self.citations orelse return error.InvalidPreContext;
        const raw = tag.attr(plan.attribute) orelse return error.InvalidPreContext;
        const index = std.fmt.parseInt(usize, raw, 10) catch return error.InvalidPreContext;
        if (index >= plan.events.items.len) return error.InvalidPreContext;
        const event = plan.events.items[index];
        if (!tag.is(switch (event.tag) {
            .ref => "ref",
            .references => "references",
            .poem => "poem",
        })) return error.InvalidPreContext;
        return event;
    }
    fn citationReference(self: *@This(), input: []const u8, at: usize, tag: syntax.Tag, body_text: ?[]const u8, depth: usize) Error!void {
        const site = self.address(input, at);
        for (self.seen_reference_sites.items) |prior| if (prior == site) return;
        try self.seen_reference_sites.append(self.a, site);
        if (!self.collecting_citations) {
            const event = try self.citationEvent(tag);
            // Missing-list footers retain the established first-ref schedule.
            // Explicit footers remain attached to their references occurrence.
            if (event.item) |item_id| {
                const plan = self.citations.?;
                for (plan.final_batches.items) |batch_index| {
                    if (batch_index >= plan.batches.items.len) return error.InvalidPreContext;
                    for (plan.batches.items[batch_index].items) |id| if (id == item_id) {
                        try self.citationFooter(batch_index, depth + 1);
                        return;
                    };
                }
            }
            return;
        }
        const name = (try self.renderer.semanticAttribute(tag, "name")) orelse "";
        const group = (try self.renderer.semanticAttribute(tag, "group")) orelse "";
        const follow = (try self.renderer.semanticAttribute(tag, "follow")) orelse "";
        const body_value = if (body_text) |value| try self.capturedCitationBody(value) else null;
        const event = self.citations.?.reference(self.a, name, group, follow, body_value) catch |err| switch (err) {
            error.InvalidAuthoredCitation => try self.citations.?.invalidReference(self.a),
            else => |remaining| return remaining,
        };
        try self.annotateCitation(input, tag, event);
    }
    fn citationListDefinitions(self: *@This(), input: []const u8, default_group: []const u8, depth: usize) Error!bool {
        if (depth > max_depth) return error.RenderLimit;
        var authored_error = false;
        var scan: syntax.OpaqueScan = .{};
        var at: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input, at, '<')) |open| {
            if (starts(input[open..], "<!--")) {
                at = scan.protectedEnd(input, open, null) orelse input.len;
                continue;
            }
            const tag = try self.renderer.semanticTagAt(input, open) orelse {
                at = open + 1;
                continue;
            };
            at = tag.end;
            if (tag.closing) continue;
            if (tag.is("includeonly")) {
                at = if (syntax.matchingTag(input, tag)) |pair| pair.end else input.len;
                continue;
            }
            const pair = scan.pair(input, tag) orelse continue;
            at = pair.end;
            if (!tag.is("ref")) {
                if (!tag.isOpaque() and !tag.is("includeonly")) {
                    const nested_error = try self.citationListDefinitions(input[tag.end..pair.inner_end], default_group, depth + 1);
                    authored_error = authored_error or nested_error;
                }
                continue;
            }
            if (self.citations.?.definition_events >= self.citations.?.limit) return error.RenderLimit;
            const name = (try self.renderer.semanticAttribute(tag, "name")) orelse "";
            const own_group = (try self.renderer.semanticAttribute(tag, "group")) orelse "";
            const group = if (own_group.len != 0) own_group else default_group;
            const body_value = if (tag.self_closing) null else try self.capturedCitationBody(input[tag.end..pair.inner_end]);
            const follow = (try self.renderer.semanticAttribute(tag, "follow")) orelse "";
            const validation = if (follow.len != 0)
                self.citations.?.rejectListDefinition()
            else
                self.citations.?.listDefinition(self.a, name, group, body_value);
            validation catch |err| switch (err) {
                error.InvalidAuthoredCitation => authored_error = true,
                else => |remaining| return remaining,
            };
        }
        return authored_error;
    }
    fn citationReferences(self: *@This(), input: []const u8, at: usize, tag: syntax.Tag, body_text: ?[]const u8, depth: usize) Error!void {
        const site = self.address(input, at);
        for (self.seen_reference_sites.items) |prior| if (prior == site) return;
        try self.seen_reference_sites.append(self.a, site);
        if (self.collecting_citations) {
            const group = (try self.renderer.semanticAttribute(tag, "group")) orelse "";
            const authored_error = if (body_text) |value| try self.citationListDefinitions(value, group, depth + 1) else false;
            const event = try self.citations.?.references(self.a, group);
            self.citations.?.events.items[event].authored_error = authored_error;
            try self.annotateCitation(input, tag, event);
        } else {
            const event = try self.citationEvent(tag);
            try self.citationFooter(event.batch orelse return error.InvalidPreContext, depth + 1);
        }
    }
    fn citationFooter(self: *@This(), batch_index: usize, depth: usize) Error!void {
        if (depth > max_depth) return error.RenderLimit;
        for (self.numbered_batches.items) |prior| if (prior == batch_index) return;
        try self.numbered_batches.append(self.a, batch_index);
        const plan = self.citations.?;
        if (batch_index >= plan.batches.items.len) return error.InvalidPreContext;
        const batch = plan.batches.items[batch_index];
        // Reused invalid-input recovery bodies already carry their earlier URL
        // labels. Replace only the old prefix, retaining this epoch's follow tail.
        for (batch.items) |item_id| {
            const item = &plan.items.items[item_id];
            if (item.recovery) |recovery_id| if (plan.recoveries.items[recovery_id].body) |recovered| {
                const body_value = item.body orelse return error.InvalidPreContext;
                if (item.recovery_prefix_len > body_value.bytes.len) return error.InvalidPreContext;
                var joined: missing_dependency.Builder = .{};
                defer joined.deinit(self.a);
                try joined.append(self.a, recovered);
                try joined.appendSlice(self.a, body_value, item.recovery_prefix_len, body_value.bytes.len);
                item.body = try joined.finish(self.a);
                item.recovery_prefix_len = recovered.bytes.len;
            };
        }
        // Controls are prepared once per joined body, before ANY footer phase.
        for (batch.recoveries) |id| if (plan.recoveries.items[id].body) |value| {
            plan.recoveries.items[id].body = try self.renderer.externalSourceControlsWithMissing(value);
        };
        for (batch.items) |id| if (plan.items.items[id].body) |value| {
            plan.items.items[id].body = try self.renderer.externalSourceControlsWithMissing(value);
        };
        // One parser domain across the whole footer, not one domain per item.
        // Null-ordinal unused-definition recovery retains existing product policy.
        for ([_]Phase{ .extensions, .interlanguage, .media, .ordinary }) |phase_kind| {
            for (batch.recoveries) |id| if (plan.recoveries.items[id].body) |value|
                try self.walk(value.bytes, phase_kind, true, true, depth + 1);
            for (batch.items) |id| if (plan.items.items[id].body) |value|
                try self.walk(value.bytes, phase_kind, true, true, depth + 1);
        }
        for (batch.recoveries) |id| if (plan.recoveries.items[id].body) |value| {
            plan.recoveries.items[id].body = try self.applyWithMissing(value);
        };
        for (batch.items) |id| if (plan.items.items[id].body) |value| {
            plan.items.items[id].body = try self.applyWithMissing(value);
        };
    }
    fn rawPoem(self: *@This(), input: []const u8, tag: syntax.Tag, content: []const u8, in_reference: bool, depth: usize) Error!void {
        if (self.renderer.poem_authored_token or self.renderer.poemHasUnregisteredItem(content)) return;
        if (!self.collecting_citations or self.native_domain_depth != 0) {
            if (!self.collecting_citations and tag.attr(self.citations.?.attribute) != null) _ = try self.citationEvent(tag);
            try self.domain(content, in_reference, depth + 1);
            return;
        }
        const plan = self.citations.?;
        const first_event = plan.events.items.len;
        const first_item = self.renderer.poem_items.items.len;
        const projected = try self.renderer.poemProjectionWithMissing(try self.trackedCitationBody(content));
        try self.tracked_domains.append(self.a, projected);
        try self.domain(projected.bytes, in_reference, depth + 1);
        if (plan.events.items.len == first_event) {
            // This scope contributes no citation state; preserve its original path.
            // Nested no-citation scopes likewise add no persistent registry entries.
            self.renderer.poem_items.shrinkRetainingCapacity(first_item);
            return;
        }
        for (self.renderer.poem_items.items[first_item..]) |item| {
            var found = false;
            for (plan.local_poem_items.items) |prior| if (std.mem.eql(u8, prior.token, item.token)) {
                found = true;
                break;
            };
            if (!found) try plan.local_poem_items.append(self.a, .{
                .token = item.token,
                .kind = @fromBackingInt(@intCast(@backingInt(item.kind))),
                .indent = item.indent,
                .tag = item.tag,
                .body = item.body,
            });
        }
        const event = try plan.preparedPoem(self.a);
        try self.annotateCitation(input, tag, event);
        try self.replaceTracked(content, 0, content.len, try self.applyWithMissing(projected));
    }
    fn body(self: *@This(), index: usize) []const u8 {
        const phase = self.phase.?;
        if (index < phase.numbered_bodies.len) if (phase.numbered_bodies[index]) |value| return value;
        return phase.items[index].body orelse "";
    }
    // Reference definitions borrowed by the existing Renderer can point into
    // its owned Poem copies. Translate only those exact byte ranges back to the
    // immutable phase body that will receive the corresponding preparation.
    fn address(self: *@This(), input: []const u8, offset: usize) usize {
        const pointer = @intFromPtr(input.ptr);
        if (self.phase != null and input.len != 0) for (self.renderer.poem_items.items, 0..) |item, index| {
            if (index >= self.phase.?.items.len) break;
            const begin = @intFromPtr(item.body.ptr);
            if (pointer >= begin and pointer < begin + item.body.len and input.len <= begin + item.body.len - pointer)
                return @intFromPtr(self.body(index).ptr) + pointer - begin + offset;
        };
        return pointer + offset;
    }
    fn enclosed(first: usize, last: usize, edit: Edit) bool {
        return if (edit.start == edit.end) edit.start >= first and edit.start < last else edit.start >= first and edit.end <= last;
    }
    fn replace(self: *@This(), input: []const u8, start: usize, end: usize, value: []const u8) Error!void {
        if (start > end or end > input.len or self.edits.items.len >= max_nodes) return error.RenderLimit;
        const first = self.address(input, start);
        const last = self.address(input, end);
        var index: usize = 0;
        while (index < self.edits.items.len) {
            const edit = self.edits.items[index];
            if (edit.start == first and edit.end == last) return;
            if (first != last and enclosed(first, last, edit)) {
                _ = self.edits.swapRemove(index);
                continue;
            }
            if (edit.start != edit.end and (if (first == last) first >= edit.start and first < edit.end else first < edit.end and last > edit.start))
                return error.InvalidPreContext;
            index += 1;
        }
        try self.edits.append(self.a, .{ .start = first, .end = last, .value = value });
    }
    fn replaceTracked(self: *@This(), input: []const u8, start: usize, end: usize, value: MissingText) Error!void {
        try self.replace(input, start, end, value.bytes);
        const first = self.address(input, start);
        const last = self.address(input, end);
        for (self.edits.items) |*edit| if (edit.start == first and edit.end == last) {
            edit.tracked = value;
            return;
        };
        return error.InvalidPreContext;
    }
    fn sourceElementProjection(self: *const @This(), original: MissingText, source: MissingText, prepared: []const u8) Error!?SourceElementProjection {
        if (!self.renderer.context.observe_source_elements or self.phase != null or
            self.renderer.context.citation_definitions.len != 0 or original.unknown or original.lost_missing_range or
            original.generated_source != null or source.unknown or source.lost_missing_range or source.generated_source != null or
            !std.mem.eql(u8, original.bytes, source.bytes)) return null;
        const begin = @intFromPtr(source.bytes.ptr);
        const end = begin + source.bytes.len;
        var selected: std.ArrayList(Edit) = .empty;
        defer selected.deinit(self.a);
        for (self.edits.items) |edit| {
            if (!enclosed(begin, end, edit) or edit.start != edit.end or edit.tracked != null or
                (!edit.numbered_label_only and !edit.citation_attribute_only)) return null;
            try selected.append(self.a, edit);
        }
        std.mem.sort(Edit, selected.items, {}, struct {
            fn less(_: void, lhs: Edit, rhs: Edit) bool { return lhs.start < rhs.start; }
        }.less);
        var copies: std.ArrayList(SourceElementProjection.Copy) = .empty;
        defer copies.deinit(self.a);
        var original_at: usize = 0;
        var prepared_at: usize = 0;
        for (selected.items) |edit| {
            const start = edit.start - begin;
            if (start < original_at) return null;
            const len = start - original_at;
            if (prepared_at > prepared.len or len > prepared.len - prepared_at or
                !std.mem.eql(u8, source.bytes[original_at..start], prepared[prepared_at..][0..len])) return null;
            if (len != 0) try copies.append(self.a, .{ .original_start = original_at, .prepared_start = prepared_at, .len = len });
            prepared_at += len;
            if (edit.value.len > prepared.len - prepared_at or !std.mem.eql(u8, edit.value, prepared[prepared_at..][0..edit.value.len])) return null;
            prepared_at += edit.value.len;
            original_at = start;
        }
        const len = source.bytes.len - original_at;
        if (prepared_at > prepared.len or len != prepared.len - prepared_at or
            !std.mem.eql(u8, source.bytes[original_at..], prepared[prepared_at..])) return null;
        if (len != 0) try copies.append(self.a, .{ .original_start = original_at, .prepared_start = prepared_at, .len = len });
        return .{ .original = original, .prepared = prepared, .copies = try copies.toOwnedSlice(self.a) };
    }
    fn classScopeTransition(self: *const @This(), original: MissingText, source: MissingText, prepared: []const u8) ?ClassScopeSourceTransition {
        if (self.collecting_citations or self.citations != null or self.phase != null or
            self.renderer.context.citation_definitions.len != 0 or !std.mem.eql(u8, original.bytes, source.bytes) or
            original.unknown or original.lost_missing_range or original.ranges.len != 0 or
            original.literal_curly_ranges.len != 0 or original.generated_links.len != 0 or source.unknown or source.lost_missing_range or
            source.ranges.len != 0 or source.literal_curly_ranges.len != 0 or source.generated_links.len != 0) return null;
        const begin = @intFromPtr(source.bytes.ptr);
        const end = begin + source.bytes.len;
        for (self.edits.items) |edit| {
            if (!enclosed(begin, end, edit) or edit.start != edit.end or !edit.numbered_label_only or edit.tracked != null) return null;
        }
        return .{ .original = original.bytes, .prepared = prepared };
    }
    fn apply(self: *@This(), input: []const u8) Error![]const u8 {
        return (try self.applyWithMissing(MissingText.untracked(input))).bytes;
    }
    fn applyWithMissing(self: *@This(), source: MissingText) Error!MissingText {
        const input = source.bytes;
        const begin = self.address(input, 0);
        const end = begin + input.len;
        var selected: std.ArrayList(Edit) = .empty;
        defer selected.deinit(self.a);
        for (self.edits.items) |edit| if (enclosed(begin, end, edit))
            try selected.append(self.a, edit);
        if (selected.items.len == 0) return source;
        std.mem.sort(Edit, selected.items, {}, struct {
            fn less(_: void, lhs: Edit, rhs: Edit) bool {
                return lhs.start < rhs.start;
            }
        }.less);
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
