    }
};
pub fn preparePageExternalLinksAlloc(a: A, source: []const u8, context: Context) Error!PreparedExternalLinks {
    return preparePageExternalLinksWithMissingAlloc(a, MissingText.untracked(source), context);
}
pub fn preparePageExternalLinksWithMissingAlloc(a: A, tracked: MissingText, context: Context) Error!PreparedExternalLinks {
    return preparePageExternalLinksModeAlloc(a, tracked, context, true, null);
}
fn preparePageExternalLinksModeAlloc(a: A, tracked: MissingText, context: Context, category_sortkeys: bool, source_renderer: ?*Renderer) Error!PreparedExternalLinks {
    const bound = try bindGeneratedSource(a, tracked, context.poem_phase);
    var category_context = context;
    category_context.content_conversion = try pageContentConversion(a, bound.bytes, context);
    var category_renderer: Renderer = .{ .a = a, .context = category_context };
    const initial_page = category_sortkeys and context.citations == null and !context.external_links_prepared and context.poem_phase == null;
    const multiline_source = if (initial_page) try category_renderer.preparePlainMultilineManualWithMissing(bound) else bound;
    const conversion_source = try category_renderer.prepareUnmatchedManualWithMissing(multiline_source);
    const category_source = if (initial_page)
        try category_renderer.preparePlainCategorySortKeys(conversion_source)
    else
        conversion_source;
    // The matched parser handles physical tables/internal links before external
    // autonumbering. An interrupted internal opener must not hide a later
    // authored bracketed external link from the page's numbering pass.
    var table_renderer: Renderer = .{ .a = a, .context = category_context };
    const opening_renderer = source_renderer orelse &table_renderer;
    // An observing renderer retains the helper's pointer-backed heading aliases.
    // Whole-page Builder callers establish their heading root after preparation.
    const normalized = if (initial_page)
        try opening_renderer.prepareTableInterruptedLinkOpenings(category_source)
    else
        category_source;
    var page_context = context;
    if (normalized.bytes.ptr != bound.bytes.ptr)
        page_context.citation_original_root = context.citation_original_root orelse bound.bytes;
    page_context.content_conversion = try pageContentConversion(a, normalized.bytes, context);
    var result = try preparePageExternalLinksInner(a, normalized, page_context);
    if (result.class_scope_transition) |*proof| {
        if (std.mem.eql(u8, tracked.bytes, bound.bytes) and std.mem.eql(u8, tracked.bytes, multiline_source.bytes) and
            std.mem.eql(u8, tracked.bytes, conversion_source.bytes) and std.mem.eql(u8, tracked.bytes, category_source.bytes) and
            std.mem.eql(u8, tracked.bytes, normalized.bytes) and proof.original.ptr == normalized.bytes.ptr and
            proof.original.len == normalized.bytes.len) proof.original = tracked.bytes else result.class_scope_transition = null;
    }
    if (result.source_element_projection) |*proof| {
        if (std.mem.eql(u8, tracked.bytes, bound.bytes) and std.mem.eql(u8, tracked.bytes, multiline_source.bytes) and
            std.mem.eql(u8, tracked.bytes, conversion_source.bytes) and std.mem.eql(u8, tracked.bytes, category_source.bytes) and
            std.mem.eql(u8, tracked.bytes, normalized.bytes) and proof.original.bytes.ptr == normalized.bytes.ptr and
            proof.original.bytes.len == normalized.bytes.len) {
            proof.original = tracked;
        } else {
            a.free(proof.copies);
            result.source_element_projection = null;
        }
    }
    result.content_conversion = page_context.content_conversion;
    if (initial_page) result.fallbacks.merge(opening_renderer.fallbacks);
    return result;
}
fn preparePageExternalLinksInner(a: A, tracked: MissingText, context: Context) Error!PreparedExternalLinks {
    // A supplied immutable registry belongs to already annotated/numbered input.
    // Owner copies must never append follows or allocate URL labels a second time.
    if (context.citations) |plan| return .{ .source = tracked.bytes, .missing = tracked, .poem_phase = context.poem_phase, .citations = plan };
    if (tracked.ranges.len == 0) if (context.poem_phase) |known| {
        if (known.numbered_source) |root| if (known.numbered_citations) |plan| {
            if (std.mem.eql(u8, tracked.bytes, root) or std.mem.eql(u8, tracked.bytes, known.full_output))
                return .{ .source = root, .missing = MissingText.transformedFrom(tracked, root), .poem_phase = known, .citations = plan };
        };
    };
    const citation_possible = PageExternalNumbering.citationPossibleInContext(tracked.bytes, context);
    const control_can_form_tag = std.mem.indexOfScalar(u8, tracked.bytes, '<') != null and
        (context.behavior_switches != null or std.mem.indexOf(u8, tracked.bytes, "__") != null);
    if (!citation_possible and !control_can_form_tag)
        return preparePageExternalCore(a, tracked, context, false, null);
    // TOC elision can complete a tag name. Resolve that tracked transformation
    // before registering identities, so later owner/body TOC passes are stable.
    const toc_source = try preparePageTocSourceWithMissingAlloc(a, tracked, context.behavior_switches);
    var citation_context = context;
    if (toc_source.bytes.ptr != tracked.bytes.ptr)
        citation_context.citation_original_root = context.citation_original_root orelse tracked.bytes;
    if (!PageExternalNumbering.citationPossibleInContext(toc_source.bytes, citation_context))
        return preparePageExternalCore(a, tracked, context, false, null);
    const plan = try a.create(CitationPlan);
    plan.* = .{ .attribute = try PageExternalNumbering.citationAttributeAlloc(a, toc_source.bytes, citation_context), .limit = max_nodes };
    for (context.citation_definitions) |definition| if (definition.name.len != 0 and definition.body.len != 0) {
        try plan.authority(a, definition.name, definition.group, definition.missing orelse MissingText.transformed(definition.body));
    };
    const collected = try preparePageExternalCore(a, toc_source, citation_context, true, plan);
    defer if (collected.source_element_projection) |proof| a.free(proof.copies);
    if (plan.events.items.len == 0) return preparePageExternalCore(a, tracked, context, false, null);
    try plan.finish(a);
    var numbered_context = citation_context;
    numbered_context.poem_phase = collected.poem_phase;
    numbered_context.citations = plan;
    var result = try preparePageExternalCore(a, collected.missing, numbered_context, false, plan);
    if (result.source_element_projection) |second| {
        defer a.free(second.copies);
        result.source_element_projection = null;
        if (toc_source.bytes.ptr == tracked.bytes.ptr and toc_source.bytes.len == tracked.bytes.len) {
            if (collected.source_element_projection) |first|
                result.source_element_projection = try SourceElementProjection.compose(a, first, second);
        }
    }
    return result;
}
fn preparePageExternalCore(a: A, tracked: MissingText, context: Context, collecting: bool, citations: ?*CitationPlan) Error!PreparedExternalLinks {
    const source = tracked.bytes;
    // Repeated whole-page rendering reuses its already numbered root. Owner
    // subdomains keep that root as definition authority without replacing it.
    if (!collecting and citations == null and tracked.ranges.len == 0) if (context.poem_phase) |known| if (known.numbered_source) |root| {
        if (std.mem.eql(u8, source, root) or std.mem.eql(u8, source, known.full_output))
            return .{ .source = root, .missing = MissingText.transformedFrom(tracked, root), .poem_phase = known };
    };
    var prep: PageExternalNumbering = .{
        .a = a,
        .renderer = .{ .a = a, .context = context },
        .phase = context.poem_phase,
        .citations = citations,
        .collecting_citations = collecting,
        .root_missing = tracked,
        .seen_poem = try a.alloc(bool, if (context.poem_phase) |phase| phase.items.len else 0),
    };
    defer prep.edits.deinit(a);
    defer prep.numbered_batches.deinit(a);
    defer prep.tracked_domains.deinit(a);
    defer prep.seen_references.deinit(a);
    defer prep.seen_reference_sites.deinit(a);
    defer prep.seen_extensions.deinit(a);
    defer a.free(prep.seen_poem);
    @memset(prep.seen_poem, false);
    try prep.renderer.loadPoemPhase();
    // Recollect against the exact prepared domain; native metadata originals
    // remain authentication evidence, not mutable source-rewrite storage.
    prep.renderer.ref_defs.clearRetainingCapacity();
    const controlled = try prep.renderer.externalSourceControlsWithMissing(tracked);
    const input = controlled.bytes;
    prep.root_missing = controlled;
    prep.renderer.poem_definitions_complete = true;
    if (citations == null) {
        try prep.renderer.referenceDefinitions(input, "");
        for (prep.renderer.ref_defs.items) |definition| if (definition.list_defined)
            try prep.reference(@intFromPtr(definition.body.ptr), definition.name, definition.group, definition.body, 0);
    }
    try prep.domain(input, false, 0);
    const prepared_missing = try prep.applyWithMissing(controlled);
    const prepared = prepared_missing.bytes;
    var phase = context.poem_phase;
    if (phase) |original| {
        const bodies = try a.alloc(?[]const u8, original.items.len);
        const body_links = try a.alloc([]const generated_link.Range, original.items.len);
        @memset(body_links, &.{});
        @memset(bodies, null);
        const previous_root = original.numbered_source orelse original.full_output;
        const whole_page = std.mem.eql(u8, source, previous_root) or if (context.citation_original_root) |root|
            std.mem.eql(u8, root, previous_root) or std.mem.eql(u8, root, original.full_output)
        else
            false;
        const prepared_root = if (whole_page) prepared else previous_root;
        // Owner slices may normalize independently, but cannot replace the
        // prepared full-page definition authority with their smaller domain.
        const prepared_plan = if (!collecting and whole_page) citations else original.numbered_citations;
        var changed = whole_page and (!std.mem.eql(u8, prepared_root, previous_root) or prepared_plan != original.numbered_citations or
            (prepared_missing.generated_links.len != 0 and prepared_root.ptr != previous_root.ptr));
        for (original.items, 0..) |item, index| {
            const body = prep.body(index);
            if (item.body == null) continue;
            const bound_body = try bindGeneratedSource(a, MissingText.untracked(body), original);
            const updated = try prep.applyWithMissing(bound_body);
            bodies[index] = if (updated.bytes.ptr != body.ptr) updated.bytes else if (index < original.numbered_bodies.len) original.numbered_bodies[index] else null;
            body_links[index] = updated.generated_links;
            changed = changed or updated.bytes.ptr != body.ptr;
        }
        if (changed) {
            const overlay = try a.create(PoemPhase);
            overlay.* = original.*;
            overlay.numbered_bodies = bodies;
            overlay.numbered_body_links = body_links;
            overlay.numbered_source = if (whole_page) prepared_root else original.numbered_source;
            overlay.numbered_links = if (whole_page) prepared_missing.generated_links else original.numbered_links;
            overlay.numbered_citations = prepared_plan;
            phase = overlay;
        } else { a.free(bodies); a.free(body_links); }
    }
    return .{ .source = prepared, .missing = prepared_missing, .poem_phase = phase, .citations = if (!collecting) citations else null,
        .class_scope_transition = if (std.mem.eql(u8, tracked.bytes, controlled.bytes)) prep.classScopeTransition(tracked, controlled, prepared) else null,
        .source_element_projection = try prep.sourceElementProjection(tracked, controlled, prepared) };
}

const HeadingSourceAlias = struct { copied: []const u8, original: []const u8 };
const HeadingSourceCopy = struct { start: usize, original: []const u8 };
const CitationLocal = struct { plan: *const CitationPlan, indices: []?usize };

const WikiTableTailProof = struct { source: MissingText, completed_close: ?usize = null };

const InlineSourceDomain = struct {
    source: []const u8,
    parent: ?*const InlineSourceDomain,
};

// Selected by the ordinary whole-page producer, never inferred by a fragment.
pub const ContentRoot = enum { unknown, parser_output };

// Issued only from the original page observation through an exact owner range.
pub const RootWikiTableRange = struct {
    page: []const u8,
    start: usize,
    prepared: []const u8,
    openings: []const usize,
    top_level_openings: []const usize = &.{},
};

pub const Renderer = struct {
    const ContainerGeometryRefusal = enum { unresolved_style, relative_context_or_source, column_fragmentation_policy, owner_font_basis, unresolved_block_margins };
    content_root: ContentRoot = .unknown,
    // Document binds this only to a builder-issued original page range. Unknown
    // fragments and new page jobs clear it; no content-root inference occurs.
    source_element_binding: ?SourceElementBinding = null,
    observed_image_map_source: ?struct { owner: []const u8, original: []const u8 } = null,
    bounded_text_class_scope: ?*const table_style_profile.BoundedTextClassScope = null,
    // Only the existing wiki table producer supplies this exact generated tag.
    page_style_wiki_tag: ?syntax.Tag = null,
    quote_class_source: ?*const QuoteClassSource = null,
    // Data-only quote operation map; consumed only for a complete File token.
    figure_caption_quote_source: ?*const QuoteClassSource = null,
    bounded_text_class_source: ?[]const u8 = null,
    // Independently issued selected context; only complete operation ranges may consume it.
    figure_class_source_binding: ?SourceElementBinding = null,
    wiki_cell_class_source: ?WikiCellClassSource = null,
    literal_url_root: ?[]const u8 = null,
    heading_source: ?[]const u8 = null,
    page_root_wiki_table_openings: ?*std.ArrayList(usize) = null,
    page_top_level_wiki_table_openings: ?*std.ArrayList(usize) = null,
    neutral_root_table_prefix: ?NeutralRootTablePrefix = null,
    root_wiki_table_range: ?RootWikiTableRange = null,
    // Enabled only by the full-page heading observation, never by a reader.
    page_html_heading_openings: ?*std.ArrayList(usize) = null,
    page_wiki_heading_openings: ?*std.ArrayList(usize) = null,
    // Other levels under the same complete top-level proof; root boundaries only.
    page_wiki_content_heading_openings: ?*std.ArrayList(usize) = null,
    // Collected only alongside the existing root observer, with identical
    // suppression and borrowed-source guards; the old channel remains H2-only.
    page_wiki_all_heading_openings: ?*std.ArrayList(usize) = null,
    // Only actual transparent rowless recovery may extend the all-level
    // observer into this borrowed slice. The old H2/rule channels stay local.
    wiki_heading_recovery: ?struct { source: []const u8, depth: usize, offset: usize } = null,
    page_wiki_rule_openings: ?*std.ArrayList(usize) = null,
    fallbacks: @import("presentation_fallback.zig").Report = .{},
    a: A,
    context: Context,
    // The exact current parser domain; allocated transformations decline unless
    // their explicit copy builder supplied a new map. Never a pointer registry.
    body_missing: ?MissingText = null,
    inline_missing: ?MissingText = null,
    inline_source_domain: ?*const InlineSourceDomain = null,
    plain_body_source_copy: ?HeadingSourceAlias = null,
    reopened_external_domain: ?*const ReopenedExternalDomain = null,
    // Raw argument instructions never earn ordinary malformed-body provenance.
    in_template_literal_scope: bool = false,
    // Borrowed only while an admitted explicit wiki-link label is parsed.
    // Arbitrary inherited action styles and destination strings cannot set it.
    explicit_wiki_label: ?struct { kind: ir.InlineKind, target: []const u8 } = null,
    heading_source_aliases: std.ArrayList(HeadingSourceAlias) = .empty,
    rendered_templates: usize = 0,
    unresolved_templates: usize = 0,
    // Diagnostic events whose complete bare parameter was already emitted as protected literal.
    protected_bare_parameter_events: usize = 0,
    diagnosed_missing_targets: usize = 0,
    nodes: usize = 0,
    truncated: bool = false,
    span_limit_marker: bool = false,
    block_limit_reached: bool = false,
    body_depth: usize = 0,
    container_child_positions: ?ContainerChildPositions = null,
    container_parent_flex: bool = false,
    // Exact original DIV -> single physical list edge, never inferred from
    // inherited style ancestry or generated block owners.
    display_parent_region: ?DisplayParentRegion = null,
    table_style_scope: table_style_profile.Scope = 0,
    table_css_ancestor_classes: []const u8 = "",
    table_style_unresolved: bool = false,
    table_style_font_unresolved: bool = false,
    // Inline table captures cannot prove a physical boundary at slice byte zero.
    orphan_close_inline_origin: bool = false,
    wiki_table_tail_proof: ?*WikiTableTailProof = null,
    // Build-only reading boundaries for one inline HTML table. Nested tables
    // restore their parent's state; cells/captions are independent domains.
    inline_table_boundaries: ?*InlineTableBoundaries = null,
    parsed_pre: bool = false,
    pre_block: bool = false,
    // An HTML li/dd suppresses implicit paragraphs and leading-space pre.
    html_list_item_flow: bool = false,
    // Only a retained cell body may promote its own mixed text/table flow.
    retained_cell_body_source: ?[]const u8 = null,
    // Exact borrowed opener admitted as the sole visible inline box on its line.
    isolated_inline_table_opening: ?[]const u8 = null,
    typed_table_depth: usize = 0,
    html_blockquote_flow: bool = false,
    pre_scope_observer: ?PreScopeObserver = null,
    body_link_target: []const u8 = "",
    // Only an active structural parent supplies this lexical lang/dir base.
    body_language_direction: ?Style = null,
    // Build-only lexical bidi nesting; never serialized as runtime HTML.
    bidi_scope_depth: usize = 0,
    active_bidi_capture: ?*BidiCapture = null,
    body_formatting_attributes: FormattingAttributes = .{},
    body_paragraph_join: ?*BodyParagraphJoin = null,
    navigation_target_probe: ?*?[]const u8 = null,
    navigation_refused_probe: ?*bool = null,
    link_quote_observation: ?LinkQuoteObservation = null,
    navigation_probe_source: []const u8 = "",
    next_quote_seed: ?QuoteSeed = null,
    unclosed_trace_events: usize = 0,
    rejection_trace_events: usize = 0,
    container_geometry_refusal: ?ContainerGeometryRefusal = null,
    // Separate nonfatal style witness; never consumes fatal rejection capture.
    page_ancestor_effect: ?table_style_profile.PageAncestorEffectBlocker = null,
    checked_page_style_profile: ?*const table_style_profile.Profile = null,
    checked_page_style_root: ?*const table_style_profile.TextElement = null,
    table_style_trace_branch: ?[]const u8 = null,
    rejection_probe_scope: bool = false,
    block_formatting: SpanFlags = .{},
    figure_caption_depth: usize = 0,
    // Typed wiki-list furniture is not represented by HTML TextElement nodes.
    // It can veto an absence proof, never authorize a Figure or CSS match.
    figure_implicit_list_context: bool = false,
    refs: std.ArrayList(Reference) = .empty,
    ref_defs: std.ArrayList(ReferenceDefinition) = .empty,
    // Borrowed build-only page definitions. Unused names never become references.
    page_reference_definitions: []const ReferenceDefinition = &.{},
    default_group_reference_count: usize = 0,
    citation_locals: std.ArrayList(CitationLocal) = .empty,
    citation_poem_plans: std.ArrayList(*const CitationPlan) = .empty,
    media_caption_spans: std.ArrayList([]const Span) = .empty,
    media: std.ArrayList(media_types.Media) = .empty,
    // Newly retained heading references must not displace a later body caption.
    media_heading_only: std.ArrayList(bool) = .empty,
    media_indices: std.StringHashMapUnmanaged(usize) = .empty,
    // Catalog metadata uses the existing per-page item ceiling, not a wire-size cap.
    media_remaining_items: usize = max_nodes,
    media_depth: usize = 0,
    media_action_depth: usize = 0,
    image_block_suppressed: bool = false,
    container_handoff_suppressed: bool = false,
    inline_image_attribute: bool = false,
    spans: std.ArrayList(Span) = .empty,
    in_reference: bool = false,
    semantic_capture: ?*SemanticHints = null,
    // Confined build-only strip items survive quote/HTML normalization and
    // deferred reference bodies. Neither item tokens nor source bodies ship.
    poem_items: std.ArrayList(PoemItem) = .empty,
    poem_phase_loaded: bool = false,
    poem_item_dispatches: usize = 0,
    poem_dispatch_limit: bool = false,
    poem_definition_dispatches: usize = 0,
    poem_definitions_complete: bool = false,
    poem_depth: usize = 0,
    poem_direction: []const u8 = "",
    poem_base_style: Style = .{},
    poem_line_indent: u8 = 0,
    poem_boundary_pending: bool = false,
    poem_authored_token: bool = false,

    const InlineTableBoundaries = struct {
        row_seen: bool = false,
        cell_seen: bool = false,
        caption_seen: bool = false,
        table_background: ?[]const u8 = null,
        row_background: ?[]const u8 = null,
    };

    const poem_prefix = "\x7fWDPOEM:";
    const PoemItem = struct {
        token: []const u8,
        kind: enum { line_break, soft_space, indent, scope, literal },
        indent: u8 = 0,
        tag: []const u8 = "",
        body: []const u8 = "",
    };
    pub fn loadPoemPhase(self: *Renderer) Error!void {
        try self.loadNativePoemPhase();
        const plan = self.context.citations orelse return;
        for (self.citation_poem_plans.items) |prior| if (prior == plan) return;
        for (plan.local_poem_items.items) |item| {
            var found = false;
            for (self.poem_items.items) |prior| if (std.mem.eql(u8, prior.token, item.token)) {
                if (!std.mem.eql(u8, prior.body, item.body) or !std.mem.eql(u8, prior.tag, item.tag) or prior.indent != item.indent or !std.mem.eql(u8, @tagName(prior.kind), @tagName(item.kind))) return error.InvalidPreContext;
                found = true;
                break;
            };
            if (!found) try self.poem_items.append(self.a, .{
                .token = item.token,
                .kind = switch (item.kind) {
                    .line_break => .line_break,
                    .soft_space => .soft_space,
                    .indent => .indent,
                    .scope => .scope,
                    .literal => .literal,
                },
                .indent = item.indent,
                .tag = item.tag,
                .body = item.body,
            });
        }
        try self.citation_poem_plans.append(self.a, plan);
    }
    fn loadNativePoemPhase(self: *Renderer) Error!void {
        if (self.poem_phase_loaded) return;
        self.poem_phase_loaded = true;
        const phase = self.context.poem_phase orelse return;
        if (phase.items.len == 0) return;
        try self.poem_items.ensureTotalCapacity(self.a, phase.items.len);
        for (phase.items, 0..) |item, item_index| {
            self.poem_items.appendAssumeCapacity(.{
                .token = try self.a.dupe(u8, item.token),
                .kind = switch (item.kind) {
                    .br => .line_break,
                    .space => .soft_space,
                    .indent => .indent,
                    .scope => .scope,
                    .literal => .literal,
                },
                .indent = item.depth orelse 0,
                .tag = if (item.tag) |value| try self.a.dupe(u8, value) else "",
                .body = if (item_index < phase.numbered_bodies.len and phase.numbered_bodies[item_index] != null)
                    if (std.mem.indexOf(u8, phase.numbered_bodies[item_index].?, generated_link.prefix) != null) phase.numbered_bodies[item_index].? else try self.a.dupe(u8, phase.numbered_bodies[item_index].?)
                else if (item.body) |value| if (std.mem.indexOf(u8, value, generated_link.prefix) != null) value else try self.a.dupe(u8, value) else "",
            });
        }
        // Follow only emitted page roots, in source order. Authenticated but
        // discarded items and display-title-only definitions remain unused.
        var has_poem = false;
        for (self.poem_items.items) |item| if (item.kind == .literal and std.mem.eql(u8, item.tag, "poem")) {
            has_poem = true;
            break;
        };
        if (has_poem) {
            try self.referenceDefinitionsInner(phase.numbered_source orelse phase.full_output, "", 0, false);
            self.poem_definitions_complete = true;
        }
    }
    fn poemItemAt(self: *Renderer, value: []const u8) ?PoemItem {
        if (!starts(value, poem_prefix)) return null;
        const rest = value[poem_prefix.len..];
        const colon = std.mem.indexOfScalar(u8, rest[0..@min(rest.len, 21)], ':') orelse return null;
        if (colon == 0) return null;
        for (rest[0..colon]) |ch| if (!std.ascii.isDigit(ch)) return null;
        const index = std.fmt.parseInt(usize, rest[0..colon], 10) catch return null;
        if (index < self.poem_items.items.len) {
            const item = self.poem_items.items[index];
            if (starts(value, item.token)) return item;
        }
        // Reused build renderers may retain another plan's generated indices;
        // only an exact registered token identity can dispatch its local item.
        for (self.poem_items.items) |item| if (starts(value, item.token)) return item;
        return null;
    }
    fn poemItemBefore(self: *Renderer, value: []const u8, at: usize) ?PoemItem {
        // Item tokens are under 100 bytes, independent of page/indent size.
        const begin = at -| 100;
        const prefix = std.mem.lastIndexOf(u8, value[begin..at], poem_prefix) orelse return null;
        const item = self.poemItemAt(value[begin + prefix ..]) orelse return null;
        return if (begin + prefix + item.token.len == at) item else null;
    }
    fn poemHasUnregisteredItem(self: *Renderer, input: []const u8) bool {
        var at: usize = 0;
        while (std.mem.indexOfPos(u8, input, at, poem_prefix)) |found| {
            const item = self.poemItemAt(input[found..]) orelse return true;
            at = found + item.token.len;
        }
        return false;
    }
    fn poemToken(self: *Renderer, kind: @FieldType(PoemItem, "kind"), indent: u8, digest: *const [64]u8) Error![]const u8 {
        if (self.poem_items.items.len >= max_nodes) return error.RenderLimit;
        const token = try std.fmt.allocPrint(self.a, "{s}{d}:{s}\x7f", .{ poem_prefix, self.poem_items.items.len, digest });
        try self.poem_items.append(self.a, .{ .token = token, .kind = kind, .indent = indent });
        return token;
    }
    fn poemClasses(self: *Renderer, existing: []const u8, indent: u8) Error![]const u8 {
        var out: std.ArrayList(u8) = .empty;
        var parts = std.mem.tokenizeAny(u8, existing, " \t\r\n\x0b\x0c");
        while (parts.next()) |part| {
            if (std.mem.eql(u8, part, "wikidict-poem") or starts(part, "wikidict-poem-indent") or starts(part, "wikidict-poem-dir")) continue;
            if (out.items.len != 0) try out.append(self.a, ' ');
            try out.appendSlice(self.a, part);
        }
        if (out.items.len != 0) try out.append(self.a, ' ');
        try out.appendSlice(self.a, "wikidict-poem");
        if (indent != 0) try out.appendSlice(self.a, try std.fmt.allocPrint(self.a, " wikidict-poem-indent-{d}", .{indent}));
        if (oneOf(self.poem_direction, &.{ "ltr", "rtl" }))
            try out.appendSlice(self.a, try std.fmt.allocPrint(self.a, " wikidict-poem-dir-{s}", .{self.poem_direction}));
        return out.toOwnedSlice(self.a);
    }
    fn poemCleanField(self: *Renderer, value: []const u8) Error![]const u8 {
        if (self.poem_items.items.len == 0) return value;
        if (std.mem.indexOf(u8, value, poem_prefix) == null) return value;
        var out: std.ArrayList(u8) = .empty;
        var at: usize = 0;
        while (std.mem.indexOfPos(u8, value, at, poem_prefix)) |found| {
            try out.appendSlice(self.a, value[at..found]);
            if (self.poemItemAt(value[found..])) |item| {
                // Only explicit authored text is lexical identity; generated
                // instructions cannot become navigation.
                if (item.kind == .literal and std.mem.eql(u8, item.tag, "text")) {
                    try out.appendSlice(self.a, item.body);
                } else {
                    self.fallbacks.unsupported_element = true;
                    if (item.kind != .indent) try out.append(self.a, ' ');
                }
                at = found + item.token.len;
                if ((item.kind == .line_break or item.kind == .soft_space) and at < value.len and value[at] == '\n') at += 1;
            } else {
                try out.appendSlice(self.a, poem_prefix);
                at = found + poem_prefix.len;
            }
        }
        try out.appendSlice(self.a, value[at..]);
        return out.toOwnedSlice(self.a);
    }
    fn poemProjection(self: *Renderer, input: []const u8) Error![]const u8 {
        return (try self.poemProjectionWithMissing(MissingText.untracked(input))).bytes;
    }
    fn poemProjectionWithMissing(self: *Renderer, source: MissingText) Error!MissingText {
        const input = source.bytes;
        if (std.mem.count(u8, input, "\n") > max_nodes / 2) return error.RenderLimit;
        var hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(input, &hash, .{});
        const digest = std.fmt.bytesToHex(hash, .lower);
        // Stage order is the official handler's raw colon transform, outer-LF
        // trimming/break insertion, then leading ASCII-space entity conversion.
        var colon: missing_dependency.Builder = .{};
        defer colon.deinit(self.a);
        var pos: usize = 0;
        while (pos < input.len) {
            const end = std.mem.indexOfScalarPos(u8, input, pos, '\n') orelse input.len;
            const line = input[pos..end];
            var count: usize = 0;
            while (count < line.len and line[count] == ':') : (count += 1) {}
            if (count != 0 and count < line.len) {
                if (count > 32) self.fallbacks.render_limit = true;
                try colon.append(self.a, MissingText.untracked(try self.poemToken(.indent, @intCast(@min(count, 32)), &digest)));
                // Exact official spelling is retained if a nested protected
                // body later displays the wrapper rather than parsing it.
                try colon.append(self.a, MissingText.untracked(try std.fmt.allocPrint(self.a, "<span class=\"mw-poem-indented\" style=\"display: inline-block; margin-inline-start: {d}em;\">", .{count})));
                try colon.appendSlice(self.a, source, pos + count, end);
                try colon.append(self.a, MissingText.untracked("</span>"));
            } else try colon.appendSlice(self.a, source, pos, end);
            if (end < input.len) try colon.appendSlice(self.a, source, end, end + 1);
            pos = if (end < input.len) end + 1 else end;
        }
        const transformed = try colon.finish(self.a);
        defer self.a.free(transformed.bytes);
        defer self.a.free(transformed.ranges);
        defer self.a.free(transformed.literal_curly_ranges);
        pos = if (starts(transformed.bytes, "\n")) 1 else 0;
        var limit = transformed.bytes.len;
        if (limit > pos and transformed.bytes[limit - 1] == '\n') limit -= 1;
        var out: missing_dependency.Builder = .{};
        defer out.deinit(self.a);
        while (pos < limit) {
            const end = std.mem.indexOfScalarPos(u8, transformed.bytes[0..limit], pos, '\n') orelse limit;
            const line = transformed.bytes[pos..end];
            var spaces: usize = 0;
            while (spaces < line.len and line[spaces] == ' ') : (spaces += 1) {}
            for (0..spaces) |_| try out.append(self.a, MissingText.untracked("&#160;"));
            try out.appendSlice(self.a, transformed, pos + spaces, end);
            if (end < limit) {
                try out.append(self.a, MissingText.untracked(try self.poemToken(if (std.mem.eql(u8, line, "----")) .soft_space else .line_break, 0, &digest)));
                try out.appendSlice(self.a, transformed, end, end + 1);
            }
            pos = if (end < limit) end + 1 else end;
        }
        return out.finish(self.a);
    }
    fn poem(self: *Renderer, input: []const u8, style: Style, depth: usize) Error!void {
        return self.poemWithPhase(input, style, depth, false);
    }
    fn poemWithPhase(self: *Renderer, input: []const u8, style: Style, depth: usize, prepared: bool) Error!void {
        if (self.poem_depth >= max_depth or depth >= max_depth) {
            self.fallbacks.render_limit = true;
            try self.protectedLiteral(input, style);
            return;
        }
        if (self.poem_authored_token or self.poemHasUnregisteredItem(input)) {
            // An authored token-like spelling is never interpreted as an item.
