            token.kind != .external_link or token.external_label_prefix.len != 0 or
            token.target.len != end - at or token.target.ptr != tracked.bytes[at..].ptr or
            token.text.ptr != token.target.ptr or token.text.len != token.target.len) return false;
        const domain = self.inline_source_domain orelse return false;
        if (domain.source.ptr != tracked.bytes.ptr or domain.source.len != tracked.bytes.len) return false;
        for (tracked.ranges) |range| if (range.start < end and range.end > at) return false;
        for (tracked.literal_curly_ranges) |range| if (range.start < end and range.end > at) return false;
        for (tracked.generated_links) |range| if (range.start < end and range.end > at) return false;
        var iterator: ir.InlineIterator = .{ .input = tracked.bytes[at..], .renderer_boundaries = true };
        const parsed = iterator.next() orelse return false;
        if (parsed.kind != .external_link or iterator.cursor != end - at or
            parsed.target.ptr != token.target.ptr or parsed.target.len != token.target.len or
            parsed.text.ptr != parsed.target.ptr or parsed.text.len != parsed.target.len or parsed.external_label_prefix.len != 0) return false;
        return literalDefaultlessExternalParameter(token.target) != null;
    }

    fn externalUrlLabel(self: *Renderer, value: []const u8, style: Style, count_parameters: bool) Error!void {
        const literal_parameters = literalDefaultlessExternalParameter(value);
        if (literalDefaultlessExternalPath(value) != null or literal_parameters != null) {
            if (count_parameters) if (literal_parameters) |count| {
                self.unresolved_templates += count;
                self.fallbacks.missing_template = true;
            };
            // Preserve the authored bare-URL label; only navigation uses the
            // escaped spelling. The shared proof covers every brace below.
            var start: usize = 0;
            while (std.mem.indexOfPos(u8, value, start, "{{{")) |at| {
                const end = (std.mem.indexOfPos(u8, value, at + 3, "}}}") orelse unreachable) + 3;
                try self.text(value[start..at], style);
                try self.protectedLiteral(value[at..end], style);
                start = end;
            }
            try self.text(value[start..], style);
            return;
        }
        // Only the proven closing-brace runs are literal. Keep all surrounding
        // visible text parsed, with the same validated action and style.
        var start: usize = 0;
        while (std.mem.indexOfPos(u8, value, start, "}}")) |at| {
            try self.text(value[start..at], style);
            var end = at + 2;
            while (end < value.len and value[end] == '}') : (end += 1) {}
            var literal_style = style;
            literal_style.provenance = .protected_literal;
            try self.text(value[at..end], literal_style);
            start = end;
        }
        try self.text(value[start..], style);
    }
    pub fn link(self: *Renderer, label: []const u8, target: []const u8, style: Style, depth: usize, external: bool) Error!void {
        return self.linkWithMissing(MissingText.untracked(label), target, style, depth, external);
    }
    pub fn linkWithMissing(self: *Renderer, tracked: MissingText, target: []const u8, style: Style, depth: usize, external: bool) Error!void {
        return self.linkWithMissingParameterProof(tracked, target, style, depth, external, null);
    }
    fn linkWithMissingParameterProof(self: *Renderer, tracked: MissingText, target: []const u8, style: Style, depth: usize, external: bool, proof: ?ExternalLiteralParameterProof) Error!void {
        return self.linkWithSourceProof(tracked, target, style, depth, external, proof, null);
    }
    fn linkWithSourceProof(self: *Renderer, tracked: MissingText, target: []const u8, style: Style, depth: usize, external: bool, proof: ?ExternalLiteralParameterProof, angle_source: ?[]const u8) Error!void {
        return self.linkWithRecognizedSource(tracked, target, style, depth, external, proof, angle_source, null);
    }
    fn linkWithRecognizedSource(self: *Renderer, tracked: MissingText, target: []const u8, style: Style, depth: usize, external: bool, proof: ?ExternalLiteralParameterProof, angle_source: ?[]const u8, reopened_parent: ?ReopenedExternalParent) Error!void {
        const label = tracked.bytes;
        const angle_proven = external and ((if (angle_source) |source| ir.bracketedAngleProtocolTarget(source, target) else false) or
            (if (reopened_parent) |parent| parent.target.ptr == target.ptr and parent.target.len == target.len and parent.borrowedOriginal() != null else false));
        var s = style;
        const parameter_proven = external and if (proof) |p| externalLiteralParameterProofMatches(p, target) else false;
        const start = self.spans.items.len;
        defer if (parameter_proven) {
            // A child action never inherits the outer source proof.
            for (self.spans.items[start..]) |*span| if (span.kind == .external_link and span.target.ptr == target.ptr and span.target.len == target.len) {
                span.external_literal_parameter = proof;
            };
        };
        const resolved_target = if (external and !parameter_proven) try self.externalUrlTarget(target) else target;
        if (external and !parameter_proven and ir.literalUnclosedConditionalUrl(target) != null)
            return error.UncompiledTemplate;
        if (parameter_proven) {
            self.unresolved_templates += if (proof.?.literal_parent_source) |raw|
                ir.literalUnclosedConditionalUrl(raw).?
            else literalDefaultlessExternalParameter(target).?;
            self.fallbacks.missing_template = true;
        }
        if (external and !parameter_proven and unresolvedExternalActionTarget(resolved_target)) {
            self.fallbacks.rejected_external_target = true;
            // Retain an authored label and all its formatting, but never inherit
            // an outer action or fabricate a replacement destination.
            s.kind = .text;
            s.target = "";
            if (std.mem.eql(u8, label, target)) {
                self.unresolved_templates += 1;
                return error.UncompiledTemplate;
            }
            const label_start = self.spans.items.len;
            try self.inlineTextWithMissing(try missingSlice(self.a, tracked, label), s, depth + 1);
            // Only this rejected action's emitted label is checked. Real
            // protected/entity literals are not deferred source instructions.
            var previous: u8 = 0;
            for (self.spans.items[label_start..]) |span| {
                if (span.kind == .line_break or span.provenance != .parsed) {
                    previous = 0;
                    continue;
                }
                for (span.text) |ch| {
                    if ((ch == '{' or ch == '}') and ch == previous) {
                        self.unresolved_templates += 1;
                        return error.UncompiledTemplate;
                    }
                    previous = ch;
                }
            }
            return;
        }
        if (resolved_target.len != 0 and (!external or safeUrl(resolved_target) or (angle_proven and std.mem.eql(u8, resolved_target, target)))) {
            s.kind = if (external) .external_link else .link;
            s.target = resolved_target;
            if (self.pageStyleDomain() != null) s = try self.wikiLinkStyleIn(style, .{ .target = resolved_target, .external = external }, target);
            if (!external) s.poem_independent_parse = false;
        }
        if (external and std.mem.eql(u8, label, target)) {
            const decoded_label = try self.entityText(label);
            // URL text containing encoded controls/whitespace uses its escaped
            // destination spelling, never raw navigation control characters.
            const escaped_label = std.mem.indexOfAny(u8, decoded_label, " \t\n\r\"") != null or
                std.mem.indexOf(u8, decoded_label, "\xc2\xa0") != null;
            const visible = if (escaped_label) resolved_target else decoded_label;
            if (s.kind == .external_link and safeUrl(resolved_target) and
                (parameter_proven or !unresolvedExternalActionTarget(resolved_target)))
                try self.externalUrlLabel(visible, s, parameter_proven or literalDefaultlessExternalPath(target) == null)
            else
                try self.text(visible, s);
            return;
        }
        try self.inlineTextWithMissing(try missingSlice(self.a, tracked, label), s, depth + 1);
    }
    fn plannedCitation(self: *Renderer, tag: syntax.Tag, style: Style) Error!void {
        const plan = self.context.citations orelse return error.InvalidPreContext;
        const raw = tag.attr(plan.attribute) orelse return error.InvalidPreContext;
        const event_id = std.fmt.parseInt(usize, raw, 10) catch return error.InvalidPreContext;
        if (event_id >= plan.events.items.len) return error.InvalidPreContext;
        const event = plan.events.items[event_id];
        if (!std.ascii.eqlIgnoreCase(@tagName(event.tag), tag.name)) return error.InvalidPreContext;
        _ = try self.semanticAttribute(tag, "name");
        _ = try self.semanticAttribute(tag, "group");
        _ = try self.semanticAttribute(tag, "follow");
        if (event.authored_error) {
            self.fallbacks.rendered_extension_error = true;
            try self.text("[Reference error: invalid citation]", .{ .role = .citation, .provenance = .protected_literal });
        }
        const item_id = event.item orelse return;
        if (item_id >= plan.items.items.len) return error.InvalidPreContext;
        const item = plan.items.items[item_id];
        var projection: ?usize = null;
        for (self.citation_locals.items, 0..) |value, index| if (value.plan == plan) {
            projection = index;
            break;
        };
        if (projection == null) {
            const indices = try self.a.alloc(?usize, plan.items.items.len);
            @memset(indices, null);
            try self.citation_locals.append(self.a, .{ .plan = plan, .indices = indices });
            projection = self.citation_locals.items.len - 1;
        }
        const indices = self.citation_locals.items[projection.?].indices;
        var local = indices[item_id];
        if (local == null) {
            var ordinal: ?u32 = null;
            if (item.kind == .note) {
                // The product consolidates footers: visible owner-local group
                // ordinals continue across source epochs; fragments consume none.
                if (item.group.len == 0) {
                    self.default_group_reference_count += 1;
                    ordinal = std.math.cast(u32, self.default_group_reference_count) orelse return error.RenderLimit;
                } else {
                    ordinal = 1;
                    for (self.refs.items) |ref_value| if (ref_value.kind == .note and std.mem.eql(u8, ref_value.group, item.group)) {
                        ordinal = std.math.add(u32, ordinal.?, 1) catch return error.RenderLimit;
                    };
                }
            }
            const index = self.refs.items.len;
            try self.refs.append(self.a, .{ .kind = item.kind, .number = index + 1, .group_number = ordinal, .name = item.name, .group = item.group, .body = if (item.body) |body_value| body_value.bytes else "", .missing = item.body, .citation_plan = plan, .citation_item = item_id });
            indices[item_id] = index;
            local = index;
        }
        if (event.marker) try self.referenceMarker(local.?, style);
    }
    fn plannedPoemScope(self: *Renderer, tag: syntax.Tag) Error!bool {
        const plan = self.context.citations orelse return false;
        const raw = tag.attr(plan.attribute) orelse return false;
        const id = std.fmt.parseInt(usize, raw, 10) catch return error.InvalidPreContext;
        if (id >= plan.events.items.len or plan.events.items[id].tag != .poem) return error.InvalidPreContext;
        return true;
    }
    fn citationFooterOrder(self: *Renderer) Error![]const Reference {
        if (self.citation_locals.items.len == 0) return self.refs.items;
        const FinalItem = struct {
            index: usize,
            position: usize,
            fragment: bool,
            fn lessThan(_: void, left: @This(), right: @This()) bool {
                if (left.position != right.position) return left.position < right.position;
                if (left.fragment != right.fragment) return left.fragment;
                return left.index < right.index;
            }
        };
        var result: std.ArrayList(Reference) = .empty;
        var seen_plans: std.ArrayList(*const CitationPlan) = .empty;
        defer seen_plans.deinit(self.a);
        for (self.refs.items) |ref_value| {
            const plan = ref_value.citation_plan orelse {
                try result.append(self.a, ref_value);
                continue;
            };
            var seen = false;
            for (seen_plans.items) |prior| if (prior == plan) {
                seen = true;
                break;
            };
            if (seen) continue;
            try seen_plans.append(self.a, plan);
            const indices = found: {
                for (self.citation_locals.items) |value| if (value.plan == plan) break :found value.indices;
                return error.InvalidPreContext;
            };
            const explicit_count = if (plan.final_batches.items.len == 0)
                plan.batches.items.len
            else
                plan.final_batches.items[0];
            if (explicit_count > plan.batches.items.len) return error.InvalidPreContext;
            for (plan.batches.items[0..explicit_count]) |batch| for (batch.items) |item_id| {
                if (item_id >= indices.len) return error.InvalidPreContext;
                if (indices[item_id]) |index| try result.append(self.a, self.refs.items[index]);
            };
            var final_items: std.ArrayList(FinalItem) = .empty;
            defer final_items.deinit(self.a);
            for (plan.final_batches.items, 0..) |batch_id, final_index| {
                if (batch_id != explicit_count + final_index or batch_id >= plan.batches.items.len)
                    return error.InvalidPreContext;
                const batch = plan.batches.items[batch_id];
                var first_local: usize = std.math.maxInt(usize);
                for (batch.items) |item_id| {
                    if (item_id >= indices.len) return error.InvalidPreContext;
                    if (indices[item_id]) |index| first_local = @min(first_local, index);
                }
                for (batch.items) |item_id| if (indices[item_id]) |index| {
                    const fragment = self.refs.items[index].kind == .fragment;
                    try final_items.append(self.a, .{
                        .index = index,
                        .position = if (fragment) first_local else index,
                        .fragment = fragment,
                    });
                };
            }
            std.mem.sort(FinalItem, final_items.items, {}, FinalItem.lessThan);
            for (final_items.items) |item| try result.append(self.a, self.refs.items[item.index]);
        }
        return result.toOwnedSlice(self.a);
    }
    fn referenceIndex(self: *Renderer, name: []const u8, group: []const u8, body: []const u8) Error!?usize {
        const use_short_name_compare = self.refs.items.len >= 16;
        if (name.len != 0) for (self.refs.items, 0..) |*ref, i| {
            const same_name = if (use_short_name_compare) referenceStringEqual(ref.name, name) else std.mem.eql(u8, ref.name, name);
            if (!same_name or !std.mem.eql(u8, ref.group, group)) continue;
            if (ref.body.len == 0 and body.len != 0) {
                ref.body = body;
                ref.missing = if (self.inline_missing) |parent| try missingSlice(self.a, parent, body) else if (self.body_missing) |parent| try missingSlice(self.a, parent, body) else MissingText.untracked(body);
            }
            return i;
        };
        var resolved_body = body;
        var resolved_missing = if (self.inline_missing) |parent| try missingSlice(self.a, parent, body) else if (self.body_missing) |parent| try missingSlice(self.a, parent, body) else MissingText.untracked(body);
        // Authenticated native phase definitions include opaque Poem bodies
        // in emitted page order. The legacy raw table cannot see those bodies.
        // Ordinary/legacy calls retain the exact previous table and precedence.
        const page_definitions = if (self.poem_definitions_complete) self.ref_defs.items else self.page_reference_definitions;
        if (name.len != 0) for (page_definitions) |definition| {
            if (definition.body.len != 0 and std.mem.eql(u8, definition.name, name) and std.mem.eql(u8, definition.group, group)) {
                resolved_body = definition.body;
                resolved_missing = definition.missing orelse MissingText.transformed(definition.body);
                break;
            }
        };
        if (name.len != 0 and resolved_body.len == 0) for (self.ref_defs.items) |definition| {
            if (std.mem.eql(u8, definition.name, name) and std.mem.eql(u8, definition.group, group)) {
                resolved_body = definition.body;
                resolved_missing = definition.missing orelse MissingText.transformed(definition.body);
                break;
            }
        };
        if (!self.spend()) return null;
        const index = self.refs.items.len;
        var group_number: usize = 1;
        if (group.len == 0) {
            self.default_group_reference_count += 1;
            group_number = self.default_group_reference_count;
        } else {
            for (self.refs.items) |ref| {
                if (ref.kind == .note and std.mem.eql(u8, ref.group, group)) group_number += 1;
            }
        }
        try self.refs.append(self.a, .{ .number = index + 1, .group_number = std.math.cast(u32, group_number) orelse return error.RenderLimit, .name = name, .group = group, .body = resolved_body, .missing = resolved_missing, .poem = self.poem_depth != 0, .poem_direction = self.poem_direction });
        return index;
    }
    fn reference(self: *Renderer, name: []const u8, group: []const u8, body: []const u8, style: Style) Error!void {
        if (self.in_reference) {
            try self.text("[nested reference]", style);
            return;
        }
        const index = (try self.referenceIndex(name, group, body)) orelse {
            try self.text("[render output truncated]", style);
            return;
        };
        try self.referenceMarker(index, style);
    }
    fn referenceMarker(self: *Renderer, index: usize, style: Style) Error!void {
        const ref = self.refs.items[index];
        const group = ref.group;
        var s = style;
        s.superscript = true;
        s.role = .reference;
        s.kind = .link;
        s.target = try std.fmt.allocPrint(self.a, "#reference-{d}", .{ref.number});
        const marker = if (group.len == 0)
            try std.fmt.allocPrint(self.a, "[{d}]", .{ref.group_number.?})
        else
            try std.fmt.allocPrint(self.a, "[{s} {d}]", .{ group, ref.group_number.? });
        // Cite armors its generated label with safeEncodeAttribute before
        // recursive parsing. The authored group is display-only here; its
        // exact identity stays in refs, and the synthesized target is validated.
        s.provenance = .protected_literal;
        try self.text(marker, s);
    }
    fn referenceDefinitions(self: *Renderer, content: []const u8, default_group: []const u8) Error!void {
        try self.referenceDefinitionsInner(content, default_group, 0, false);
    }
    fn referenceDefinitionsInner(self: *Renderer, content: []const u8, default_group: []const u8, depth: usize, list_defined: bool) Error!void {
        if (depth >= max_depth) {
            self.fallbacks.render_limit = true;
            return;
        }
        var pos: usize = 0;
        var opaque_scan: syntax.OpaqueScan = .{};
        var next_tag = std.mem.indexOfScalar(u8, content, '<');
        var next_item = if (self.poem_items.items.len != 0) std.mem.indexOf(u8, content, poem_prefix) else null;
        while (true) {
            if (next_tag) |at| if (at < pos) {
                next_tag = std.mem.indexOfScalarPos(u8, content, pos, '<');
            };
            if (next_item) |at| if (at < pos) {
                next_item = std.mem.indexOfPos(u8, content, pos, poem_prefix);
            };
            const open = next_tag orelse content.len;
            const marker = next_item orelse content.len;
            if (open == content.len and marker == content.len) break;
            if (marker < open) {
                const item = self.poemItemAt(content[marker..]) orelse {
                    pos = marker + poem_prefix.len;
                    continue;
                };
                pos = marker + item.token.len;
                if (item.kind != .literal or !std.mem.eql(u8, item.tag, "poem")) continue;
                if (self.poem_definition_dispatches >= max_nodes) {
                    self.fallbacks.render_limit = true;
                    return;
                }
                self.poem_definition_dispatches += 1;
                const inner_open = std.mem.indexOfScalar(u8, item.body, '<') orelse continue;
                const inner_tag = syntax.tagAt(item.body, inner_open) orelse continue;
                if (!inner_tag.is("poem") or inner_tag.closing or inner_tag.self_closing) continue;
                const inner_pair = syntax.matchingTag(item.body, inner_tag) orelse continue;
                try self.referenceDefinitionsInner(item.body[inner_tag.end..inner_pair.inner_end], default_group, depth + 1, list_defined);
                continue;
            }
            if (starts(content[open..], "<!--")) {
                pos = syntax.protectedEnd(content, open) orelse content.len;
                continue;
            }
            const tag = try self.semanticTagAt(content, open) orelse {
                pos = open + 1;
                continue;
            };
            pos = tag.end;
            if (!tag.closing and tag.is("references")) {
                const pair = opaque_scan.pair(content, tag) orelse continue;
                const own_group = ((try self.semanticAttribute(tag, "group")) orelse "");
                try self.referenceDefinitionsInner(content[tag.end..pair.inner_end], if (own_group.len != 0) own_group else default_group, depth + 1, true);
                pos = pair.end;
                continue;
            }
            if (!tag.closing and tag.isOpaque() and !tag.is("ref")) {
                pos = if (opaque_scan.pair(content, tag)) |pair| pair.end else tag.end;
                continue;
            }
            if (tag.closing or !tag.is("ref")) continue;
            const pair = opaque_scan.pair(content, tag) orelse continue;
            const name = ((try self.semanticAttribute(tag, "name")) orelse "");
            const follow = ((try self.semanticAttribute(tag, "follow")) orelse "");
            // A rejected name/follow combination cannot become a later body's authority.
            if (name.len == 0 or follow.len != 0) {
                pos = pair.end;
                continue;
            }
            const own_group = ((try self.semanticAttribute(tag, "group")) orelse "");
            const group = if (own_group.len != 0) own_group else default_group;
            const body = if (tag.self_closing) "" else content[tag.end..pair.inner_end];
            var found = false;
            for (self.ref_defs.items) |*definition| {
                if (!std.mem.eql(u8, definition.name, name) or !std.mem.eql(u8, definition.group, group)) continue;
                if (definition.body.len == 0 and body.len != 0) {
                    definition.body = body;
                    definition.missing = if (self.body_missing) |parent| try missingSlice(self.a, parent, body) else MissingText.untracked(body);
                    definition.list_defined = list_defined;
                }
                found = true;
                break;
            }
            if (!found) {
                if (self.ref_defs.items.len >= max_nodes) {
                    self.fallbacks.render_limit = true;
                    return;
                }
                try self.ref_defs.append(self.a, .{ .name = name, .group = group, .body = body, .missing = if (self.body_missing) |parent| try missingSlice(self.a, parent, body) else MissingText.untracked(body), .list_defined = list_defined });
            }
            for (self.refs.items) |*ref| {
                if (std.mem.eql(u8, ref.name, name) and std.mem.eql(u8, ref.group, group) and ref.body.len == 0 and body.len != 0) {
                    ref.body = body;
                    ref.missing = if (self.body_missing) |parent| try missingSlice(self.a, parent, body) else MissingText.untracked(body);
                }
            }
            pos = pair.end;
        }
    }
    const ReferenceTableLink = struct { start: usize, inner_end: usize, end: usize };

    // Tables are parsed before internal links. Restrict this recovery to an
    // otherwise empty target surrounding one complete physical table; neither
    // a label nor an ordinary target may lend its body to this proof.
    fn referenceTableLink(input: []const u8, at: usize, scan: *syntax.OpaqueScan) ?ReferenceTableLink {
        if (!starts(input[at..], "[[")) return null;
        const pair = syntax.balancedWithOpaqueScan(input, at, scan) orelse return null;
        var first = at + 2;
        while (first < pair.inner_end and std.ascii.isWhitespace(input[first])) : (first += 1) {}
        if (first == at + 2 or input[first - 1] != '\n' or !starts(input[first..pair.inner_end], "{|")) return null;
        var last = pair.inner_end;
        while (last > first and std.ascii.isWhitespace(input[last - 1])) : (last -= 1) {}
        if (last < first + 4 or !std.mem.eql(u8, input[last - 2 .. last], "|}")) return null;
        const close = last - 2;
        if (close == 0 or input[close - 1] != '\n') return null;
        // Extra table delimiters, even in protected subdomains, remain outside
        // this finite proof. The ordinary parser still owns their validation.
        if (std.mem.indexOf(u8, input[first + 2 .. close], "{|") != null or
            std.mem.indexOf(u8, input[first + 2 .. close], "|}") != null) return null;
        return .{ .start = at, .inner_end = pair.inner_end, .end = pair.end };
    }

    fn referenceTableFormatting(name: []const u8) bool {
        return oneOf(name, &.{ "sup", "sub", "small", "big", "b", "strong", "i", "em", "u", "s", "strike", "del", "span", "font" });
    }

    fn nextReferenceTableLink(input: []const u8, start: usize) ?ReferenceTableLink {
        var scan: syntax.OpaqueScan = .{};
        var at = start;
        while (at < input.len) {
            if ((at == 0 or input[at - 1] == '\n') and (input[at] == ' ' or input[at] == '\t')) {
                at = std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len;
                if (at < input.len) at += 1;
                continue;
            }
            if (input[at] == '<') {
                if (scan.protectedEnd(input, at, null)) |end| { at = end; continue; }
                const tag = scan.tagAt(input, at, null) orelse return null;
                if (!tag.closing and !tag.self_closing and !referenceTableFormatting(tag.name)) {
                    at = if (syntax.matchingTagWithOpaqueScan(input, tag, &scan)) |pair| pair.end else input.len;
                } else {
                    if (!tag.closing and !tag.self_closing and syntax.matchingTagWithOpaqueScan(input, tag, &scan) == null) return null;
                    at = tag.end;
                }
                continue;
            }
            if (starts(input[at..], "{{")) {
                at = (syntax.balancedWithOpaqueScan(input, at, &scan) orelse return null).end;
                continue;
            }
            if (starts(input[at..], "[[")) {
                if (referenceTableLink(input, at, &scan)) |found| return found;
                at = (syntax.balancedWithOpaqueScan(input, at, &scan) orelse return null).end;
                continue;
            }
            if (input[at] == '[') {
                at = (std.mem.indexOfScalarPos(u8, input, at + 1, ']') orelse return null) + 1;
                continue;
            }
            at += 1;
        }
        return null;
    }

    fn prepareReferenceTableLinks(self: *Renderer, source: MissingText) Error!MissingText {
        if (!self.in_reference or source.unknown or self.pre_block or self.parsed_pre or
            self.block_formatting.code or self.in_template_literal_scope or
            self.body_link_target.len != 0 or self.inline_source_domain != null) return source;
        const input = source.bytes;
        if (std.mem.indexOf(u8, input, "[[") == null or std.mem.indexOf(u8, input, "{|") == null) return source;
        try generated_link.validateRanges(input, source.generated_source, source.generated_links);
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
        var copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer copies.deinit(self.a);
        var emitted: usize = 0;
        var cursor: usize = 0;
        while (nextReferenceTableLink(input, cursor)) |found| {
            cursor = found.end;
            var trusted = true;
            for (source.ranges) |range| if (range.start < found.end and range.end > found.start) { trusted = false; };
            for (source.generated_links) |range| if (range.start < found.end and range.end > found.start) { trusted = false; };
            if (!trusted) continue;
            try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, found.start);
            try self.appendMissingHeadingSourceEdit(&out, &copies, source, found.start, "&#91;");
            try self.appendMissingHeadingSourceEdit(&out, &copies, source, found.start + 1, "&#91;");
            try self.appendMissingHeadingSourceCopy(&out, &copies, source, found.start + 2, found.inner_end);
            try self.appendMissingHeadingSourceEdit(&out, &copies, source, found.inner_end, "&#93;");
            try self.appendMissingHeadingSourceEdit(&out, &copies, source, found.inner_end + 1, "&#93;");
            emitted = found.end;
            self.fallbacks.literal_markup = true;
        }
        if (emitted == 0) return source;
        try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, input.len);
        const result = try out.finish(self.a);
        try self.registerHeadingSourceCopies(result.bytes, copies.items);
        return result;
    }

    // Table handling precedes inline formatting and link handling. Only
    // balanced supported formatting may expose its physical table lines here;
    // action, code, template and opaque domains remain separate.
    fn referenceHasWikiTableBody(input: []const u8) bool {
        return referenceHasWikiTableBodyDepth(input, 0, true);
    }
    fn referenceHasWikiTableBodyDepth(input: []const u8, depth: usize, begins_line: bool) bool {
        if (depth >= max_depth) return false;
        if (nextReferenceTableLink(input, 0) != null) return true;
        var scan: syntax.OpaqueScan = .{};
        var missing_nowiki = false;
        var at: usize = 0;
        while (at < input.len) {
            if ((at == 0 and begins_line) or (at != 0 and input[at - 1] == '\n')) {
                const end = std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len;
                const line = std.mem.trimEnd(u8, input[at..end], "\r");
                if (line.len != 0 and line[0] != ' ' and line[0] != '\t' and wikiTableIndent(line) != null)
                    return true;
            }
            if (input[at] == '<') {
                if (scan.protectedEnd(input, at, &missing_nowiki)) |end| {
                    at = end;
                    continue;
                }
                if (scan.tagAt(input, at, &missing_nowiki)) |tag| {
                    if (!tag.closing and !tag.self_closing and knownInlineHtmlName(tag.name)) {
                        if (syntax.matchingTagWithOpaqueScan(input, tag, &scan)) |pair| {
                            if (referenceTableFormatting(tag.name) and referenceHasWikiTableBodyDepth(input[tag.end..pair.inner_end], depth + 1, false)) return true;
                            at = pair.end;
                            continue;
                        }
                        return false;
                    }
                    at = tag.end;
                    continue;
                }
            }
            if (starts(input[at..], "{{") or starts(input[at..], "[[")) {
                const pair = syntax.balancedWithOpaqueScan(input, at, &scan) orelse return false;
                at = pair.end;
                continue;
            }
            at += 1;
        }
        return false;
    }
    fn hasFigureBody(self: *Renderer, source: []const u8) bool {
        var at: usize = 0;
        var scan: syntax.OpaqueScan = .{};
        while (at < source.len) {
            if (scan.protectedEnd(source, at, null)) |end| { at = end; continue; }
            if (starts(source[at..], "{{")) {
                const pair = syntax.balancedWithOpaqueScan(source, at, &scan) orelse return false;
                at = pair.end;
                continue;
            }
            if (starts(source[at..], "[[")) {
                const pair = syntax.balancedWithOpaqueScan(source, at, &scan) orelse return false;
                const body = source[at + 2 .. pair.end - 2];
                at = pair.end;
                const pipe = syntax.delimiter(body, "|", 0) orelse continue;
                const target = trim(body[0..pipe]);
                if (target.len == 0 or target[0] == ':' or self.namespaceOfTarget(target) != 6) continue;
                const colon = std.mem.indexOfScalar(u8, target, ':') orelse continue;
                const file = target[colon + 1 ..];
                if (media_types.referencedKind(file) != .image) continue;
                var seen_format = false;
                var pos = pipe + 1;
                while (pos <= body.len) {
                    const end = syntax.delimiter(body, "|", pos) orelse body.len;
                    if (self.mediaOption(trim(body[pos..end]), mediaOptionMode(file, false), &seen_format)) |option|
                        if (oneOf(option.id, &.{ "img_thumbnail", "img_framed" })) return true;
                    if (end == body.len) break;
                    pos = end + 1;
                }
                continue;
            }
            if (scan.tagAt(source, at, null)) |tag| { at = tag.end; continue; }
            at += 1;
        }
        return false;
    }
    pub fn finishReferences(self: *Renderer) Error![]const Reference {
        self.in_reference = true;
        defer self.in_reference = false;
        for (self.refs.items) |*ref| {
            const previous_citations = self.context.citations;
            self.context.citations = ref.citation_plan;
            defer self.context.citations = previous_citations;
            try self.loadPoemPhase();
            const previous_depth = self.poem_depth;
            const previous_direction = self.poem_direction;
            const previous_style = self.poem_base_style;
            const previous_indent = self.poem_line_indent;
            self.poem_depth = if (ref.poem) 1 else 0;
            self.poem_direction = ref.poem_direction;
            self.poem_base_style = .{};
            self.poem_line_indent = 0;
            defer {
                self.poem_depth = previous_depth;
                self.poem_direction = previous_direction;
                self.poem_base_style = previous_style;
                self.poem_line_indent = previous_indent;
            }
            const source = if (ref.body.len != 0) ref.missing orelse MissingText.transformed(ref.body) else MissingText.untracked("Reference text unavailable");
            if (referenceHasWikiTableBody(source.bytes) or self.hasFigureBody(source.bytes) or hasContainerBody(source.bytes, false) or try self.hasAlignedBlockScope(source.bytes)) {
                // Retain typed grids and proved paragraph alignment. A flat
                // span projection cannot preserve either block representation.
                // Reference bodies own a separate tracked source domain; their
                // headings must not publish main-page source offsets.
                const body_before = .{
                    .headings = self.page_html_heading_openings,
                    .pre = self.pre_block, .parsed_pre = self.parsed_pre,
                    .formatting = self.block_formatting,
                    .attributes = self.body_formatting_attributes,
                    .language_direction = self.body_language_direction,
                    .link_target = self.body_link_target,
                    .domain = self.inline_source_domain,
                    .table = self.inline_table_boundaries,
                    .blockquote_flow = self.html_blockquote_flow,
                    .quote_seed = self.next_quote_seed,
                    .table_style_scope = self.table_style_scope,
                    .table_css_ancestor_classes = self.table_css_ancestor_classes,
                    .table_style_unresolved = self.table_style_unresolved,
                    .table_style_font_unresolved = self.table_style_font_unresolved,
                };
                defer {
                    self.page_html_heading_openings = body_before.headings;
                    self.pre_block = body_before.pre;
                    self.parsed_pre = body_before.parsed_pre;
                    self.block_formatting = body_before.formatting;
                    self.body_formatting_attributes = body_before.attributes;
                    self.body_language_direction = body_before.language_direction;
                    self.body_link_target = body_before.link_target;
                    self.inline_source_domain = body_before.domain;
                    self.inline_table_boundaries = body_before.table;
                    self.html_blockquote_flow = body_before.blockquote_flow;
                    self.next_quote_seed = body_before.quote_seed;
                    self.table_style_scope = body_before.table_style_scope;
                    self.table_css_ancestor_classes = body_before.table_css_ancestor_classes;
                    self.table_style_unresolved = body_before.table_style_unresolved;
                    self.table_style_font_unresolved = body_before.table_style_font_unresolved;
                }
                self.page_html_heading_openings = null;
                self.pre_block = false;
                self.parsed_pre = false;
                self.block_formatting = .{};
                self.body_formatting_attributes = .{};
                self.body_language_direction = null;
                self.body_link_target = "";
                self.inline_source_domain = null;
                self.inline_table_boundaries = null;
                self.html_blockquote_flow = false;
                self.next_quote_seed = null;
                self.table_style_scope = 0;
                self.table_css_ancestor_classes = "";
                self.table_style_unresolved = false;
                self.table_style_font_unresolved = false;
                ref.blocks = try self.renderBodyWithMissing(source);
                ref.spans = &.{};
            } else {
                ref.blocks = null;
                ref.spans = try self.parseSpansWithMissing(source, .{});
            }
        }
        return self.citationFooterOrder();
    }
    fn gallery(self: *Renderer, input: []const u8, tag: syntax.Tag, style: Style, _: usize) Error!void {
        var lines = std.mem.splitScalar(u8, input, '\n');
        var emitted = false;
        // Gallery-wide captions are separately parsed extension attributes, not
        // filenames or one of the per-item media captions.
        if (try self.semanticAttribute(tag, "caption")) |caption| {
            if (trim(caption).len != 0) {
                if (self.media_depth >= max_depth) {
                    self.fallbacks.render_limit = true;
                    try self.protectedLiteral(caption, style);
                    emitted = true;
                } else {
                    self.media_depth += 1;
                    defer self.media_depth -= 1;
                    const caption_spans = try self.parseSpans(caption, style);
                    try self.spans.appendSlice(self.a, caption_spans);
                    emitted = caption_spans.len != 0;
                }
            }
        }
        while (lines.next()) |raw_line| {
            const line = trim(raw_line);
            if (line.len == 0) continue;
            const pipe = syntax.delimiter(line, "|", 0);
            const raw_file = trim(line[0 .. pipe orelse line.len]);
            const colon = std.mem.indexOfScalar(u8, raw_file, ':');
            const file = if (colon != null and self.namespaceOfTarget(raw_file) == 6) raw_file[colon.? + 1 ..] else raw_file;
            if (media_types.referencedKind(file) == null) continue;
            const options = if (pipe) |at_pipe| trim(line[at_pipe + 1 ..]) else "";
            const selected_label = self.mediaCaptionChoice(options, file, mediaOptionMode(file, true));
            const caption = selected_label.text;
            var media_style = style;
            media_style.classes = try self.mediaCaptionClasses("", style.classes);
            media_style = try self.mediaActionStyle(media_style, file, selected_label.link_target);
            const visible_label = if (caption.len == 0) file else caption;
            const caption_style: ?MediaCaptionCapture = if (std.mem.eql(u8, caption, visible_label)) .{ .style = mediaCaptionStyle(media_style, false, selected_label.authored_caption) } else null;
            const parsed = try self.mediaFileKindWithSpans(file, caption, null, caption_style);
            media_style.classes = try self.mediaCaptionClasses(try self.mediaClasses(file), style.classes);
            if (emitted) try self.lineBreak(style);
            emitted = true;
            try self.mediaLabel(visible_label, media_style, false, selected_label.authored_caption, false, parsed);
        }
    }
    const ImageMapRejection = struct { reason: []const u8, offset: usize };
    fn imageMapIncomplete(complete: *bool, first: *?ImageMapRejection, reason: []const u8, offset: usize) void {
        if (first.* == null) first.* = .{ .reason = reason, .offset = offset };
        complete.* = false;
    }
    fn imageMapUnavailable(self: *Renderer, input: []const u8, offset: usize, reason: []const u8, bits: u64) Error {
        self.tracePresentationRejection("imagemap", reason, input, offset, bits, error.UncompiledPresentation);
        self.fallbacks.unrepresented_image_map = true;
        self.fallbacks.unsupported_element = true;
        return error.UncompiledPresentation;
    }
    fn imageMapActionBudget(action: presentation_types.MapAction, remaining: *usize) bool {
        for ([_][]const u8{ action.target, action.target_fragment orelse "", action.label }) |value| {
            if (value.len > remaining.*) return false;
            remaining.* -= value.len;
        }
        return true;
    }
    fn imageMapAction(self: *Renderer, spans: []const Span, source_target: []const u8, external: bool) Error!?presentation_types.MapAction {
        const target = if (external) try self.externalUrlTarget(source_target) else source_target;
        if (target.len == 0 or (if (external) !safeUrl(target) or unresolvedExternalActionTarget(target) else unresolvedActionTarget(target))) return null;
        const current_page_action = current: {
            if (!external) for (spans) |span| {
                if (span.self_link) break :current try self.isSelfLink(target);
            };
            break :current false;
        };
        var label: std.ArrayList(u8) = .empty;
        defer label.deinit(self.a);
        const maximum: usize = 32 * 1024 * 1024;
        for (spans) |span| {
            if (span.image != null or span.generated_link != null or span.generated_diagnostic or
                span.external_literal_parameter != null or span.target_fragment != null or span.tooltip != null) return null;
            // ImageMap builds area/default hrefs directly from Title, including
            // the current page. Keep the ordinary text self-link nonaction;
            // only its separately validated spatial action retains the target.
            if (span.self_link) {
                if (!current_page_action or span.target.len != 0 or
                    (span.kind != .text and span.kind != .line_break)) return null;
            } else {
                const expected: ir.InlineKind = if (external) .external_link else .link;
                if (span.kind != expected and span.kind != .line_break) return null;
                if (!std.mem.eql(u8, span.target, target)) return null;
            }
            const visible = if (span.kind == .line_break) "\n" else span.text;
            if (visible.len > maximum - label.items.len) return null;
            try label.appendSlice(self.a, visible);
        }
        const action: presentation_types.MapAction = .{ .kind = if (external) .external else .internal, .target = target, .target_fragment = null, .label = try label.toOwnedSlice(self.a) };
        return if (presentation_types.validMapAction(action)) action else null;
    }
    // Only operation-issued whole-slice copy relations may lead back to the
    // selected occurrence. Equal allocations and first-byte maps do not qualify.
    fn observedImageMapSource(self: *const Renderer, input: []const u8) []const u8 {
        var current = input;
        var remaining: usize = max_depth;
        while (remaining != 0) : (remaining -= 1) {
            if (self.observed_image_map_source) |binding| {
                const offset: ?usize = std.math.sub(usize, @intFromPtr(current.ptr), @intFromPtr(binding.owner.ptr)) catch null;
                if (offset) |start| if (start <= binding.owner.len and current.len <= binding.owner.len - start and
                    start <= binding.original.len and current.len <= binding.original.len - start and
                    std.mem.eql(u8, current, binding.original[start..][0..current.len]))
                    return binding.original[start..][0..current.len];
            }
            var mapped = false;
            for (self.heading_source_aliases.items) |alias| {
                const start = std.math.sub(usize, @intFromPtr(current.ptr), @intFromPtr(alias.copied.ptr)) catch continue;
                if (start > alias.copied.len or current.len > alias.copied.len - start or
                    start > alias.original.len or current.len > alias.original.len - start) continue;
                const original = alias.original[start..][0..current.len];
                if (!std.mem.eql(u8, current, original)) return input;
                current = original;
                mapped = true;
                break;
            }
            if (!mapped) return current;
        }
        return input;
    }

    // The callback supplies a plain observed sentence, not source markup.
    // Keep the Registry's bounded message domain explicit at this API boundary.
    fn imageMapPlainErrorText(message: []const u8) bool {
        if (message.len == 0 or message.len > 4096 or !std.unicode.utf8ValidateSlice(message) or
            message[0] == ':' or std.mem.indexOf(u8, message, "''") != null or magicLinkStart(message, 0) != null) return false;
        for (message, 0..) |byte, at| {
            if (byte < 0x80 and !std.ascii.isAlphanumeric(byte) and std.mem.indexOfScalar(u8, " .,!?-()':", byte) == null) return false;
            if (byte == ':' and at + 1 < message.len and message[at + 1] != ' ') return false;
        }
        return true;
    }
    fn observedImageMapErrorMarkup(self: *Renderer, tracked: MissingText, style: Style) Error!?[]const u8 {
        if (tracked.unknown or tracked.lost_missing_range or tracked.generated_source != null or
            tracked.ranges.len != 0 or tracked.literal_curly_ranges.len != 0 or tracked.generated_links.len != 0 or
            self.in_template_literal_scope or self.in_reference or self.pre_block or self.parsed_pre or self.block_formatting.code or
            self.body_link_target.len != 0 or self.explicit_wiki_label != null or
            style.kind != .text or style.target.len != 0 or style.self_link_target != null or style.provenance != .parsed or
            style.code or style.preserve_whitespace or style.missing_nonaction) return null;
        const branch = imageMapNoLinkSource(tracked.bytes) orelse return null;
        if (self.namespaceOfTarget(branch.file) != 6) return null;
        const source = self.context.figure_sizing orelse return null;
        const resolve = source.resolve_image_map_no_link_fn orelse return null;
        const message = (try resolve(source.page_observation_ctx, self.a, self.observedImageMapSource(tracked.bytes), branch.line)) orelse return null;
        if (!imageMapPlainErrorText(message)) return null;
        return try std.fmt.allocPrint(self.a, "<p class=\"error\">{s}</p>", .{message});
    }
    const ObservedImageMapError = struct { end: usize, markup: []const u8 };
    fn observedImageMapErrorAt(self: *Renderer, input: []const u8, at: usize) Error!?ObservedImageMapError {
        if (!self.interruptedBodyTargetDomain()) return null;
        const source = self.context.figure_sizing orelse return null;
        if (source.resolve_image_map_no_link_fn == null) return null;
        const tag = syntax.tagAt(input, at) orelse return null;
        if (!tag.is("imagemap") or tag.closing or tag.self_closing or trim(tag.attrs).len != 0) return null;
        const pair = syntax.matchingTag(input, tag) orelse return null;
        const parent = self.body_missing orelse MissingText.untracked(input);
        // A slice must not erase generated-source or whole-owner uncertainty.
        if (parent.unknown or parent.lost_missing_range or parent.generated_source != null) return null;
        const tracked = try self.missingSliceWithHeadingSource(parent, input[tag.end..pair.inner_end]);
        const markup = (try self.observedImageMapErrorMarkup(tracked, self.bodyFormattingStyle(.{}))) orelse return null;
        return .{ .end = pair.end, .markup = markup };
    }

    fn imageMap(self: *Renderer, tracked: MissingText, style: Style, depth: usize) Error!bool {
        errdefer self.fallbacks.unrepresented_image_map = true;
        // The header and label parsers retain unknown below. Local missing,
        // protected or generated source still cannot certify a spatial action.
        const input = tracked.bytes;
        if (tracked.ranges.len != 0 or tracked.literal_curly_ranges.len != 0 or tracked.generated_links.len != 0) {
            const bits: u64 = @as(u64, @intFromBool(tracked.unknown)) |
                (@as(u64, @intFromBool(tracked.ranges.len != 0)) << 1) |
                (@as(u64, @intFromBool(tracked.literal_curly_ranges.len != 0)) << 2) |
                (@as(u64, @intFromBool(tracked.generated_links.len != 0)) << 3);
            return self.imageMapUnavailable(input, 0, "source_metadata", bits);
        }
        // Owner/paragraph slicing may already have discarded a crossing range.
        // The ordinary Text copy path retains that refusal fact independently
        // of global unknown, including before this Renderer was constructed.
        if (tracked.lost_missing_range)
            return self.imageMapUnavailable(input, 0, "lost_missing_range", 1);
        if (try self.observedImageMapErrorMarkup(tracked, style)) |markup| {
            try self.inlineTextWithMissing(.{ .bytes = markup }, style, depth + 1);
            self.fallbacks.rendered_extension_error = true;
            return true;
        }
