                    if (language_value != null or value.len > 64) return false;
                    for (value) |byte| if (!std.ascii.isAlphanumeric(byte) and byte != '-') return false;
                    language_value = value;
                } else return false;
            }
            const classes = class_value orelse return false;
            if (htmlOwnAttributePresence(&tag, "class") != .present or
                !std.mem.eql(u8, tag.attr("class") orelse return false, classes)) return false;
            if (language_value) |language| {
                if (htmlOwnAttributePresence(&tag, "lang") != .present or
                    !std.mem.eql(u8, tag.attr("lang") orelse return false, language)) return false;
                self.has_language = true; // Empty lang is a barrier too.
            } else if (htmlOwnAttributePresence(&tag, "lang") != .absent) return false;
            const separator: usize = @intFromBool(self.classes_len != 0);
            if (classes.len + separator > self.classes.len - self.classes_len) return false;
            if (separator != 0) { self.classes[self.classes_len] = ' '; self.classes_len += 1; }
            @memcpy(self.classes[self.classes_len..][0..classes.len], classes);
            self.classes_len += classes.len;
            self.attributed_spans += 1;
            return true;
        }
    };

    fn figureCaptionAuthoredSpan(tracked: MissingText, caption: []const u8) ?FigureCaptionAuthoredInventory {
        if (caption.len == 0 or caption.len > 4096 or tracked.lost_missing_range or
            tracked.generated_source != null or !figureCaptionInlineNodes(caption)) return null;
        for (caption) |byte| if (byte < 0x20 or byte == 0x7f) return null;
        var inventory: FigureCaptionAuthoredInventory = .{};
        if (!figureCaptionFiniteNodesWithInventory(null, tracked, caption, &inventory) or
            inventory.attributed_spans == 0) return null;
        return inventory;
    }

    // Compose the existing ordinary remote and local-fragment grammars. This
    // inventory supplies only finite caption nodes/classes, never outer scope.
    // Attributed spans stay in their independently qualified existing route.
    fn figureCaptionRemoteInventory(self: *const Renderer, tracked: MissingText, caption: []const u8) ?FigureCaptionAuthoredInventory {
        if (caption.len == 0 or caption.len > 4096 or tracked.lost_missing_range or
            tracked.generated_source != null or !figureCaptionInlineNodes(caption)) return null;
        for (caption) |byte| if (byte < 0x20 or byte == 0x7f) return null;
        var inventory: FigureCaptionAuthoredInventory = .{};
        if (!figureCaptionFiniteNodesWithInventory(self, tracked, caption, &inventory) or
            inventory.attributed_spans != 0 or inventory.remote_links == 0) return null;
        return inventory;
    }

    fn figureCaptionLocalFragment(target: []const u8) bool {
        const hash = std.mem.indexOfScalar(u8, target, '#') orelse return false;
        if (hash == 0 or hash + 1 == target.len or trim(target[0..hash]).len == 0 or
            trim(target[hash + 1 ..]).len == 0 or !safeInternalTarget(target)) return false;
        if (std.mem.indexOfAny(u8, target, ":[]|{}<>&/\\\r\n\x00") != null or
            std.mem.indexOfScalarPos(u8, target, hash + 1, '#') != null) return false;
        for (target) |byte| if (byte < 0x20 or byte == 0x7f) return false;
        return true;
    }

    fn figureCaptionItalicLocalLabel(label: []const u8) bool {
        const body = if (label.len > 4 and starts(label, "''") and std.mem.endsWith(u8, label, "''"))
            label[2 .. label.len - 2]
        else if (label.len > 7 and starts(label, "<i>") and std.mem.endsWith(u8, label, "</i>"))
            label[3 .. label.len - 4]
        else return false;
        if (trim(body).len == 0 or std.mem.indexOfAny(u8, body, "[]:#|{}<>&/\\'\r\n\x00") != null) return false;
        for (body) |byte| if (byte < 0x20 or byte == 0x7f) return false;
        return true;
    }

    fn figureCaptionFiniteNodes(list_context: ?*const Renderer, tracked: MissingText, caption: []const u8) bool {
        return figureCaptionFiniteNodesWithInventory(list_context, tracked, caption, null);
    }

    fn figureCaptionFiniteNodesWithInventory(list_context: ?*const Renderer, tracked: MissingText, caption: []const u8, inventory: ?*FigureCaptionAuthoredInventory) bool {
        const begin = @intFromPtr(tracked.bytes.ptr);
        const at = @intFromPtr(caption.ptr);
        if (at < begin or at - begin > tracked.bytes.len or caption.len > tracked.bytes.len - (at - begin)) return false;
        if (tracked.ranges.len != 0 or tracked.literal_curly_ranges.len != 0 or tracked.generated_links.len != 0) return false;
        if (!std.unicode.utf8ValidateSlice(caption) or std.mem.indexOf(u8, caption, "__") != null) return false;
        // This consumes the exact borrowed caption, not a normalized copy.
        // Unknown missing-phase state is retained: it does not manufacture new
        // nodes in these bytes. Local protected/generated occurrences refuse.
        // Quotes and balanced bare formatting tags create only classless nodes;
        // simple local links may additionally create the known selflink classes.
        var tags: [16]u8 = undefined;
        var depth: usize = 0;
        var pos: usize = 0;
        while (pos < caption.len) {
            const byte = caption[pos];
            if (byte == '<') {
                // A complete bare NOWIKI around ordinary text creates no
                // element/class/action. Keep its normal protected-text parse;
                // only the independent class/list inventory consumes this proof.
                if (starts(caption[pos..], "<nowiki>")) {
                    const nowiki_body_at = pos + "<nowiki>".len;
                    const nowiki_close_at = std.mem.indexOfPos(u8, caption, nowiki_body_at, "</nowiki>") orelse return false;
                    const caption_nowiki_body = caption[nowiki_body_at..nowiki_close_at];
                    if (trim(caption_nowiki_body).len == 0 or std.mem.indexOfAny(u8, caption_nowiki_body, "[]:#|{}<>&/\\'_") != null) return false;
                    for (caption_nowiki_body) |ch| if (ch < 0x20 or ch == 0x7f) return false;
                    pos = nowiki_close_at + "</nowiki>".len;
                    continue;
                }
                const close = pos + 1 < caption.len and caption[pos + 1] == '/';
                const name_at = pos + 1 + @intFromBool(close);
                var name_end = name_at;
                while (name_end < caption.len and std.ascii.isAlphabetic(caption[name_end])) : (name_end += 1) {}
                const name = caption[name_at..name_end];
                const kind: u8 = if (std.mem.eql(u8, name, "b")) 'b' else if (std.mem.eql(u8, name, "i")) 'i' else if (std.mem.eql(u8, name, "span")) 's' else if (std.mem.eql(u8, name, "small")) 'm' else if (std.mem.eql(u8, name, "sup")) 'u' else if (std.mem.eql(u8, name, "br")) 'r' else return false;
                var end = name_end;
                while (end < caption.len and std.mem.indexOfScalar(u8, " \t\r\n\x0c", caption[end]) != null) : (end += 1) {}
                // Bare BR is void. Only its optional closing slash is accepted;
                // ordinary caption parsing still emits the actual line break.
                if (kind == 'r' and !close and end < caption.len and caption[end] == '/') end += 1;
                if (end == caption.len) return false;
                if (caption[end] != '>') {
                    const authored = inventory orelse return false;
                    if (close or kind != 's') return false;
                    const tag = syntax.tagAt(caption, pos) orelse return false;
                    if (!authored.span(tag)) return false;
                    end = tag.end - 1;
                }
                if (kind == 'r') {
                    if (close) return false;
                } else if (close) {
                    if (depth == 0 or tags[depth - 1] != kind) return false;
                    depth -= 1;
                } else {
                    if (depth == tags.len) return false;
                    tags[depth] = kind; depth += 1;
                }
                pos = end + 1;
                continue;
            }
            if (byte == '\r' or byte == '\n') return depth == 0 and trim(caption[pos..]).len == 0;
            if (byte == '[') {
                // Numeric bracket prose is not an external-link or reference
                // token. Consume only the complete literal decimal form.
                if (pos + 1 < caption.len and std.ascii.isDigit(caption[pos + 1])) {
                    var end = pos + 2;
                    while (end < caption.len and std.ascii.isDigit(caption[end])) : (end += 1) {}
                    if (end == caption.len or caption[end] != ']') return false;
                    pos = end + 1; continue;
                }
                if (!starts(caption[pos..], "[[")) return false;
                const end = std.mem.indexOfPos(u8, caption, pos + 2, "]]") orelse return false;
                const inner_link = caption[pos + 2 .. end];
                const separator = std.mem.indexOfScalar(u8, inner_link, '|');
                const caption_target = if (separator) |pipe_offset| inner_link[0..pipe_offset] else inner_link;
                if (trim(caption_target).len == 0 or std.mem.indexOfAny(u8, caption_target, "[]|{}<>&/\\\r\n\x00") != null) return false;
                if (std.mem.indexOfScalar(u8, caption_target, '#') != null and
                    (inventory == null or !figureCaptionLocalFragment(caption_target))) return false;
                if (std.mem.indexOfScalar(u8, caption_target, ':') != null) {
                    const renderer = list_context orelse return false;
                    if (!renderer.figureCaptionRemoteTarget(caption_target)) return false;
                    if (inventory) |facts| if (!facts.remote()) return false;
                }
                if (separator) |pipe_offset| {
                    // A literal nonempty label changes visible text, not the
                    // local link's generated node/class domain. The ordinary
                    // caption parser still owns its action and text.
                    const caption_label = inner_link[pipe_offset + 1 ..];
                    if (trim(caption_label).len == 0 or
                        (std.mem.indexOfAny(u8, caption_label, "[]:#|{}<>&/\\'\r\n\x00") != null and
                            !figureCaptionBoldLocalLabel(caption_label) and
                            !(inventory != null and figureCaptionItalicLocalLabel(caption_label)))) return false;
                }
                pos = end + 2;
                continue;
            }
            if (byte == ':' and inventory != null) {
                // This complete one-line caption already excludes a list-line
                // opener. Retain literal prose punctuation, not protocol syntax.
                if (pos == 0 or pos + 1 == caption.len or caption[pos + 1] != ' ') return false;
                pos += 1;
                continue;
            }
            if (byte == ':' and list_context != null) {
                // A prose colon after an alphanumeric byte and before a space
                // cannot start a physical wiki-list line. Do not normalize it.
                if (pos == 0 or !std.ascii.isAlphanumeric(caption[pos - 1]) or
                    pos + 1 == caption.len or caption[pos + 1] != ' ') return false;
                pos += 1;
                continue;
            }
            if (byte == '&') {
                // Ordinary visible references emit literal text after block and
                // inline markup recognition. Decode only to prove this exact
                // source span cannot add nodes outside the finite inventory,
                // authored classes or list containers;
                // the ordinary caption renderer still emits the actual text.
                var scratch: [4]u8 = undefined;
                const entity_value = decodeEntity(caption[pos..], &scratch, true) orelse return false;
                pos += entity_value.consumed;
                continue;
            }
            if (std.mem.indexOfScalar(u8, "]>{}&|:\r\n\x00", byte) != null) return false;
            pos += 1;
        }
        return depth == 0;
    }

    // This class inventory is independent of the inline/block flow predicate.
    // The ordinary caption parser still owns the DIV, CSS and line breaks.
    fn figureCaptionClasslessDiv(tracked: MissingText, caption: []const u8) bool {
        const begin = @intFromPtr(tracked.bytes.ptr);
        const at = @intFromPtr(caption.ptr);
        if (at < begin or at - begin > tracked.bytes.len or caption.len > tracked.bytes.len - (at - begin)) return false;
        const subtree = trim(caption);
        if (!std.unicode.utf8ValidateSlice(subtree)) return false;
        const opening = syntax.tagAt(subtree, 0) orelse return false;
        if (!opening.is("div") or opening.closing or opening.self_closing or
            htmlOwnAttributePresence(&opening, "class") != .absent) return false;
        const attrs = trim(opening.attrs);
        if (attrs.len != 0) {
            const equal = std.mem.indexOfScalar(u8, attrs, '=') orelse return false;
            if (!std.ascii.eqlIgnoreCase(trim(attrs[0..equal]), "style")) return false;
            const value = trim(attrs[equal + 1 ..]);
            if (value.len < 2 or (value[0] != '\'' and value[0] != '"') or
                value[value.len - 1] != value[0] or
                std.mem.indexOfScalar(u8, value[1 .. value.len - 1], value[0]) != null) return false;
        }
        const pair = syntax.matchingTag(subtree, opening) orelse return false;
        if (pair.end != subtree.len) return false;
        const closing = syntax.tagAt(subtree, pair.inner_end) orelse return false;
        if (!closing.closing or !closing.is("div") or trim(closing.attrs).len != 0) return false;
        const body = subtree[opening.end..pair.inner_end];
        return figureCaptionClassless(tracked, body) and figureCaptionInlineNodes(body);
    }

    // Keep structural-looking first-line syntax outside this additional node
    // certificate. The ordinary caption parser remains the sole body authority;
    // the earlier class-only proof and its admission scope are unchanged.
    fn figureCaptionInlineNodes(caption: []const u8) bool {
        const caption_text = trim(caption);
        return caption_text.len == 0 or std.mem.indexOfScalar(u8, "*#;:=-", caption_text[0]) == null;
    }

    fn prepareFigureGeometry(self: *Renderer, choice: FigureChoice, inherited: Style, rtl: bool, sizing: ?presentation_types.FigureSizingPolicy, caption_classes: ?[]const u8, caption_tags: ?[]const []const u8, caption_no_language_override: bool, complete_caption_classes: ?[]const u8) Error!PreparedFigureGeometry {
        if (self.content_root != .parser_output) return self.prepareFigureGeometryForRoot(choice, inherited, rtl, sizing, null);
        const profile = try self.figureStyleProfile();
        // New generated classes may widen possible subjects, never lend absence.
        const possible_classes = if (choice.content == .missing and caption_classes != null)
            try std.fmt.allocPrint(self.a, "{s} new mw-broken-media", .{caption_classes.?}) else caption_classes;
        var root_witness: table_style_profile.Profile.FigureRootDirectionWitness = .{};
        const use = if (profile) |value| value.figureRootDirectionUseWithCompleteClasses(inherited.text_element, possible_classes, caption_tags, self.figurePageLanguage(), caption_no_language_override, if (self.figurePageLanguageContext()) |page| page.outer_languages else null, complete_caption_classes, &root_witness) else table_style_profile.Profile.FigureRootDirectionUse.independent;
        if (use == .unresolved) {
            const css = root_witness.css[0..@min(root_witness.css.len, 128)];
            var css_hex: [256]u8 = undefined;
            const alphabet = "0123456789abcdef";
            for (css, 0..) |byte, index| { css_hex[index * 2] = alphabet[byte >> 4]; css_hex[index * 2 + 1] = alphabet[byte & 15]; }
            diagnostics.logLine("presentation figure_root_witness reason={s} rule_index={d} custom_rule={any} css_bytes={d} css_hex={s} css_truncated={any} caption_classes_known={any} caption_tags_known={any} caption_language_known={any}", .{
                @tagName(root_witness.reason), root_witness.rule_index, root_witness.custom_rule, root_witness.css.len,
                css_hex[0 .. css.len * 2], css.len != root_witness.css.len, caption_classes != null, caption_tags != null, caption_no_language_override,
            });
            self.tracePresentationRejection("figure_root_direction", "selector_dependency", choice.file, 0, 0, error.UncompiledPresentation);
            return self.figureUnavailable();
        }
        // This is independent from root-direction invariance. Only a complete
        // consumed File/caption certificate and a closed inherited class scope
        // can refute ordinary text-paint candidates on generated query nodes.
        const inherited_classes_closed = if (inherited.text_element) |node|
            self.currentAncestorScope(node) and node.complete_ancestor_classes != null else true;
        const query_classes: ?[]const u8 = if (complete_caption_classes != null and possible_classes != null and inherited_classes_closed and
            complete_caption_classes.?.len <= 32768 and possible_classes.?.len <= 16384)
            try std.mem.concat(self.a, u8, &.{ complete_caption_classes.?, " ", possible_classes.?,
                " mw-content-ltr mw-content-rtl mw-parser-output mw-default-size mw-halign-none mw-halign-center mw-halign-left mw-halign-right mw-file-element mw-file-description mw-selflink selflink internal mw-magiclink-isbn extiw new mw-broken-media mw-3d-wrapper" }) else null;
        const ltr = try self.prepareFigureGeometryForRootWithClasses(choice, inherited, rtl, sizing, false, query_classes);
        // No rule can distinguish the alternatives; avoid a second full cascade.
        if (use == .independent) return ltr;
        const other = try self.prepareFigureGeometryForRootWithClasses(choice, inherited, rtl, sizing, true, query_classes);
        var ltr_style = ltr.caption_style;
        var other_style = other.caption_style;
        // Downstream root-dependent caption selectors were refused above.
        // Only these private alternative ancestry pointers may differ.
        ltr_style.text_element = null;
        other_style.text_element = null;
        var ltr_missing = ltr.missing_style;
        var other_missing = other.missing_style;
        if (ltr_missing) |*value| value.text_element = null;
        if (other_missing) |*value| value.text_element = null;
        if (!sameFigurePreparationValue(ltr.value, other.value) or
            !sameFigurePreparationValue(ltr.resolutions, other.resolutions) or
            !sameFigurePreparationValue(ltr.fonts, other.fonts) or
            !sameFigurePreparationValue(ltr_style, other_style) or !sameFigurePreparationValue(ltr_missing, other_missing)) {
            const groups = [_]bool{
                !sameFigurePreparationValue(ltr.value, other.value),
                !sameFigurePreparationValue(ltr.resolutions, other.resolutions),
                !sameFigurePreparationValue(ltr.fonts, other.fonts),
                !sameFigurePreparationValue(ltr_style, other_style) or !sameFigurePreparationValue(ltr_missing, other_missing),
            };
            var mismatch_bits: u64 = 0;
            for (groups, 0..) |different, index| if (different) {
                mismatch_bits |= @as(u64, 1) << @intCast(index);
            };
            self.tracePresentationRejection("figure_root_direction", "preparation_mismatch", choice.file, 0, mismatch_bits, error.UncompiledPresentation);
            return self.figureUnavailable();
        }
        return ltr;
    }

    fn missingPaintResetClass(names: []const u8) bool {
        var classes = std.mem.tokenizeAny(u8, names, " \t\r\n\x0c");
        while (classes.next()) |name| if (oneOf(name, &.{ "notheme", "skin-invert" })) return true;
        return false;
    }
    fn prepareFigureGeometryForRoot(self: *Renderer, choice: FigureChoice, inherited: Style, rtl: bool, sizing: ?presentation_types.FigureSizingPolicy, root_rtl: ?bool) Error!PreparedFigureGeometry {
        return self.prepareFigureGeometryForRootWithClasses(choice, inherited, rtl, sizing, root_rtl, null);
    }
    fn prepareFigureGeometryForRootWithClasses(self: *Renderer, choice: FigureChoice, inherited: Style, rtl: bool, sizing: ?presentation_types.FigureSizingPolicy, root_rtl: ?bool, query_classes: ?[]const u8) Error!PreparedFigureGeometry {
        const missing = switch (choice.content) { .missing => |value| value, .image => null };
        if ((missing != null) == (sizing != null)) return self.figureUnavailable();
        if (missing != null) {
            if (missingPaintResetClass(inherited.classes)) return self.figureUnavailable();
            var paint_ancestor = inherited.text_element;
            while (paint_ancestor) |element| : (paint_ancestor = element.parent) {
                if (missingPaintResetClass(element.classes)) return self.figureUnavailable();
            }
            for (self.customParent(inherited).values) |binding| if (table_style_profile.missingLinkCustomProperty(binding.name)) return self.figureUnavailable();
        }
        const defaults = self.figureDefaults() catch |failure| return self.figureGeometryRejected(choice, "source_defaults", failure);
        var parent = inherited;
        parent.text_element = if (root_rtl) |alternative| self.figureContentParent(inherited.text_element, alternative) catch |failure| return self.figureGeometryRejected(choice, "content_parent", failure) else inherited.text_element;
        const profile = self.figureStyleProfile() catch |failure| return self.figureGeometryRejected(choice, "stylesheet_profile", failure);
        if (parent.font_size_unknown or parent.small or parent.superscript or parent.subscript or
            self.block_formatting.small or self.block_formatting.superscript or self.block_formatting.subscript or
            (parent.font_scale != null and parent.font_scale_basis != .normal_body)) return self.figureGeometryRejected(choice, "inherited_font_scope", self.figureUnavailable());
        // Text direction resolves caption start alignment. Physical defaults
        // instead follow the content classes: the skin's RTL rule follows its
        // equally specific LTR rule, regardless of ancestor proximity.
        var float_rtl = defaults.rtl;
        var ancestor = parent.text_element;
        while (ancestor) |element| : (ancestor = element.parent) {
            // Synthetic alternative classes do not attest physical page direction.
            // Keep the existing site default and actual authored-class contract.
            if (element.ancestry_complete) continue;
            var classes = std.mem.tokenizeAny(u8, element.classes, " \t\r\n\x0c");
            while (classes.next()) |name| if (std.mem.eql(u8, name, "mw-content-rtl")) { float_rtl = true; };
        }
        const placement: presentation_types.FigurePlacement = if (choice.horizontal) |value|
            (if (std.mem.eql(u8, value, "img_none")) .none else if (std.mem.eql(u8, value, "img_center")) .center else if (std.mem.eql(u8, value, "img_left")) .float_left else .float_right)
        else if (float_rtl) .float_left else .float_right;
        const figure_element = try self.a.create(table_style_profile.TextElement);
        // Linker adds this class only for an authored horizontal option.
        const horizontal_class = if (choice.horizontal != null) switch (placement) { .none => "mw-halign-none", .center => "mw-halign-center", .float_left => "mw-halign-left", .float_right => "mw-halign-right" } else "";
        const figure_classes = if (choice.default_size)
            if (horizontal_class.len == 0) "mw-default-size" else try std.fmt.allocPrint(self.a, "mw-default-size {s}", .{horizontal_class})
        else horizontal_class;
        figure_element.* = .{ .tag = "figure", .typeof_tokens = if (missing != null) "mw:Error mw:File/Thumb" else if (choice.format == .thumbnail) "mw:File/Thumb" else "mw:File/Frame", .classes = figure_classes, .parent = parent.text_element };
        if (choice.page_style_token) |token| self.bindGeneratedPageStyle(figure_element, token);
        const poster = if (choice.content == .image) choice.content.image.static_poster else null;
        const wrapper: ?*table_style_profile.TextElement = if (poster != null) value: {
            const element = try self.a.create(table_style_profile.TextElement);
            element.* = .{ .tag = "span", .classes = "mw-3d-wrapper", .parent = figure_element };
            if (choice.page_style_token) |token| self.bindGeneratedPageStyle(element, token);
            break :value element;
        } else null;
        const anchor_element = try self.a.create(table_style_profile.TextElement);
        anchor_element.* = .{ .tag = "a", .classes = if (missing != null) "new" else if (poster != null) "mw-file-description" else "", .parent = wrapper orelse figure_element,
            .attribute_presence = if (missing) |value| value.anchor_attributes else try self.observedFigureAnchorAttributes(choice) };
        const image_element = try self.a.create(table_style_profile.TextElement);
        image_element.* = .{ .tag = if (missing != null) "span" else "img",
            .classes = if (missing != null) "mw-file-element mw-broken-media" else "mw-file-element", .parent = anchor_element,
            .attribute_presence = if (missing) |value| value.element_attributes else null };
        const caption_element = try self.a.create(table_style_profile.TextElement);
        caption_element.* = .{ .tag = "figcaption", .typeof_tokens = "", .parent = figure_element };
        if (choice.page_style_token) |token| {
            self.bindGeneratedPageStyle(anchor_element, token);
            self.bindGeneratedPageStyle(image_element, token);
            self.bindGeneratedPageStyle(caption_element, token);
        }
        const figure_font = self.figureFont(profile, figure_element, parent.font_scale orelse 1, 1) catch |failure| return self.figureGeometryRejected(choice, "frame_font", failure);
        if (wrapper) |element| {
            // The closed source policy supplies the wrapper and ::after defaults.
            // Authored wrapper overrides need an explicit representation; never
            // discard a selector just because the image itself is representable.
            const wrapper_font = try self.figureFont(profile, element, figure_font, 1);
            if (wrapper_font != figure_font) return self.figureUnavailable();
            if (profile) |value| {
                const box = try value.resolveFigure(self.a, element, wrapper_font, rtl);
                const paint = try value.resolveTextPaint(self.a, element, "");
                if (!std.meta.eql(box, table_style_profile.FigureStyle{}) or
                    paint.color != null or paint.weight != null or paint.font_style != null) return self.figureUnavailable();
            }
        }
        const caption_font = self.figureFont(profile, caption_element, figure_font, 0.884) catch |failure| return self.figureGeometryRejected(choice, "caption_font", failure);
        const image_font = self.figureFont(profile, image_element, figure_font, if (missing != null) 0.94 else 1) catch |failure| return self.figureGeometryRejected(choice, "image_font", failure);
