            const label_style = prepared.missing_style orelse return self.figureUnavailable();
            const parent_spans = self.spans;
            self.spans = .empty;
            defer self.spans = parent_spans;
            defer self.spans.deinit(self.a);
            try self.text(choice.content.missing.label, label_style);
            if (self.spans.items.len != 1 or self.spans.items[0].image != null) return self.figureUnavailable();
            result.content.missing.label = self.spans.items[0];
        }
        const owned = try self.a.create(Figure); owned.* = result;
        return owned;
    }
    fn figureBlockKind(kind: Kind) bool {
        return switch (kind) {
            .paragraph, .list_item, .definition, .example, .quotation, .term, .list_detail, .indent => true,
            else => false,
        };
    }
    fn extractFigures(self: *Renderer, blocks: []const Block) Error![]const Block {
        var needed = false;
        for (blocks) |block_value| for (block_value.spans) |span| if (span.pending_figure != null or span.pending_bidi_scope != null) { needed = true; };
        if (!needed) return blocks;
        const result = try self.a.dupe(Block, blocks);
        errdefer self.a.free(result);
        for (result) |*block_value| {
            var count: usize = 0;
            for (block_value.spans) |span| if (span.pending_figure != null or span.pending_bidi_scope != null) { count += 1; };
            if (count == 0) continue;
            if (!figureBlockKind(block_value.kind) or block_value.table != null or block_value.feature != null or
                block_value.figure != null or block_value.flow != null or
                (block_value.kind == .paragraph and (block_value.depth != 0 or block_value.list_path.len != 0))) return self.figureUnavailable();
            var parts: std.ArrayList(FlowPart) = .empty;
            errdefer parts.deinit(self.a);
            var begin: usize = 0;
            for (block_value.spans, 0..) |span, index| {
                if (span.pending_bidi_scope) |scope| {
                    if (span.pending_figure != null or span.image != null or span.text.len != 0 or
                        span.target.len != 0 or !presentation_types.validBidiScopeHeader(scope.*)) return self.figureUnavailable();
                    if (index != begin) {
                        if (!self.spend()) return error.RenderLimit;
                        try parts.append(self.a, .{ .kind = .@"inline", .spans = block_value.spans[begin..index] });
                    }
                    if (!self.spend()) return error.RenderLimit;
                    try parts.append(self.a, .{ .kind = .scope, .scope = scope.* });
                    begin = index + 1;
                    continue;
                }
                var figure = (span.pending_figure orelse continue).*;
                const fallback_end = std.math.add(usize, index + 1, if (figure.map_fallback) |value| value.len else 0) catch return self.figureUnavailable();
                if (fallback_end > block_value.spans.len) return self.figureUnavailable();
                if (figure.map_fallback) |value| for (value, block_value.spans[index + 1 .. fallback_end]) |expected, actual| {
                    if (!std.meta.eql(expected, actual) or actual.pending_figure != null or actual.pending_bidi_scope != null) return self.figureUnavailable();
                };
                if (index != begin) {
                    if (!self.spend()) return error.RenderLimit;
                    try parts.append(self.a, .{ .kind = .@"inline", .spans = block_value.spans[begin..index] });
                }
                const content_span = figure.content.spanPtr();
                content_span.* = span;
                content_span.pending_figure = null;
                content_span.pending_bidi_scope = null;
                content_span.nonfloating_image = false;
                content_span.nonfloating_image_alignment = null;
                switch (figure.content) {
                    .image => if (content_span.image == null or content_span.text.len != 0) return self.figureUnavailable(),
                    .missing => if (content_span.image != null or content_span.text.len == 0 or figure.map_fallback != null) return self.figureUnavailable(),
                }
                if (!self.spend()) return error.RenderLimit;
                try parts.append(self.a, .{ .kind = .figure, .figure = figure });
                // Fallback links remain in the following original inline slice.
                // Never move them into a caption or discard styled empty spans.
                begin = index + 1;
            }
            if (begin != block_value.spans.len) {
                if (!self.spend()) return error.RenderLimit;
                try parts.append(self.a, .{ .kind = .@"inline", .spans = block_value.spans[begin..] });
            }
            block_value.text = "";
            block_value.spans = &.{};
            if (parts.items.len == 1 and parts.items[0].kind == .figure and block_value.style == null) {
                block_value.figure = parts.items[0].figure.?;
                parts.deinit(self.a);
            } else {
                // One anonymous flow retains the original list/style/alignment
                // owner. Its parts introduce no synthetic paragraph boundaries.
                block_value.flow = try parts.toOwnedSlice(self.a);
            }
        }
        return result;
    }

    const ImageChoice = struct { image: presentation_types.InlineImage, nonfloating: bool, alignment: ?presentation_types.CellTextAlign = null };
    fn inlineImageChoice(self: *Renderer, raw: []const u8, file: []const u8, style: Style) Error!?ImageChoice {
        if (style.code or style.preserve_whitespace or self.pre_block or self.parsed_pre or self.media_action_depth != 0) return null;
        if (media_types.referencedKind(file) != .image) return null;
        const mode = mediaOptionMode(file, false);
        if (mode != .image and mode != .svg) return null;
        var image: presentation_types.InlineImage = .{ .file = file };
        var caption: []const u8 = "";
        var alt: ?[]const u8 = null;
        var image_class: ?[]const u8 = null;
        var dimensions: std.ArrayList([]const u8) = .empty;
        defer dimensions.deinit(self.a);
        var admitted = true;
        var horizontal: ?[]const u8 = null;
        var seen_format = false;
        var pos: usize = 0;
        while (pos <= raw.len) {
            const end = syntax.delimiter(raw, "|", pos) orelse raw.len;
            const part = trim(raw[pos..end]);
            if (self.mediaOption(part, mode, &seen_format)) |matched| {
                if (std.mem.eql(u8, matched.id, "img_width")) {
                    try dimensions.append(self.a, matched.value orelse "");
                } else if (std.mem.eql(u8, matched.id, "img_border")) {
                    image.border = true;
                } else if (std.mem.eql(u8, matched.id, "img_class")) {
                    // Parser::makeImageInternal keeps the last valid class option.
                    image_class = matched.value orelse "";
                } else if (std.mem.eql(u8, matched.id, "img_alt")) {
                    alt = matched.value orelse "";
                } else if (oneOf(matched.id, &.{ "img_left", "img_right", "img_center", "img_none" })) {
                    // Parser::makeImage selects the first distinct horizontal
                    // option, independently of repeated dimensions/alt values.
                    if (horizontal == null) horizontal = matched.id;
                } else if (!std.mem.eql(u8, matched.id, "img_link")) admitted = false;
            } else caption = part;
            if (end == raw.len) break;
            pos = end + 1;
        }
        // None and center own isolated figure paragraphs, including cell blocks.
        // Center uses the existing block alignment; it is not a floating image.
        // Left/right, frames and span-only scopes retain their existing route.
        const centered = if (horizontal) |value| std.mem.eql(u8, value, "img_center") else false;
        const nonfloating = centered or if (horizontal) |value| std.mem.eql(u8, value, "img_none") else false;
        if (horizontal != null and !nonfloating) admitted = false;
        if (nonfloating and (style.heading or style.kind != .text or style.direction.len != 0 or
            self.body_link_target.len != 0 or self.poem_depth != 0 or self.html_list_item_flow or
            (self.media_depth != 0 and self.figure_caption_depth == 0) or self.image_block_suppressed or self.bidi_scope_depth != 0 or
            !(if (self.semantic_capture) |hints| hints.image_blocks else false))) return null;
        if (!admitted) return null;
        if (image_class) |value| {
            // Selected Vector CSSCustomProperties applies this exact class to
            // descendant image pixels in dark mode. It does not filter captions,
            // alter dimensions or change image-map coordinate/action semantics.
            // Other classes and protected/markup class values remain unsupported.
            const class_name = trim(value);
            if (std.mem.eql(u8, class_name, "skin-invert-image")) {
                image.dark_mode_filter = .invert_hue_rotate_180;
            } else if (class_name.len != 0) return null;
        }
        for (dimensions.items) |value| inlineImageDimensions(value, &image) catch |err| {
            self.fallbacks.render_limit = true;
            return err;
        };
        if (caption.len != 0) image.tooltip = try self.inlineImagePlainText(caption);
        image.alt = if (alt) |value| try self.inlineImagePlainText(value) else image.tooltip;
        return .{ .image = image, .nonfloating = nonfloating, .alignment = if (centered) .center else null };
    }

    fn emitInlineImage(self: *Renderer, original: Style, image: presentation_types.InlineImage) Error!void {
        const file = (try self.resolvedMediaFile(image.file)) orelse {
            self.fallbacks.render_limit = true;
            return error.RenderLimit;
        };
        var present = false;
        for (self.media.items) |item| if (item.kind == .image and std.mem.eql(u8, item.file, file)) { present = true; break; };
        if (!present) {
            self.fallbacks.render_limit = true;
            return error.RenderLimit;
        }
        var style = original;
        var occurrence = image;
        occurrence.file = file;
        style.image = occurrence;
        style.image_fields_compiled = true;
        // Empty text keeps the ordinary action/style path and node budget.
        const before = self.spans.items.len;
        try self.text("", style);
        // A reached Poem dispatch cap can suppress text without appending.
        // An image occurrence cannot succeed without its typed payload.
        if (self.spans.items.len <= before or self.spans.items[self.spans.items.len - 1].image == null) {
            self.fallbacks.render_limit = true;
            return error.RenderLimit;
        }
    }

    fn mediaOptionMode(file: []const u8, gallery_mode: bool) @import("namespace_registry").image_options.Mode {
        const ext = std.fs.path.extension(file);
        const timed = media_types.kind(file) == .audio or oneOf(ext, &.{ ".webm", ".ogv", ".mp4" });
        if (gallery_mode) return if (timed) .timed_gallery else .gallery;
        if (std.ascii.eqlIgnoreCase(ext, ".pdf")) return .pdf;
        if (std.ascii.eqlIgnoreCase(ext, ".djvu") or std.ascii.eqlIgnoreCase(ext, ".djv")) return .djvu;
        if (std.ascii.eqlIgnoreCase(ext, ".svg")) return .svg;
        return if (timed) .timed else .image;
    }
    fn mediaTime(input: []const u8) bool {
        var parts = std.mem.splitScalar(u8, input, ':');
        var count: usize = 0;
        while (parts.next()) |part| {
            count += 1;
            if (count > 3 or !mediaNumber(trim(part))) return false;
        }
        return true;
    }
    fn mediaOption(self: *Renderer, value: []const u8, mode: @import("namespace_registry").image_options.Mode, seen_format: *bool) ?@import("namespace_registry").image_options.Match {
        const options = @import("namespace_registry").image_options;
        const option = trim(value);
        const found = if (self.context.image_options) |registry| registry.match(option, mode) else options.matchEnglish(option, mode);
        const matched = found orelse return null;
        if (oneOf(matched.id, &.{ "img_thumbnail", "img_framed", "img_frameless", "img_manualthumb" })) {
            const valid = !seen_format.*;
            seen_format.* = true;
            if (!valid) return null;
        } else if (matched.value) |parameter| {
            if (std.mem.eql(u8, matched.id, "img_page")) {
                const page = std.mem.trim(u8, parameter, " \n\r\t\x0b\x00");
                if (mode == .pdf) {
                    if (page.len == 0) return null;
                    for (page) |byte| if (!std.ascii.isDigit(byte)) return null;
                } else {
                    const number = std.fmt.parseInt(i64, page, 10) catch return null;
                    var buffer: [32]u8 = undefined;
                    const canonical = std.fmt.bufPrint(&buffer, "{d}", .{number}) catch return null;
                    if (!std.mem.eql(u8, page, canonical)) return null;
                }
            }
            if (std.mem.eql(u8, matched.id, "img_lang") and !mediaLanguageTag(parameter)) return null;
            if (oneOf(matched.id, &.{ "timedmedia_thumbtime", "timedmedia_starttime", "timedmedia_endtime" }) and !mediaTime(parameter)) return null;
            if (std.mem.eql(u8, matched.id, "timedmedia_disablecontrols")) {
                var controls = std.mem.splitScalar(u8, parameter, ',');
                while (controls.next()) |control| {
                    if (!(std.mem.eql(u8, control, "options") or std.mem.eql(u8, control, "timedText") or std.mem.eql(u8, control, "fullscreen"))) return null;
                }
            }
            if (oneOf(matched.id, &.{ "img_upright", "img_left", "img_right", "img_center", "img_none", "img_baseline", "img_sub", "img_super", "img_top", "img_text_top", "img_middle", "img_bottom", "img_text_bottom", "img_border" }) and !mediaNumber(trim(parameter))) return null;
        }
        return matched;
    }
    fn tagAlpha(part: []const u8) bool {
        for (part) |c| if (!std.ascii.isAlphabetic(c)) return false;
        return true;
    }
    fn tagAlnum(part: []const u8) bool {
        for (part) |c| if (!std.ascii.isAlphanumeric(c)) return false;
        return true;
    }
    fn mediaLanguageTag(raw: []const u8) bool {
        // LanguageCode::isWellFormedLanguageTag current retained source, not code registration.
        // PCRE dollar accepts a final LF; no other surrounding whitespace is permitted.
        const input = if (std.mem.endsWith(u8, raw, "\n")) raw[0 .. raw.len - 1] else raw;
        if (oneOf(input, &.{ "en-gb-oed", "i-ami", "i-bnn", "i-default", "i-enochian", "i-hak", "i-klingon", "i-lux", "i-mingo", "i-navajo", "i-pwn", "i-tao", "i-tay", "i-tsu", "no-bok", "no-nyn", "sgn-be-fr", "sgn-be-nl", "sgn-ch-de", "zh-min-nan" })) return true;
        var parts = std.mem.splitScalar(u8, input, '-');
        const primary = parts.next() orelse return false;
        var next = parts.next();
        if (std.ascii.eqlIgnoreCase(primary, "x")) return tagPrivate(next, &parts);
        if (primary.len < 2 or primary.len > 8 or !tagAlpha(primary)) return false;
        if (next) |p| if (primary.len <= 3 and p.len == 3 and tagAlpha(p)) {
            next = parts.next();
        };
        if (next) |p| if (p.len == 4 and tagAlpha(p)) {
            next = parts.next();
        };
        if (next) |p| {
            var region = p.len == 2 and tagAlpha(p);
            if (p.len == 3) {
                region = true;
                for (p) |c| {
                    if (!std.ascii.isDigit(c)) region = false;
                }
            }
            if (region) next = parts.next();
        }
        while (next) |p| {
            if (tagAlnum(p) and ((p.len >= 5 and p.len <= 8) or (p.len == 4 and std.ascii.isDigit(p[0])))) next = parts.next() else break;
        }
        while (next) |p| {
            if (std.ascii.eqlIgnoreCase(p, "x")) return tagPrivate(parts.next(), &parts);
            if (p.len != 1 or !tagAlpha(p)) return false;
            next = parts.next();
            var count: usize = 0;
            while (next) |value| {
                if (value.len < 2 or value.len > 8 or !tagAlnum(value)) break;
                count += 1;
                next = parts.next();
            }
            if (count == 0) return false;
        }
        return true;
    }
    fn tagPrivate(first: ?[]const u8, parts: *std.mem.SplitIterator(u8, .scalar)) bool {
        var next = first;
        if (next == null) return false;
        while (next) |p| {
            if (p.len == 0 or p.len > 8 or !tagAlnum(p)) return false;
            next = parts.next();
        }
        return true;
    }
    fn mediaNumber(input: []const u8) bool {
        // PHP is_numeric's decimal/exponent syntax, without accepting NaN/Inf.
        var cursor: usize = 0;
        if (cursor < input.len and (input[cursor] == '+' or input[cursor] == '-')) cursor += 1;
        var digits: usize = 0;
        while (cursor < input.len and std.ascii.isDigit(input[cursor])) : (cursor += 1) digits += 1;
        if (cursor < input.len and input[cursor] == '.') {
            cursor += 1;
            while (cursor < input.len and std.ascii.isDigit(input[cursor])) : (cursor += 1) digits += 1;
        }
        if (digits == 0) return false;
        if (cursor < input.len and (input[cursor] == 'e' or input[cursor] == 'E')) {
            cursor += 1;
            if (cursor < input.len and (input[cursor] == '+' or input[cursor] == '-')) cursor += 1;
            const begin = cursor;
            while (cursor < input.len and std.ascii.isDigit(input[cursor])) : (cursor += 1) {}
            if (begin == cursor) return false;
        }
        return cursor == input.len;
    }
    const MediaLabelChoice = struct { text: []const u8, authored_caption: bool, link_target: ?[]const u8 = null, unframed_tooltip: ?[]const u8 = null };
    fn mediaCaption(self: *Renderer, raw: []const u8, fallback: []const u8, mode: @import("namespace_registry").image_options.Mode) []const u8 {
        return self.mediaCaptionChoice(raw, fallback, mode).text;
    }
    fn mediaCaptionChoice(self: *Renderer, raw: []const u8, fallback: []const u8, mode: @import("namespace_registry").image_options.Mode) MediaLabelChoice {
        var candidate: []const u8 = "";
        var link_target: ?[]const u8 = null;
        // Timed media has no visible caption without a thumbnail or frame.
        // Unknown words such as noicon remain captions when that frame exists.
        var caption_visible = mode != .timed;
        var seen_format = false;
        var pos: usize = 0;
        while (pos <= raw.len) {
            const end = syntax.delimiter(raw, "|", pos) orelse raw.len;
            const part = trim(raw[pos..end]);
            if (self.mediaOption(part, mode, &seen_format)) |matched| {
                if (oneOf(matched.id, &.{ "img_thumbnail", "img_framed", "img_manualthumb" })) caption_visible = true;
                if (std.mem.eql(u8, matched.id, "img_link")) link_target = matched.value orelse "";
            } else candidate = part;
            if (end == raw.len) break;
            pos = end + 1;
        }
        const tooltip = if (!caption_visible and candidate.len != 0) candidate else null;
        if (!caption_visible) candidate = "";
        return .{ .text = if (candidate.len == 0) fallback else candidate, .authored_caption = candidate.len != 0, .link_target = link_target, .unframed_tooltip = tooltip };
    }
    // Parser::stripAltText replaces parsed link holders by DISPLAY text and
    // strips formatting before interpreting link=. Reuse normal inline parsing
    // in an isolated arena: nowiki remains literal, entities decode once, and
    // references/media/numbering from an option cannot become page content.
    fn mediaLinkText(self: *Renderer, raw: []const u8) Error![]const u8 {
        if (self.media_action_depth >= max_depth) {
            self.fallbacks.render_limit = true;
            return error.RenderLimit;
        }
        var arena = std.heap.ArenaAllocator.init(self.a);
        defer arena.deinit();
        var probe: Renderer = .{ .a = arena.allocator(), .context = self.context, .media_depth = self.media_depth, .media_action_depth = self.media_action_depth + 1, .nodes = self.nodes };
        defer self.nodes = probe.nodes;
        const spans = try probe.parseSpans(raw, .{});
        if (probe.truncated or probe.fallbacks.render_limit) {
            self.fallbacks.render_limit = true;
            return error.RenderLimit;
        }
        return self.a.dupe(u8, try plainText(arena.allocator(), spans));
    }
    // Media identity/caption metadata stays attached to the source file. Only
    // the occurrence's semantic click action follows the recognized link option.
    fn mediaActionStyle(self: *Renderer, original: Style, file: []const u8, override: ?[]const u8) Error!Style {
        var style = original;
        style.kind = .link;
        const resolved_file = (try self.resolvedMediaFile(file)) orelse file;
        style.target = try std.fmt.allocPrint(self.a, "File:{s}", .{resolved_file});
        const raw = override orelse return style;
        const value = trim(try self.withoutBehaviorControls(raw));
        if (value.len == 0) {
            style.kind = .text;
            style.target = "";
            return style;
        }
        const formatted = std.mem.indexOfAny(u8, value, "<[") != null or std.mem.indexOf(u8, value, "''") != null;
        var target = trim(if (formatted) try self.mediaLinkText(value) else try self.entityText(value));
        if (target.len == 0) {
            style.kind = .text;
            style.target = "";
            return style;
        }
        // Native URL parser functions preserve an active missing title parameter
        // rather than laundering it into percent escapes. Keep this occurrence's
        // visible file label, but neither invent a File action nor retain a parent.
        // Formatted/protected literals and authored percent-encoded URLs do not
        // enter this narrow active-parameter path.
        if (!formatted and std.mem.indexOf(u8, value, "{{{") != null) {
            style.kind = .text;
            style.target = "";
            style.self_link_target = null;
            self.fallbacks.rejected_external_target = true;
            self.fallbacks.missing_template = true;
            self.unresolved_templates += 1;
            return style;
        }
        if (ir.hasExternalProtocol(target)) {
            // Plain authored URLs retain the established escaping path. Parsed
            // display text is already entity-decoded: never decode it again.
            if (!formatted) target = try self.externalUrlTarget(value);
            if (safeUrl(target) and !unresolvedExternalActionTarget(target)) {
                style.kind = .external_link;
                style.target = target;
            }
            // Invalid nonempty overrides keep the pre-existing File action.
            return style;
        }
        // Only the title branch percent-decodes (Parser::parseLinkParameter).
        // URL percent escapes above remain unchanged.
        if (std.mem.indexOfScalar(u8, target, '%') != null)
            target = std.Uri.percentDecodeInPlace(try self.a.dupe(u8, target));
        if (std.mem.indexOfAny(u8, target, "<>") != null) return style;
        if (std.mem.indexOfScalar(u8, target, '_') != null) {
            const normalized = try self.a.dupe(u8, target);
            std.mem.replaceScalar(u8, normalized, '_', ' ');
            target = normalized;
        }
        if (starts(target, ":")) target = target[1..];
        target = self.currentWikiTarget(target);
        if (target.len != 0 and safeInternalTarget(target)) {
            const destination = try self.interwikiDestination(target, 0);
            style.kind = if (destination.target.len == 0) .text else if (destination.external) .external_link else .link;
            style.target = destination.target;
        }
        return style;
    }
    fn mediaHeadingCaption(self: *Renderer, raw: []const u8, file: []const u8) MediaLabelChoice {
        var caption: []const u8 = "";
        var alt: []const u8 = "";
        const mode = mediaOptionMode(file, false);
        var caption_visible = mode != .timed;
        var seen_format = false;
        var pos: usize = 0;
        while (pos <= raw.len) {
            const end = syntax.delimiter(raw, "|", pos) orelse raw.len;
            const part = trim(raw[pos..end]);
            if (self.mediaOption(part, mode, &seen_format)) |matched| {
                if (oneOf(matched.id, &.{ "img_thumbnail", "img_framed", "img_manualthumb" })) caption_visible = true;
                if (std.mem.eql(u8, matched.id, "img_alt")) alt = trim(matched.value orelse "");
            } else caption = part;
            if (end == raw.len) break;
            pos = end + 1;
        }
        if (!caption_visible) return .{ .text = "", .authored_caption = false };
        return .{ .text = if (caption.len != 0) caption else alt, .authored_caption = caption.len != 0 };
    }
    fn normalizedTag(self: *Renderer, tag: syntax.Tag) Error!syntax.Tag {
        if (std.mem.indexOfScalar(u8, tag.attrs, '<') == null) return tag;
        var out: std.ArrayList(u8) = .empty;
        var copied: usize = 0;
        var cursor: usize = 0;
        var no_more_close = false;
        var changed = false;
        while (std.mem.indexOfScalarPos(u8, tag.attrs, cursor, '<')) |open| {
            const region = syntax.nowikiRegionAtCached(tag.attrs, open, &no_more_close) orelse {
                cursor = open + 1;
                continue;
            };
            try out.appendSlice(self.a, tag.attrs[copied..open]);
            if (!region.self_closing) for (tag.attrs[region.opening_end..region.inner_end]) |byte| {
                // Preserve entity spellings and raw quote/whitespace semantics.
                switch (byte) {
                    '<' => try out.appendSlice(self.a, "&lt;"),
                    '>' => try out.appendSlice(self.a, "&gt;"),
                    else => try out.append(self.a, byte),
                }
            };
