                if (at != first) {
                    const raw_decoded = std.fmt.parseInt(u32, value[first..at], 16) catch return null;
                    const decoded: u21 = if (raw_decoded == 0 or raw_decoded > 0x10ffff or (raw_decoded >= 0xd800 and raw_decoded <= 0xdfff)) 0xfffd else @intCast(raw_decoded);
                    if (at < value.len and std.ascii.isWhitespace(value[at])) {
                        const cr = value[at] == '\r';
                        at += 1;
                        if (cr and at < value.len and value[at] == '\n') at += 1;
                    }
                    if (decoded > 0x7f) {
                        var encoded: [4]u8 = undefined;
                        const count = std.unicode.utf8Encode(decoded, &encoded) catch return null;
                        if (used + count > buffer.len) return null;
                        @memcpy(buffer[used..][0..count], encoded[0..count]);
                        used += count;
                        continue;
                    }
                    byte = @intCast(decoded);
                } else {
                    byte = value[at];
                    at += 1;
                }
                // An escaped delimiter remains inside one identifier, and
                // therefore cannot create a valid display keyword sequence.
                if (!(std.ascii.isAlphanumeric(byte) or byte == '-' or byte == '_')) return null;
            } else if (std.ascii.isWhitespace(byte)) {
                byte = ' ';
                if (used == 0 or buffer[used - 1] == ' ') continue;
            }
            if (used == buffer.len) return null;
            buffer[used] = byte;
            used += 1;
        }
        return trim(buffer[0..used]);
    }

    fn displayPriorityBang(value: []const u8) ?usize {
        var at: usize = 0;
        var depth: usize = 0;
        var quote: u8 = 0;
        while (at < value.len) : (at += 1) {
            const byte = value[at];
            if (byte == '\\') {
                if (at + 1 < value.len) at += 1;
                continue;
            }
            if (quote != 0) {
                if (byte == quote) quote = 0;
                continue;
            }
            if (byte == '\'' or byte == '"') quote = byte;
            if (byte == '(' or byte == '[' or byte == '{') depth += 1;
            if ((byte == ')' or byte == ']' or byte == '}') and depth != 0) depth -= 1;
            if (byte == '!' and depth == 0 and quote == 0) return at;
        }
        return null;
    }

    fn displayCompoundValid(value: []const u8) bool {
        var outside = false;
        var inside = false;
        var list_item = false;
        var list_inside = true;
        var count: usize = 0;
        var tokens = std.mem.tokenizeAny(u8, value, " \t\r\n\x0c");
        while (tokens.next()) |token| {
            count += 1;
            if (count > 3) return false;
            if (std.ascii.eqlIgnoreCase(token, "list-item")) {
                if (list_item) return false;
                list_item = true;
            } else if (std.ascii.eqlIgnoreCase(token, "block") or std.ascii.eqlIgnoreCase(token, "inline") or std.ascii.eqlIgnoreCase(token, "run-in")) {
                if (outside) return false;
                outside = true;
            } else {
                var valid_inside = false;
                for ([_][]const u8{ "flow", "flow-root", "table", "flex", "grid", "ruby", "math" }) |name| {
                    if (std.ascii.eqlIgnoreCase(token, name)) valid_inside = true;
                }
                if (!valid_inside or inside) return false;
                inside = true;
                list_inside = std.ascii.eqlIgnoreCase(token, "flow") or std.ascii.eqlIgnoreCase(token, "flow-root");
            }
        }
        return count > 1 and (!list_item or list_inside);
    }

    // CSS substitution functions defer display's grammar until computed-value
    // time. Arbitrary functions (calc, url, etc.) do not have that privilege.
    fn displaySubstitution(value: []const u8) bool {
        var at: usize = 0;
        var depth: usize = 0;
        var quote: u8 = 0;
        var found = false;
        var identifier_continuation = false;
        while (at < value.len) : (at += 1) {
            const byte = value[at];
            if (byte == '\\') {
                if (at + 1 == value.len or value[at + 1] == '\n' or value[at + 1] == '\r') return false;
                at += 1;
                if (std.ascii.isHex(value[at])) {
                    const first = at;
                    while (at + 1 < value.len and at + 1 - first < 6 and std.ascii.isHex(value[at + 1])) : (at += 1) {}
                    if (at + 1 < value.len and std.ascii.isWhitespace(value[at + 1])) at += 1;
                }
                identifier_continuation = true;
                continue;
            }
            if (quote != 0) {
                if (byte == quote) {
                    quote = 0;
                    identifier_continuation = false;
                }
                continue;
            }
            if (byte == '\'' or byte == '"') {
                quote = byte;
                identifier_continuation = false;
                continue;
            }
            const begins_identifier = !identifier_continuation;
            identifier_continuation = std.ascii.isAlphanumeric(byte) or byte == '-' or byte == '_' or byte >= 0x80;
            if (byte == '(') depth += 1;
            if (byte == ')') {
                if (depth == 0) return false;
                depth -= 1;
            }
            if (!begins_identifier) continue;
            const var_fn = value.len - at >= 4 and std.ascii.eqlIgnoreCase(value[at..][0..4], "var(");
            const env_fn = value.len - at >= 4 and std.ascii.eqlIgnoreCase(value[at..][0..4], "env(");
            if (!var_fn and !env_fn) continue;
            const argument = std.mem.trimStart(u8, value[at + 4 ..], " \t\r\n\x0c");
            const end = std.mem.indexOfAny(u8, argument, ",) \t\r\n\x0c") orelse return false;
            const name = argument[0..end];
            if (name.len == 0 or (var_fn and (name.len <= 2 or !starts(name, "--")))) return false;
            for (name) |ch| if (!(std.ascii.isAlphanumeric(ch) or ch == '-' or ch == '_' or ch >= 0x80)) return false;
            if (env_fn) {
                if (std.ascii.isDigit(name[0]) or (name[0] == '-' and (name.len == 1 or std.ascii.isDigit(name[1])))) return false;
                for ([_][]const u8{ "initial", "inherit", "unset", "revert", "revert-layer", "default" }) |reserved| {
                    if (std.ascii.eqlIgnoreCase(name, reserved)) return false;
                }
            }
            var tail = std.mem.trimStart(u8, argument[end..], " \t\r\n\x0c");
            while (env_fn and tail.len != 0 and tail[0] != ',' and tail[0] != ')') {
                const index_end = std.mem.indexOfAny(u8, tail, ",) \t\r\n\x0c") orelse return false;
                const index = tail[0..index_end];
                const digits = if (index.len != 0 and (index[0] == '+' or index[0] == '-')) index[1..] else index;
                if (digits.len == 0) return false;
                for (digits) |digit| if (!std.ascii.isDigit(digit) or (index[0] == '-' and digit != '0')) return false;
                tail = std.mem.trimStart(u8, tail[index_end..], " \t\r\n\x0c");
            }
            if (tail.len == 0 or (tail[0] != ',' and tail[0] != ')')) return false;
            found = true;
        }
        return found and depth == 0 and quote == 0;
    }

    // Resolve static source-profile and inline declarations with the same value
    // grammar. An uncertain winning selector or missing sheet preserves content.
    fn htmlDisplayNone(self: *Renderer, tag: syntax.Tag) Error!bool {
        return self.htmlDisplayNoneIn(tag, null);
    }
    fn htmlDisplayNoneIn(self: *Renderer, tag: syntax.Tag, parent: ?*const table_style_profile.TextElement) Error!bool {
        var cascade: table_style_profile.DisplayCascade = .{};
        if (self.context.table_styles) |profile| if (profile.display_rules.len != 0) {
            var rules = profile.displayRules(tag.name,
                (try self.semanticAttribute(tag, "class")) orelse "",
                (try self.semanticAttribute(tag, "id")) orelse "");
            const node = if (hasCompleteAncestorClasses(parent) or (parent == null and self.boundedTextClassScopeFor(tag) != null))
                try self.textElement(tag, parent, "") else null;
            rules.complete_ancestor_classes = if (node) |value| value.complete_ancestor_classes else null;
            rules.physical_parent_tag = self.physicalDisplayParent(tag);
            while (rules.next()) |rule|
                try self.applyDisplayCss(&cascade, rule.css, rule.specificity, rule.order, rule.uncertain, false);
        };
        if (try self.semanticAttribute(tag, "style")) |css|
            try self.applyDisplayCss(&cascade, css, 0, 0, false, true);
        if (cascade.seen) if (self.context.table_styles) |profile| if (profile.globally_unresolved) {
            // An unavailable import may contain an important override. A known
            // inline important declaration still outranks author stylesheets.
            cascade.consider(null, true, std.math.maxInt(u32), std.math.maxInt(u32), false);
        };
        if (cascade.hidden) |resolved| return resolved;
        self.fallbacks.unsupported_element = true;
        return false;
    }

    fn applyDisplayCss(self: *Renderer, cascade: *table_style_profile.DisplayCascade, css: []const u8, specificity: u32, base_order: u32, uncertain: bool, inline_style: bool) Error!void {
        var pos: usize = 0;
        var order = base_order;
        while (try self.nextColorDeclaration(css, &pos)) |raw| {
            order += 1;
            const colon = std.mem.indexOfScalar(u8, raw, ':') orelse continue;
            const property = trim(raw[0..colon]);
            const all = std.ascii.eqlIgnoreCase(property, "all");
            const escaped_property = std.mem.indexOfScalar(u8, property, '\\') != null;
            if (!all and !escaped_property and !std.ascii.eqlIgnoreCase(property, "display")) continue;
            var value = trim(raw[colon + 1 ..]);
            var important = false;
            if (displayPriorityBang(value)) |bang| {
                var priority_buffer: [256]u8 = undefined;
                const priority = displayLiteral(trim(value[bang + 1 ..]), &priority_buffer) orelse continue;
                if (!std.ascii.eqlIgnoreCase(priority, "important")) continue;
                important = true;
                value = trim(value[0..bang]);
            }
            if (escaped_property) {
                cascade.consider(null, important, specificity, order, inline_style);
                continue;
            }
            var substitution = displaySubstitution(value);
            var literal_buffer: [256]u8 = undefined;
            if (!substitution) {
                value = displayLiteral(value, &literal_buffer) orelse continue;
                substitution = displaySubstitution(value);
            }
            if (all) {
                const initial = std.ascii.eqlIgnoreCase(value, "initial") or std.ascii.eqlIgnoreCase(value, "unset");
                const contextual = std.ascii.eqlIgnoreCase(value, "inherit") or std.ascii.eqlIgnoreCase(value, "revert") or std.ascii.eqlIgnoreCase(value, "revert-layer");
                if (!initial and !contextual and !substitution) continue;
                // all expands in place to display's CSS-wide reset. Display
                // is non-inherited, so both initial and unset remove none.
                cascade.consider(if (initial and !uncertain) false else null, important, specificity, order, inline_style);
                continue;
            }
            const none = std.ascii.eqlIgnoreCase(value, "none");
            var supported = none;
            for ([_][]const u8{ "inline", "block", "inline-block", "table", "inline-table", "table-row", "table-cell", "table-row-group", "table-header-group", "table-footer-group", "table-caption", "table-column", "table-column-group", "list-item", "flex", "inline-flex", "grid", "inline-grid", "contents", "flow", "flow-root", "initial", "unset" }) |name| {
                if (std.ascii.eqlIgnoreCase(value, name)) supported = true;
            }
            var unresolved = displayCompoundValid(value) or substitution;
            for ([_][]const u8{ "inherit", "revert", "revert-layer", "run-in", "ruby", "ruby-base", "ruby-text", "ruby-base-container", "ruby-text-container", "math" }) |name| {
                if (std.ascii.eqlIgnoreCase(value, name)) unresolved = true;
            }
            if (supported) {
                cascade.consider(if (uncertain) null else none, important, specificity, order, inline_style);
            } else if (unresolved) {
                // Preserve an explicit unsupported-style diagnostic rather than
                // silently projecting inherited, dynamic or compound display.
                cascade.consider(null, important, specificity, order, inline_style);
            } else continue; // An unknown standalone keyword is invalid CSS.
        }
    }

    // Span capture owns a separate presentation array but deliberately retains
    // reference registries and ordinals. Hidden boxes still participate in the
    // page's citation semantics, including definitions used outside the scope.
    fn consumeHiddenHtml(self: *Renderer, content: []const u8, style: Style, depth: usize) Error!void {
        const tracked = if (self.inline_missing) |parent|
            try missingSlice(self.a, parent, content)
        else if (self.body_missing) |parent|
            try missingSlice(self.a, parent, content)
        else
            MissingText.untracked(content);
        const parent = self.spans;
        const parent_table = self.inline_table_boundaries;
        const parent_capture = self.semantic_capture;
        self.spans = .empty;
        self.inline_table_boundaries = null;
        self.semantic_capture = null;
        defer {
            self.spans.deinit(self.a);
            self.spans = parent;
            self.inline_table_boundaries = parent_table;
            self.semantic_capture = parent_capture;
        }
        try self.inlineTextWithMissing(tracked, style, depth + 1);
    }

    fn observeHiddenHtml(self: *Renderer, input: []const u8, origin: ?usize, opening: usize, tag: syntax.Tag, pair: syntax.Pair) Error!void {
        const observer = self.pre_scope_observer orelse return;
        if (origin == null or self.in_reference or self.pre_block or self.parsed_pre) return;
        const rest = input[opening..];
        const matched = syntax.matchingTag(rest, tag) orelse return;
        if (matched.inner_end != pair.inner_end or matched.end != pair.end) return;
        try observer.enter(observer.ctx, input, origin, opening, opening + tag.end, opening + pair.inner_end, opening + pair.end, true, .hidden, self.block_formatting, "", self.formattingAttributes());
    }

    // Canonical opaque named/hex RGB only. No dynamic CSS values are evaluated.
    fn canonicalColor(self: *Renderer, raw: []const u8) Error!?[]const u8 {
        return table_style_profile.canonicalColorAlloc(self.a, raw);
    }

    // Split declarations at top-level semicolons only. Quoted font names,
    // escaped bytes and function bodies cannot create a color declaration.
    fn nextColorDeclaration(self: *Renderer, css: []const u8, pos: *usize) Error!?[]const u8 {
        return table_style_profile.nextDeclarationAlloc(self.a, css, pos);
    }

    fn customParent(self: *Renderer, style: Style) table_style_profile.CustomEnvironment {
        if (style.custom_properties) |value| return value;
        if (self.body_language_direction) |body| if (body.custom_properties) |value| return value;
        if (self.body_formatting_attributes.custom_properties) |value| return value;
        if (self.context.table_styles) |profile| {
            if (profile.page_style_parent != null) return .{};
            if (profile.custom_properties) |custom| if (custom.appliesTo(self.context.title)) return custom.root_environment;
        }
        return .{};
    }
    fn customElement(self: *Renderer, tag: syntax.Tag, inherited: Style) Error!?table_style_profile.CustomEnvironment {
        const profile = self.context.table_styles orelse return null;
        const custom = profile.custom_properties orelse return null;
        if (!custom.appliesTo(self.context.title)) return null;
        if (profile.page_style_parent != null) {
            // A logical parent cannot lend local variables across an unproved
            // generated boundary. The invariant is a computed value at every
            // observed element, not an assumed parser-root default.
            if (self.pageStyleRootForTag(tag, inherited.text_element) == null) return .{};
            const domain = self.pageStyleDomain() orelse return .{};
            if (self.sourceRootChildForTag(tag) == null) {
                if (!self.sourceCustomElementForTag(tag)) return .{};
                const invariant = domain.scope.page_custom_invariant orelse return .{};
                const own = try custom.element(self.a, invariant, .{
                    .tag = tag.name, .classes = (try self.semanticAttribute(tag, "class")) orelse "",
                    .id = (try self.semanticAttribute(tag, "id")) orelse "",
                }, (try self.semanticAttribute(tag, "style")) orelse "");
                return try table_style_profile.intersectCustomEnvironmentsAlloc(self.a, invariant, own);
            }
            const root = domain.scope.page_style_complete_root orelse return .{};
            const left = root.observed_custom_environment orelse return .{};
            const right = (root.alternative_ancestry orelse return .{}).observed_custom_environment orelse return .{};
            const parent = try table_style_profile.intersectCustomEnvironmentsAlloc(self.a, left, right);
            return try custom.element(self.a, parent, .{
                .tag = tag.name, .classes = (try self.semanticAttribute(tag, "class")) orelse "",
                .id = (try self.semanticAttribute(tag, "id")) orelse "",
            }, (try self.semanticAttribute(tag, "style")) orelse "");
        }
        return try custom.element(self.a, self.customParent(inherited), .{
            .tag = tag.name, .classes = (try self.semanticAttribute(tag, "class")) orelse "",
            .id = (try self.semanticAttribute(tag, "id")) orelse "",
        }, (try self.semanticAttribute(tag, "style")) orelse "");
    }

    const AuthoredColor = struct { value: ?[]const u8, specified: bool = false };
    fn authoredColor(self: *Renderer, tag: syntax.Tag, property: []const u8, legacy: ?[]const u8, fallback: ?[]const u8) Error!AuthoredColor {
        return self.authoredColorIn(tag, property, legacy, fallback, .{});
    }
    fn authoredColorIn(self: *Renderer, tag: syntax.Tag, property: []const u8, legacy: ?[]const u8, fallback: ?[]const u8, environment: table_style_profile.CustomEnvironment) Error!AuthoredColor {
        var result: AuthoredColor = .{ .value = fallback };
        if (legacy) |attribute| if (try self.semanticAttribute(tag, attribute)) |raw| {
            result = .{ .value = try self.canonicalColor(raw), .specified = true };
        };
        const css = (try self.semanticAttribute(tag, "style")) orelse return result;
        var pos: usize = 0;
        var important_seen = false;
        while (try self.nextColorDeclaration(css, &pos)) |raw| {
            const colon = std.mem.indexOfScalar(u8, raw, ':') orelse continue;
            const name = trim(raw[0..colon]);
            const matches = std.ascii.eqlIgnoreCase(name, property);
            const background_reset = std.ascii.eqlIgnoreCase(property, "background-color") and
                std.ascii.eqlIgnoreCase(name, "background");
            if (!matches and !background_reset) continue;
            var value = trim(raw[colon + 1 ..]);
            const variable = std.mem.indexOf(u8, value, "var(") != null;
            var variable_unknown = false;
            var important = false;
            if (variable) {
                const priority = table_style_profile.customPriority(value);
                value = priority.value;
                important = priority.important;
                variable_unknown = priority.unknown;
            } else if (std.mem.lastIndexOfScalar(u8, value, '!')) |bang| {
                if (!std.ascii.eqlIgnoreCase(trim(value[bang + 1 ..]), "important")) continue;
                important = true;
                value = trim(value[0..bang]);
            }
            var variable_invalid = false;
            var variable_unrepresented = false;
            if (variable and !variable_unknown) switch (try table_style_profile.customColorValue(self.a, environment, value)) {
                .known => |resolved| value = resolved,
                .unknown => variable_unknown = true,
                .invalid => variable_invalid = true,
            };
            var next: ?[]const u8 = null;
            if (variable_unknown) {
                next = null;
            } else if (variable_invalid) {
                next = fallback;
            } else if (std.ascii.eqlIgnoreCase(value, "inherit") or std.ascii.eqlIgnoreCase(value, "unset") or
                std.ascii.eqlIgnoreCase(value, "currentcolor"))
            {
                next = if (std.ascii.eqlIgnoreCase(property, "color") or !std.ascii.eqlIgnoreCase(value, "currentcolor")) fallback else null;
            } else if (std.ascii.eqlIgnoreCase(value, "transparent") or std.ascii.eqlIgnoreCase(value, "initial") or
                (background_reset and std.ascii.eqlIgnoreCase(value, "none")))
            {
                next = if (std.ascii.eqlIgnoreCase(property, "background-color")) fallback else null;
            } else if (try self.canonicalColor(value)) |color| {
                // A single opaque color is also a complete supported shorthand.
                next = color;
            } else if (unrepresentedColorValue(value) or (background_reset and std.mem.indexOfAny(u8, value, " /\t") != null)) {
                // Valid dynamic/system/alpha or complex background values do
                // not have a supported opaque RGB projection. Suppress stale
                // prior color, without evaluating functions/images/layers.
                next = null;
                variable_unrepresented = variable;
            } else if (variable) {
                // Invalid at computed-value time does not revive an earlier
                // declaration and is not a reason to use the var fallback.
                next = fallback;
            } else continue; // An invalid declaration has no cascade priority.
            if (important_seen and !important) continue;
            important_seen = important;
            if (variable_unknown or variable_unrepresented) {
                if (self.context.table_styles) |profile| if (profile.custom_properties) |custom| {
                    if (custom.appliesTo(self.context.title)) self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "authoredColorIn.1", tag.attrs);
                };
            }
            result.specified = true;
            result.value = next;
        }
        return result;
    }

    fn unrepresentedColorValue(value: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(value, "revert") or std.ascii.eqlIgnoreCase(value, "revert-layer")) return true;
        const system_names = .{ "accentcolor", "accentcolortext", "activetext", "buttonborder", "buttonface", "buttontext", "canvas", "canvastext", "field", "fieldtext", "graytext", "highlight", "highlighttext", "linktext", "mark", "marktext", "selecteditem", "selecteditemtext", "visitedtext", "activeborder", "activecaption", "appworkspace", "background", "buttonhighlight", "buttonshadow", "captiontext", "inactiveborder", "inactivecaption", "inactivecaptiontext", "infobackground", "infotext", "menu", "menutext", "scrollbar", "threeddarkshadow", "threedface", "threedhighlight", "threedlightshadow", "threedshadow", "window", "windowframe", "windowtext" };
        inline for (system_names) |name| if (std.ascii.eqlIgnoreCase(value, name)) return true;
        if (std.mem.indexOfScalar(u8, value, '(')) |open| {
            const name = trim(value[0..open]);
            inline for (.{ "rgb", "rgba", "hsl", "hsla", "hwb", "lab", "lch", "oklab", "oklch", "color", "color-mix", "light-dark", "contrast-color", "device-cmyk", "var", "env", "url", "linear-gradient", "radial-gradient", "conic-gradient", "repeating-linear-gradient", "repeating-radial-gradient", "repeating-conic-gradient" }) |supported_function| {
                if (std.ascii.eqlIgnoreCase(name, supported_function)) return true;
            }
        }
        return false;
    }

    fn unresolvedEmBasis(style: Style, formatting: SpanFlags) bool {
        return style.heading or style.font_scale_set or style.font_scale != null or style.font_scale_basis != .context or
            formatting.small or formatting.superscript or formatting.subscript or formatting.code or
            style.small or style.superscript or style.subscript or style.code;
    }
    fn provedEmBodyScale(style: Style, formatting: SpanFlags) ?f32 {
        if (style.font_size_unknown or style.font_scale_basis != .normal_body or
            formatting.small or formatting.superscript or formatting.subscript or formatting.code or
            style.small or style.superscript or style.subscript or style.code) return null;
        const scale = style.font_scale orelse return null;
        return if (std.math.isFinite(scale) and scale >= 0) scale else null;
    }
    fn rebaseEmLength(value: *presentation_types.StyleLength, scale: f32) bool {
        if (value.unit != .em) return true;
        const product = @as(f64, value.value) * @as(f64, scale);
        if (!std.math.isFinite(product) or product < 0 or product > std.math.floatMax(f32)) return false;
        value.value = @floatCast(product);
        return true;
    }
    fn rebasedEmEdges(value: presentation_types.StyleEdges, scale: f32) ?presentation_types.StyleEdges {
        var result = value;
        if (!rebaseEmLength(&result.top, scale) or !rebaseEmLength(&result.right, scale) or
            !rebaseEmLength(&result.bottom, scale) or !rebaseEmLength(&result.left, scale)) return null;
        return result;
    }
    fn hasEmEdges(edges: presentation_types.StyleEdges) bool {
        return edges.top.unit == .em or edges.right.unit == .em or edges.bottom.unit == .em or edges.left.unit == .em;
    }
    fn hasEmBorderEdge(edge: presentation_types.StyleBorderEdge) bool {
        return switch (edge) { .none, .hidden => false, .solid, .dotted => |line| line.width.unit == .em };
    }
    fn hasEmBorder(border: presentation_types.StyleBorder) bool {
        return switch (border) {
            .none => false,
            .solid => |solid| solid.width.unit == .em,
            .edges => |edges| hasEmBorderEdge(edges.top) or hasEmBorderEdge(edges.right) or hasEmBorderEdge(edges.bottom) or hasEmBorderEdge(edges.left),
        };
    }
    fn rebaseEmBorderEdge(edge: *presentation_types.StyleBorderEdge, scale: f32) bool {
        return switch (edge.*) { .none, .hidden => true, .solid, .dotted => |*line| rebaseEmLength(&line.width, scale) };
    }
    fn rebasedEmBorder(value: presentation_types.StyleBorder, scale: f32) ?presentation_types.StyleBorder {
        var result = value;
        switch (result) {
            .none => {},
            .solid => |*solid| {
                if (!rebaseEmLength(&solid.width, scale)) return null;
            },
            .edges => |*edges| {
                if (!rebaseEmBorderEdge(&edges.top, scale) or !rebaseEmBorderEdge(&edges.right, scale) or
                    !rebaseEmBorderEdge(&edges.bottom, scale) or !rebaseEmBorderEdge(&edges.left, scale)) return null;
            },
        }
        return result;
    }
    fn guardTableEmStyle(self: *Renderer, resolved: *table_style_profile.TableResolution, style: Style, formatting: SpanFlags) void {
        self.guardTableEmStyleAt(resolved, style, formatting, "");
    }

    fn guardTableEmStyleAt(self: *Renderer, resolved: *table_style_profile.TableResolution, style: Style, formatting: SpanFlags, authored_attrs: []const u8) void {
        if (resolved.style) |*table| {
            const scale = provedEmBodyScale(style, formatting);
            const uncertain = self.table_style_font_unresolved or resolved.margin_basis_unresolved or unresolvedEmBasis(style, formatting) or style.font_size_unknown;
            if (table.margins) |margins| if (hasEmEdges(margins)) {
                if (scale) |known| { table.margins = rebasedEmEdges(margins, known); } else if (uncertain) { table.margins = null; }
                if (table.margins == null) self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "guardTableEmStyle.1", authored_attrs);
            };
            if (table.padding) |padding| if (hasEmEdges(padding)) {
                if (scale) |known| { table.padding = rebasedEmEdges(padding, known); } else if (uncertain) { table.padding = null; }
                if (table.padding == null) self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "guardTableEmStyle.2", authored_attrs);
            };
            if (table.width) |width| if (width.unit == .em) {
                if (scale) |known| {
                    var length: presentation_types.StyleLength = .{ .unit = .em, .value = width.value };
                    table.width = if (rebaseEmLength(&length, known)) .{ .unit = .em, .value = length.value } else null;
                } else if (uncertain) { table.width = null; }
                if (table.width == null) self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "guardTableEmStyle.3", authored_attrs);
            };
            if (table.border) |border| if (hasEmBorder(border)) {
                if (scale) |known| { table.border = rebasedEmBorder(border, known); } else if (uncertain) { table.border = null; }
                if (table.border == null) self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "guardTableEmStyle.4", authored_attrs);
            };
        }
        if (resolved.style) |table| if (!presentation_types.validTableStyle(table)) { resolved.style = null; };
    }
    fn guardCellEmStyle(self: *Renderer, resolved: *table_style_profile.CellResolution, style: Style, formatting: SpanFlags) void {
        self.guardCellEmStyleAt(resolved, style, formatting, "");
    }

    fn guardCellEmStyleAt(self: *Renderer, resolved: *table_style_profile.CellResolution, style: Style, formatting: SpanFlags, authored_attrs: []const u8) void {
        if (resolved.style) |*cell| {
            const scale = provedEmBodyScale(style, formatting);
            const uncertain = self.table_style_font_unresolved or resolved.padding_basis_unresolved or unresolvedEmBasis(style, formatting) or style.font_size_unknown;
            if (cell.width) |width| if (width.unit == .em and width.value != 0) {
                if (scale) |known| {
                    var length: presentation_types.StyleLength = .{ .unit = .em, .value = width.value };
                    cell.width = if (rebaseEmLength(&length, known)) .{ .unit = .em, .value = length.value } else null;
                } else if (uncertain) cell.width = null;
                if (cell.width == null) self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "guardCellEmStyle.1", authored_attrs);
            };
            if (cell.min_width) |minimum| if (minimum.unit == .em) {
                if (scale) |known| {
                    var computed = minimum;
                    cell.min_width = if (rebaseEmLength(&computed, known)) computed else null;
                } else if (uncertain) cell.min_width = null;
                if (cell.min_width == null) self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "guardCellEmStyle.2", authored_attrs);
            };
            if (cell.padding) |padding| if (hasEmEdges(padding)) {
                if (scale) |known| { cell.padding = rebasedEmEdges(padding, known); } else if (uncertain) { cell.padding = null; }
                if (cell.padding == null) self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "guardCellEmStyle.3", authored_attrs);
            };
            if (cell.border) |border| if (hasEmBorder(border)) {
                if (scale) |known| { cell.border = rebasedEmBorder(border, known); } else if (uncertain) { cell.border = null; }
                if (cell.border == null) self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "guardCellEmStyle.4", authored_attrs);
            };
        }
        if (resolved.style) |cell| if (!presentation_types.validCellStyle(cell)) { resolved.style = null; };
    }

    fn cssClassesWith(self: *Renderer, parent: []const u8, tag: syntax.Tag) Error![]const u8 {
        // These are wikitext control/opaque regions, not authored DOM ancestors.
        if (tag.closing or tag.self_closing or tag.isOpaque() or tag.html_pre or
            oneOf(tag.name, &.{ "noinclude", "onlyinclude", "includeonly", "nowiki" })) return parent;
        const names = trim((try self.semanticAttribute(tag, "class")) orelse "");
        if (names.len == 0) return parent;
        return if (parent.len == 0) names else try std.fmt.allocPrint(self.a, "{s} {s}", .{ parent, names });
    }

    // Only line terminators may precede the first authored root table. This
    // cannot hide an opening wrapper, prose, indentation or another construct.
    fn rootWikiTableLinePrefix(source: []const u8, start: usize) bool {
        if (start >= source.len) return false;
        for (source[0..start]) |byte| if (byte != '\r' and byte != '\n') return false;
        return true;
    }

    // The observer owns this state for one exact original whole-page parse only.
    const NeutralRootTablePrefix = struct {
        source: []const u8,
        end: usize = 0,
    };

    // A strict, single-physical-line structural classifier, not a rendering pass.
    // Every permitted holder closes on this line; unsupported syntax declines.
    fn neutralRootTableInline(self: *const Renderer, line: []const u8, depth: usize, allow_links: bool, allow_quotes: bool) bool {
        if (depth >= max_depth or !std.unicode.utf8ValidateSlice(line) or
            std.mem.indexOfAny(u8, line, "\r\n") != null) return false;
        var at: usize = 0;
        while (at < line.len) {
            const tail = line[at..];
            if (starts(tail, "-{")) {
                const stop = std.mem.indexOfPos(u8, line, at + 2, "}-") orelse return false;
                const body = trim(line[at + 2 .. stop]);
                if (body.len == 0 or std.mem.indexOfAny(u8, body, "{}[]<>|&'\";:") != null) return false;
                for (body) |byte| if (std.ascii.isControl(byte)) return false;
                at = stop + 2;
                continue;
            }
            if (tail[0] == '<') {
                const tag = syntax.tagAt(line, at) orelse return false;
                // Only the complete heading's ordinary SPAN is needed here.
                // No DIV, action, include, extension, protected or block holder.
                if (!tag.is("span") or tag.closing or tag.self_closing or !formattingAngleAttributesBalanced(tag.attrs) or
                    std.mem.indexOfAny(u8, tag.attrs, "<>{}&\r\n") != null) return false;
                const pair = syntax.matchingTag(line, tag) orelse return false;
                if (pair.end > line.len or pair.inner_end < tag.end or
                    !self.neutralRootTableInline(line[tag.end..pair.inner_end], depth + 1, allow_links, allow_quotes)) return false;
                at = pair.end;
                continue;
            }
            if (tail[0] == '[') {
                if (!allow_links or !starts(tail, "[[")) return false;
                const pair = syntax.balanced(line, at) orelse return false;
                if (pair.end > line.len) return false;
                const complete = line[at..pair.end];
                var iterator: ir.InlineIterator = .{ .input = complete, .renderer_boundaries = true, .link_trail = self.context.link_trail };
                const node = iterator.next() orelse return false;
                if (node.kind != .link or iterator.cursor != complete.len or node.trail.len != 0 or
                    node.link_empty_label or node.link_label_restored_close or node.target.len == 0 or
                    !safeInternalTarget(node.target) or std.mem.indexOfAny(u8, node.target, "[]{}<>|&'\r\n") != null) return false;
                if (self.namespaceOfTarget(node.target)) |ns| if (ns == 6 or ns == 14) return false;
                if (!self.neutralRootTableInline(node.text, depth + 1, false, allow_quotes)) return false;
                at = pair.end;
                continue;
            }
            if (tail[0] == '\'') {
                if (!allow_quotes) return false;
                var run: usize = 1;
                while (at + run < line.len and line[at + run] == '\'') : (run += 1) {}
                if (run != 2 and run != 3 and run != 5) return false;
                const closing = std.mem.indexOfScalarPos(u8, line, at + run, '\'') orelse return false;
                var closing_run: usize = 1;
                while (closing + closing_run < line.len and line[closing + closing_run] == '\'') : (closing_run += 1) {}
                if (closing_run != run or closing == at + run or
                    !self.neutralRootTableInline(line[at + run .. closing], depth + 1, allow_links, false)) return false;
                at = closing + run;
                continue;
            }
            if (std.mem.indexOfScalar(u8, "]{}>&", tail[0]) != null or
                (std.ascii.isControl(tail[0]) and tail[0] != '\t')) return false;
            at += 1;
        }
        return true;
    }

    fn neutralRootTableCategory(self: *const Renderer, line: []const u8) bool {
        if (line.len < 5 or !starts(line, "[[") or !std.mem.endsWith(u8, line, "]]")) return false;
        const target = line[2 .. line.len - 2];
        return target.len != 0 and target[0] != ':' and safeInternalTarget(target) and
            std.mem.indexOfAny(u8, target, "[]{}<>|&'\r\n") == null and self.namespaceOfTarget(target) == 14;
    }

    // This certifies ancestry of the supplied original bytes, not missing-content
    // recovery. Global unknown is preserved; disjoint tail diagnostics do not add
    // an authored wrapper. Known overlap, lost mapping or a copied source declines.
    fn neutralRootTableSourceRange(self: *const Renderer, source: []const u8, end: usize) bool {
        if (end > source.len) return false;
        if (self.body_missing) |tracked| {
            if (tracked.bytes.ptr != source.ptr or tracked.bytes.len != source.len or tracked.lost_missing_range) return false;
            for (tracked.ranges) |range| {
                if (range.start >= range.end or range.end > source.len or range.start < end) return false;
            }
            for (tracked.literal_curly_ranges) |range| {
                if (range.start >= range.end or range.end > source.len or range.start < end) return false;
            }
            for (tracked.generated_links) |range| {
                if (range.start >= range.end or range.end > source.len or range.start < end) return false;
            }
        }
        return true;
    }

    // 'state.end' is zero, or the end of a table accepted by advance below.
    // Never initialize it from a projected fragment, a copied buffer, an opening
    // list alone, or the generic wiki_table_tail_proof.completed_close.
    fn neutralRootTablePrefix(self: *Renderer, source: []const u8, opening: usize, state: *const NeutralRootTablePrefix) bool {
        const root = self.heading_source orelse return false;
        if (source.ptr != root.ptr or source.len != root.len or
            source.ptr != state.source.ptr or source.len != state.source.len or
            state.end > opening or opening >= source.len or
            (opening != 0 and source[opening - 1] != '\n') or !starts(source[opening..], "{|")) return false;
        if (self.body_depth != 1 or self.in_reference or self.pre_block or self.parsed_pre or
            self.block_formatting.code or self.in_template_literal_scope or self.poem_depth != 0 or
            self.explicit_wiki_label != null or self.body_link_target.len != 0 or self.inline_source_domain != null or
            self.context.namespace_catalog == null) return false;
        if (!self.neutralRootTableSourceRange(source, opening)) return false;
        const matcher = self.behaviorControlMatcher();
        var at = state.end;
        while (at < opening) {
            const end = std.mem.indexOfScalarPos(u8, source, at, '\n') orelse return false;
            if (end >= opening) return false;
            const line = std.mem.trimEnd(u8, source[at..end], "\r");
            if (line.len == 0) {
                at = end + 1;
                continue;
            }
            // Use only authenticated empty behavior controls, not __TOC__ and not
            // a spelling guessed from a missing behavior registry.
            if (matcher != null and syntax.leadingBehaviorControlOffset(line, matcher) == line.len) {
                at = end + 1;
                continue;
            }
            if (headingLineControlled(line, matcher)) |heading| {
                // Check the whole line too: a control/heading recognizer must not
                // conceal an unmatched HTML or action suffix outside its title.
                if (heading.title.len == 0 or !self.neutralRootTableInline(line, 0, true, true)) return false;
                at = end + 1;
                continue;
            }
            if (self.neutralRootTableCategory(line)) {
                at = end + 1;
                continue;
            }
            return false;
        }
        return at == opening;
    }

    // Call ONLY after the ordinary table parser reports completed_close for the
    // same exact source/opening and confirms projected tag=table,parent=null.
    // This strict nonnested-table check refuses malformed/fostered holder leakage
    // before allowing that completed table to serve as a prefix for the next one.
    fn advanceNeutralRootTablePrefix(self: *Renderer, source: []const u8, opening: usize, close: []const u8, state: *NeutralRootTablePrefix) bool {
        if (!self.neutralRootTablePrefix(source, opening, state)) return false;
        const base = @intFromPtr(source.ptr);
        const pointer = @intFromPtr(close.ptr);
        if (close.len != 2 or !std.mem.eql(u8, close, "|}") or pointer < base or
            pointer - base > source.len or close.len > source.len - (pointer - base)) return false;
        const closing = pointer - base;
        if (closing <= opening or source[closing - 1] != '\n') return false;
        const close_end = std.mem.indexOfScalarPos(u8, source, closing, '\n') orelse source.len;
        if (std.mem.trim(u8, source[closing + 2 .. close_end], " \t\r").len != 0) return false;
        if (!self.neutralRootTableSourceRange(source, close_end + @as(usize, @intFromBool(close_end < source.len)))) return false;
        var at = opening;
        while (at < closing) {
            const end = std.mem.indexOfScalarPos(u8, source, at, '\n') orelse return false;
            if (end >= closing) return false;
            const line = std.mem.trimEnd(u8, source[at..end], "\r");
            const body = if (at == opening) line[2..] else line;
            // Remaining raw braces are not table syntax admitted by this subset;
            // no nested table, cross-line holder or unmatched template is skipped.
            if (!self.neutralRootTableInline(body, 0, true, true)) return false;
            at = end + 1;
        }
        if (at != closing) return false;
        state.end = close_end + @as(usize, @intFromBool(close_end < source.len));
        return true;
    }

    fn observeTopLevelWikiTable(self: *Renderer, source: []const u8, opening: usize, close: []const u8, element: ?*const table_style_profile.TextElement) Error!void {
        const openings = self.page_top_level_wiki_table_openings orelse return;
        const root = self.heading_source orelse return;
        if (self.body_depth != 1 or source.ptr != root.ptr or source.len != root.len) return;
        if (element) |item| if (!std.ascii.eqlIgnoreCase(item.tag, "table") or item.parent != null) return;
        if (self.neutral_root_table_prefix == null) self.neutral_root_table_prefix = .{ .source = source };
        if (self.advanceNeutralRootTablePrefix(source, opening, close, &self.neutral_root_table_prefix.?))
            try openings.append(self.a, opening);
    }

    fn witnessedTopLevelWikiTableOpening(self: *const Renderer, source: []const u8, start: usize) bool {
        const proof = self.root_wiki_table_range orelse return false;
        if (self.content_root != .parser_output or self.body_depth != 1 or
            self.in_reference or self.pre_block or self.parsed_pre or self.body_link_target.len != 0 or
            self.inline_source_domain != null or source.ptr != proof.prepared.ptr or source.len != proof.prepared.len or
            proof.start > proof.page.len or source.len > proof.page.len - proof.start or
            !std.mem.eql(u8, source, proof.page[proof.start..][0..source.len]) or start >= source.len or
            (start != 0 and source[start - 1] != '\n') or !starts(source[start..], "{|")) return false;
        const absolute = proof.start + start;
        for (proof.top_level_openings) |opening| if (opening == absolute) return true;
        return false;
    }

    fn observedRootWikiTableOpening(self: *const Renderer, source: []const u8, start: usize) bool {
        const root = self.heading_source orelse return false;
        return self.body_depth == 1 and !self.in_reference and !self.pre_block and !self.parsed_pre and
            self.body_link_target.len == 0 and self.inline_source_domain == null and
            source.ptr == root.ptr and source.len == root.len and rootWikiTableLinePrefix(source, start) and
            (start == 0 or source[start - 1] == '\n') and starts(source[start..], "{|");
    }

    fn witnessedRootWikiTableOpening(self: *const Renderer, source: []const u8, start: usize) bool {
        const proof = self.root_wiki_table_range orelse return false;
        if (proof.start != 0 or !rootWikiTableLinePrefix(source, start) or self.content_root != .parser_output or self.body_depth != 1 or
            self.in_reference or self.pre_block or self.parsed_pre or self.body_link_target.len != 0 or
            self.inline_source_domain != null or source.ptr != proof.prepared.ptr or source.len != proof.prepared.len or
            proof.start > proof.page.len or source.len > proof.page.len - proof.start or
            !std.mem.eql(u8, source, proof.page[proof.start..][0..source.len]) or start >= source.len or
            (start != 0 and source[start - 1] != '\n') or !starts(source[start..], "{|")) return false;
        const absolute = proof.start + start;
        for (proof.openings) |opening| if (opening == absolute) return true;
        return false;
    }

    // This alternative witness comes from the authenticated complete observed
    // tree, not a lexical claim that preceding prose has no open ancestors.
    fn witnessedObservedRootWikiTable(self: *const Renderer, source: []const u8, start: usize, projected: ?*const table_style_profile.TextElement) bool {
        if (self.typed_table_depth != 1 or self.context.namespace_catalog == null) return false;
        // The observed original parent cannot discharge an active projected
        // font scope that is absent from the current text-element chain.
        if (self.block_formatting.bold or self.block_formatting.italic or self.block_formatting.code or
            self.block_formatting.small or self.block_formatting.superscript or self.block_formatting.subscript or
            self.body_formatting_attributes.font_scale_set or self.body_formatting_attributes.font_scale != null or
            self.body_formatting_attributes.font_size_unknown or self.body_formatting_attributes.font_scale_basis != .context) return false;
        if (self.body_language_direction) |parent| if (parent.font_scale_set or parent.font_scale != null or
            parent.font_size_unknown or parent.font_scale_basis != .context or parent.bold or parent.italic or parent.code or
            parent.small or parent.superscript or parent.subscript or parent.heading) return false;
        if (projected) |element| if (!std.ascii.eqlIgnoreCase(element.tag, "table") or element.parent != null or element.ancestry_complete) return false;
        if (self.content_root != .parser_output or self.body_depth != 1 or self.in_reference or self.pre_block or self.parsed_pre or
            self.in_template_literal_scope or self.body_link_target.len != 0 or self.inline_source_domain != null or
            start >= source.len or (start != 0 and source[start - 1] != '\n') or !starts(source[start..], "{|")) return false;
        const binding = self.source_element_binding orelse return false;
        const scope = binding.scope;
        if (scope.complete_ancestor_class_superset == null) return false;
        const original = scope.source_root_tables_source orelse return false;
        if (original.ptr != binding.projection.original.bytes.ptr or original.len != binding.projection.original.bytes.len) return false;
        const end = std.mem.indexOfScalarPos(u8, source, start, '\n') orelse return false;
        const opening = std.mem.trimEnd(u8, source[start..end], "\r");
        const original_start = binding.originalRange(opening) orelse return false;
        for (scope.source_root_tables) |proof| {
            if (proof.opening_start != original_start or proof.opening_end < proof.opening_start or
                proof.opening_end - proof.opening_start != opening.len or proof.anchor_start <= proof.opening_end or
                proof.anchor_end <= proof.anchor_start or proof.anchor_end > original.len) continue;
            const anchor = binding.ownerRange(proof.anchor_start, proof.anchor_end - proof.anchor_start) orelse continue;
            if (!wikiClassContains(source, anchor)) continue;
            const anchor_start = @intFromPtr(anchor.ptr) - @intFromPtr(source.ptr);
            if (anchor_start <= end or source[anchor_start - 1] != '\n') continue;
            // Projection may update the preceding File's stage options, but it
            // may not insert an open holder or move this cell into another row
            // or table. Recheck the same closed initial-grid grammar locally.
            var at = end + 1;
            var valid = true;
            var cell_ordinal: usize = 0;
            while (at < anchor_start) {
                const stop = std.mem.indexOfScalarPos(u8, source, at, '\n') orelse { valid = false; break; };
                if (stop >= anchor_start) { valid = false; break; }
                const line = std.mem.trimEnd(u8, source[at..stop], "\r");
                if (line.len < 3 or line[0] != '|' or line[1] == '-' or line[1] == '+' or line[1] == '|' or line[1] == '}') { valid = false; break; }
                const separator = std.mem.indexOfScalarPos(u8, line, 1, '|') orelse { valid = false; break; };
                const body = line[separator + 1 ..];
                if (!starts(body, "[[") or !std.mem.endsWith(u8, body, "]]")) { valid = false; break; }
                const pair = syntax.balanced(body, 0) orelse { valid = false; break; };
                if (pair.end != body.len) { valid = false; break; }
                const inner = body[2 .. body.len - 2];
                if (std.mem.indexOfAny(u8, inner, "[]{}<>&'\r\n\x00") != null or std.mem.indexOf(u8, inner, "__") != null) { valid = false; break; }
                const split = std.mem.indexOfScalar(u8, inner, '|') orelse { valid = false; break; };
                if (split == 0 or inner[0] == ':' or self.namespaceOfTarget(inner[0..split]) != 6 or
                    std.mem.indexOfAny(u8, inner[split + 1 ..], ":/\\") != null or std.mem.indexOfAny(u8, line[1..separator], "{}[]<>\x00") != null) { valid = false; break; }
                cell_ordinal += 1;
                at = stop + 1;
            }
            if (valid and at == anchor_start and cell_ordinal == proof.cell_ordinal) return true;
        }
        return false;
    }

    // A builder-issued original root-table witness is mandatory. A projected
    // TextElement chain alone cannot prove that no original wrapper was lost.
    fn completeTableFontAncestorIds(self: *Renderer, original: ?*const table_style_profile.TextElement, witnessed_root: bool) Error!?[]const []const u8 {
        if (!witnessed_root or self.content_root != .parser_output) return null;
        const profile = self.context.table_styles orelse return null;
        var chain: [max_html_normalization_frames]*const table_style_profile.TextElement = undefined;
        var count: usize = 0;
        var cursor = original;
        while (cursor) |element| : (cursor = element.parent) {
            if (element.ancestry_complete or element.source_key == 0 or count == chain.len) return null;
            chain[count] = element;
            count += 1;
        }
        for ([_]bool{ false, true }) |rtl| {
            const root: table_style_profile.TextElement = .{
                .tag = "div", .typeof_tokens = "",
                .classes = if (rtl) "mw-content-rtl mw-parser-output" else "mw-content-ltr mw-parser-output",
                .language = self.figurePageLanguage(), .ancestry_complete = true,
            };
            if (!profile.contentParentEffectsUnchanged(null, &root)) return null;
            var projected: [max_html_normalization_frames]table_style_profile.TextElement = undefined;
            var parent: *const table_style_profile.TextElement = &root;
            var remaining = count;
            while (remaining != 0) {
                remaining -= 1;
                projected[remaining] = chain[remaining].*;
                projected[remaining].parent = parent;
                projected[remaining].complete_ancestor_classes = null;
                if (!profile.contentParentEffectsUnchanged(chain[remaining], &projected[remaining])) return null;
                parent = &projected[remaining];
            }
        }
        var ids: std.ArrayList([]const u8) = .empty;
        for (chain[0..count]) |element| if (element.id.len != 0) {
            try ids.append(self.a, element.id);
        };
