    fn chemicalScriptDigits(value: []const u8) bool {
        if (value.len == 0 or value.len > 64) return false;
        for (value) |ch| if (!std.ascii.isDigit(ch)) return false;
        return true;
    }

    fn chemicalScriptCharge(value: []const u8) bool {
