        if (class_stack) {
            if (!upper.is("span") or upper.closing or upper.self_closing or trim(upper.attrs).len != 0) return false;
        } else if (!try self.chemicalStackCss(upper, .upper)) return false;
        const upper_pair = syntax.matchingTag(children, upper) orelse return false;
        const rest = trim(children[upper_pair.end..]);
        const lower = try self.semanticTagAt(rest, 0) orelse return false;
        if (class_stack) {
            if (!lower.is("span") or lower.closing or lower.self_closing or trim(lower.attrs).len != 0) return false;
        } else if (!try self.chemicalStackCss(lower, .lower)) return false;
        const lower_pair = syntax.matchingTag(rest, lower) orelse return false;
        if (trim(rest[lower_pair.end..]).len != 0) return false;
        const charge = try self.entityText(children[upper.end..upper_pair.inner_end]);
        const count = try self.entityText(rest[lower.end..lower_pair.inner_end]);
        if (!chemicalScriptCharge(charge) or !chemicalScriptDigits(count)) return false;
        // Conventional chemical linear order is count below, charge above.
        // Existing readers expose these roles; no same-x pixel stack is claimed.
        var count_style = style;
        count_style.subscript = true;
        var charge_style = style;
        charge_style.superscript = true;
        try self.text(count, count_style);
        try self.text(charge, charge_style);
        return true;
    }

    const RelativeFontSize = struct { value: ?f32, normal_body: bool = false, unknown: bool = false };
    fn htmlProjectedFontSize(self: *Renderer, tag: syntax.Tag, parent: ?f32) Error!?RelativeFontSize {
        // Select the winning UA default/author declaration before resolving
        // against the parent. A losing default or declaration may overflow
        // even when the winning value is zero or inherits the parent.
        var selected_factor: ?f32 = if (tag.is("big")) 1.2 else if (tag.is("small")) 1.0 / 1.2 else null;
        var selected_inherit = false;
        var selected_absolute = false;
        const css = (try self.semanticAttribute(tag, "style")) orelse "";
        var position: usize = 0;
        var important_seen = false;
        // Reuse the existing quoted/comment-aware CSS declaration scanner.
        // Declarations on one element resolve against the parent, not each other.
        while (try self.nextColorDeclaration(css, &position)) |raw| {
            const colon = std.mem.indexOfScalar(u8, raw, ':') orelse continue;
            if (!std.ascii.eqlIgnoreCase(trim(raw[0..colon]), "font-size")) continue;
            var value = trim(raw[colon + 1 ..]);
            var important = false;
            if (std.mem.lastIndexOfScalar(u8, value, '!')) |bang| {
                if (!std.ascii.eqlIgnoreCase(trim(value[bang + 1 ..]), "important")) continue;
                important = true;
                value = trim(value[0..bang]);
            }
            if (important_seen and !important) continue;
            const inherited = std.ascii.eqlIgnoreCase(value, "inherit") or std.ascii.eqlIgnoreCase(value, "unset");
            const absolute = if (inherited) null else relative_font.absoluteKeyword(value);
            const factor: ?f32 = if (inherited) null else absolute orelse relative_font.parseRelative(value) orelse continue;
            selected_factor = factor;
            selected_inherit = inherited;
            selected_absolute = absolute != null;
            important_seen = important;
        }
        if (selected_inherit) return .{ .value = parent };
        if (selected_absolute) return .{ .value = selected_factor.?, .normal_body = true };
        return if (selected_factor) |factor| .{ .value = try relative_font.resolve(parent, factor) } else null;
    }

    fn htmlRelativeFontSize(self: *Renderer, tag: syntax.Tag, parent: ?f32) Error!?RelativeFontSize {
        return self.htmlComputedFontSize(tag, .{ .font_scale = parent });
    }
    fn htmlComputedFontSize(self: *Renderer, tag: syntax.Tag, parent: Style) Error!?RelativeFontSize {
        const css = (try self.semanticAttribute(tag, "style")) orelse "";
        const authored = if (self.context.table_styles) |profile|
            try profile.resolveFontSizeIn(self.a, try self.textElement(tag, parent.text_element, parent.language), css, .{ .ctx = &tag, .get = htmlOwnAttributePresence })
        else try table_style_profile.resolveInlineFontSizeAlloc(self.a, css);
        const selected = authored orelse (if (tag.is("big")) table_style_profile.FontSizeValue{ .relative = 1.2 } else if (tag.is("small")) table_style_profile.FontSizeValue{ .relative = 1.0 / 1.2 } else return null);
        const parent_known = !parent.font_size_unknown and
            (!parent.heading or parent.font_scale_basis == .normal_body) and
            !parent.small and !parent.superscript and !parent.subscript and
            !self.block_formatting.small and !self.block_formatting.superscript and !self.block_formatting.subscript;
        // A numeric context projection is not a body-size certificate. Only
        // an untouched ordinary body context establishes the first body basis;
        // later relative declarations inherit that explicit proved basis.
        const ordinary_body_parent = self.body_depth != 0 and !self.in_reference and !self.pre_block and !self.parsed_pre and
            self.body_formatting_attributes.font_scale == null and !self.body_formatting_attributes.font_scale_set and
            self.body_formatting_attributes.font_scale_basis == .context and !self.body_formatting_attributes.font_size_unknown and
            parent.font_scale_basis == .context and parent.font_scale == null and !parent.font_scale_set and
            !parent.heading and !parent.code and !self.block_formatting.code and parent_known;
        const body_basis = parent_known and !parent.code and !self.block_formatting.code and
            (parent.font_scale_basis == .normal_body or ordinary_body_parent);
        switch (selected) {
            .absolute => |size| return .{ .value = size, .normal_body = true },
            .inherit => return .{ .value = parent.font_scale, .normal_body = body_basis, .unknown = !parent_known },
            .relative => |factor| return .{ .value = try relative_font.resolve(parent.font_scale, factor), .normal_body = body_basis, .unknown = !parent_known },
            .step => |direction| if (parent_known) {
                return .{ .value = try relative_font.resolveKeyword(parent.font_scale orelse 1, direction), .normal_body = true };
            },
            .unknown => {},
        }
        // Keep the established inline numeric projection when computed size is
        // unknown. It cannot authorize a relative-keyword table lookup.
        self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "htmlComputedFontSize.1", tag.attrs);
        var projection = (try self.htmlProjectedFontSize(tag, parent.font_scale)) orelse RelativeFontSize{ .value = parent.font_scale };
        projection.unknown = true;
        return projection;
    }

    fn htmlInlineStyle(self: *Renderer, tag: syntax.Tag, style: Style) Error!Style {
        var s = style;
        if (oneOf(tag.name, &.{ "b", "strong" })) s.bold = true;
        if (oneOf(tag.name, &.{ "i", "em", "cite", "var", "dfn" })) s.italic = true;
        if (tag.is("u") or tag.is("ins")) s.underline = true;
        if (oneOf(tag.name, &.{ "s", "del", "strike" })) s.strike = true;
        if (tag.is("sup")) s.superscript = true;
        if (tag.is("sub")) s.subscript = true;
        // Authored big/small are numeric sizes; legacy Style.small remains independent.
        if (oneOf(tag.name, &.{ "code", "tt", "kbd", "samp" })) s.code = true;
        if (try self.htmlFontWeightIn(tag, style.text_element, style.bold, style.language)) |bold| s.bold = bold;
        if (try self.htmlFontStyleIn(tag, style.text_element, style.italic, style.language)) |italic| s.italic = italic;
        if ((try self.semanticAttribute(tag, "class"))) |classes| {
            const decoded_classes = classes;
            var safe_classes: std.ArrayList(u8) = .empty;
            defer safe_classes.deinit(self.a);
            var tokens = std.mem.tokenizeAny(u8, decoded_classes, " \t\r\n");
            while (tokens.next()) |class| {
                var safe = class.len != 0;
                for (class) |c| if (!(std.ascii.isAlphanumeric(c) or c == '_' or c == '-')) {
                    safe = false;
                    break;
                };
                // Media ownership is compiler-generated metadata, never an authored CSS capability.
                if (!safe or std.mem.startsWith(u8, class, "wikidict-media-file-")) continue;
                if (safe_classes.items.len != 0) try safe_classes.append(self.a, ' ');
                try safe_classes.appendSlice(self.a, class);
                if (std.mem.eql(u8, class, "scribunto-error")) self.fallbacks.rendered_lua_error = true;
                if (std.mem.eql(u8, class, "ext-phonos-error")) self.fallbacks.rendered_extension_error = true;
                if (std.mem.eql(u8, class, "headword-line") or std.mem.eql(u8, class, "headword")) s.role = .headword;
                if (s.role != .headword and (std.mem.eql(u8, class, "label-content") or std.mem.eql(u8, class, "qualifier-content"))) s.role = .label;
                if (std.mem.eql(u8, class, "IPA")) s.role = .pronunciation;
                if (std.mem.eql(u8, class, "e-example")) s.role = .example;
                if (std.mem.eql(u8, class, "nyms")) {
                    if (self.semantic_capture) |hints| hints.relation_note = true;
                }
            }
            if (safe_classes.items.len != 0) {
                s.classes = if (s.classes.len == 0)
                    try self.a.dupe(u8, safe_classes.items)
                else
                    try std.fmt.allocPrint(self.a, "{s} {s}", .{ s.classes, safe_classes.items });
            }
        }
        // Only authored abbreviation titles are semantic explanations. An
        // explicit empty title clears inherited meaning; missing titles inherit.
        if (tag.is("abbr")) if (try self.semanticAttribute(tag, "title")) |explanation| {
            s.explanation = explanation;
            s.explanation_set = true;
        };
        s = try self.htmlLanguageDirection(tag, s);
        if (!tag.is("table")) s.background = (try self.authoredColorIn(tag, "background-color", null, style.background, self.customParent(s))).value;
        return s;
    }
    // Module:etymon/tree emits child-first fragments, not nested HTML lists.
    // Validate that small structural grammar before compiling any visible body.
    // The hidden etymon JSON is deliberately not another presentation source.
    const EtymologyTreeNode = struct {
        raw: []const u8,
        prefix: []const u8 = "",
        style: Style = .{},
        scopes: []const syntax.Tag,
        children: []const usize,
        height: usize,
        spans: []const Span = &.{},
        relation_note: bool = false,
        group: bool = false,
    };
    const EtymologyTreePlan = struct {
        renderer: *Renderer,
        nodes: std.ArrayList(EtymologyTreeNode) = .empty,
        limited: bool = false,

        fn hasClass(self: *EtymologyTreePlan, tag: syntax.Tag, wanted: []const u8) Error!bool {
            const classes = (try self.renderer.semanticAttribute(tag, "class")) orelse return false;
            var tokens = std.mem.tokenizeAny(u8, classes, " \t\r\n");
            while (tokens.next()) |value| if (std.mem.eql(u8, value, wanted)) return true;
            return false;
        }
        fn skipSpaceAndComments(input: []const u8, cursor: *usize) bool {
            while (cursor.* < input.len) {
                if (std.ascii.isWhitespace(input[cursor.*])) {
                    cursor.* += 1;
                } else if (starts(input[cursor.*..], "<!--")) {
                    cursor.* = syntax.protectedEnd(input, cursor.*) orelse return false;
                } else break;
            }
            return true;
        }
        fn addNode(self: *EtymologyTreePlan, raw: []const u8, prefix: []const u8, scopes: []const syntax.Tag, children: []const usize, group: bool) Error!?usize {
            var height: usize = 1;
            for (children) |child| height = @max(height, self.nodes.items[child].height + 1);
            if (self.nodes.items.len >= 1024 or height >= max_depth) {
                self.limited = true;
                return null;
            }
            const index = self.nodes.items.len;
            try self.nodes.append(self.renderer.a, .{ .raw = raw, .prefix = prefix, .scopes = scopes, .children = children, .height = height, .group = group });
            return index;
        }
        fn extendScopes(self: *EtymologyTreePlan, scopes: []const syntax.Tag, tag: syntax.Tag) Error![]const syntax.Tag {
            const extended = try self.renderer.a.alloc(syntax.Tag, scopes.len + 1);
            @memcpy(extended[0..scopes.len], scopes);
            extended[scopes.len] = tag;
            return extended;
        }
        fn groupLabel(self: *EtymologyTreePlan, input: []const u8) Error!bool {
            var cursor: usize = 0;
            if (!skipSpaceAndComments(input, &cursor)) return false;
            const tag = try self.renderer.semanticTagAt(input, cursor) orelse return false;
            if (tag.closing or !tag.is("span") or !(try self.hasClass(tag, "etytree-group-label"))) return false;
            const pair = syntax.matchingTag(input, tag) orelse return false;
            cursor = pair.end;
            return skipSpaceAndComments(input, &cursor) and cursor == input.len;
        }
        fn branches(self: *EtymologyTreePlan, input: []const u8, scopes: []const syntax.Tag, depth: usize) Error!?[]const usize {
            if (depth >= max_depth) {
                self.limited = true;
                return null;
            }
            var roots: std.ArrayList(usize) = .empty;
            var cursor: usize = 0;
            var columns: usize = 0;
            while (cursor < input.len) {
                if (!skipSpaceAndComments(input, &cursor)) return null;
                if (cursor == input.len) break;
                const tag = try self.renderer.semanticTagAt(input, cursor) orelse return null;
                if (tag.closing or !tag.is("div") or !(try self.hasClass(tag, "etytree-branch"))) return null;
                const pair = syntax.matchingTag(input, tag) orelse return null;
                const child_scopes = try self.extendScopes(scopes, tag);
                const children = (try self.sequence(input[tag.end..pair.inner_end], child_scopes, depth + 1, true)) orelse return null;
                try roots.appendSlice(self.renderer.a, children);
                columns += 1;
                cursor = pair.end;
            }
            if (columns < 2) return null;
            return try roots.toOwnedSlice(self.renderer.a);
        }
        fn sequence(self: *EtymologyTreePlan, input: []const u8, scopes: []const syntax.Tag, depth: usize, branch_tail: bool) Error!?[]const usize {
            if (depth >= max_depth) {
                self.limited = true;
                return null;
            }
            var roots: std.ArrayList(usize) = .empty;
            var needs_parent = false;
            var tail_stage: enum { none, short, done } = .none;
            var prefix: []const u8 = "";
            var cursor: usize = 0;
            while (cursor < input.len) {
                if (!skipSpaceAndComments(input, &cursor)) return null;
                if (cursor == input.len) break;
                if (tail_stage == .done) return null;
                const at = cursor;
                const tag = try self.renderer.semanticTagAt(input, at) orelse return null;
                if (tag.closing or (!tag.is("div") and !tag.is("span"))) return null;
                const pair = syntax.matchingTag(input, tag) orelse return null;
                const content = input[tag.end..pair.inner_end];
                if (tail_stage == .short and !(tag.is("span") and try self.hasClass(tag, "etytree-branch-mid"))) return null;
                const scoped_tags = try self.extendScopes(scopes, tag);
                if (tag.is("div") and try self.hasClass(tag, "etytree-block")) {
                    if (roots.items.len != 0 and !needs_parent) return null;
                    const children = try roots.toOwnedSlice(self.renderer.a);
                    const child = (try self.addNode(content, prefix, scoped_tags, children, false)) orelse return null;
                    try roots.append(self.renderer.a, child);
                    prefix = "";
                    needs_parent = false;
                } else if (tag.is("div") and try self.hasClass(tag, "etytree-branch-group")) {
                    if (roots.items.len != 0 or prefix.len != 0) return null;
                    const children = (try self.branches(content, scoped_tags, depth + 1)) orelse return null;
                    try roots.appendSlice(self.renderer.a, children);
                    needs_parent = true;
                } else if (tag.is("span") and ((try self.hasClass(tag, "etytree-connector-vertical")) or
                    (try self.hasClass(tag, "etytree-connector-dotted"))))
                {
                    if (roots.items.len == 0 or prefix.len != 0) return null;
                    if (trim(content).len != 0) {
                        if (!(try self.groupLabel(content))) return null;
                        const children = try roots.toOwnedSlice(self.renderer.a);
                        const child = (try self.addNode(content, "", scoped_tags, children, true)) orelse return null;
                        try roots.append(self.renderer.a, child);
                    }
                    needs_parent = true;
                } else if (tag.is("span") and ((try self.hasClass(tag, "etytree-branch-left")) or
                    (try self.hasClass(tag, "etytree-branch-right")) or
                    (try self.hasClass(tag, "etytree-branch-mid")) or
                    (try self.hasClass(tag, "etytree-connector-vertical-short"))))
                {
                    if (!branch_tail or roots.items.len == 0 or trim(content).len != 0) return null;
                    // A container may supply a forest or a labelled group to
                    // the shared parent outside this branch column.
                    if (try self.hasClass(tag, "etytree-connector-vertical-short")) {
                        if (tail_stage != .none) return null;
                        tail_stage = .short;
                    } else {
                        if ((try self.hasClass(tag, "etytree-branch-mid")) != (tail_stage == .short)) return null;
                        tail_stage = .done;
                    }
                } else if (tag.is("div") and try self.hasClass(tag, "etytree-duplicate-connector")) {
                    // This marker means ancestry was hidden. Keep its visible
                    // arrow, never invent the hidden nodes or another edge.
                    if (roots.items.len != 0 or prefix.len != 0) return null;
                    prefix = input[at..pair.end];
                } else return null;
                cursor = pair.end;
            }
            if (prefix.len != 0 or roots.items.len == 0) return null;
            if (branch_tail) {
                if (tail_stage != .done) return null;
            } else if (roots.items.len != 1 or needs_parent) return null;
            return try roots.toOwnedSlice(self.renderer.a);
        }
    };

    fn etymologyTreeSpans(self: *Renderer, node_value: EtymologyTreeNode) Error![]const Span {
        var spans: std.ArrayList(Span) = .empty;
        if (node_value.prefix.len != 0) {
            const prefix_source = if (self.body_missing) |parent| try self.missingSliceWithHeadingSource(parent, node_value.prefix) else MissingText.untracked(node_value.prefix);
            const parsed_prefix = try self.parseSpansWithMissing(prefix_source, node_value.style);
            var end = parsed_prefix.len;
            while (end != 0 and parsed_prefix[end - 1].kind == .line_break) end -= 1;
            try spans.appendSlice(self.a, parsed_prefix[0..end]);
        }
        const tracked = if (self.body_missing) |parent| try self.missingSliceWithHeadingSource(parent, node_value.raw) else MissingText.untracked(node_value.raw);
        const parsed = try self.parseSpansWithMissing(tracked, node_value.style);
        var prefix_boundary = spans.items.len != 0;
        var separated_label = false;
        for (parsed) |span| {
            var label = false;
            var tokens = std.mem.tokenizeAny(u8, span.classes, " \t\r\n");
            while (tokens.next()) |value| label = label or std.mem.eql(u8, value, "etytree-label-container");
            var separate = label and !separated_label;
            if (prefix_boundary) {
                if (span.kind == .line_break) prefix_boundary = false else if (span.text.len != 0) {
                    separate = separate or !std.ascii.isWhitespace(span.text[0]);
                    prefix_boundary = false;
                }
            }
            if (separate and spans.items.len != 0 and !formattingVisibleEndsSpace(spans.items)) {
                var separator = span;
                separator.kind = .text;
                separator.text = " ";
                separator.target = "";
                separator.target_fragment = null;
                separator.generated_link = null;
                separator.external_literal_parameter = null;
                separator.image = null;
                separator.image_fields_compiled = false;
                separator.pending_figure = null;
                separator.pending_bidi_scope = null;
                separator.captured_bidi_scope = null;
                separator.nonfloating_image = false;
                separator.nonfloating_image_alignment = null;
                separator.self_link = false;
                try spans.append(self.a, separator);
            }
            if (label) separated_label = true;
            try spans.append(self.a, span);
        }
        return try spans.toOwnedSlice(self.a);
    }
    fn emitEtymologyTree(self: *Renderer, blocks: *std.ArrayList(Block), nodes: []const EtymologyTreeNode, index: usize, parent_path: []const u8) Error!void {
        const node_value = nodes[index];
        const path = try std.fmt.allocPrint(self.a, "{s}*", .{parent_path});
        try self.appendBlockBudgeted(blocks, .{ .kind = .list_item, .depth = @intCast(path.len), .list_path = path, .spans = node_value.spans, .relation_note = node_value.relation_note });
        for (node_value.children) |child| {
            if (self.truncated) break;
            try self.emitEtymologyTree(blocks, nodes, child, path);
        }
    }
    fn appendEtymologyTree(self: *Renderer, blocks: *std.ArrayList(Block), input: []const u8, tag: syntax.Tag) Error!bool {
        if (!tag.is("div") or self.pre_block or self.parsed_pre) return false;
        var plan: EtymologyTreePlan = .{ .renderer = self };
        if (!(try plan.hasClass(tag, "etytree-body"))) return false;
        const roots = (try plan.sequence(input, &.{tag}, 0, false)) orelse {
            if (plan.limited) self.fallbacks.render_limit = true;
            return false;
        };
        const previous_implicit_list = self.figure_implicit_list_context;
        self.figure_implicit_list_context = true;
        defer self.figure_implicit_list_context = previous_implicit_list;
        // Indices are in source DOM order, including group labels after their
        // terms. Register content effects once before projecting parent-first.
        for (plan.nodes.items) |*node_value| {
            var hints: SemanticHints = .{ .relation_note = self.body_formatting_attributes.relation_note, .figure_blocks = true };
            const previous_capture = self.semantic_capture;
            self.semantic_capture = &hints;
            defer self.semantic_capture = previous_capture;
            const parent_italic = self.block_formatting.italic;
            const parent_poem_italic = self.poem_base_style.italic;
            defer self.block_formatting.italic = parent_italic;
            defer self.poem_base_style.italic = parent_poem_italic;
            var node_style = self.bodyFormattingStyle(self.body_language_direction orelse .{});
            for (node_value.scopes) |scope_tag| {
                node_style = try self.htmlInlineStyle(scope_tag, node_style);
                if (try self.htmlFontStyle(scope_tag)) |italic| {
                    self.block_formatting.italic = italic;
                    if (self.poem_depth != 0) self.poem_base_style.italic = italic;
                }
            }
            node_value.style = node_style;
            node_value.spans = try self.etymologyTreeSpans(node_value.*);
            node_value.relation_note = hints.relation_note;
        }
        try self.emitEtymologyTree(blocks, plan.nodes.items, roots[0], "");
        return true;
    }

    const BidiScope = struct {
        opening: []const u8,
        closing: []const u8 = "\xe2\x81\xa9",
        automatic: bool = false,
        mode: presentation_types.BidiMode = .isolate,
        authored_direction: ?presentation_types.BidiDirectionInput = null,
        language: ?[]const u8 = null,
        legacy_unicode: bool = true,
    };
    const unicode_bidi = @import("unicode_bidi.zig");

    fn firstBidiDirection(spans: []const Span) unicode_bidi.Direction {
        for (spans) |span| {
            if (span.bidi_auto_excluded) continue;
            var characters = (std.unicode.Utf8View.init(span.text) catch continue).iterator();
            while (characters.nextCodepoint()) |cp| if (unicode_bidi.strongDirection(cp)) |direction| return direction;
        }
        return .ltr; // HTML auto/undefined BDI with no strong descendant text.
    }

    const BidiTextScan = struct {
        remaining: usize = max_nodes,

        fn take(self: *BidiTextScan, count: usize) Error!void {
            if (count > self.remaining) return error.RenderLimit;
            self.remaining -= count;
        }
        fn spans(self: *BidiTextScan, values: []const Span, depth: CaptionCatalogDepth) Error!?unicode_bidi.Direction {
            try self.take(values.len);
            var index: usize = 0;
            while (index < values.len) {
                const span = values[index];
                if (span.pending_figure) |pending| {
                    const end = try pendingFigureFallbackEnd(values, index, pending.*);
                    if (!span.bidi_auto_excluded) if (try self.figure(pending.*, depth)) |direction| return direction;
                    // Area labels are accessibility fallback siblings, not
                    // descendant DOM text. Match their occurrence ownership.
                    index = end;
                    continue;
                }
                index += 1;
                if (span.bidi_auto_excluded or span.generated_bidi_boundary or span.pending_bidi_scope != null) continue;
                var characters = (std.unicode.Utf8View.init(span.text) catch continue).iterator();
                while (characters.nextCodepoint()) |cp| if (unicode_bidi.strongDirection(cp)) |direction| return direction;
            }
            return null;
        }
        fn figure(self: *BidiTextScan, value: Figure, depth: CaptionCatalogDepth) Error!?unicode_bidi.Direction {
            // The image's file, target, alternative and advice are attributes.
            return if (value.caption_blocks) |children| self.blocks(children, try depth.contentChild()) else self.spans(value.caption, depth);
        }
        fn flow(self: *BidiTextScan, parts: []const FlowPart, depth: CaptionCatalogDepth) Error!?unicode_bidi.Direction {
            try self.take(parts.len);
            for (parts) |part| {
                const found = switch (part.kind) {
                    .@"inline" => try self.spans(part.spans, depth),
                    .figure => try self.figure(part.figure orelse return error.UncompiledPresentation, depth),
                    // A nested authored BDI/valid-dir scope is an exclusion,
                    // regardless of its own resolved direction or visible text.
                    .scope => null,
                };
                if (found) |direction| return direction;
            }
            return null;
        }
        fn blocks(self: *BidiTextScan, values: []const Block, depth: CaptionCatalogDepth) Error!?unicode_bidi.Direction {
            try self.take(values.len);
            for (values) |value| {
                if (value.container) |container| if (try self.blocks(container.blocks, try depth.contentChild())) |direction| return direction;
                if (value.figure) |image| if (try self.figure(image, depth)) |direction| return direction;
                if (value.flow) |parts| if (try self.flow(parts, try depth.contentChild())) |direction| return direction;
                if (try self.spans(value.spans, depth)) |direction| return direction;
                if (value.table) |grid| if (try self.table(grid, try depth.nestedTable())) |direction| return direction;
            }
            return null;
        }
        fn table(self: *BidiTextScan, value: Table, depth: CaptionCatalogDepth) Error!?unicode_bidi.Direction {
            if (value.caption_blocks) |children| {
                if (try self.blocks(children, try depth.contentChild())) |direction| return direction;
            } else if (try self.spans(value.caption, depth)) |direction| return direction;
            try self.take(value.rows.len);
            for (value.rows) |row| {
                try self.take(row.cells.len);
                for (row.cells) |cell| {
                    if (cell.blocks) |children| {
                        if (try self.blocks(children, depth)) |direction| return direction;
                    } else {
                        if (try self.spans(cell.spans, depth)) |direction| return direction;
                        if (cell.nested_table) |grid| if (try self.table(grid, try depth.nestedTable())) |direction| return direction;
                    }
                }
            }
            return null;
        }
    };

    fn pendingFigureFallbackEnd(values: []const Span, index: usize, figure: Figure) Error!usize {
        const end = std.math.add(usize, index + 1, if (figure.map_fallback) |fallback| fallback.len else 0) catch return error.UncompiledPresentation;
        if (end > values.len) return error.UncompiledPresentation;
        if (figure.map_fallback) |fallback| for (fallback, values[index + 1 .. end]) |expected, actual| {
            if (!std.meta.eql(expected, actual) or actual.pending_figure != null or actual.pending_bidi_scope != null) return error.UncompiledPresentation;
        };
        return end;
    }

    fn resolvedBidiFigure(self: *Renderer, original: Figure, depth: CaptionCatalogDepth, inherited_direction: ?presentation_types.BidiDirectionInput) Error!Figure {
        var result = original;
        if (original.deferred_geometry) |deferred| {
            const direction = deferred.owner.resolved orelse return self.figureUnavailable();
            if (direction == .rtl) {
                result = deferred.rtl_geometry;
                result.content = original.content;
                result.caption = original.caption;
                result.caption_blocks = original.caption_blocks;
                result.map_fallback = original.map_fallback;
            }
            result.deferred_geometry = null;
        }
        result.content.spanPtr().* = (try self.resolvedBidiSpans(&.{result.content.span()}, depth, inherited_direction))[0];
        if (result.caption_blocks) |children| result.caption_blocks = try self.resolvedBidiBlocks(children, try depth.contentChild(), inherited_direction) else result.caption = try self.resolvedBidiSpans(result.caption, depth, inherited_direction);
        return result;
    }
    fn captureLegacyDirection(style: *Style) void {
        // Re-entering an implicit child owner must retain the pre-clear value.
        if (style.captured_direction == null) style.captured_direction = style.direction;
        style.direction = "";
    }
    fn resolvedBidiSpans(self: *Renderer, values: []const Span, depth: CaptionCatalogDepth, inherited_direction: ?presentation_types.BidiDirectionInput) Error![]const Span {
        var result: std.ArrayList(Span) = .empty;
        errdefer result.deinit(self.a);
        var index: usize = 0;
        while (index < values.len) {
            var span = values[index];
            if (span.captured_bidi_scope) |captured| {
                const count = captured.legacy_spans.len;
                if (!captured.source_eligible or count == 0 or count > values.len - index) return self.figureUnavailable();
                // Match the complete occurrence, not adjacent language/direction
                // values. A later mutation or partial copied interval refuses.
                for (captured.legacy_spans, values[index..][0..count]) |expected, actual| {
                    if (!std.meta.eql(expected, actual)) return self.figureUnavailable();
                }
                const nested = try self.resolvedBidiSpans(captured.spans, try depth.contentChild(), captured.authored_direction);
                const scope = try self.a.create(FlowScope);
                scope.* = .{ .mode = captured.mode, .authored_direction = captured.authored_direction,
                    .resolved_direction = captured.resolved_direction, .language = captured.language,
                    .parts = try self.bidiScopeParts(nested) };
                if (!presentation_types.validBidiScopeHeader(scope.*)) return self.figureUnavailable();
                if (!self.spend()) return error.RenderLimit;
                try result.append(self.a, .{ .text = "", .pending_bidi_scope = scope, .bidi_auto_excluded = true });
                index += count;
                continue;
            }
            // Validate the original occurrence before restoring any metadata.
            // A map's fallback is a paired sibling interval, not caption text.
            const fallback_end = if (span.pending_figure) |pending|
                try pendingFigureFallbackEnd(values, index, pending.*)
            else index + 1;
            if (span.captured_direction) |effective| {
                span.direction = effective;
                span.captured_direction = null;
            }
            // Direction remains effective span metadata. The typed scope owns
            // isolation; only a certified captured interval creates a child
            // scope, never equality with an inherited direction value.
            if (span.pending_figure) |pending| {
                const owned = try self.a.create(Figure);
                owned.* = try self.resolvedBidiFigure(pending.*, depth, inherited_direction);
                if (pending.map_fallback != null) {
                    // Transform once and retain these exact values in both the
                    // emitted sibling sequence and its private identity proof.
                    const fallback = try self.resolvedBidiSpans(values[index + 1 .. fallback_end], depth, inherited_direction);
                    owned.map_fallback = fallback;
                    span.pending_figure = owned;
                    try result.append(self.a, span);
                    try result.appendSlice(self.a, fallback);
                    index = fallback_end;
                    continue;
                }
                span.pending_figure = owned;
            }
            try result.append(self.a, span);
            index += 1;
        }
        return result.toOwnedSlice(self.a);
    }
    fn resolvedBidiFlow(self: *Renderer, values: []const FlowPart, depth: CaptionCatalogDepth, inherited_direction: ?presentation_types.BidiDirectionInput) Error![]const FlowPart {
        var result: std.ArrayList(FlowPart) = .empty;
        errdefer result.deinit(self.a);
        for (values) |part| switch (part.kind) {
            .@"inline" => {
                const spans = try self.resolvedBidiSpans(part.spans, depth, inherited_direction);
                if (hasPendingFigure(spans)) try result.appendSlice(self.a, try self.bidiScopeParts(spans)) else try result.append(self.a, .{ .kind = .@"inline", .spans = spans });
            },
            .figure => try result.append(self.a, .{ .kind = .figure, .figure = try self.resolvedBidiFigure(part.figure orelse return self.figureUnavailable(), depth, inherited_direction) }),
            .scope => {
                var scope = part.scope orelse return self.figureUnavailable();
                scope.parts = try self.resolvedBidiFlow(scope.parts, try depth.contentChild(), scope.authored_direction);
                try result.append(self.a, .{ .kind = .scope, .scope = scope });
            },
        };
        return result.toOwnedSlice(self.a);
    }
    fn resolvedBidiBlocks(self: *Renderer, values: []const Block, depth: CaptionCatalogDepth, inherited_direction: ?presentation_types.BidiDirectionInput) Error![]const Block {
        const result = try self.a.dupe(Block, values);
        for (result) |*value| {
            if (value.container) |*container| container.blocks = try self.resolvedBidiBlocks(container.blocks, try depth.contentChild(), inherited_direction);
            if (value.figure) |image| value.figure = try self.resolvedBidiFigure(image, depth, inherited_direction);
            if (value.flow) |parts| value.flow = try self.resolvedBidiFlow(parts, try depth.contentChild(), inherited_direction);
            value.spans = try self.resolvedBidiSpans(value.spans, depth, inherited_direction);
            if (value.table) |grid| value.table = try self.resolvedBidiTable(grid, try depth.nestedTable(), inherited_direction);
        }
        return result;
    }
    fn resolvedBidiTable(self: *Renderer, original: Table, depth: CaptionCatalogDepth, inherited_direction: ?presentation_types.BidiDirectionInput) Error!Table {
        var result = original;
        if (original.caption_blocks) |children| result.caption_blocks = try self.resolvedBidiBlocks(children, try depth.contentChild(), inherited_direction) else result.caption = try self.resolvedBidiSpans(original.caption, depth, inherited_direction);
        const rows = try self.a.dupe(Row, original.rows);
        result.rows = rows;
        for (rows) |*row| {
            const cells = try self.a.dupe(Cell, row.cells);
            row.cells = cells;
            for (cells) |*cell| {
                if (cell.blocks) |children| cell.blocks = try self.resolvedBidiBlocks(children, depth, inherited_direction) else {
                    cell.spans = try self.resolvedBidiSpans(cell.spans, depth, inherited_direction);
                    if (cell.nested_table) |grid| cell.nested_table = try self.resolvedBidiTable(grid, try depth.nestedTable(), inherited_direction);
                }
            }
        }
        return result;
    }

    fn validBidiDirection(self: *Renderer, tag: syntax.Tag) Error!bool {
        const raw = (try self.semanticAttribute(tag, "dir")) orelse return false;
        return std.ascii.eqlIgnoreCase(raw, "ltr") or std.ascii.eqlIgnoreCase(raw, "rtl") or std.ascii.eqlIgnoreCase(raw, "auto");
    }

    fn compiledBidiScope(self: *Renderer, tag: syntax.Tag) Error!?BidiScope {
        const raw = try self.semanticAttribute(tag, "dir");
        const direction: []const u8 = if (raw) |value|
            if (std.ascii.eqlIgnoreCase(value, "ltr")) "ltr" else if (std.ascii.eqlIgnoreCase(value, "rtl")) "rtl" else if (std.ascii.eqlIgnoreCase(value, "auto")) "auto" else ""
        else
            "";
        const authored = std.meta.stringToEnum(presentation_types.BidiDirectionInput, direction);
        const language = try self.semanticAttribute(tag, "lang");
        if (tag.is("bdo")) {
            if (std.mem.eql(u8, direction, "ltr")) return .{ .opening = "\xe2\x81\xa6\xe2\x80\xad", .closing = "\xe2\x80\xac\xe2\x81\xa9", .mode = .isolate_override, .authored_direction = authored, .language = language };
            if (std.mem.eql(u8, direction, "rtl")) return .{ .opening = "\xe2\x81\xa7\xe2\x80\xae", .closing = "\xe2\x80\xac\xe2\x81\xa9", .mode = .isolate_override, .authored_direction = authored, .language = language };
            return null; // Do not invent override semantics for an invalid/missing direction.
        }
        // BDI defaults to auto, not its DOM parent's direction. Explicit child
        // dir scopes inside a compiled bidi scope also span all styled atoms.
        if (!tag.is("bdi") and direction.len == 0) return null;
        return .{
            .opening = if (std.mem.eql(u8, direction, "rtl")) "\xe2\x81\xa7" else "\xe2\x81\xa6",
            .automatic = direction.len == 0 or std.mem.eql(u8, direction, "auto"),
            .authored_direction = authored,
            .language = language,
            .legacy_unicode = tag.is("bdi") or self.bidi_scope_depth != 0,
        };
    }

    fn independentBidiBlockOwner(self: *Renderer, source: []const u8) Error!bool {
        var scan: syntax.OpaqueScan = .{};
        var at: usize = 0;
        while (at < source.len) {
            if (starts(source[at..], "<!--")) {
                const end = std.mem.indexOfPos(u8, source, at + 4, "-->") orelse return false;
                at = end + 3;
                continue;
            }
            if (source[at] == '<') if (scan.tagAt(source, at, null)) |tag| {
                if (!tag.closing and (tag.isOpaque() or tag.html_pre or oneOf(tag.name, &.{ "nowiki", "script", "style", "textarea" }))) {
                    if (syntax.matchingTagWithOpaqueScan(source, tag, &scan)) |pair| { at = pair.end; continue; }
                }
                if (!tag.closing and oneOf(tag.name, &.{ "div", "p", "blockquote", "center", "ul", "ol", "dl", "li", "dt", "dd", "table", "tr", "td", "th", "caption", "h1", "h2", "h3", "h4", "h5", "h6" }) and try self.validBidiDirection(tag)) return true;
                at = tag.end;
                continue;
            };
            at += 1;
        }
        return false;
    }
    fn bidiSourceEligible(self: *Renderer, header: MissingText, closing: MissingText, content: []const u8, element: ?*const table_style_profile.TextElement, css: []const u8) Error!bool {
        if (header.ranges.len != 0 or header.literal_curly_ranges.len != 0 or header.generated_links.len != 0) return false;
        if (closing.ranges.len != 0 or closing.literal_curly_ranges.len != 0 or closing.generated_links.len != 0) return false;
        // A detached block's authored direction is not an inline-span proof.
        // Cross-array scope ownership remains an explicit unsupported case.
        if (try self.independentBidiBlockOwner(content)) return false;
        const profile = self.context.table_styles orelse return false;
        return profile.sourceBidiScopeUnchanged(self.a, element orelse return false, css);
    }
    fn bidiScopeParts(self: *Renderer, staged: []const Span) Error![]const FlowPart {
        // This temporary anonymous owner only extracts ordered parts. It does
        // not add a paragraph, margin, or list marker to the emitted document.
        const extracted = try self.extractFigures(&.{.{ .kind = .paragraph, .spans = staged }});
        if (extracted[0].flow) |ordered| return ordered;
        if (!self.spend()) return error.RenderLimit;
        const parts = try self.a.alloc(FlowPart, 1);
        parts[0] = if (extracted[0].figure) |image| .{ .kind = .figure, .figure = image } else .{ .kind = .@"inline", .spans = extracted[0].spans };
        return parts;
    }
    fn wrapFigureBidiSpans(self: *Renderer, start: usize, descriptor: BidiScope, capture: *BidiCapture, header: MissingText, closing: MissingText, content: []const u8, element: ?*const table_style_profile.TextElement, css: []const u8) Error!void {
        if (!(try self.bidiSourceEligible(header, closing, content, element, css))) return self.figureUnavailable();
        const original = self.spans.items[start..];
        var scan: BidiTextScan = .{};
        const resolved: presentation_types.BidiResolvedDirection = if (descriptor.automatic)
            if (((try scan.spans(original, .{ .content = 2 })) orelse .ltr) == .rtl) .rtl else .ltr
        else if (descriptor.authored_direction == .rtl) .rtl else .ltr;
        capture.resolved = resolved;
        const staged = try self.resolvedBidiSpans(original, .{ .content = 2 }, descriptor.authored_direction);
        const parts = try self.bidiScopeParts(staged);
        const scope = try self.a.create(FlowScope);
        scope.* = .{ .mode = descriptor.mode, .authored_direction = descriptor.authored_direction, .resolved_direction = resolved, .language = descriptor.language, .parts = parts };
        if (!presentation_types.validBidiScopeHeader(scope.*)) return self.figureUnavailable();
        if (!self.spend()) return error.RenderLimit;
        self.spans.items.len = start;
        try self.spans.append(self.a, .{ .text = "", .pending_bidi_scope = scope });
    }

    fn bidiBoundary(value: []const u8, neighbor: Span) Span {
        var result = neighbor;
        result.text = value;
        result.kind = .text;
        result.target = "";
        result.direction = "";
        result.captured_direction = null;
        result.explanation = "";
        result.explanation_set = false;
        result.tooltip = null;
        result.tooltip_set = false;
        result.provenance = .protected_literal;
        result.generated_bidi_boundary = true;
        result.generated_link = null;
        result.target_fragment = null;
        result.image = null;
        result.image_fields_compiled = false;
        result.pending_figure = null;
        result.pending_bidi_scope = null;
        result.captured_bidi_scope = null;
        result.nonfloating_image = false;
        result.nonfloating_image_alignment = null;
        // Retain layout classes (especially Poem) without creating an action.
        return result;
    }

    fn bidiSeparatorLength(value: []const u8) usize {
        if (value.len == 0) return 0;
        if (value[0] == '\n' or value[0] == '\r') return 1;
        if (starts(value, "\xe2\x80\xa8") or starts(value, "\xe2\x80\xa9")) return 3;
        return 0;
    }

    fn wrapBidiSpans(self: *Renderer, start: usize, scope: BidiScope) Error!void {
        const original = self.spans.items[start..];
        // Resolve auto once over the whole element, not once per output line.
        // Descendant text has already been decoded; raw link targets and HTML
        // attributes are not scan input. Authored Unicode isolates are not DOM
        // exclusions: their L/R/AL text still participates in this HTML rule.
        const opening: []const u8 = if (scope.automatic)
            if (firstBidiDirection(original) == .rtl) "\xe2\x81\xa7" else "\xe2\x81\xa6"
        else
            scope.opening;
        var wrapped: std.ArrayList(Span) = .empty;
        defer wrapped.deinit(self.a);
        var opened = false;
        var last: Span = .{ .text = "" };
        // Children have already consumed their normal budget. Build the entire
        // balanced replacement first; shortage preserves those children and
        // reports a limit, rather than dropping a generated PDF/PDI later.
        const maximum = original.len + (max_nodes -| self.nodes);
        for (original) |span| {
            if (span.text.len == 0) try wrapped.append(self.a, span);
            var offset: usize = 0;
            while (offset < span.text.len) {
                const separator = bidiSeparatorLength(span.text[offset..]);
                if (separator != 0 or span.kind == .line_break) {
                    if (opened) {
                        try wrapped.append(self.a, bidiBoundary(scope.closing, last));
                        opened = false;
                    }
                    var part = span;
                    const length = if (span.kind == .line_break) span.text.len - offset else separator;
                    part.text = span.text[offset .. offset + length];
                    if (span.generated_link != null) part = try generatedLabelSlice(span, part.text);
                    try wrapped.append(self.a, part);
                    offset += length;
                } else {
                    var end = offset + 1;
                    while (end < span.text.len and bidiSeparatorLength(span.text[end..]) == 0) : (end += 1) {}
                    if (!opened) {
                        try wrapped.append(self.a, bidiBoundary(opening, span));
                        opened = true;
                    }
                    var part = span;
                    part.text = span.text[offset..end];
                    if (span.generated_link != null) part = try generatedLabelSlice(span, part.text);
                    try wrapped.append(self.a, part);
                    last = part;
                    offset = end;
                }
                if (wrapped.items.len + @intFromBool(opened) > maximum) {
                    self.fallbacks.render_limit = true;
                    return;
                }
            }
        }
        if (opened) try wrapped.append(self.a, bidiBoundary(scope.closing, last));
        self.nodes += wrapped.items.len -| original.len;
        self.spans.items.len = start;
        try self.spans.appendSlice(self.a, wrapped.items);
    }

    fn htmlTag(self: *Renderer, input: []const u8, at: usize, style: Style, depth: usize, no_more_nowiki_close: ?*bool, opaque_scan: *syntax.OpaqueScan) Error!?usize {
        return self.htmlTagWithMissing(MissingText.untracked(input), at, style, depth, no_more_nowiki_close, opaque_scan, null);
    }
    // Select the existing block pass only for an authored physical closer in
    // this ordinary layout domain. Owned bodies and tag attributes cannot
    // trigger a change to surrounding layout merely by containing LF + |}.
    fn physicalLayoutTableClose(input: []const u8) bool {
        var scan: syntax.OpaqueScan = .{};
        var at: usize = 0;
        while (at < input.len) {
            if (at != 0 and input[at - 1] == '\n' and starts(input[at..], "|}")) return true;
            if (starts(input[at..], "<!--")) {
                const end = std.mem.indexOfPos(u8, input, at + 4, "-->") orelse return false;
                at = end + 3;
                continue;
            }
            if (input[at] == '<') if (scan.tagAt(input, at, null)) |tag| {
                if (!tag.closing and (tag.isOpaque() or tag.html_pre or
                    oneOf(tag.name, &.{ "nowiki", "pre", "ref", "references", "a", "script", "style", "iframe", "object", "embed" })))
                {
                    const pair = syntax.matchingTagWithOpaqueScan(input, tag, &scan) orelse return false;
                    at = pair.end;
                } else at = tag.end;
                continue;
            };
            if (starts(input[at..], "[[") or starts(input[at..], "{{")) {
                const pair = syntax.balancedWithOpaqueScan(input, at, &scan) orelse return false;
                at = pair.end;
                continue;
            }
            if (input[at] == '[') {
                if (!ir.hasExternalProtocol(input[at + 1 ..])) return false;
                var links: ir.InlineIterator = .{ .input = input[at..], .renderer_boundaries = true };
                const token = links.next() orelse return false;
                if (token.kind != .external_link) return false;
                at += links.cursor;
                continue;
            }
            at += 1;
        }
        return false;
    }

    fn knownInlineHtmlName(name: []const u8) bool {
        return oneOf(name, &.{
            "b",         "strong", "i",    "em", "u",          "s",      "del", "strike", "ins", "sup",  "sub", "small", "big",
            "span",      "font",   "code", "tt", "kbd",        "samp",   "var", "cite",   "dfn", "abbr", "q",   "time",  "mark",
            "bdi",       "bdo",    "ruby", "rb", "rt",         "rtc",    "rp",  "data",   "wbr", "h1",   "h2",  "h3",    "h4",
            "h5",        "h6",     "div",  "p",  "blockquote", "center", "ul",  "ol",     "li",  "dl",   "dt",  "dd",    "onlyinclude",
            "noinclude", "table",
        });
    }
    // Sanitizer::validateTag requires attribute presence, including minimized
    // and explicitly empty values. Ambiguous attribute syntax proves neither
    // validity nor absence; leave its existing strict handling unchanged.
    fn microdataRequiredAttributes(tag: syntax.Tag) ?bool {
        if (tag.closing or (!tag.is("link") and !tag.is("meta")) or tag.attrs.len > 4096) return null;
        var itemprop = false;
        var content = false;
        var href = false;
        var property = false;
        var at: usize = 0;
        while (at < tag.attrs.len) {
            while (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\n\r\x0c", tag.attrs[at]) != null) : (at += 1) {}
            if (at == tag.attrs.len) break;
            const first = at;
            while (at < tag.attrs.len and (std.ascii.isAlphanumeric(tag.attrs[at]) or std.mem.indexOfScalar(u8, "_-:", tag.attrs[at]) != null)) : (at += 1) {}
            if (at == first) return null;
            const name = tag.attrs[first..at];
            if (!std.ascii.isAlphabetic(name[0]) and name[0] != '_' and name[0] != ':') return null;
            if (at < tag.attrs.len and tag.attrs[at] != '=' and std.mem.indexOfScalar(u8, " \t\n\r\x0c", tag.attrs[at]) == null) return null;
            itemprop = itemprop or std.ascii.eqlIgnoreCase(name, "itemprop");
            content = content or std.ascii.eqlIgnoreCase(name, "content");
            href = href or std.ascii.eqlIgnoreCase(name, "href");
            property = property or std.ascii.eqlIgnoreCase(name, "property");
            while (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\n\r\x0c", tag.attrs[at]) != null) : (at += 1) {}
            if (at == tag.attrs.len or tag.attrs[at] != '=') continue;
            at += 1;
            while (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\n\r\x0c", tag.attrs[at]) != null) : (at += 1) {}
            if (at == tag.attrs.len) break;
            const quote = tag.attrs[at];
            if (quote == '\'' or quote == '"') {
                at += 1;
                const close = std.mem.indexOfScalarPos(u8, tag.attrs, at, quote) orelse return null;
                if (std.mem.indexOfAny(u8, tag.attrs[at..close], "<>") != null) return null;
                at = close + 1;
                if (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\n\r\x0c", tag.attrs[at]) == null) return null;
            } else {
