        if (at == 0 or at >= input.len or at > 1024 or input[at] != '<') return false;
        // Keep the complete available prefix plain, including prior physical
        // lines. A newline cannot release an unfinished attribute/action scope.
        if (std.mem.indexOfAny(u8, input[0..at], "<>[]{}&'\"") != null) return false;
        var left = at;
        while (left != 0 and comparisonIdentifierByte(input[left - 1])) : (left -= 1) {}
        if (left == at or at - left > 64 or !comparisonIdentifierStart(input[left])) return false;
        if (left != 0 and std.mem.indexOfScalar(u8, " \t\r\n;(,=", input[left - 1]) == null) return false;
        var cursor = at + 1;
        if (cursor >= input.len or !comparisonIdentifierStart(input[cursor])) return false;
        const object_start = cursor;
        while (cursor < input.len and comparisonIdentifierByte(input[cursor])) : (cursor += 1) {}
        if (cursor - object_start > 64 or cursor >= input.len or input[cursor] != '.') return false;
        cursor += 1;
        if (cursor >= input.len or !comparisonIdentifierStart(input[cursor])) return false;
        const member_start = cursor;
        while (cursor < input.len and comparisonIdentifierByte(input[cursor])) : (cursor += 1) {}
        return cursor - member_start <= 64 and cursor < input.len and input[cursor] == ';';
    }
    // Parsed HTML pre retains a multiline paragraph. Prove the comparison's
    // physical line without treating a newline as an HTML/action scope boundary.
    fn parsedPreMemberComparisonOpening(input: []const u8, at: usize) bool {
        if (at >= input.len or at > 4096) return false;
        const line_start = if (std.mem.lastIndexOfScalar(u8, input[0..at], '\n')) |newline| newline + 1 else 0;
        if (!plainMemberComparisonOpening(input[line_start..], at - line_start)) return false;
        const prefix = input[0..line_start];
        var cursor: usize = 0;
        while (cursor < prefix.len) {
            if (starts(prefix[cursor..], "<!--")) {
                cursor = (std.mem.indexOfPos(u8, prefix, cursor + 4, "-->") orelse return false) + 3;
                continue;
            }
            if (starts(prefix[cursor..], "{{") or starts(prefix[cursor..], "[[")) {
                const pair = syntax.balanced(prefix, cursor) orelse return false;
                // A bracket/template boundary is not proof that an HTML owner
                // inside it closed. Such compound domains retain existing paths.
                if (std.mem.indexOfScalar(u8, prefix[cursor..pair.end], '<') != null) return false;
                cursor = pair.end;
                continue;
            }
            if (starts(prefix[cursor..], "{|")) return false;
            if (prefix[cursor] == '[') {
                const opening = cursor;
                var nesting: usize = 1;
                cursor += 1;
                while (cursor < prefix.len and nesting != 0) : (cursor += 1) {
                    if (prefix[cursor] == '[') {
                        if (nesting == max_depth) return false;
                        nesting += 1;
                    } else if (prefix[cursor] == ']') nesting -= 1;
                }
                if (nesting != 0 or std.mem.indexOfScalar(u8, prefix[opening..cursor], '<') != null) return false;
                continue;
            }
            if (prefix[cursor] == '<') {
                // Even a prior complete HTML tag is outside this finite plain
                // source proof. In particular, a quoted '>' cannot release an
                // unfinished attribute through tagAt's lexical boundary.
                if (syntax.tagAt(prefix, cursor) != null) return false;
                const earlier_line = if (std.mem.lastIndexOfScalar(u8, prefix[0..cursor], '\n')) |newline| newline + 1 else 0;
                if (!plainMemberComparisonOpening(prefix[earlier_line..], cursor - earlier_line)) {
                    // The existing atomic unknown-token rule proves this token
                    // independently, after this scanner proved its prefix plain.
                    // It owns neither HTML attributes nor a following line.
                    if (completeUnknownHtmlTokenEnd(prefix[cursor..], 0)) |end| {
                        cursor += end;
                        continue;
                    }
                    if (cursor + 1 == prefix.len or std.ascii.isAlphabetic(prefix[cursor + 1]) or prefix[cursor + 1] == '/') return false;
                }
            }
            cursor += 1;
        }
        return true;
    }
    fn prepareParsedPreComparisons(self: *Renderer, tracked: MissingText, style: Style, has_inline_parent: bool) Error!PreparedQuoteSource {
        if (!self.parsed_pre or !self.pre_block or has_inline_parent or tracked.generated_links.len != 0 or
            !style.code or !style.preserve_whitespace or style.provenance != .parsed or
            style.kind != .text or style.target.len != 0 or style.self_link_target != null or
            style.image != null or style.missing_nonaction or self.in_template_literal_scope or
            self.in_reference or self.poem_depth != 0 or self.body_link_target.len != 0 or
            self.navigation_target_probe != null)
            return .{ .source = tracked, .angles = &.{} };
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
        var angles: std.ArrayList(usize) = .empty;
        errdefer angles.deinit(self.a);
        var emitted: usize = 0;
        var scan: usize = 0;
        while (std.mem.indexOfScalarPos(u8, tracked.bytes, scan, '<')) |at| {
            if (at > 4096) break;
            scan = at + 1;
            if (!parsedPreMemberComparisonOpening(tracked.bytes, at)) continue;
            try out.append(self.a, try missingSlice(self.a, tracked, tracked.bytes[emitted..at]));
            try out.append(self.a, missingEdit(tracked, at, at + 1, "&lt;"));
            try angles.append(self.a, at);
            self.fallbacks.literal_markup = true;
            emitted = at + 1;
        }
        if (angles.items.len == 0) return .{ .source = tracked, .angles = &.{} };
        try out.append(self.a, try missingSlice(self.a, tracked, tracked.bytes[emitted..]));
        const result = try out.finish(self.a);
        errdefer {
            self.a.free(result.bytes);
            self.a.free(result.ranges);
            self.a.free(result.literal_curly_ranges);
        }
        return .{ .source = result, .angles = try angles.toOwnedSlice(self.a) };
    }
    fn comparisonIdentifierStart(byte: u8) bool {
        return std.ascii.isAlphabetic(byte) or byte == '_' or byte == '$';
    }
    fn comparisonIdentifierByte(byte: u8) bool {
        return comparisonIdentifierStart(byte) or std.ascii.isDigit(byte);
    }
    fn plainMemberComparisonInDomain(self: *const Renderer, input: []const u8, at: usize, style: Style) bool {
        if (style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.image != null or style.missing_nonaction or
            self.in_template_literal_scope or self.body_link_target.len != 0 or
            self.navigation_target_probe != null or !plainMemberComparisonOpening(input, at)) return false;
        // Leading-space wiki preformat is parsed source, even though its style
        // has code/whitespace flags. Opaque input and HTML/label parents must not
        // gain the same proof by handing us a convenient child slice.
        var domain = self.inline_source_domain;
        var remaining: usize = max_depth + 1;
        while (domain) |current| {
            if (remaining == 0) return false;
            remaining -= 1;
            const base = @intFromPtr(current.source.ptr);
            const child = @intFromPtr(input.ptr);
            if (child < base) return false;
            const relative = child - base;
            if (relative > current.source.len or input.len > current.source.len - relative or
                !plainMemberComparisonOpening(current.source, relative + at)) return false;
            domain = current.parent;
        }
        return true;
    }
    // A non-ASCII-leading lexical abbreviation is not an HTML tag name. The
    // sanitizer splits at each '<', so it cannot own a following unknown token.
    // Keep attributes, quotes, controls and ordinary ASCII HTML prefixes out.
    fn nonAsciiLexicalAnglePrefix(prefix: []const u8) bool {
        if (prefix.len < 4 or prefix.len > 256 or prefix[0] < 0x80 or
            (prefix[prefix.len - 1] != ' ' and prefix[prefix.len - 1] != '\t')) return false;
        const abbreviation = std.mem.trimEnd(u8, prefix, " \t");
        if (abbreviation.len < 2 or abbreviation[abbreviation.len - 1] != '.') return false;
        const word = abbreviation[0 .. abbreviation.len - 1];
        if (!std.unicode.utf8ValidateSlice(word)) return false;
        var cursor: usize = 0;
        while (cursor < word.len) {
            const width = std.unicode.utf8ByteSequenceLength(word[cursor]) catch return false;
            const cp = std.unicode.utf8Decode(word[cursor .. cursor + width]) catch return false;
            if (cp < 0x80) {
                if (!std.ascii.isAlphabetic(@intCast(cp))) return false;
            } else if (cp <= 0x00a0 or cp == 0x1680 or
                (cp >= 0x2000 and cp <= 0x200f) or (cp >= 0x2028 and cp <= 0x202f) or
                (cp >= 0x205f and cp <= 0x206f) or cp == 0x3000 or cp == 0xfeff or cp == 0xfffd) return false;
            cursor += width;
        }
        return true;
    }

    fn ordinaryNonAsciiLexicalAnglePrefix(input: []const u8, opening: usize, child: usize) bool {
        if (!nonAsciiLexicalAnglePrefix(input[opening + 1 .. child])) return false;
        // The prefix must be the first angle on its physical source line, not
        // attribute text hidden behind another unfinished opener. Do not borrow
        // an unproved wiki/action/quote domain on that line either.
        var cursor = opening;
        while (cursor != 0 and input[cursor - 1] != '\n' and input[cursor - 1] != '\r') {
            cursor -= 1;
            if (std.mem.indexOfScalar(u8, "<>[]{}'\"", input[cursor]) != null) return false;
        }
        // A physical newline does not terminate an unfinished HTML attribute.
        // Retain the original prior-angle veto across lines up to a real '>'.
        cursor = opening;
        while (cursor != 0) {
            cursor -= 1;
            if (input[cursor] == '<') return false;
            if (input[cursor] == '>') break;
        }
        return true;
    }

    // A qualified name is one Sanitizer element token, including its final dot.
    // Keep unqualified abbreviation ownership and all other dotted names separate.
    fn qualifiedDottedUnknownHtmlName(name: []const u8) bool {
        if (!std.mem.endsWith(u8, name, ".")) return false;
        const colon = std.mem.indexOfScalar(u8, name, ':') orelse return false;
        if (colon == 0 or colon + 2 >= name.len) return false;
        for (name[0..colon]) |ch| if (!std.ascii.isAlphabetic(ch)) return false;
        for (name[colon + 1 .. name.len - 1]) |ch| if (!std.ascii.isAlphabetic(ch)) return false;
        return true;
    }

    // Recover a complete unknown atomic name; the caller owns protected/template domains.
    // MediaWiki REL1_43 Sanitizer::ELEMENT_BITS_REGEX supplies the atomic boundary;
    // established protocols and unqualified terminal-dot domains remain separate.
    fn completeUnknownHtmlTokenEnd(input: []const u8, at: usize) ?usize {
        if (at >= input.len or input[at] != '<') return null;
        var preceding = at;
        while (preceding != 0) {
            preceding -= 1;
            if (input[preceding] == '<') {
                if (!ordinaryNonAsciiLexicalAnglePrefix(input, preceding, at)) return null;
                break;
            }
            if (input[preceding] == '>') break;
        }
        var cursor = at + 1;
        if (cursor < input.len and input[cursor] == '/') cursor += 1;
        const name_start = cursor;
        // A quote-leading unknown angle form fails the upstream element regex and
        // is escaped there as text. Keep earned BR quote-phase behavior explicitly.
        while (cursor < input.len and input[cursor] == '\'') : (cursor += 1) {}
        if (cursor >= input.len or !std.ascii.isAlphabetic(input[cursor])) return null;
        while (cursor < input.len) : (cursor += 1) {
            const ch = input[cursor];
            if (ch == '<' or ch == 0 or ch == '\r' or ch == '\n' or ch == 0x0b or ch == 0x0c) return null;
            if (ch == ' ' or ch == '\t' or ch == '/' or ch == '>') break;
        }
        if (cursor == input.len) return null;
        const name = input[name_start..cursor];
        const suffix_start = cursor;
        const prose_suffix = input[cursor] == ' ' or input[cursor] == '\t';
        // Ordinary ASCII names already belong to tagAt and its existing dispatch,
        // including table/extension and ordinary unknown-attribute handling.
        if (ordinaryHtmlName(name)) return null;
        if (!std.unicode.utf8ValidateSlice(name) or recognizedInlineHtmlName(name) or oneOf(name, &.{ "a", "img" })) return null;
        // Unqualified terminal-dot names retain their ordinary-nonaction proof.
        // A qualified ASCII name instead has the upstream atomic-name boundary.
        if (std.mem.endsWith(u8, name, ".") and !qualifiedDottedUnknownHtmlName(name)) return null;
        const protocol_end = std.mem.indexOfScalar(u8, name, ':') orelse name.len;
        if (ir.hasExternalProtocolScheme(name[0..protocol_end])) return null;
        // Unknown names have no recognized attribute owner. Preserve the suffix
        // verbatim until the first raw >; its wiki quote/actions run normally later.
        while (cursor < input.len and input[cursor] != '>') : (cursor += 1) {
            const ch = input[cursor];
            if (ch == '<' or ch == 0 or ch == '\r' or ch == '\n' or ch == 0x0b or ch == 0x0c) return null;
        }
        if (cursor == input.len) return null;
        const token = input[at + 1 .. cursor];
        if (!std.unicode.utf8ValidateSlice(token)) return null;
        // Sanitizer preserves an unknown token's prose suffix, including U+200B.
        // Admit that byte only after an ASCII name/suffix boundary; retain all
        // name, protocol, other format-control and protected-domain exclusions.
        var byte: usize = 0;
        while (byte < token.len) {
            const width = std.unicode.utf8ByteSequenceLength(token[byte]) catch return null;
            const cp = std.unicode.utf8Decode(token[byte .. byte + width]) catch return null;
            const prose_zero_width = cp == 0x200b and prose_suffix and at + 1 + byte > suffix_start;
            if ((cp < 0x20 and cp != '\t') or (cp >= 0x7f and cp <= 0x00a0) or cp == 0x1680 or
                (cp >= 0x2000 and cp <= 0x200f and !prose_zero_width) or (cp >= 0x2028 and cp <= 0x202f) or
                (cp >= 0x205f and cp <= 0x206f) or cp == 0x3000 or cp == 0xfeff or cp == 0xfffd) return null;
            byte += width;
        }
        return cursor + 1;
    }
    // Sanitization precedes link expansion: a raw '<' followed by '[' cannot
    // open an HTML element. Protect only that exact source byte; independently
    // parsed link labels, following HTML and unresolved tails keep their guards.
    fn preserveLinkedAngleOpening(self: *Renderer, input: []const u8, start: usize, end: usize, style: Style) Error!void {
        if (style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.missing_nonaction or start == 0 or
            end < start or end > input.len or end - start < 4 or input[start - 1] != '<' or
            !std.mem.eql(u8, input[start .. start + 2], "[[") or
            !std.mem.eql(u8, input[end - 2 .. end], "]]")) return;
        // Adjacent opening angles are independently literal, but an earlier
        // element opener must not lend its attribute bytes to this source proof.
        var before = start - 1;
        while (before != 0 and input[before - 1] == '<') before -= 1;
        while (before != 0) {
            before -= 1;
            if (input[before] == '<') return;
            if (input[before] == '>') break;
        }
        if (self.spans.items.len == 0) return;
        const opening = &self.spans.items[self.spans.items.len - 1];
        if (opening.provenance == .parsed and opening.kind == .text and opening.target.len == 0 and
            opening.text.len == 1 and opening.text.ptr == input[start - 1 ..].ptr)
            opening.provenance = .protected_literal;
    }

    // A complete unregistered alphabetic abbreviation ending in one dot, with
    // optional plain lexical text, is not an HTML tag. Use only in ordinary
    // parsed nonaction text after tagAt declined; keep syntax/attribute domains.
    // A dotted label followed by an italic comma-list of stem/suffix examples
    // is lexical text. The ordinary quote pass still owns an unmatched italic
    // toggle; do not turn the slash-separated examples into HTML attributes.
    fn terminalDotMorphologyEnd(input: []const u8, at: usize) ?usize {
        if (at >= input.len or input[at] != '<') return null;
        var preceding = at;
        while (preceding != 0) {
            preceding -= 1;
            if (input[preceding] == '<') return null;
            if (input[preceding] == '>') break;
        }
        var cursor = at + 1;
        const name_start = cursor;
        while (cursor < input.len and std.ascii.isAlphabetic(input[cursor])) : (cursor += 1) {}
        if (cursor == name_start or cursor >= input.len or input[cursor] != '.') return null;
        const name = input[name_start..cursor];
        if (recognizedInlineHtmlName(name) or oneOf(name, &.{ "a", "img" }) or ir.hasExternalProtocolScheme(name)) return null;
        cursor += 1;
        const space_start = cursor;
        while (cursor < input.len and (input[cursor] == ' ' or input[cursor] == '\t')) : (cursor += 1) {}
        if (cursor == space_start or !starts(input[cursor..], "''") or starts(input[cursor..], "'''")) return null;
        cursor += 2;
        var examples: usize = 0;
        while (cursor < input.len) {
            const stem = cursor;
            while (cursor < input.len and std.ascii.isAlphabetic(input[cursor])) : (cursor += 1) {}
            if (cursor == stem or cursor >= input.len or input[cursor] != '/') return null;
            cursor += 1;
            const suffix = cursor;
            while (cursor < input.len and std.ascii.isAlphabetic(input[cursor])) : (cursor += 1) {}
            if (cursor == suffix) return null;
            examples += 1;
            while (cursor < input.len and (input[cursor] == ' ' or input[cursor] == '\t')) : (cursor += 1) {}
            if (cursor < input.len and input[cursor] == ',') {
                cursor += 1;
                const separator = cursor;
                while (cursor < input.len and (input[cursor] == ' ' or input[cursor] == '\t')) : (cursor += 1) {}
                if (cursor == separator) return null;
                continue;
            }
            if (starts(input[cursor..], "''") and !starts(input[cursor..], "'''")) {
                cursor += 2;
                while (cursor < input.len and (input[cursor] == ' ' or input[cursor] == '\t')) : (cursor += 1) {}
            }
            return if (examples >= 2 and cursor < input.len and input[cursor] == '>') cursor + 1 else null;
        }
        return null;
    }

    // The complete dotted name is unknown upstream even when an initial is a
    // formatting tag name (B in <B.T.W.>). Keep this finite ordinary-text proof
    // separate from paired angles and registered/attributed tag handling.
    fn terminalDotInitialismEnd(input: []const u8, at: usize) ?usize {
        if (at >= input.len or input[at] != '<') return null;
        var preceding = at;
        while (preceding != 0) {
            preceding -= 1;
            if (input[preceding] == '<') return null;
            if (input[preceding] == '>') break;
        }
        var cursor = at + 1;
        var initials: usize = 0;
        while (cursor < input.len) {
            if (!std.ascii.isUpper(input[cursor])) return null;
            cursor += 1;
            if (cursor >= input.len or input[cursor] != '.') return null;
            cursor += 1;
            initials += 1;
            if (cursor < input.len and input[cursor] == '>')
                return if (initials >= 2) cursor + 1 else null;
        }
        return null;
    }

    fn terminalDotUnregisteredHtmlNameEnd(input: []const u8, at: usize) ?usize {
        return terminalDotLexicalEnd(input, at, false);
    }
    fn terminalDotLexicalEnd(input: []const u8, at: usize, quoted: bool) ?usize {
        if (at >= input.len or input[at] != '<') return null;
        var cursor = at + 1;
        const name_start = cursor;
        while (cursor < input.len and std.ascii.isAlphabetic(input[cursor])) : (cursor += 1) {}
        if (cursor == name_start or input.len - cursor < 2 or input[cursor] != '.') return null;
        const name = input[name_start..cursor];
        if (recognizedInlineHtmlName(name) or oneOf(name, &.{ "a", "img" }) or ir.hasExternalProtocolScheme(name)) return null;
        cursor += 1;
        var italic = false;
        var italic_lexical = false;
        var pairs: usize = 0;
        if (input[cursor] != '>') {
            if (input[cursor] != ' ' and input[cursor] != '\t') return null;
            var lexical = false;
            while (cursor < input.len and input[cursor] != '>') {
                const ch = input[cursor];
                if (quoted and ch == '\'') {
                    var end = cursor;
                    while (end < input.len and input[end] == '\'') : (end += 1) {}
                    if (end - cursor != 2) return null;
                    if (italic) {
                        if (!italic_lexical) return null;
                        pairs += 1;
                    } else italic_lexical = false;
                    italic = !italic;
                    cursor = end;
                    continue;
                }
                // No nested HTML, wiki/action/entity syntax, or attribute syntax.
                if (std.mem.indexOfScalar(u8, "<[]{}&'\"=/:\\", ch) != null) return null;
                const width = std.unicode.utf8ByteSequenceLength(ch) catch return null;
                if (width > input.len - cursor) return null;
                const cp = std.unicode.utf8Decode(input[cursor .. cursor + width]) catch return null;
                if ((cp < 0x20 and cp != '\t') or (cp >= 0x7f and cp <= 0x00a0) or cp == 0x1680 or
                    (cp >= 0x2000 and cp <= 0x200f) or (cp >= 0x2028 and cp <= 0x202f) or
                    (cp >= 0x205f and cp <= 0x206f) or cp == 0x3000 or cp == 0xfeff or cp == 0xfffd) return null;
                if (cp != ' ' and cp != '\t') {
                    lexical = true;
                    if (italic) italic_lexical = true;
                }
                cursor += width;
            }
            if (!lexical or cursor == input.len) return null;
        }
        if (quoted and (italic or pairs == 0)) return null;
        var preceding = at;
        while (preceding != 0) {
            preceding -= 1;
            if (input[preceding] == '<') return null;
            if (input[preceding] == '>') break;
        }
        return cursor + 1;
    }

    // A source-local parenthetical etymology abbreviation has its own lexical
    // boundary even when no greater-than follows it. Keep unrelated openers,
    // HTML/attribute syntax and wiki actions outside this finite proof.
    fn parentheticalTerminalDotBodyEnd(input: []const u8, at: usize) ?usize {
        if (at == 0 or at >= input.len or input[at - 1] != '(' or input[at] != '<') return null;
        var cursor = at + 1;
        const name_start = cursor;
        while (cursor < input.len and std.ascii.isAlphabetic(input[cursor])) : (cursor += 1) {}
        if (cursor == name_start or input.len - cursor < 3 or input[cursor] != '.') return null;
        const name = input[name_start..cursor];
        if (recognizedInlineHtmlName(name) or oneOf(name, &.{ "a", "img" }) or ir.hasExternalProtocolScheme(name)) return null;
        cursor += 1;
        if (input[cursor] != ' ' and input[cursor] != '\t') return null;
        var lexical = false;
        while (cursor < input.len and input[cursor] != ')') {
            const ch = input[cursor];
            if (std.mem.indexOfScalar(u8, "<>([]{}&'\"=/:\\", ch) != null) return null;
            const width = std.unicode.utf8ByteSequenceLength(ch) catch return null;
            if (width > input.len - cursor) return null;
            const cp = std.unicode.utf8Decode(input[cursor .. cursor + width]) catch return null;
            if ((cp < 0x20 and cp != '\t') or (cp >= 0x7f and cp <= 0x00a0) or cp == 0x1680 or
                (cp >= 0x2000 and cp <= 0x200f) or (cp >= 0x2028 and cp <= 0x202f) or
                (cp >= 0x205f and cp <= 0x206f) or cp == 0x3000 or cp == 0xfeff or cp == 0xfffd) return null;
            if (cp != ' ' and cp != '\t') lexical = true;
            cursor += width;
        }
        if (!lexical or cursor == input.len) return null;
        return cursor + 1;
    }
    fn parentheticalTerminalDotEnd(input: []const u8, at: usize) ?usize {
        const end = parentheticalTerminalDotBodyEnd(input, at) orelse return null;
        var preceding = at;
        while (preceding != 0) {
            preceding -= 1;
            if (input[preceding] == '>') break;
            if (input[preceding] == '<') {
                const previous_end = parentheticalTerminalDotBodyEnd(input, preceding) orelse return null;
                if (previous_end > at) return null;
            }
        }
        return end;
    }

    // A second raw opener cannot be part of this unregistered ASCII tag name.
    // Protect only the first angle: child HTML and wiki actions keep their phases.
    // No attribute, quote, closing-tag, or opaque/registered-name recovery here.
    fn interruptedUnregisteredHtmlName(input: []const u8, at: usize) bool {
        var cursor = at + 1;
        const name_start = cursor;
        if (cursor >= input.len or !std.ascii.isAlphabetic(input[cursor])) return false;
        while (cursor < input.len and (std.ascii.isAlphanumeric(input[cursor]) or input[cursor] == '-' or input[cursor] == ':')) : (cursor += 1) {}
        const name = input[name_start..cursor];
        // A colon is part of Sanitizer's interrupted name token, not a
        // registered HTML element. Keep URI schemes in their existing path.
        if (std.mem.indexOfScalar(u8, name, ':')) |colon|
            if (ir.hasExternalProtocolScheme(name[0..colon])) return false;
        return cursor < input.len and input[cursor] == '<' and
            !recognizedInlineHtmlName(name);
    }
    fn formattingAngleAttributesBalanced(attrs: []const u8) bool {
        var quote: u8 = 0;
        for (attrs) |byte| {
            if (quote != 0) {
                if (byte == quote) quote = 0;
            } else if (byte == '\'' or byte == '"') quote = byte;
        }
        return quote == 0;
    }
