        if (matched_inline_end) |proved| proved.* = matched != null and !block_boundary;
        if (paired_brackets) {
            // Outside the formatting/bidi scope: this is the authored outer
            // close, while the complete inner [text] keeps ordinary child IR.
            try self.protectedLiteral(input[pair.end .. pair.end + 1], style);
            return pair.end + 1;
        }
        return pair.end;
    }
    const FileTitleText = struct { text: []const u8, decoded_file: bool = false };
    fn fileTitleNamespace(self: *Renderer, original: []const u8) Error!bool {
        var title = original;
        if (std.mem.indexOfScalar(u8, title, '_') != null) {
            const normalized = try self.a.dupe(u8, title);
            std.mem.replaceScalar(u8, normalized, '_', ' ');
            title = normalized;
        }
        if (starts(title, ":")) title = title[1..];
        return self.namespaceOfTarget(self.currentWikiTarget(title)) == 6;
    }
    // Parser::replaceInternalLinks decodes the authored title once before
    // Title parsing. Keep this File seam separate from link= and URL targets.
    fn internalFileTitleText(self: *Renderer, raw: []const u8) Error!FileTitleText {
        const ordinary = try self.entityText(raw);
        if (std.mem.indexOfScalar(u8, raw, '%') == null) return .{ .text = ordinary };
        const decoded = try self.entityText(std.Uri.percentDecodeInPlace(try self.a.dupe(u8, raw)));
        if (try self.fileTitleNamespace(decoded) or try self.fileTitleNamespace(ordinary))
            return .{ .text = decoded, .decoded_file = true };
        return .{ .text = ordinary };
    }
    fn invalidDecodedFileTitle(target: []const u8) bool {
        if (!safeInternalTarget(target) or std.mem.indexOfAny(u8, target, "|<>") != null) return true;
        // TitleCodec rejects residual URL escapes and named references after
        // the single Parser decode and title entity normalization.
        for (target, 0..) |ch, i| if (ch == '%' and target.len - i >= 3 and
            std.ascii.isHex(target[i + 1]) and std.ascii.isHex(target[i + 2])) return true;
        for (target, 0..) |ch, i| if (ch == '&') {
            var end = i + 1;
            while (end < target.len and (std.ascii.isAlphanumeric(target[end]) or target[end] >= 128)) : (end += 1) {}
            if (end > i + 1 and end < target.len and target[end] == ';') return true;
        };
        return false;
    }

    fn entityText(self: *Renderer, value: []const u8) Error![]const u8 {
        if (std.mem.indexOfScalar(u8, value, '&') == null) return value;
        var out: std.ArrayList(u8) = .empty;
        var start: usize = 0;
        while (std.mem.indexOfScalarPos(u8, value, start, '&')) |i| {
            try out.appendSlice(self.a, value[start..i]);
            var buf: [4]u8 = undefined;
            if (decodeEntity(value[i..], &buf, false)) |decoded| {
                try out.appendSlice(self.a, decoded.bytes);
                start = i + decoded.consumed;
            } else {
                try out.append(self.a, '&');
                start = i + 1;
            }
        }
        try out.appendSlice(self.a, value[start..]);
        return try out.toOwnedSlice(self.a);
    }
    fn generatedDiagnostic(self: *Renderer, value: []const u8, inherited: Style) Error!void {
        var diagnostic = inherited;
        diagnostic.kind = .text;
        diagnostic.target = "";
        diagnostic.self_link_target = null;
        try self.diagnosticText(value, diagnostic);
    }
    // Mark only emitted diagnostic bytes. The existing boundary pass may space
    // their brackets without granting authored text a provenance exemption.
    fn diagnosticText(self: *Renderer, value: []const u8, style: Style) Error!void {
        const first = self.spans.items.len;
        try self.text(value, style);
        // textRaw appends (never coalesces) and ignores empty emissions. Poem
        // may add an actual break; it is not a diagnostic character boundary.
        for (self.spans.items[first..]) |*span| if (span.kind != .line_break) {
            span.generated_diagnostic = true;
        };
    }
    // A generated diagnostic terminator is not an authored close delimiter.
    // Keep an immediately following authored single ] separate without
    // discarding it or granting any parsed text a provenance exemption.
    fn malformedLinkMarker(self: *Renderer, style: Style, prefix_space: bool, following: []const u8) Error!void {
        try self.generatedDiagnostic(if (prefix_space) " [malformed link]" else "[malformed link]", style);
        if (following.len != 0 and following[0] == ']') try self.text(" ", style);
    }
    // Diagnose raw, self-contained malformed syntax with one forward scan.
    // Nested structural bytes cancel a candidate; protected/entity text is not
    // reinterpreted from its decoded display value.
    // Called only after the complete template/parameter matcher refuses.
    // Own a single-brace malformed invocation suffix without granting ordinary
    // inline table delimiters literal provenance or consuming child markup.
    fn malformedTemplateSingleBraceEnd(input: []const u8, start: usize) ?usize {
        if (!starts(input[start..], "{{") or starts(input[start..], "{{{")) return null;
        var at = start + 2;
        while (at < input.len and (input[at] == ' ' or input[at] == '\t')) : (at += 1) {}
        const name_start = at;
        while (at < input.len and !std.ascii.isWhitespace(input[at]) and
            std.mem.indexOfScalar(u8, "[]{}<>&'\"|", input[at]) == null) : (at += 1) {}
        if (at == name_start) return null;
        // The rejected invocation owns its lone closer. Leaving it outside the
        // diagnostic can join it to another brace across parsed formatting.
        if (starts(input[at..], "}") and !starts(input[at..], "}}")) return at + 1;
        if (!starts(input[at..], "|}") or starts(input[at..], "|}}")) return null;
        return at + 2;
    }

    // A rejected, same-line invocation can also have a plain spaced name and
    // plain argument followed by a pipe and lone closing brace. Diagnose only
    // that proved prefix; never scan past child syntax or a physical line end.
    fn malformedArgumentSingleBraceEnd(input: []const u8, start: usize) ?usize {
        if (!starts(input[start..], "{{") or starts(input[start..], "{{{")) return null;
        var at = start + 2;
        var first_pipe: ?usize = null;
        while (at < input.len) : (at += 1) {
            const c = input[at];
            if (std.mem.indexOfScalar(u8, "[]{}<>&'\"\r\n", c) != null) {
                if (c != '}' or starts(input[at..], "}}") or at == 0 or input[at - 1] != '|') return null;
                const pipe = first_pipe orelse return null;
                if (at <= pipe + 1 or trim(input[pipe + 1 .. at - 1]).len == 0) return null;
                return at + 1;
            }
            if (c == '|' and first_pipe == null) {
                if (trim(input[start + 2 .. at]).len == 0) return null;
                first_pipe = at;
            }
        }
        return null;
    }

    // The matched preprocessor keeps isolated closing braces inside an unclosed
    // invocation as literal text. Prove only a finite plain argument domain;
    // nested syntax and a complete closing pair remain outside this recovery.
    fn malformedInteriorBraceArgumentEnd(input: []const u8, start: usize) ?usize {
        if (start >= input.len or !starts(input[start..], "{{") or starts(input[start..], "{{{")) return null;
        const limit = start + @min(input.len - start, 4096);
        var at = start + 2;
        var first_pipe: ?usize = null;
        var last_interior: ?usize = null;
        while (at < limit) : (at += 1) {
            const c = input[at];
            if (c < 0x20 or c == 0x7f or std.mem.indexOfScalar(u8, "[]{<>&'\"", c) != null) return null;
            if (c == '|') {
                if (first_pipe == null) {
                    if (!literalBareParameterName(trim(input[start + 2 .. at]))) return null;
                    first_pipe = at;
                }
                continue;
            }
            if (c != '}') continue;
            if (at + 1 < input.len and input[at + 1] == '}') return null;
            const pipe = first_pipe orelse return null;
            if (at > pipe and input[at - 1] == '|') {
                const interior = last_interior orelse return null;
                if (!literalBareParameterName(trim(input[interior + 1 .. at - 1])) or
                    !std.unicode.utf8ValidateSlice(input[start .. at + 1])) return null;
                return at + 1;
            }
            const part_start = if (last_interior) |previous| previous + 1 else pipe + 1;
            if (!literalBareParameterName(trim(input[part_start..at])) or at + 1 >= limit or
                std.ascii.isWhitespace(input[at - 1]) or std.ascii.isWhitespace(input[at + 1]) or
                input[at + 1] == '|') return null;
            last_interior = at;
        }
        return null;
    }

    // An unmatched spaced bare name followed by an empty argument and one
    // closing brace is literal source, not a table terminator. The caller has
    // already refused a balanced invocation and excluded action/template scopes.
    fn malformedSpacedEmptyArgumentEnd(input: []const u8, start: usize) ?usize {
        if (start >= input.len or !starts(input[start..], "{{") or starts(input[start..], "{{{")) return null;
        const limit = start + @min(input.len - start, 4096);
        const pipe = std.mem.indexOfScalarPos(u8, input[0..limit], start + 2, '|') orelse return null;
        if (!starts(input[pipe..limit], "|}") or starts(input[pipe..], "|}}")) return null;
        var words = std.mem.splitScalar(u8, input[start + 2 .. pipe], ' ');
        var count: usize = 0;
        while (words.next()) |word| {
            if (!literalBareParameterName(word)) return null;
            count += 1;
        }
        if (count < 2) return null;
        return pipe + 2;
    }

    // A rejected invocation may contain ordinary inline HTML before its lone
    // closing brace. Prove the complete same-line delimiter domain first; only
    // its braces become literal, while children keep normal rendering semantics.
    // A complete single-bracket gloss is ordinary text only when the normal
    // inline parser proves it contains no action, rejected opener or child syntax.
    fn literalSquareGlossEnd(input: []const u8, start: usize) ?usize {
        if (start >= input.len or input[start] != '[' or starts(input[start..], "[[")) return null;
        const end = std.mem.indexOfScalarPos(u8, input, start + 1, ']') orelse return null;
        if (end == start + 1 or starts(input[end..], "]]")) return null;
        const body = input[start + 1 .. end];
        if (std.mem.indexOfAny(u8, body, "[]{}<>&'\"|\r\n") != null or trim(body).len == 0 or
            ir.hasExternalProtocol(body)) return null;
        var it: ir.InlineIterator = .{ .input = input[start .. end + 1], .renderer_boundaries = true };
        while (it.next()) |token| {
            if (token.kind != .text or token.target.len != 0 or token.literal_tail or token.rejected_external_opener or
                token.bold or token.italic) return null;
        }
        return end + 1;
    }

    fn malformedLiteralGlossArgumentSingleBraceEnd(input: []const u8, start: usize) ?usize {
        return malformedInlineArgumentSingleBraceEnd(input, start, true);
    }

    fn malformedStyledArgumentSingleBraceEnd(input: []const u8, start: usize) ?usize {
        return malformedInlineArgumentSingleBraceEnd(input, start, false);
    }

    // Preprocessor_Hash leaves isolated braces and an unclosed invocation
