                at += 1;
                continue;
            }
            if (std.mem.indexOfScalar(u8, "[]{}>&'\"\r\n", c) != null) {
                if (c != '}' or count != 0 or (if (allow_gloss) !gloss else !child) or starts(input[at..], "}}") or input[at - 1] != '|') return null;
                const pipe = first_pipe orelse return null;
                if (at <= pipe + 1 or trim(input[pipe + 1 .. at - 1]).len == 0 or
                    !std.unicode.utf8ValidateSlice(input[start .. at + 1])) return null;
                return at + 1;
            }
            if (c == '|' and first_pipe == null) {
                if (trim(input[start + 2 .. at]).len == 0) return null;
                first_pipe = at;
            }
            at += 1;
        }
        return null;
    }

    fn malformedPlain(self: *Renderer, tracked: MissingText, raw: []const u8, style: Style, entity_tail: []const u8, depth: usize) Error!?usize {
        if (style.provenance != .parsed) return null;
        const Candidate = struct { start: usize, template: bool, pipe: bool = false, name: bool = false };
        var candidate: ?Candidate = null;
        var emitted: usize = 0;
        var recovered = false;
        var at: usize = 0;
        while (at < raw.len) {
            if (candidate) |current| {
                const close: []const u8 = if (current.template) "}}" else "]]";
                if (starts(raw[at..], close)) {
                    const body = raw[current.start + 1 .. at];
                    if (trim(body).len != 0 and (!current.template or (current.pipe and current.name))) {
                        // Earlier text ends at a real malformed-token boundary;
                        // only the final untouched suffix can cross an entity.
                        _ = try self.plainWithMagicLinks(raw[emitted..current.start], style, "");
                        self.fallbacks.literal_markup = true;
                        var diagnostic = style;
                        diagnostic.kind = .text;
                        diagnostic.target = "";
                        diagnostic.self_link_target = null;
                        if (current.template) {
                            try self.generatedDiagnostic("[malformed template]", diagnostic);
                        } else {
                            try self.malformedInternalBody(tracked, body, "", raw[at + close.len ..], diagnostic, depth);
                        }
                        at += close.len;
                        emitted = at;
                        recovered = true;
                        candidate = null;
                        continue;
                    }
                    candidate = null;
                } else if (std.mem.indexOfScalar(u8, "{}[]<>&\r\n", raw[at]) != null) {
                    candidate = null;
                } else if (raw[at] == '|' and current.template and !current.pipe) {
                    candidate.?.pipe = true;
                    // This prefix is inspected only once for each candidate.
                    candidate.?.name = trim(raw[current.start + 1 .. at]).len != 0;
                }
            }
            if (candidate == null and starts(raw[at..], "]]")) {
                _ = try self.plainWithMagicLinks(raw[emitted..at], style, "");
                var diagnostic = style;
                diagnostic.kind = .text;
                diagnostic.target = "";
                diagnostic.self_link_target = null;
                if (style.kind == .text and style.target.len == 0 and style.self_link_target == null and
                    !style.missing_nonaction and !style.code and !style.preserve_whitespace and !self.in_template_literal_scope)
                {
                    // No accepted action or malformed opener owns this exact
                    // source pair. Preserve only its authored closing bytes.
                    try self.protectedLiteral(raw[at .. at + 2], diagnostic);
                } else try self.malformedLinkMarker(diagnostic, true, raw[at + 2 ..]);
                self.fallbacks.literal_markup = true;
                at += 2;
                emitted = at;
                recovered = true;
                continue;
            }
            // Complete template/parameter pairs and URL tokens are consumed by
            // inlineTextWithMissing before plain-token recovery. Diagnose only
            // this still-parsed raw closing pair, never decoded literal text.
            if (candidate == null and starts(raw[at..], "}}")) {
                _ = try self.plainWithMagicLinks(raw[emitted..at], style, "");
                try self.generatedDiagnostic("[malformed template]", style);
                self.fallbacks.literal_markup = true;
                at += 2;
                emitted = at;
                recovered = true;
                continue;
            }
            if (candidate == null and (raw[at] == '{' or raw[at] == '[') and
                (at == 0 or raw[at - 1] != raw[at]) and
                (at + 1 == raw.len or raw[at + 1] != raw[at]))
            {
                candidate = .{ .start = at, .template = raw[at] == '{' };
            }
            at += 1;
        }
        if (!recovered) return null;
        // Preserve normal ISBN entity-boundary recognition and its consumed
        // byte count exactly for the final untouched portion of this token.
        return try self.plainWithMagicLinks(raw[emitted..], style, entity_tail);
    }
    // MediaWiki leaves complete empty/space-only link pairs as visible text.
    // The raw pair has no child syntax; keep only these proved bytes literal.
    fn emptyInternalLinkLiteral(self: *Renderer, raw: []const u8, inherited: Style) Error!bool {
        if (inherited.provenance != .parsed or raw.len < 4 or !starts(raw, "[[") or
            !std.mem.endsWith(u8, raw, "]]")) return false;
        for (raw[2 .. raw.len - 2]) |byte| if (byte != ' ') return false;
        var nonaction = inherited;
        nonaction.kind = .text;
        nonaction.target = "";
        nonaction.self_link_target = null;
        self.fallbacks.literal_markup = true;
        try self.protectedLiteral(raw, nonaction);
        return true;
    }

    // A raw isolated curly makes a title invalid, not navigable. MediaWiki's
    // invalid-form path preserves its authored brackets and separator. Protect
    // only those delimiters; independently parsed children keep their domains.
    fn preserveIsolatedCurlyInvalidLink(self: *Renderer, tracked: MissingText, raw: []const u8, trail: []const u8, inherited: Style, depth: usize) Error!bool {
        if (tracked.unknown or !self.interruptedBodyTargetDomain() or
            inherited.kind != .text or inherited.target.len != 0 or inherited.self_link_target != null or
            inherited.provenance != .parsed or inherited.code or inherited.preserve_whitespace or inherited.missing_nonaction)
            return false;
        if (raw.len < 7 or raw.len > 4096 or !starts(raw, "[[") or !std.mem.endsWith(u8, raw, "]]")) return false;
        const base = @intFromPtr(tracked.bytes.ptr);
        const ptr = @intFromPtr(raw.ptr);
        if (ptr < base or ptr - base > tracked.bytes.len or raw.len > tracked.bytes.len - (ptr - base)) return false;
        const first = ptr - base;
        const last = first + raw.len;
        for (tracked.ranges) |range| if (range.start < last and range.end > first) return false;
        for (tracked.generated_links) |range| if (range.start < last and range.end > first) return false;
        var opaque_scan: syntax.OpaqueScan = .{};
        const pair = syntax.balancedWithOpaqueScan(raw, 0, &opaque_scan) orelse return false;
        if (pair.end != raw.len) return false;
        const body = raw[2 .. raw.len - 2];
        const pipe = std.mem.indexOfScalar(u8, body, '|') orelse return false;
        const target = body[0..pipe];
        // A single raw opening curly is itself an invalid title. Its following
        // pipe belongs to this complete rejected link, not a physical table.
        // Keep this additional case source-local and do not lend authority to
        // transformed, protected or separately narrowed child input.
        const bare_opening_title = std.mem.eql(u8, target, "{");
        if (bare_opening_title) {
            if (tracked.lost_missing_range or tracked.generated_source != null or
                self.navigation_target_probe != null or self.inline_image_attribute or
                std.mem.indexOfAny(u8, body[pipe + 1 ..], "\r\n") != null) return false;
            if (self.inline_source_domain) |domain| if (domain.parent != null or
