        return try self.plainWithMagicLinks(plain_text[emitted..], style, tail);
    }

    fn literalPlainTableTails(self: *Renderer, input: []const u8, plain_text: []const u8, style: Style, tail: []const u8) Error!?usize {
        if (style.provenance != .parsed or style.code or style.preserve_whitespace or
            style.kind != .text or style.target.len != 0 or style.self_link_target != null) return null;
        var emitted: usize = 0;
        var search: usize = 0;
        var found = false;
        while (std.mem.indexOfPos(u8, plain_text, search, "|}")) |at| {
            search = at + 2;
            if (!self.ordinaryInlineTableTailInDomain(input, plain_text, at) and
                !(try self.formattedInlineTableTailInDomain(input, plain_text, at, style)) and
                !self.literalDisplayFormulaTableTailInDomain(input, plain_text, at) and
                !self.literalSingleBraceFieldsTailInDomain(input, plain_text, at)) {
                if (style.missing_nonaction or (!self.literalLinkedBraceTableTailInDomain(input, plain_text, at) and
                    !self.hiddenCategoryTableTailInDomain(input, plain_text, at))) continue;
                self.fallbacks.literal_markup = true;
            }
            _ = try self.plainWithMagicLinks(plain_text[emitted..at], style, "");
            try self.protectedLiteral(plain_text[at .. at + 2], style);
            emitted = at + 2;
            found = true;
        }
        if (!found) return null;
        return try self.plainWithMagicLinks(plain_text[emitted..], style, tail);
    }
    // Link syntax has already become complete anchors when MediaWiki converts
    // manual raw bodies. Prove only complete ordinary links here, keeping their
    // target punctuation separate from the conversion grammar in visible text.
    // Internal targets become link holders before conversion. Permit decoded
    // entity transport only inside an already explicit fragment; the raw title
    // and namespace domain and every unsupported decoded delimiter stay strict.
    fn manualConversionInternalTarget(raw: []const u8) bool {
        if (raw.len == 0) return false;
        var at: usize = 0;
        var in_fragment = false;
        while (at < raw.len) {
            if (raw[at] == '#') in_fragment = true;
            var scratch: [4]u8 = undefined;
            const decoded = if (raw[at] == '&') decodeEntity(raw[at..], &scratch, false) else null;
            const part = if (decoded) |value| value.bytes else raw[at .. at + 1];
            if (std.mem.indexOfAny(u8, part, "[]{}|;<>\r\n") != null) return false;
            if (decoded != null) {
                if (!in_fragment or std.mem.indexOf(u8, part, "\xef\xbf\xbd") != null) return false;
                for (part) |byte| if (std.ascii.isControl(byte)) return false;
            }
            at += if (decoded) |value| value.consumed else 1;
        }
        return true;
    }

    // An authored leading colon prevents relative/subpage normalization. Prove
    // only a single encoded leading slash and a flat ordinary main title;
    // the existing link emitter still owns its one decode and fragment action.
    // Ordinary links become anchors before conversion. This narrow raw-title
    // proof keeps semicolons out of variant grammar: the title has no colon
    // after its optional, independently resolved remote interwiki prefix.
    // Ordinary link emission still owns normalization, URL escaping and labels.
    fn manualConversionSemicolonTarget(self: *const Renderer, raw: []const u8) bool {
        if (raw.len == 0 or raw.len > 4096 or !std.unicode.utf8ValidateSlice(raw) or
            std.mem.indexOfScalar(u8, raw, ';') == null or !safeInternalTarget(raw) or
            std.mem.indexOfAny(u8, raw, "[]{}|<>&%#\"'\r\n\t") != null or
            std.mem.indexOf(u8, raw, "=>") != null) return false;
        for (raw) |byte| if (std.ascii.isControl(byte)) return false;
        var title = trim(raw);
        if (starts(title, ":")) {
            const ns = self.context.namespace_catalog orelse return false;
            title = trim(title[1..]);
            if (self.namespaceOfTarget(title) != null) return false;
            const colon = std.mem.indexOfScalar(u8, title, ':') orelse return false;
            var known_remote = false;
            const prefix = trim(title[0..colon]);
            for (ns.interwiki_rows) |row| if (std.ascii.eqlIgnoreCase(prefix, row.prefix)) {
                known_remote = !row.is_current_wiki;
                break;
            };
            if (!known_remote) return false;
            title = trim(title[colon + 1 ..]);
        }
        if (title.len == 0 or starts(title, "/") or starts(title, ".") or
            std.mem.indexOfScalar(u8, title, ':') != null) return false;
        var pieces = std.mem.splitScalar(u8, title, ';');
        while (pieces.next()) |piece| if (trim(piece).len == 0) return false;
        return true;
    }

    fn manualConversionExplicitSlashEntityTarget(raw: []const u8) bool {
        if (raw.len < 4 or raw.len > 4096 or raw[0] != ':' or raw[1] != '&') return false;
        var scratch: [4]u8 = undefined;
        const slash = decodeEntity(raw[1..], &scratch, false) orelse return false;
        if (!std.mem.eql(u8, slash.bytes, "/")) return false;
        const rest = raw[1 + slash.consumed ..];
        const hash = std.mem.indexOfScalar(u8, rest, '#') orelse rest.len;
        const title = rest[0..hash];
        if (title.len == 0 or title[0] == '.' or !std.mem.eql(u8, title, trim(title)) or
            std.mem.indexOfAny(u8, title, ":/&%[]{}|;<>\r\n\t") != null) return false;
        var decoded: [4096]u8 = undefined;
        decoded[0] = ':';
        decoded[1] = '/';
        @memcpy(decoded[2 .. 2 + rest.len], rest);
        const target = decoded[0 .. 2 + rest.len];
        return safeInternalTarget(target) and manualConversionInternalTarget(target);
    }

    // Complete explicit local links become anchors before conversion. Decode
    // only separator entities for this proof; ordinary link emission still
    // owns the original target and its one entity-normalization pass.
    fn manualConversionLocalEntityTarget(self: *const Renderer, raw: []const u8) bool {
        if (raw.len < 3 or raw.len > 4096 or raw[0] != ':') return false;
        const namespaces = self.context.namespace_catalog orelse return false;
        var buffer: [4096]u8 = undefined;
        var used: usize = 0;
        var at: usize = 0;
        var has_entity = false;
        while (at < raw.len) {
            if (raw[at] == '#') {
                // Preserve the authored fragment for the existing fragment
                // proof. Ordinary link emission still decodes it only once.
                @memcpy(buffer[used .. used + raw.len - at], raw[at..]);
                used += raw.len - at;
                break;
            }
            if (raw[at] == '&') {
                var scratch: [4]u8 = undefined;
                const entity_value = decodeEntity(raw[at..], &scratch, false) orelse return false;
                if (entity_value.bytes.len != 1 or (entity_value.bytes[0] != ':' and entity_value.bytes[0] != '/')) return false;
                buffer[used] = entity_value.bytes[0]; used += 1;
                at += entity_value.consumed; has_entity = true;
            } else {
                buffer[used] = raw[at]; used += 1; at += 1;
            }
        }
        const decoded = buffer[0..used];
        if (!has_entity or !safeInternalTarget(decoded) or !manualConversionInternalTarget(decoded)) return false;
        const fragment = std.mem.indexOfScalar(u8, decoded, '#') orelse decoded.len;
        const title = decoded[1..fragment];
        const colon = std.mem.indexOfScalar(u8, title, ':') orelse return false;
        if (colon == 0) return false;
        var title_buffer: [4096]u8 = undefined;
        var title_writer = std.Io.Writer.fixed(&title_buffer);
        @import("namespace_registry").normalizeSpacing(&title_writer, title[colon + 1 ..]) catch return false;
        if (title_writer.buffered().len == 0) return false;
        const namespace = namespaces.byName(title[0..colon]) orelse return false;
        // Never promote encoded transclusions or an interwiki/unknown prefix.
        return namespace.id != -2 and namespace.id != 0 and namespace.id != 6 and namespace.id != 14;
    }

    // This is only an admission proof for an already explicit interwiki link.
    // Keep the authored bytes for ordinary emission, which owns entity decoding
    // and expands one selected interwiki row over the complete remaining title.
    fn manualConversionInterwikiEntityTarget(self: *const Renderer, raw: []const u8) bool {
        if (raw.len < 3 or raw.len > 4096 or raw[0] != ':' or !safeInternalTarget(raw)) return false;
        const registry = self.context.namespace_catalog orelse return false;
        var buffer: [4096]u8 = undefined;
        var used: usize = 0;
        var cursor: usize = 0;
        var has_entity = false;
        while (cursor < raw.len) {
            if (raw[cursor] == '&') {
                var scratch: [4]u8 = undefined;
                const decoded_entity = decodeEntity(raw[cursor..], &scratch, false) orelse return false;
                if (!std.mem.eql(u8, decoded_entity.bytes, ":")) return false;
                buffer[used] = ':'; used += 1;
                cursor += decoded_entity.consumed; has_entity = true;
            } else {
                buffer[used] = raw[cursor]; used += 1; cursor += 1;
            }
        }
        const decoded = buffer[0..used];
        if (!has_entity or !safeInternalTarget(decoded) or !manualConversionInternalTarget(decoded)) return false;
        // Match ordinary title normalization and namespace precedence. A local
        // namespace, including an alias colliding with an interwiki prefix, is
        // never authorized by this separate interwiki proof.
        std.mem.replaceScalar(u8, decoded, '_', ' ');
        const title = decoded[1..];
        if (self.namespaceOfTarget(title) != null) return false;
        const colon = std.mem.indexOfScalar(u8, title, ':') orelse return false;
        const prefix = std.mem.trim(u8, title[0..colon], " \t");
        if (prefix.len == 0 or std.mem.trim(u8, title[colon + 1 ..], " \t").len == 0) return false;
        for (registry.interwiki_rows) |row| if (std.ascii.eqlIgnoreCase(row.prefix, prefix)) {
            // Current-wiki aliases require a separate local-title proof. Do not
            // recursively reinterpret a remote row's remainder as another map.
            return !row.is_current_wiki;
        };
        return false;
    }

    // With a complete normal map, an unrecognized prefix is an ordinary main
    // title, exactly as in interwikiDestination. This proves only admission;
    // the existing emitter still decodes and creates the original link.
    fn manualConversionMainEntityTarget(self: *const Renderer, raw: []const u8) bool {
        if (raw.len < 3 or raw.len > 4096 or raw[0] != ':' or !safeInternalTarget(raw)) return false;
        const registry = self.context.namespace_catalog orelse return false;
        if (registry.interwiki_magic == null) return false;
        var buffer: [4096]u8 = undefined;
        var used: usize = 0;
        var cursor: usize = 0;
        var has_entity = false;
        var has_at_entity = false;
        while (cursor < raw.len) {
            if (raw[cursor] == '#') {
                @memcpy(buffer[used .. used + raw.len - cursor], raw[cursor..]);
                used += raw.len - cursor;
                break;
            }
            if (raw[cursor] == '&') {
                var scratch: [4]u8 = undefined;
                const decoded_entity = decodeEntity(raw[cursor..], &scratch, false) orelse return false;
                if (decoded_entity.bytes.len != 1 or (decoded_entity.bytes[0] != ':' and decoded_entity.bytes[0] != '@')) return false;
                has_at_entity = has_at_entity or decoded_entity.bytes[0] == '@';
                buffer[used] = decoded_entity.bytes[0]; used += 1;
                cursor += decoded_entity.consumed; has_entity = true;
            } else {
                buffer[used] = raw[cursor]; used += 1; cursor += 1;
            }
        }
        const decoded = buffer[0..used];
        if (!has_entity or !safeInternalTarget(decoded) or !manualConversionInternalTarget(decoded)) return false;
        std.mem.replaceScalar(u8, decoded, '_', ' ');
        const fragment_at = std.mem.indexOfScalar(u8, decoded, '#') orelse decoded.len;
        const title = decoded[1..fragment_at];
        if (trim(title).len == 0 or self.namespaceOfTarget(title) != null) return false;
        // Without a colon this is an ordinary explicit main title. An encoded
        // at sign has no namespace or interwiki meaning; the normal emitter
        // still owns its one decode, while the fragment proof stays unchanged.
        const colon = std.mem.indexOfScalar(u8, title, ':') orelse return has_at_entity;
        const prefix = std.mem.trim(u8, title[0..colon], " \t");
        const remainder = title[colon + 1 ..];
        const fragment = std.mem.indexOfScalar(u8, remainder, '#') orelse remainder.len;
        if (prefix.len == 0 or std.mem.trim(u8, remainder[0..fragment], " \t").len == 0) return false;
        // Current-wiki aliases also belong to the existing map route. Do not
        // infer another namespace or language from any unmatched prefix.
        for (registry.interwiki_rows) |row| if (std.ascii.eqlIgnoreCase(row.prefix, prefix)) return false;
        return true;
    }

    // Sanitizer escapes these punctuation angles before conversion, and the
    // ordinary bracketed-link pass owns the complete action. Keep this proof
    // delimiter-free so its source spelling cannot change conversion nesting.
    fn manualExternalAngleEnd(input: []const u8, at: usize) ?usize {
        if (at >= input.len or !starts(input[at..], "<[")) return null;
        const opening = at + 1;
        const stop = std.mem.indexOfAnyPos(u8, input, opening + 1, "[]<>{}|&\"'\r\n") orelse return null;
        if (input[stop] != ']' or stop + 1 >= input.len or input[stop + 1] != '>') return null;
        var iterator: ir.InlineIterator = .{ .input = input[opening .. stop + 1], .renderer_boundaries = true };
        const token = iterator.next() orelse return null;
        if (token.kind != .external_link or iterator.cursor != stop + 1 - opening or
            token.external_label_prefix.len != 0 or token.text.len == 0 or
            token.text.ptr == token.target.ptr or !safeUrl(token.target) or
            unresolvedExternalActionTarget(token.target)) return null;
        return stop + 2;
    }
    fn manualConversionLinkedScope(self: *Renderer, body: []const u8, allow_links: bool) bool {
        return self.manualConversionInlineScope(body, allow_links, false);
    }
    fn manualConversionInlineScope(self: *Renderer, body: []const u8, allow_links: bool, selected_alternative: bool) bool {
        // Quotes run before conversion upstream. This subset requires an
        // already balanced HTML scope, not raw quote state spanning choices.
        if (selected_alternative and std.mem.indexOf(u8, body, "''") != null) return false;
        // Core parses a complete anchor before conversion. A colon in its
        // visible label has the generated anchor prefix, not a variant prefix.
        // Raw semicolons can start another choice; keep those labels unsupported
        // (including entity semicolons conservatively) when admitting colons.
        if (!selected_alternative and !allow_links and std.mem.indexOfScalar(u8, body, ':') != null and
            std.mem.indexOfScalar(u8, body, ';') != null) return false;
        var stack: [max_depth][]const u8 = undefined;
        var count: usize = 0;
        var scan: usize = 0;
        var complete_link_prefix = false;
        const has_semicolon = std.mem.indexOfScalar(u8, body, ';') != null;
        while (scan < body.len) {
            const tail = body[scan..];
            if (tail[0] == '[') {
                // A plain IPA/gloss group is ordinary text, not an anchor.
                // ConverterRule has no rule without a colon; retain the normal
                // inline parser's no-action proof and refuse choice delimiters.
                // Selected alternatives and nested link labels keep their gates.
                if (allow_links and !selected_alternative) if (literalSquareGlossEnd(body, scan)) |literal_end| {
                    const bracket_text = body[scan + 1 .. literal_end - 1];
                    var ordinary = std.unicode.utf8ValidateSlice(bracket_text) and
                        std.mem.indexOfAny(u8, bracket_text, ":;") == null and magicLinkStart(bracket_text, 0) == null;
                    for (bracket_text) |byte| if (std.ascii.isControl(byte)) { ordinary = false; break; };
                    if (ordinary) {
                        scan = literal_end;
                        continue;
                    }
                };
                if (!allow_links) return false;
                var links: ir.InlineIterator = .{ .input = body, .cursor = scan, .renderer_boundaries = true, .link_trail = self.context.link_trail };
                const link_node = links.next() orelse return false;
                const internal = starts(tail, "[[");
                if (link_node.kind != (if (internal) ir.InlineKind.link else ir.InlineKind.external_link) or
                    links.cursor <= scan or link_node.target.len == 0 or link_node.text.len == 0 or
                    link_node.link_empty_label or link_node.link_label_restored_close or
                    (if (internal) !manualConversionInternalTarget(link_node.target) and
                        (selected_alternative or (!self.manualConversionLocalEntityTarget(link_node.target) and
                            !self.manualConversionInterwikiEntityTarget(link_node.target) and
                            !self.manualConversionMainEntityTarget(link_node.target) and
                            !manualConversionExplicitSlashEntityTarget(link_node.target) and
                            !self.manualConversionSemicolonTarget(link_node.target))) else std.mem.indexOfAny(u8, link_node.target, "[]{}|;<>\r\n") != null) or
                    std.mem.indexOf(u8, link_node.target, "=>") != null or
                    std.mem.indexOf(u8, link_node.target, "=&gt;") != null) return false;
                // Media/category transclusions are not ordinary link scopes.
                if (internal) if (self.namespaceOfTarget(link_node.target)) |ns| {
                    if (ns == 6 or ns == 14) return false;
                };
                if (selected_alternative and internal and !starts(link_node.target, ":") and
                    std.mem.indexOfScalar(u8, link_node.target, ':') != null and
                    self.namespaceOfTarget(link_node.target) == null) return false;
                // Link holders precede conversion upstream. Do not infer the
                // separator meaning of a semicolon hidden in that earlier phase.
                if (selected_alternative and std.mem.indexOfScalar(u8, body[scan..links.cursor], ';') != null) return false;
                if (!self.manualConversionInlineScope(link_node.text, false, selected_alternative)) return false;
                // Unescaped interlanguage links can disappear before conversion.
                // Only a local/explicit ordinary link (or an external anchor)
                // supplies the HTML prefix needed by the new colon proof.
                if (!internal or starts(link_node.target, ":") or
                    std.mem.indexOfScalar(u8, link_node.target, ':') == null or
                    self.namespaceOfTarget(link_node.target) != null)
                    complete_link_prefix = true;
                scan = links.cursor;
                continue;
            }
            if (tail[0] == '<') {
                if (!selected_alternative and allow_links and manualExternalAngleEnd(body, scan) != null) {
                    // The existing link branch still validates its target/label.
                    scan += 1;
                    continue;
                }
                const tag = syntax.tagAt(body, scan) orelse return false;
                if (selected_alternative and (!formattingAngleAttributesBalanced(tag.attrs) or
                    (tag.closing and trim(tag.attrs).len != 0))) return false;
                // A complete ordinary link is already an anchor before core
                // conversion. Its attribute-free BR has no matching closer or
                // rule syntax; keep the normal line-break renderer and target.
                // Choice alternatives and BR outside the label remain strict.
                if (!selected_alternative and !allow_links and tag.is("br") and
                    !tag.closing and trim(tag.attrs).len == 0)
                {
                    scan = tag.end;
                    continue;
                }
                const linked_abbreviation = !allow_links and !selected_alternative and tag.is("abbr");
                if (linked_abbreviation and (!formattingAngleAttributesBalanced(tag.attrs) or
                    (tag.closing and trim(tag.attrs).len != 0))) return false;
                if (!(tag.is("b") or tag.is("i") or tag.is("strong") or tag.is("em") or tag.is("span") or tag.is("sup") or (!selected_alternative and tag.is("small")) or linked_abbreviation) or tag.self_closing or
                    std.mem.indexOfAny(u8, body[scan..tag.end], "[]{}|:") != null) return false;
                if (tag.closing) {
                    if (count == 0 or !std.ascii.eqlIgnoreCase(stack[count - 1], tag.name)) return false;
                    count -= 1;
                } else {
                    if (count == stack.len) return false;
                    stack[count] = tag.name;
                    count += 1;
                }
                scan = tag.end;
                continue;
            }
            // Links are rendered before ConverterRule splits at its first colon.
            // A completed anchor in that prefix cannot name a valid variant, so
            // the whole body is displayed raw. Keep choice separators unsupported
            // here; a leading plain colon must still follow the existing rule path.
            if (std.mem.indexOfScalar(u8, "[]{}|\r\n", tail[0]) != null or
                (!selected_alternative and allow_links and tail[0] == ':' and (!complete_link_prefix or has_semicolon)) or
                starts(tail, "=>") or starts(tail, "=&gt;")) return false;
            scan += 1;
        }
        return count == 0;
    }

    const ManualVariantAlias = struct { code: []const u8, replacement: []const u8 };
    fn manualDeprecatedVariant(code: []const u8) []const u8 {
        // Matched MediaWiki LanguageCode::replaceDeprecatedCodes. Comparison is
        // case-insensitive because validateVariant first lowercases its input.
        const aliases = [_]ManualVariantAlias{
            .{ .code = "als", .replacement = "gsw" },
            .{ .code = "bat-smg", .replacement = "sgs" },
            .{ .code = "be-x-old", .replacement = "be-tarask" },
            .{ .code = "fiu-vro", .replacement = "vro" },
            .{ .code = "roa-rup", .replacement = "rup" },
            .{ .code = "zh-classical", .replacement = "lzh" },
            .{ .code = "zh-min-nan", .replacement = "nan" },
            .{ .code = "zh-yue", .replacement = "yue" },
        };
        for (aliases) |alias| if (std.ascii.eqlIgnoreCase(code, alias.code)) return alias.replacement;
        return code;
    }
    fn manualBcp47Variant(code: []const u8) []const u8 {
        // These are LanguageCode's nonstandard spellings. Remaining BCP47 work
        // changes case only, which the comparison below already disregards.
        const normalized = manualDeprecatedVariant(code);
        const aliases = [_]ManualVariantAlias{
            .{ .code = "cbk-zam", .replacement = "cbk" },
            .{ .code = "de-formal", .replacement = "de-x-formal" },
            .{ .code = "eml", .replacement = "egl" },
            .{ .code = "en-rtl", .replacement = "en-x-rtl" },
            .{ .code = "es-formal", .replacement = "es-x-formal" },
            .{ .code = "hu-formal", .replacement = "hu-x-formal" },
            .{ .code = "map-bms", .replacement = "jv-x-bms" },
            .{ .code = "mo", .replacement = "ro-cyrl-md" },
            .{ .code = "nrm", .replacement = "nrf" },
            .{ .code = "nl-informal", .replacement = "nl-x-informal" },
            .{ .code = "roa-tara", .replacement = "nap-x-tara" },
            .{ .code = "simple", .replacement = "en-simple" },
            .{ .code = "sr-ec", .replacement = "sr-cyrl" },
            .{ .code = "sr-el", .replacement = "sr-latn" },
            .{ .code = "crh-ro", .replacement = "crh-latn-ro" },
            .{ .code = "kk-cn", .replacement = "kk-arab-cn" },
            .{ .code = "kk-tr", .replacement = "kk-latn-tr" },
            .{ .code = "zh-cn", .replacement = "zh-hans-cn" },
            .{ .code = "zh-sg", .replacement = "zh-hans-sg" },
            .{ .code = "zh-my", .replacement = "zh-hans-my" },
            .{ .code = "zh-tw", .replacement = "zh-hant-tw" },
            .{ .code = "zh-hk", .replacement = "zh-hant-hk" },
            .{ .code = "zh-mo", .replacement = "zh-hant-mo" },
        };
        for (aliases) |alias| if (std.ascii.eqlIgnoreCase(normalized, alias.code)) return alias.replacement;
        return normalized;
    }
    fn manualVariantKnown(code: []const u8, variants: []const []const u8) bool {
        const normalized = manualDeprecatedVariant(code);
        for (variants) |variant| if (std.ascii.eqlIgnoreCase(normalized, variant)) return true;
        for (variants) |variant| if (std.ascii.eqlIgnoreCase(normalized, manualBcp47Variant(variant))) return true;
        return false;
    }
    fn invalidPlainManualRules(body: []const u8, variants: []const []const u8) bool {
        // An invalid selector clears all bidirectional/unidirectional tables in
        // ConverterRule::parseRules, then raw display retains the complete body.
        // No preferred variant, edition language or partial winning choice is used.
        if (body.len == 0 or body.len > 4096 or variants.len == 0 or variants.len > 64 or
            !std.unicode.utf8ValidateSlice(body) or std.mem.indexOfAny(u8, body, "[]{}<>&|\"'") != null) return false;
        for (body) |byte| if (std.ascii.isControl(byte)) return false;
        for (variants) |variant| {
            if (variant.len == 0 or variant.len > 128) return false;
            for (variant) |byte| if (!std.ascii.isLower(byte) and !std.ascii.isDigit(byte) and byte != '-') return false;
        }
        var invalid = false;
        var choices: usize = 0;
        var fields = std.mem.splitScalar(u8, body, ';');
        while (fields.next()) |field| {
            choices += 1;
            if (choices > 64) return false;
            const colon = std.mem.indexOfScalar(u8, field, ':') orelse return false;
            const code = std.mem.trim(u8, field[0..colon], " ");
            const value = field[colon + 1 ..];
            // A slash-delimited plain pronunciation is not a variant name.
            // With one choice and no pipe, ConverterRule clears both tables
            // for its invalid selector and returns the complete original body.
            const slash_selector = code.len > 1 and code[0] == '/' and
