        if (std.mem.indexOf(u8, input, "{|") == null) return source;
        const Wrapper = struct { start: usize, body_start: usize, body_end: usize, end: usize, selected: bool = false };
        var wrappers: std.ArrayList(Wrapper) = .empty;
        defer wrappers.deinit(self.a);
        var active: ?usize = null;
        var table_owner: ?usize = null;
        var table_depth: usize = 0;
        var selected = false;
        var scan: syntax.OpaqueScan = .{};
        var at: usize = 0;
        while (at < input.len) {
            if (active) |index| if (at == wrappers.items[index].body_end) {
                at = wrappers.items[index].end;
                active = null;
                continue;
            };
            if (starts(input[at..], "[[") or starts(input[at..], "{{")) {
                const pair = syntax.balancedWithOpaqueScan(input, at, &scan) orelse break;
                at = pair.end;
                continue;
            }
            if (input[at] == '[') {
                // Neither a link label nor an unresolved bracket domain lends
                // physical table markers to its containing page.
                at = (std.mem.indexOfScalarPos(u8, input, at + 1, ']') orelse break) + 1;
                continue;
            }
            if (input[at] == '<') {
                if (scan.protectedEnd(input, at, null)) |end| {
                    at = end;
                    continue;
                }
                // A declined outer opener can contain raw nested angles in
                // an attribute. Never resume inside its unproved tag domain.
                const tag = scan.tagAt(input, at, null) orelse return source;
                if (!tag.closing and (tag.is("includeonly") or tag.is("a"))) {
                    at = if (syntax.matchingTag(input, tag)) |pair| pair.end else input.len;
                    continue;
                }
                if (tag.is("noinclude")) {
                    if (!tag.closing and !tag.self_closing) if (syntax.matchingTag(input, tag)) |pair| {
                        const close = syntax.tagAt(input, pair.inner_end) orelse return source;
                        if (active == null and (at == 0 or input[at - 1] == '\n') and
                            trim(tag.attrs).len == 0 and trim(close.attrs).len == 0)
                        {
                            if (wrappers.items.len == max_nodes) return source;
                            active = wrappers.items.len;
                            try wrappers.append(self.a, .{ .start = at, .body_start = tag.end, .body_end = pair.inner_end, .end = pair.end });
                            at = tag.end;
                            continue;
                        }
                        // A nested/attributed/inline wrapper cannot bridge this
                        // table proof, even if its bytes resemble a boundary.
                        table_owner = null;
                        at = pair.end;
                        continue;
                    };
                    table_owner = null;
                }
                at = tag.end;
                continue;
            }
            const physical_start = at == 0 or input[at - 1] == '\n' or
                (if (active) |index| at == wrappers.items[index].body_start else false);
            if (physical_start and starts(input[at..], "{|")) {
                if (table_depth == 0) table_owner = active;
                if (table_depth == max_depth) return source;
                table_depth += 1;
                at += 2;
                continue;
            }
            if (physical_start and starts(input[at..], "|}") and table_depth != 0) {
                table_depth -= 1;
                if (table_depth == 0) {
                    if (table_owner) |first| if (active) |last| if (last > first) {
                        for (wrappers.items[first .. last + 1]) |*wrapper| wrapper.selected = true;
                        selected = true;
                    };
                    table_owner = null;
                }
                at += 2;
                continue;
            }
            at += 1;
        }
        if (!selected) return source;
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
        var copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer copies.deinit(self.a);
        var emitted: usize = 0;
        for (wrappers.items) |wrapper| {
            if (!wrapper.selected) continue;
            try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, wrapper.start);
            try self.appendMissingHeadingSourceCopy(&out, &copies, source, wrapper.body_start, wrapper.body_end);
            emitted = wrapper.end;
        }
        try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, input.len);
        const result = try out.finish(self.a);
        try self.registerHeadingSourceCopies(result.bytes, copies.items);
        return result;
    }

    // Parser.handleTables precedes handleInternalLinks: a physical table close
    // is not a label separator in a link target interrupted by that newline.
    // Preserve only the invalid opener before cells/wrappers slice the source;
    // otherwise a quote walk borrows its later ]] across the real table close.
    // The physical table pass runs before links. A nonempty target followed
    // by LF + {| cannot own that table as a link label, even when a later ]]
    // balances the raw bracket scan. This is syntax evidence, never category
    // or language evidence. Keep the complete original table and child actions.
    fn openingTableTargetPrefix(raw: []const u8) bool {
        if (raw.len == 0 or raw.len > 4096 or trim(raw).len == 0) return false;
        var decoded: [4096]u8 = undefined;
        var used: usize = 0;
        var at: usize = 0;
        while (at < raw.len) {
            if (raw[at] == '&') {
                var entity_buffer: [4]u8 = undefined;
                const decoded_entity = decodeEntity(raw[at..], &entity_buffer, false) orelse return false;
                if (decoded_entity.bytes.len > decoded.len - used) return false;
                @memcpy(decoded[used..][0..decoded_entity.bytes.len], decoded_entity.bytes);
                used += decoded_entity.bytes.len;
                at += decoded_entity.consumed;
            } else {
                decoded[used] = raw[at];
                used += 1;
                at += 1;
            }
        }
        const value = decoded[0..used];
        if (!std.unicode.utf8ValidateSlice(value) or std.mem.indexOfAny(u8, value, "[]{}|<>\r\n\t\"'") != null) return false;
        for (value) |byte| if (byte < 0x20 or byte == 0x7f) return false;
        const title = trim(value);
        const name = if (starts(title, ":")) std.mem.trimStart(u8, title[1..], " ") else title;
        return !ir.hasExternalProtocol(name) and internalTargetSyntaxAllowed(value, false);
    }

    // This certificate is only needed before admitting a new ordinary-body
    // case. A permissively truncated HTML attribute may not lend a later [[.
    fn tableLinkAnglesComplete(input: []const u8) bool {
        var at: usize = 0;
        var scan: syntax.OpaqueScan = .{};
        while (std.mem.indexOfScalarPos(u8, input, at, '<')) |opening| {
            if (scan.protectedEnd(input, opening, null)) |end| {
                if (starts(input[opening..], "<!--")) {
                    const comment_end = std.mem.indexOfPos(u8, input, opening + 4, "-->") orelse return false;
                    if (end != comment_end + 3) return false;
                } else {
                    const tag = scan.tagAt(input, opening, null) orelse return false;
                    if (!formattingAngleAttributesBalanced(tag.attrs)) return false;
                    if (!tag.closing and !tag.self_closing) {
                        const pair = syntax.matchingTagWithOpaqueScan(input, tag, &scan) orelse return false;
                        if (pair.end != end) return false;
                    }
                }
                at = end;
                continue;
            }
            const tag = scan.tagAt(input, opening, null) orelse {
                // A bare comparison/etymology angle followed by whitespace
                // cannot begin an HTML attribute or protected element.
                if (opening + 1 < input.len and std.ascii.isWhitespace(input[opening + 1])) {
                    at = opening + 1;
                    continue;
                }
                return false;
            };
            if (!recognizedInlineHtmlName(tag.name) or !formattingAngleAttributesBalanced(tag.attrs)) return false;
            if (!tag.closing and !tag.self_closing and
                (tag.html_pre or tag.isOpaque() or oneOf(tag.name, &.{ "a", "code", "tt", "kbd", "samp", "var" })))
            {
                const pair = syntax.matchingTagWithOpaqueScan(input, tag, &scan) orelse return false;
                at = pair.end;
            } else at = tag.end;
        }
        return true;
    }

    fn openingTableLink(input: []const u8, at: usize, scan: *syntax.OpaqueScan) ?ReferenceTableLink {
        if (!starts(input[at..], "[[")) return null;
        const pair = syntax.balancedWithOpaqueScan(input, at, scan) orelse return null;
        const line_end = std.mem.indexOfScalarPos(u8, input[0..pair.inner_end], at + 2, '\n') orelse return null;
        if (line_end >= pair.inner_end) return null;
        const prefix = std.mem.trimEnd(u8, input[at + 2 .. line_end], "\r");
        if (!openingTableTargetPrefix(prefix)) return null;
        const first = line_end + 1;
        // Require an actual column-zero physical opener, not a label, inline
        // token, indented pre line or apparent delimiter inside an attribute.
        if (first + 2 > pair.inner_end or !starts(input[first..], "{|")) return null;
        const header_end = std.mem.indexOfScalarPos(u8, input[0..pair.inner_end], first + 2, '\n') orelse return null;
        if (header_end >= pair.inner_end) return null;
        const attributes = std.mem.trimEnd(u8, input[first + 2 .. header_end], "\r");
        if (!formattingAngleAttributesBalanced(attributes) or std.mem.indexOfAny(u8, attributes, "[]{}<>") != null) return null;
        const close_line = std.mem.indexOfPos(u8, input[0..pair.inner_end], header_end, "\n|}") orelse return null;
        const close = close_line + 1;
        const close_end = std.mem.indexOfScalarPos(u8, input[0..pair.inner_end], close, '\n') orelse return null;
        if (close_end >= pair.inner_end or !std.mem.eql(u8, std.mem.trimEnd(u8, input[close..close_end], "\r"), "|}")) return null;
        // One complete table only. Unknown/nested/protected extra markers do
        // not supply this finite proof; normal validation remains responsible.
        if (std.mem.indexOf(u8, input[first + 2 .. close], "{|") != null or
            std.mem.indexOf(u8, input[first + 2 .. close], "|}") != null or
            !tableLinkAnglesComplete(input[first..close_end])) return null;
        var suffix = close_end + 1;
        while (suffix < pair.inner_end) {
            const byte = input[suffix];
            if (std.ascii.isWhitespace(byte)) { suffix += 1; continue; }
            if (byte == '<') {
                const tag = syntax.tagAt(input[0..pair.inner_end], suffix) orelse return null;
                if (tag.closing or !tag.is("br") or !formattingAngleAttributesBalanced(tag.attrs) or
                    std.mem.indexOfAny(u8, tag.attrs, "[]{}<>\r\n") != null) return null;
                suffix = tag.end;
                continue;
            }
            if (byte < 0x20 or byte == 0x7f or std.mem.indexOfScalar(u8, "[]{}|<>&\"'", byte) != null) return null;
            suffix += 1;
        }
        return .{ .start = at, .inner_end = pair.inner_end, .end = pair.end };
    }

    fn nextOpeningTableLink(input: []const u8, start: usize) ?ReferenceTableLink {
        var scan: syntax.OpaqueScan = .{};
        var at = start;
        while (at < input.len) {
            if ((at == 0 or input[at - 1] == '\n') and (input[at] == ' ' or input[at] == '\t')) {
                at = std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len;
                if (at < input.len) at += 1;
                continue;
            }
            if (input[at] == '<') {
                if (scan.protectedEnd(input, at, null)) |end| {
                    if (!tableLinkAnglesComplete(input[at..end])) return null;
                    at = end;
                    continue;
                }
                const tag = scan.tagAt(input, at, null) orelse {
                    if (at + 1 < input.len and std.ascii.isWhitespace(input[at + 1])) { at += 1; continue; }
                    return null;
                };
                if (!recognizedInlineHtmlName(tag.name) or !formattingAngleAttributesBalanced(tag.attrs)) return null;
                if (!tag.closing and !tag.self_closing) {
                    const pair = syntax.matchingTagWithOpaqueScan(input, tag, &scan) orelse return null;
                    if (!tableLinkAnglesComplete(input[at..pair.end])) return null;
                    at = pair.end;
                } else at = tag.end;
                continue;
            }
            if (starts(input[at..], "{{")) {
                const pair = syntax.balancedWithOpaqueScan(input, at, &scan) orelse return null;
                if (!tableLinkAnglesComplete(input[at..pair.end])) return null;
                at = pair.end;
                continue;
            }
            if (starts(input[at..], "[[")) {
                if (openingTableLink(input, at, &scan)) |found| return found;
                const pair = syntax.balancedWithOpaqueScan(input, at, &scan) orelse return null;
                if (!tableLinkAnglesComplete(input[at..pair.end])) return null;
                at = pair.end;
                continue;
            }
            if (input[at] == '[') {
                var links: ir.InlineIterator = .{ .input = input[at..], .renderer_boundaries = true };
                if (links.next()) |token| if (token.kind == .external_link) {
                    if (!tableLinkAnglesComplete(input[at .. at + links.cursor])) return null;
                    at += links.cursor;
                    continue;
                };
                const end = (std.mem.indexOfScalarPos(u8, input, at + 1, ']') orelse return null) + 1;
                if (!tableLinkAnglesComplete(input[at..end])) return null;
                at = end;
                continue;
            }
            at += 1;
        }
        return null;
    }

    fn prepareOpeningTableLinks(self: *Renderer, source: MissingText) Error!MissingText {
        if (source.unknown or !self.interruptedBodyTargetDomain() or self.inline_source_domain != null or
            self.navigation_target_probe != null or self.inline_image_attribute) return source;
        const input = source.bytes;
        if (std.mem.indexOf(u8, input, "[[") == null or std.mem.indexOf(u8, input, "{|") == null) return source;
        try generated_link.validateRanges(input, source.generated_source, source.generated_links);
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
        var copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer copies.deinit(self.a);
        var emitted: usize = 0;
        var cursor: usize = 0;
        while (nextOpeningTableLink(input, cursor)) |found| {
            cursor = found.end;
            var trusted = true;
            for (source.ranges) |range| if (range.start < found.end and range.end > found.start) { trusted = false; };
            for (source.generated_links) |range| if (range.start < found.end and range.end > found.start) { trusted = false; };
            for (source.literal_curly_ranges) |range| if (range.start < found.end and range.end > found.start) { trusted = false; };
            if (!trusted) continue;
            try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, found.start);
            try self.appendMissingHeadingSourceEdit(&out, &copies, source, found.start, "&#91;");
            try self.appendMissingHeadingSourceEdit(&out, &copies, source, found.start + 1, "&#91;");
            try self.appendMissingHeadingSourceCopy(&out, &copies, source, found.start + 2, found.inner_end);
            try self.appendMissingHeadingSourceEdit(&out, &copies, source, found.inner_end, "&#93;");
            try self.appendMissingHeadingSourceEdit(&out, &copies, source, found.inner_end + 1, "&#93;");
            emitted = found.end;
            self.fallbacks.literal_markup = true;
        }
        if (emitted == 0) return source;
        try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, input.len);
        const result = try out.finish(self.a);
        try self.registerHeadingSourceCopies(result.bytes, copies.items);
        return result;
    }

    fn prepareTableInterruptedLinkOpenings(self: *Renderer, original_source: MissingText) Error!MissingText {
        const source = try self.prepareOpeningTableLinks(original_source);
        if (source.unknown or self.pre_block or self.parsed_pre or self.in_reference or self.body_link_target.len != 0 or
            self.block_formatting.code or self.in_template_literal_scope or self.inline_source_domain != null)
            return source;
        const input = source.bytes;
        if (std.mem.indexOf(u8, input, "[[") == null or std.mem.indexOf(u8, input, "{|") == null) return source;
        try generated_link.validateRanges(input, source.generated_source, source.generated_links);
        const Proof = struct {
            fn trusted(tracked: MissingText, first: usize, last: usize) bool {
                for (tracked.ranges) |range| if (range.start < last and range.end > first) return false;
                for (tracked.generated_links) |range| if (range.start < last and range.end > first) return false;
                return true;
            }
            fn ordinary(tracked: MissingText, first: usize, last: usize) bool {
                if (!trusted(tracked, first, last)) return false;
                for (tracked.literal_curly_ranges) |range| if (range.start < last and range.end > first) return false;
                return true;
            }
        };
        var opaque_scan: syntax.OpaqueScan = .{};
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
        var copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer copies.deinit(self.a);
        var tables: usize = 0;
        var trusted_tables: [max_depth]bool = undefined;
        var ordinary_tables: [max_depth]bool = undefined;
        var nested_source_trusted = true;
        var generated_index: usize = 0;
        var at: usize = 0;
        var emitted: usize = 0;
        while (at < input.len) {
            while (generated_index < source.generated_links.len and source.generated_links[generated_index].end <= at) : (generated_index += 1) {}
            if (generated_index < source.generated_links.len and source.generated_links[generated_index].start <= at) {
                at = source.generated_links[generated_index].end;
                continue;
            }
            if (at == 0 or input[at - 1] == '\n') {
                const end = std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len;
                const line = trim(input[at..end]);
                if (wikiTableIndent(line) != null) {
                    if (tables == max_depth) break;
                    trusted_tables[tables] = (tables == 0 or trusted_tables[tables - 1]) and Proof.trusted(source, at, end);
                    ordinary_tables[tables] = (tables == 0 or ordinary_tables[tables - 1]) and Proof.ordinary(source, at, end);
                    tables += 1;
                } else if (starts(line, "|}") and tables != 0) {
                    if (Proof.trusted(source, at, end)) tables -= 1 else tables = 0;
                }
                // A leading-space pre line is a different source domain.
                if (starts(input[at..end], " ") and wikiTableIndent(line) == null and !starts(line, "|}")) {
                    at = if (end < input.len) end + 1 else end;
                    continue;
                }
            }
            if (input[at] == '<') {
                if (opaque_scan.protectedEnd(input, at, null)) |end| { at = end; continue; }
                const tag = opaque_scan.tagAt(input, at, null) orelse break;
                // Do not lend an apparent body position from a truncated HTML
                // attribute to the new nested-target proof. Existing newline
                // recovery retains its independent contract.
                if (!formattingAngleAttributesBalanced(tag.attrs) or (tag.closing and trim(tag.attrs).len != 0)) nested_source_trusted = false;
                if (!recognizedInlineHtmlName(tag.name) and !tag.is("a")) break;
                if (!tag.closing and (tag.html_pre or tag.isOpaque() or
                    oneOf(tag.name, &.{ "a", "code", "tt", "kbd", "samp", "var", "includeonly", "script", "style", "textarea", "iframe", "object", "embed" })))
                {
                    const end = if (syntax.matchingTag(input, tag)) |pair| pair.end else input.len;
                    if (tag.is("a") and std.mem.indexOfScalar(u8, input[at..end], '\n') != null) tables = 0;
                    at = end;
                } else at = tag.end;
                continue;
            }
            if (starts(input[at..], "{{")) {
                nested_source_trusted = false;
                at = if (syntax.balancedWithOpaqueScan(input, at, &opaque_scan)) |pair| pair.end else input.len;
                continue;
            }
            if (starts(input[at..], "[[")) {
                const pair = syntax.balancedWithOpaqueScan(input, at, &opaque_scan) orelse break;
                var selected = false;
                if (tables != 0 and trusted_tables[tables - 1]) if (std.mem.indexOfAny(u8, input[at + 2 .. pair.inner_end], "[]{}|<>&\r\n")) |relative| {
                    const boundary = at + 2 + relative;
                    var next = boundary;
                    if (input[next] == '\r') next += 1;
                    if (trim(input[at + 2 .. boundary]).len != 0 and internalTargetSyntaxAllowed(input[at + 2 .. boundary], true) and
                        next < pair.inner_end and input[next] == '\n') {
                        next += 1;
                        while (next < pair.inner_end and (input[next] == ' ' or input[next] == '\t')) : (next += 1) {}
                        selected = next + 2 <= pair.inner_end and starts(input[next..], "|}");
                    } else if (nested_source_trusted and ordinary_tables[tables - 1] and starts(input[boundary..], "[[") and
                        trim(input[at + 2 .. boundary]).len != 0 and
                        internalTargetSyntaxAllowed(input[at + 2 .. boundary], true))
                    {
                        // The primary link pass splits on each [[. A plain
                        // unterminated target prefix before a complete child
                        // link stays literal; the child keeps its own action.
                        // Prove the immediate physical table close before any
                        // later ]] can lend a crossing label/quote domain.
                        const line_end = std.mem.indexOfScalarPos(u8, input, boundary, '\n') orelse input.len;
                        if (line_end < pair.inner_end) if (syntax.balanced(input[0..line_end], boundary)) |child| {
                            const target = input[boundary + 2 .. child.inner_end];
                            if (trim(target).len != 0 and std.mem.indexOfAny(u8, target, "[]{}|<>&\r\n") == null and
                                internalTargetSyntaxAllowed(target, true) and trim(input[child.end..line_end]).len == 0)
                            {
                                var physical = line_end + 1;
                                while (physical < pair.inner_end and (input[physical] == ' ' or input[physical] == '\t')) : (physical += 1) {}
                                selected = physical + 2 <= pair.inner_end and starts(input[physical..], "|}");
                                // Literal-curly provenance cannot lend a new
                                // ordinary-source proof to this nested form.
                                if (selected) selected = Proof.ordinary(source, at, pair.end);
                            }
                        };
                    }
                };
                if (selected) selected = Proof.trusted(source, at, pair.end);
                if (selected) {
                    try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, at);
                    try self.appendMissingHeadingSourceEdit(&out, &copies, source, at, "&#91;");
                    try self.appendMissingHeadingSourceEdit(&out, &copies, source, at + 1, "&#91;");
                    self.fallbacks.literal_markup = true;
                    emitted = at + 2;
                    at += 2;
                } else {
                    // Tables precede link processing. Do not carry an active
                    // table across a skipped multiline label whose physical
                    // boundaries were deliberately not interpreted here.
                    if (std.mem.indexOfAny(u8, input[at..pair.end], "<>{}") != null) nested_source_trusted = false;
                    if (std.mem.indexOfScalar(u8, input[at..pair.end], '\n') != null) tables = 0;
                    at = pair.end;
                }
                continue;
            }
            if (input[at] == '[') {
                var links: ir.InlineIterator = .{ .input = input[at..], .renderer_boundaries = true };
                if (links.next()) |token| if (token.kind == .external_link) {
                    if (std.mem.indexOfAny(u8, input[at .. at + links.cursor], "<>{}") != null) nested_source_trusted = false;
                    if (std.mem.indexOfScalar(u8, input[at .. at + links.cursor], '\n') != null) tables = 0;
                    at += links.cursor; continue;
                };
                // Unproved bracket domains cannot lend a table/link boundary.
                const end = (std.mem.indexOfScalarPos(u8, input, at + 1, ']') orelse break) + 1;
                if (std.mem.indexOfAny(u8, input[at..end], "<>{}") != null) nested_source_trusted = false;
                if (std.mem.indexOfScalar(u8, input[at..end], '\n') != null) tables = 0;
                at = end;
                continue;
            }
            at += 1;
        }
        if (emitted == 0) return source;
        try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, input.len);
        const result = try out.finish(self.a);
        try self.registerHeadingSourceCopies(result.bytes, copies.items);
        return result;
    }

    // The table pass consumes one physical control per line. A cell's
    // opening DIV does not promote its same-line |}, and a consumed close
    // does not recursively interpret another |} in its suffix.
    fn prepareInlineWikiTableClosers(self: *Renderer, source: MissingText) Error!MissingText {
        if (source.unknown or !self.interruptedBodyTargetDomain() or self.inline_source_domain != null) return source;
        const input = source.bytes;
        if (std.mem.indexOf(u8, input, "|}") == null or std.mem.indexOf(u8, input, "{|") == null) return source;
        try generated_link.validateRanges(input, source.generated_source, source.generated_links);
        const Proof = struct {
            fn trusted(tracked: MissingText, first: usize, last: usize) bool {
                for (tracked.ranges) |range| if (range.start < last and range.end > first) return false;
                for (tracked.generated_links) |range| if (range.start < last and range.end > first) return false;
                return true;
            }
        };
        var opaque_scan: syntax.OpaqueScan = .{};
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
        var copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer copies.deinit(self.a);
        var tables: usize = 0;
        var trusted_tables: [max_depth]bool = undefined;
        var generated_index: usize = 0;
        var at: usize = 0;
        var emitted: usize = 0;
        while (at < input.len) {
            while (generated_index < source.generated_links.len and source.generated_links[generated_index].end <= at) : (generated_index += 1) {}
            if (generated_index < source.generated_links.len and source.generated_links[generated_index].start <= at) {
                at = source.generated_links[generated_index].end;
                tables = 0;
                continue;
            }
            if (at == 0 or input[at - 1] == '\n') {
                const end = std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len;
                const line = trim(input[at..end]);
                const line_offset = @intFromPtr(line.ptr) - @intFromPtr(input.ptr);
                var literal_closer_offset: ?usize = null;
                if (wikiTableIndent(line) != null) {
                    if (tables == max_depth) break;
                    trusted_tables[tables] = (tables == 0 or trusted_tables[tables - 1]) and Proof.trusted(source, at, end);
                    tables += 1;
                } else if (tables != 0 and starts(line, "|}")) {
                    if (trusted_tables[tables - 1] and Proof.trusted(source, at, end) and std.mem.eql(u8, line, "|}|}"))
                        literal_closer_offset = line_offset + 2;
                    if (Proof.trusted(source, at, end)) tables -= 1 else tables = 0;
                } else if (tables != 0 and trusted_tables[tables - 1] and line.len > 1 and line[0] == '|' and
                    line[1] != '-' and line[1] != '+' and Proof.trusted(source, at, end))
                {
                    // Only an ordinary cell attribute separator supplies this
                    // origin. An arbitrary token-local DIV or inherited action
                    // cannot stand in for the physical cell line.
                    const cell = line[1..];
                    if (cellAttributePipe(cell)) |pipe| {
                        const body = cell[pipe + 1 ..];
                        if (syntax.tagAt(body, 0)) |tag| {
                            if (tag.is("div") and !tag.closing and !tag.self_closing and
                                std.mem.indexOfAny(u8, cell[0..pipe], "[]{}<>&") == null and
                                std.mem.indexOfAny(u8, tag.attrs, "[]{}<>&") == null and
                                std.mem.eql(u8, body[tag.end..], "|}"))
                            {
                                const opening = @intFromPtr(body.ptr) - @intFromPtr(input.ptr);
                                if (syntax.tagAt(input, opening)) |full_tag| if (syntax.matchingTag(input, full_tag)) |pair| {
                                    if (Proof.trusted(source, opening, pair.end)) literal_closer_offset = opening + tag.end;
                                };
                            }
                        }
                    }
                }
                if (literal_closer_offset) |marker| {
                    try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, marker);
                    try self.appendMissingHeadingSourceEdit(&out, &copies, source, marker, "&#124;");
                    emitted = marker + 1;
                    at = if (end < input.len) end + 1 else end;
                    continue;
                }
                if (starts(input[at..end], " ") and wikiTableIndent(line) == null and !starts(line, "|}")) {
                    at = if (end < input.len) end + 1 else end;
                    continue;
                }
            }
            if (input[at] == '<') {
                if (opaque_scan.protectedEnd(input, at, null)) |end| { at = end; continue; }
                const tag = opaque_scan.tagAt(input, at, null) orelse break;
                if (!recognizedInlineHtmlName(tag.name) and !tag.is("a")) break;
                if (!tag.closing and (tag.html_pre or tag.isOpaque() or
                    oneOf(tag.name, &.{ "a", "code", "tt", "kbd", "samp", "var", "includeonly", "script", "style", "textarea", "iframe", "object", "embed" })))
                {
                    const end = if (syntax.matchingTag(input, tag)) |pair| pair.end else input.len;
                    if (std.mem.indexOfScalar(u8, input[at..end], '\n') != null) tables = 0;
                    at = end;
                } else at = tag.end;
                continue;
            }
            if (starts(input[at..], "{{") or starts(input[at..], "[[")) {
                const pair = syntax.balancedWithOpaqueScan(input, at, &opaque_scan) orelse break;
                if (std.mem.indexOfScalar(u8, input[at..pair.end], '\n') != null) tables = 0;
                at = pair.end;
                continue;
            }
            if (input[at] == '[') {
                const end = std.mem.indexOfScalarPos(u8, input, at + 1, ']') orelse break;
                if (std.mem.indexOfScalar(u8, input[at..end], '\n') != null) tables = 0;
                at = end + 1;
                continue;
            }
            at += 1;
        }
        if (emitted == 0) return source;
        try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, input.len);
        const result = try out.finish(self.a);
        try self.registerHeadingSourceCopies(result.bytes, copies.items);
        return result;
    }


    // A recognized HTML heading rejects an outer link target before owner
    // slicing. Its standalone later closing pair is still authored punctuation,
    // not a new instruction in the independently rendered owner fragment.
    fn prepareHeadingInterruptedLinkClosers(self: *Renderer, source: MissingText) Error!MissingText {
        if (source.unknown or !self.interruptedBodyTargetDomain() or self.inline_source_domain != null) return source;
        const input = source.bytes;
        if (std.mem.indexOf(u8, input, "[[<") == null) return source;
        try generated_link.validateRanges(input, source.generated_source, source.generated_links);
        var scan: syntax.OpaqueScan = .{};
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
        var copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer copies.deinit(self.a);
        var at: usize = 0;
        var emitted: usize = 0;
        var generated_index: usize = 0;
        while (at < input.len) {
            while (generated_index < source.generated_links.len and source.generated_links[generated_index].end <= at) : (generated_index += 1) {}
            if (generated_index < source.generated_links.len and source.generated_links[generated_index].start <= at) {
                at = source.generated_links[generated_index].end;
                continue;
            }
            if (input[at] == '<') {
                if (scan.protectedEnd(input, at, null)) |end| { at = end; continue; }
                const tag = scan.tagAt(input, at, null) orelse break;
                if (!recognizedInlineHtmlName(tag.name) and !tag.is("a")) break;
                if (!tag.closing and (tag.html_pre or tag.isOpaque() or
                    oneOf(tag.name, &.{ "a", "code", "tt", "kbd", "samp", "var", "includeonly", "script", "style", "textarea", "iframe", "object", "embed" })))
                    at = if (syntax.matchingTag(input, tag)) |pair| pair.end else input.len
                else
                    at = tag.end;
                continue;
            }
            if (starts(input[at..], "[[") or starts(input[at..], "{{")) {
                const pair = syntax.balancedWithOpaqueScan(input, at, &scan) orelse break;
                var selected = false;
                if ((at == 0 or input[at - 1] == '\n') and starts(input[at..], "[[<") and
                    htmlInterruptedInternalOpening(input, at))
                {
                    const tag = syntax.tagAt(input, at + 2).?;
                    const first_line_end = std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len;
                    if (htmlHeadingLevel(tag) != null and !tag.closing and !tag.self_closing) if (syntax.matchingTag(input, tag)) |heading| {
                        if (heading.end <= first_line_end and pair.inner_end > first_line_end) {
                            var close_line = pair.inner_end;
                            while (close_line != 0 and input[close_line - 1] != '\n') close_line -= 1;
                            const close_end = std.mem.indexOfScalarPos(u8, input, pair.end, '\n') orelse input.len;
                            selected = close_line == pair.inner_end and trim(input[pair.end..close_end]).len == 0;
                        }
                    };
                }
                if (selected) {
                    for (source.ranges) |range| if (range.start < pair.end and range.end > at) { selected = false; break; };
                    for (source.generated_links) |range| if (range.start < pair.end and range.end > at) { selected = false; break; };
                }
                if (selected) {
                    try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, at);
                    try self.appendMissingHeadingSourceEdit(&out, &copies, source, at, "&#91;");
                    try self.appendMissingHeadingSourceEdit(&out, &copies, source, at + 1, "&#91;");
                    try self.appendMissingHeadingSourceCopy(&out, &copies, source, at + 2, pair.inner_end);
                    try self.appendMissingHeadingSourceEdit(&out, &copies, source, pair.inner_end, "&#93;");
                    try self.appendMissingHeadingSourceEdit(&out, &copies, source, pair.inner_end + 1, "&#93;");
                    emitted = pair.end;
                    self.fallbacks.literal_markup = true;
                }
                at = pair.end;
                continue;
            }
            if (input[at] == '[') {
                const end = std.mem.indexOfScalarPos(u8, input, at + 1, ']') orelse break;
                at = end + 1;
                continue;
            }
            at += 1;
        }
        if (emitted == 0) return source;
        try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, input.len);
        const result = try out.finish(self.a);
        try self.registerHeadingSourceCopies(result.bytes, copies.items);
        return result;
    }


    // Preprocessor_Hash::breakSyntax retains an unmatched invocation's literal
    // delimiters and child nodes. Prove this finite two-line field shape before
    // block/list slicing; inline children and the physical newline stay intact.
    fn malformedTwoLineFieldEnd(input: []const u8, start: usize) ?usize {
        if (!starts(input[start..], "{{") or starts(input[start..], "{{{")) return null;
        const limit = start + @min(input.len - start, 4096);
        const Name = struct {
            fn valid(bytes: []const u8) bool {
                return bytes.len != 0 and trim(bytes).len == bytes.len and
                    std.unicode.utf8ValidateSlice(bytes) and
                    std.mem.indexOfAny(u8, bytes, " []{}<>&'\"|=:#/\\\r\n\t") == null;
            }
        };
        const pipe = std.mem.indexOfScalarPos(u8, input[0..limit], start + 2, '|') orelse return null;
        if (!Name.valid(input[start + 2 .. pipe])) return null;
        const equal = std.mem.indexOfScalarPos(u8, input[0..limit], pipe + 1, '=') orelse return null;
        if (!Name.valid(input[pipe + 1 .. equal])) return null;
        var at = equal + 1;
        var names: [16][]const u8 = undefined;
        var count: usize = 0;
        var child = false;
        while (at < limit) {
            const c = input[at];
            if (c == '[') {
                at = literalSquareGlossEnd(input[0..limit], at) orelse return null;
                continue;
            }
            if (c == '<') {
                const tag = syntax.tagAt(input[0..limit], at) orelse return null;
                if (std.mem.indexOfAny(u8, input[at..tag.end], "[]{}&\r\n") != null) return null;
                if (tag.self_closing) {
                    if (tag.closing or !tag.is("templatestyles")) return null;
                } else if (tag.closing) {
                    if (count == 0 or !std.ascii.eqlIgnoreCase(names[count - 1], tag.name) or trim(tag.attrs).len != 0) return null;
                    count -= 1;
                } else {
                    if (!tag.is("span")) {
                        const flags = blockFormattingFlags(tag) orelse return null;
                        if (flags.code) return null;
                    }
                    if (count == names.len) return null;
                    names[count] = tag.name;
                    count += 1;
                    child = true;
                }
                at = tag.end;
                continue;
            }
            if (c == '\r' or c == '\n') {
                if (count != 0 or !child or trim(input[equal + 1 .. at]).len == 0 or ir.hasExternalProtocol(input[equal + 1 .. at])) return null;
                if (c == '\r') at += 1;
                if (at >= limit or input[at] != '\n') return null;
                at += 1;
                if (at >= limit or input[at] != '|') return null;
                const field = at + 1;
                const field_equal = std.mem.indexOfScalarPos(u8, input[0..limit], field, '=') orelse return null;
                if (!Name.valid(input[field..field_equal])) return null;
                at = field_equal + 1;
                if (at + 2 > limit or !starts(input[at..], "|}") or starts(input[at + 1 ..], "}}")) return null;
                return at + 2;
            }
            if (std.mem.indexOfScalar(u8, "]{}>&'\"|", c) != null) return null;
            at += 1;
        }
        return null;
    }

    fn prepareMalformedTwoLineFields(self: *Renderer, source: MissingText) Error!MissingText {
        if (source.unknown or self.pre_block or self.parsed_pre or self.in_reference or self.poem_depth != 0 or
            self.body_link_target.len != 0 or self.navigation_target_probe != null or self.pre_scope_observer != null or
            self.block_formatting.code or self.in_template_literal_scope or self.inline_source_domain != null) return source;
        const input = source.bytes;
        if (std.mem.indexOf(u8, input, "{{") == null) return source;
        try generated_link.validateRanges(input, source.generated_source, source.generated_links);
        const Proof = struct {
            fn trusted(tracked: MissingText, first: usize, last: usize) bool {
                for (tracked.ranges) |range| if (range.start < last and range.end > first) return false;
                for (tracked.literal_curly_ranges) |range| if (range.start < last and range.end > first) return false;
                for (tracked.generated_links) |range| if (range.start < last and range.end > first) return false;
                return true;
            }
        };
        var opaque_scan: syntax.OpaqueScan = .{};
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
        var copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer copies.deinit(self.a);
        var tables: usize = 0;
        var generated_index: usize = 0;
        var at: usize = 0;
        var emitted: usize = 0;
        while (at < input.len) {
            while (generated_index < source.generated_links.len and source.generated_links[generated_index].end <= at) : (generated_index += 1) {}
            if (generated_index < source.generated_links.len and source.generated_links[generated_index].start <= at) {
                at = source.generated_links[generated_index].end;
                continue;
            }
            if (at == 0 or input[at - 1] == '\n') {
                const end = std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len;
                const line = trim(input[at..end]);
                if (!Proof.trusted(source, at, end)) break;
                if (wikiTableIndent(line) != null) {
                    if (tables == max_depth) break;
                    tables += 1;
                } else if (starts(line, "|}") and tables != 0) tables -= 1;
                if (starts(input[at..end], " ") and wikiTableIndent(line) == null and !starts(line, "|}")) {
                    at = if (end < input.len) end + 1 else end;
                    continue;
                }
            }
            if (input[at] == '<') {
                // protectedEnd may return only the opener for an unmatched
                // extension. Its remaining body still cannot lend this proof.
                if (syntax.tagAt(input, at)) |candidate| {
                    if (!candidate.closing and !candidate.self_closing and (candidate.html_pre or candidate.isOpaque() or
                        oneOf(candidate.name, &.{ "a", "q", "blockquote", "code", "tt", "kbd", "samp", "var", "table", "includeonly", "script", "style", "textarea", "iframe", "object", "embed" }))) {
                        at = if (syntax.matchingTag(input, candidate)) |pair| pair.end else input.len;
                        continue;
                    }
                }
                if (opaque_scan.protectedEnd(input, at, null)) |end| { at = end; continue; }
                const tag = opaque_scan.tagAt(input, at, null) orelse break;
                if (!recognizedInlineHtmlName(tag.name) and !tag.is("templatestyles")) break;
                at = tag.end;
                continue;
            }
            if (starts(input[at..], "''")) {
                if (starts(input[at..], "''''")) break;
                const width: usize = if (starts(input[at..], "'''")) 3 else 2;
                const end = std.mem.indexOfPos(u8, input, at + width, "''") orelse break;
                if (!starts(input[end..], input[at .. at + width]) or
                    (end + width < input.len and input[end + width] == '\'')) break;
                at = end + width;
                continue;
            }
            if (starts(input[at..], "{{")) {
                if (syntax.balancedWithOpaqueScan(input, at, &opaque_scan)) |pair| {
                    at = pair.end;
                    continue;
                }
                if (tables == 0) if (malformedTwoLineFieldEnd(input, at)) |end| {
                    if (Proof.trusted(source, at, end)) {
                        try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, at);
                        try self.appendMissingHeadingSourceEdit(&out, &copies, source, at, "&#123;");
                        try self.appendMissingHeadingSourceEdit(&out, &copies, source, at + 1, "&#123;");
                        try self.appendMissingHeadingSourceCopy(&out, &copies, source, at + 2, end - 1);
                        try self.appendMissingHeadingSourceEdit(&out, &copies, source, end - 1, "&#125;");
                        self.fallbacks.literal_markup = true;
                        emitted = end;
                        at = end;
                        continue;
                    }
                };
                break;
            }
            if (starts(input[at..], "[[")) {
                at = if (syntax.balancedWithOpaqueScan(input, at, &opaque_scan)) |pair| pair.end else input.len;
                continue;
            }
            if (input[at] == '[') {
                const end = (std.mem.indexOfScalarPos(u8, input, at + 1, ']') orelse break) + 1;
                at = end;
                continue;
            }
            at += 1;
        }
        if (emitted == 0) return source;
        try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, input.len);
        const result = try out.finish(self.a);
        try self.registerHeadingSourceCopies(result.bytes, copies.items);
        return result;
    }

    pub fn prepareBodySourceWithMissing(self: *Renderer, source: MissingText) Error!MissingText {
        return self.prepareHeadingInterruptedLinkClosers(try self.prepareInlineWikiTableClosers(try self.prepareCrossingNoincludeTables(try self.prepareTableInterruptedLinkOpenings(try self.prepareReferenceTableLinks(try self.prepareUnmatchedOpaqueWithMissing(try self.prepareMalformedTwoLineFields(source)))))));
    }

    pub fn prepareBodySource(self: *Renderer, input: []const u8) Error![]const u8 {
        return (try self.prepareBodySourceWithMissing(MissingText.untracked(input))).bytes;
    }

    // The caller already prepared this page and applied the one full-page TOC
    // pass. A separate probe Renderer may discard blocks while retaining these
    // sparse source-backed events and its ordinary fallback report.
    pub fn renderBodyWithPreObserver(self: *Renderer, input: []const u8, observer: PreScopeObserver) Error![]const Block {
        const previous_literal_root = self.literal_url_root;
        if (previous_literal_root == null) self.literal_url_root = input;
        defer self.literal_url_root = previous_literal_root;
        try self.loadPoemPhase();
        const previous = self.pre_scope_observer;
        self.pre_scope_observer = observer;
        defer self.pre_scope_observer = previous;
        return self.renderBodySlice(input, false, false, 0, null);
    }

    // Keep references, media, Poem state and budgets on this Renderer, while
    // restoring the lexical pre state at every independently owned fragment.
    pub fn renderBodyWithFragmentPreAndMissing(self: *Renderer, tracked: MissingText, context: FragmentPreContext) Error![]const Block {
        const previous = self.body_missing;
        self.body_missing = tracked;
        defer self.body_missing = previous;
        return self.renderBodyWithFragmentPre(tracked.bytes, context);
    }
    fn cssScopeSourcePolicyAuthority(self: *Renderer, tag: syntax.Tag, attributes: FormattingAttributes) Error!bool {
        const css = (try self.semanticAttribute(tag, "style")) orelse "";
        if (attributes.column_fragmentation_policy_present and
            try table_style_profile.hasColumnFragmentationDeclarationsAlloc(self.a, css)) return true;
        if (!attributes.relative_context_policy_present) return false;
        if (try table_style_profile.hasRelativeContextDeclarationsAlloc(self.a, css)) return true;
        // A copied policy bit is not source authority. A stylesheet candidate
        // must remain bound to the actual observed physical opening node.
        const node = attributes.text_element orelse return false;
        if (node.source_key != @intFromPtr(tag.name.ptr) or !std.ascii.eqlIgnoreCase(node.tag, tag.name)) return false;
        if (self.context.table_styles) |profile| if (try profile.relativeContextPolicyPresentIn(self.a, node, css)) return true;
        if (self.context.text_paint_styles) |profile| if (self.context.table_styles == null or self.context.table_styles.? != profile) {
            if (try profile.relativeContextPolicyPresentIn(self.a, node, css)) return true;
        };
        return false;
    }

    pub fn renderBodyWithFragmentPre(self: *Renderer, input: []const u8, context: FragmentPreContext) Error![]const Block {
        const previous_literal_root = self.literal_url_root;
        if (previous_literal_root == null) self.literal_url_root = input;
        defer self.literal_url_root = previous_literal_root;
        const previous_prepared = self.context.external_links_prepared;
        self.context.external_links_prepared = true;
        defer self.context.external_links_prepared = previous_prepared;
        var inherited_pre: usize = 0;
        var inherited_hidden: usize = 0;
        for (context.initial) |scope| if (scope.kind == .pre) {
            inherited_pre += 1;
        };
        for (context.initial) |scope| if (scope.kind == .hidden) {
            if (scope.tag_name.len == 0 or !knownInlineHtmlName(scope.tag_name) or oneOf(scope.tag_name, &.{ "noinclude", "onlyinclude" })) return error.InvalidPreContext;
            inherited_hidden += 1;
        };
        if (context.initial_block_pre and inherited_pre == 0) return error.InvalidPreContext;
        if (context.initial.len > max_depth or context.trailing.len > max_depth) {
            self.fallbacks.render_limit = true;
            return error.RenderLimit;
        }
        var previous_end: usize = 0;
        for (context.initial) |scope| {
            if (scope.kind == .refused_link) return error.InvalidPreContext;
            if (scope.kind == .css_block and (!std.ascii.eqlIgnoreCase(scope.tag_name, "div") or (trim(scope.attributes.css_ancestor_classes).len == 0 and scope.attributes.text_align == null and scope.attributes.custom_properties == null and (!scope.attributes.table_inheritance_scoped or scope.attributes.table_collapse == null) and !scope.attributes.relative_context_policy_present and !scope.attributes.column_fragmentation_policy_present and !scope.attributes.tooltip_set and scope.attributes.tooltip == null))) return error.InvalidPreContext;
            if (scope.kind == .link and (scope.target.len == 0 or !safeInternalTarget(scope.target))) return error.InvalidPreContext;
            if (scope.body_end < previous_end or scope.body_end > scope.resume_at or scope.resume_at > input.len)
                return error.InvalidPreContext;
            if (scope.body_end == input.len) {
                if (scope.resume_at != input.len) return error.InvalidPreContext;
            } else if (scope.kind == .link) {
                if (scope.resume_at - scope.body_end < 2 or
                    !std.mem.eql(u8, input[scope.body_end .. scope.body_end + 2], "]]")) return error.InvalidPreContext;
            } else {
                var tag = syntax.tagAt(input, scope.body_end) orelse return error.InvalidPreContext;
                if (!tag.closing or tag.end != scope.resume_at) return error.InvalidPreContext;
                tag.closing = false;
                if (scope.kind == .pre) {
                    if (!tag.is("pre")) return error.InvalidPreContext;
                } else if (scope.kind == .layout_div) {
                    if (!tag.is("div")) return error.InvalidPreContext;
                } else if (scope.kind == .css_block) {
                    if (!tag.is("div") or scope.tag_name.len == 0 or !tag.is(scope.tag_name) or (scope.attributes.css_ancestor_classes.len == 0 and scope.attributes.text_align == null and scope.attributes.custom_properties == null and (!scope.attributes.table_inheritance_scoped or scope.attributes.table_collapse == null) and !scope.attributes.relative_context_policy_present and !scope.attributes.column_fragmentation_policy_present and !scope.attributes.tooltip_set and scope.attributes.tooltip == null)) return error.InvalidPreContext;
                } else if (scope.kind == .hidden) {
                    if (!tag.is(scope.tag_name)) return error.InvalidPreContext;
                } else if (!tag.is("span") and !tag.is("noinclude") and blockFormattingFlags(tag) == null) return error.InvalidPreContext;
            }
            previous_end = scope.resume_at;
        }
        previous_end = 0;
        var remaining_initial = context.initial.len;
        var checked_initial: usize = 0;
        for (context.trailing, 0..) |scope, index| {
            if (scope.kind == .refused_link) return error.InvalidPreContext;
            if (scope.opening_start < previous_end or scope.opening_start >= scope.body_start or scope.body_start > input.len)
                return error.InvalidPreContext;
            if (scope.kind == .link) {
                if (scope.target.len == 0 or !safeInternalTarget(scope.target) or scope.body_start - scope.opening_start < 4 or
