    fn bodyRawInterruptedParagraph(self: *Renderer, blocks: *std.ArrayList(Block), source: []const u8, raw: []const u8, opening: usize, fallback: ?QuoteSeed, quotes: *?QuoteBoundaryScan, pending_join: *?bool) Error!void {
