    fn wikiListLineBody(raw: []const u8) []const u8 {
        const body = std.mem.trimStart(u8, raw, " \t");
        const trimmed = std.mem.trimEnd(u8, body, " \t");
        if (trimmed.len == body.len) return body;
        var scan: syntax.OpaqueScan = .{};
        var no_more_nowiki_close = false;
        var at: usize = 0;
        while (at < trimmed.len) {
            if (body[at] == '\n' or body[at] == '\r') return body;
            if (body[at] == '<') if (scan.tagAt(body, at, &no_more_nowiki_close)) |tag| {
                if (!tag.closing and !tag.self_closing and (tag.isOpaque() or tag.html_pre)) {
                    const pair = syntax.matchingTagWithOpaqueScan(body, tag, &scan) orelse return body;
                    if (pair.end > trimmed.len) return body;
                    at = pair.end;
                } else at = tag.end;
                continue;
            };
            if (scan.protectedEnd(body, at, &no_more_nowiki_close)) |end| {
                if (end > trimmed.len) return body;
                at = end;
                continue;
            }
            if (starts(body[at..], "[[") or starts(body[at..], "{{")) {
                const pair = syntax.balancedWithOpaqueScan(body, at, &scan) orelse {
                    if (!starts(body[at..], "{{")) return body;
                    // The inline renderer already proved these same-line literal
                    // boundaries. Only whitespace outside the whole range trims.
                    const literal_end = malformedStyledArgumentSingleBraceEnd(body, at) orelse
                        malformedLiteralGlossArgumentSingleBraceEnd(body, at) orelse return body;
                    if (literal_end > trimmed.len) return body;
                    at = literal_end;
                    continue;
                };
                if (pair.end > trimmed.len) return body;
                at = pair.end;
                continue;
            }
            at += 1;
        }
        return trimmed;
    }

    // Project only one physical colon item after an invisible opening line.
    // Protected, mixed and multi-line contents retain their existing ownership.
    fn headingColonListBody(self: *Renderer, raw: []const u8) Error!?[]const u8 {
        const first_end = std.mem.indexOfScalar(u8, raw, '\n') orelse return null;
        const opening = std.mem.trim(u8, raw[0..first_end], " \t\r");
        const matcher = self.behaviorControlMatcher();
        if (syntax.leadingBehaviorControlOffset(opening, matcher) != opening.len) return null;
        const item = std.mem.trimEnd(u8, raw[first_end + 1 ..], "\r");
        if (std.mem.indexOfScalar(u8, item, '\n') != null) return null;
        const prefix = try syntax.controlListPrefixAlloc(self.a, item, matcher);
        if (!std.mem.eql(u8, prefix.path, ":")) return null;
        return wikiListLineBody(item[prefix.body_start..]);
    }

    pub fn renderBodyWithHeadingOffsets(self: *Renderer, tracked: MissingText) Error![]const Block {
        const previous_literal_root = self.literal_url_root;
        if (previous_literal_root == null) self.literal_url_root = tracked.bytes;
        defer self.literal_url_root = previous_literal_root;
        const previous_prepared = self.context.external_links_prepared;
        self.context.external_links_prepared = true;
        defer self.context.external_links_prepared = previous_prepared;
        const previous_source = self.heading_source;
        const previous_missing = self.body_missing;
        self.heading_source = tracked.bytes;
        self.body_missing = tracked;
        defer {
            self.heading_source = previous_source;
            self.body_missing = previous_missing;
        }
        try self.loadPoemPhase();
        return self.renderBodySlice(tracked.bytes, false, false, 0, null);
    }

    fn missingSliceWithHeadingSource(self: *Renderer, parent: MissingText, child: []const u8) Error!MissingText {
        var tracked = try missingSlice(self.a, parent, child);
        if (self.pre_scope_observer != null and
            (parent.ranges.len != 0 or parent.literal_curly_ranges.len != 0 or parent.generated_links.len != 0) and
            tracked.bytes.ptr != child.ptr and tracked.bytes.len == child.len)
        {
            const base = @intFromPtr(parent.bytes.ptr);
            const at = @intFromPtr(child.ptr);
            if (at >= base and at - base <= parent.bytes.len and child.len <= parent.bytes.len - (at - base)) {
                // missingSlice just validated and rebased this exact borrowed
                // interval through Text.Builder. Only its byte copy is temporary:
                // observation needs original source pointers, while the returned
                // metadata arrays and generated Bound roots keep their lifetimes.
                const copied_bytes = tracked.bytes;
                tracked.bytes = child;
                tracked.generated_source = if (tracked.generated_links.len == 0) null else child;
                self.a.free(copied_bytes);
            }
        }
        if (self.heading_source != null and child.len != 0 and tracked.bytes.ptr != child.ptr)
            try self.heading_source_aliases.append(self.a, .{ .copied = tracked.bytes, .original = child });
        return tracked;
    }

    // A tracked MissingText slice may allocate a byte-identical whole-page
    // copy. Only the existing explicit copy relation can preserve root scope;
    // a matching string or a mapping for just its first byte is insufficient.
    fn wikiHeadingRootSource(self: *const Renderer, input: []const u8) bool {
        return self.page_wiki_heading_openings != null and self.headingRootSource(input);
    }

    fn wikiAllHeadingRootOffset(self: *const Renderer, input: []const u8) ?usize {
        if (self.page_wiki_all_heading_openings == null) return null;
        if (self.wikiHeadingRootSource(input)) return 0;
        const recovery = self.wiki_heading_recovery orelse return null;
        const root = self.heading_source orelse return null;
        if (self.body_depth != recovery.depth or input.ptr != recovery.source.ptr or input.len != recovery.source.len or
            recovery.offset > root.len or input.len > root.len - recovery.offset) return null;
        return recovery.offset;
    }

    fn headingRootSource(self: *const Renderer, input: []const u8) bool {
        if (self.body_depth != 0) return false;
        const root = self.heading_source orelse return false;
        if (input.ptr == root.ptr and input.len == root.len) return true;
        if (input.len != root.len) return false;
        var current = input;
        var depth: usize = 0;
        while (depth < max_depth) : (depth += 1) {
            if (current.ptr == root.ptr and current.len == root.len)
                return std.mem.eql(u8, input, root);
            var mapped = false;
            for (self.heading_source_aliases.items) |alias| {
                const offset = std.math.sub(usize, @intFromPtr(current.ptr), @intFromPtr(alias.copied.ptr)) catch continue;
                if (offset > alias.copied.len or current.len > alias.copied.len - offset or
                    offset > alias.original.len or current.len > alias.original.len - offset) continue;
                current = alias.original[offset .. offset + current.len];
                mapped = true;
                break;
            }
            if (!mapped) return false;
        }
        return false;
    }

    fn headingSourceOffset(self: *const Renderer, raw: []const u8) ?usize {
        const root = self.heading_source orelse return null;
        var address = @intFromPtr(raw.ptr);
        var depth: usize = 0;
        while (depth < max_depth) : (depth += 1) {
            const root_address = @intFromPtr(root.ptr);
            if (address >= root_address and address - root_address <= root.len and (address - root_address < root.len or raw.len == 0))
                return address - root_address;
            var mapped = false;
            for (self.heading_source_aliases.items) |alias| {
                const copied = @intFromPtr(alias.copied.ptr);
                if (address >= copied and address - copied < alias.copied.len) {
                    address = @intFromPtr(alias.original.ptr) + (address - copied);
                    mapped = true;
                    break;
                }
            }
            if (!mapped) return null;
        }
        return null;
    }

    fn appendHeadingSourceCopy(self: *Renderer, output: *std.ArrayList(u8), copies: *std.ArrayList(HeadingSourceCopy), original: []const u8) Error!void {
        const start = output.items.len;
        try output.appendSlice(self.a, original);
        try self.recordHeadingSourceCopy(copies, start, original);
    }

    fn recordHeadingSourceCopy(self: *Renderer, copies: *std.ArrayList(HeadingSourceCopy), start: usize, original: []const u8) Error!void {
        // Occurrence custody also needs exact copy ranges when no headings
        // are being collected. This grants no heading/class/ancestor authority.
        const image_map_observed = if (self.context.figure_sizing) |source| source.resolve_image_map_no_link_fn != null else false;
        if ((self.heading_source == null and !image_map_observed) or original.len == 0) return;
        if (copies.items.len != 0) {
            const previous = &copies.items[copies.items.len - 1];
            if (previous.start + previous.original.len == start and
                @intFromPtr(previous.original.ptr) + previous.original.len == @intFromPtr(original.ptr))
            {
                previous.original = previous.original.ptr[0 .. previous.original.len + original.len];
                return;
            }
        }
        try copies.append(self.a, .{ .start = start, .original = original });
    }

    fn appendMissingHeadingSourceCopy(self: *Renderer, output: *missing_dependency.Builder, copies: *std.ArrayList(HeadingSourceCopy), source: MissingText, start: usize, end: usize) Error!void {
        const output_start = output.bytes.items.len;
        try output.appendSlice(self.a, source, start, end);
        try self.recordHeadingSourceCopy(copies, output_start, source.bytes[start..end]);
    }

    fn appendMissingHeadingSourceEdit(self: *Renderer, output: *missing_dependency.Builder, copies: *std.ArrayList(HeadingSourceCopy), source: MissingText, at: usize, replacement: []const u8) Error!void {
        const output_start = output.bytes.items.len;
        try output.append(self.a, missingEdit(source, at, at + 1, replacement));
        // Only the replacement's first byte identifies its authored source byte.
        // The remaining generated entity spelling has no source identity.
        if (replacement.len != 0) try self.recordHeadingSourceCopy(copies, output_start, source.bytes[at .. at + 1]);
    }

    fn registerHeadingSourceCopies(self: *Renderer, output: []const u8, copies: []const HeadingSourceCopy) Error!void {
        for (copies) |copy| try self.heading_source_aliases.append(self.a, .{
            .copied = output[copy.start .. copy.start + copy.original.len],
            .original = copy.original,
        });
    }

    fn literalBodyDelimiterSpans(self: *Renderer, raw: []const u8, seed: ?QuoteSeed) Error![]const Span {
        const parent = self.spans;
        self.spans = .empty;
        defer self.spans = parent;
        errdefer self.spans.deinit(self.a);
        var style = self.bodyFormattingStyle(.{});
        if (seed) |quote| {
            const flags = quoteFormatting(quote.state);
            style.bold = flags.bold;
            style.italic = flags.italic;
        }
        try self.protectedLiteral(raw, style);
        return self.spans.toOwnedSlice(self.a);
    }
    // Tables are recognized before headings and only from a physical {| line
    // opener. In this exact malformed bare heading, both brace pairs are text.
    fn literalMalformedWikiHeading(self: *Renderer, source: []const u8, raw: []const u8) bool {
        if (raw.len < 5 or raw.len > 4096 or !starts(raw, "{|") or
            !std.mem.endsWith(u8, raw, "}}") or !literalBareParameterName(raw[2 .. raw.len - 2])) return false;
        if (self.pre_block or self.parsed_pre or self.block_formatting.code or self.in_reference or
            self.in_template_literal_scope or self.poem_depth != 0 or self.explicit_wiki_label != null or self.body_link_target.len != 0) return false;
        const style = self.bodyFormattingStyle(.{ .heading = true });
        if (style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.code or style.preserve_whitespace or style.missing_nonaction) return false;
        const base = @intFromPtr(source.ptr);
        const ptr = @intFromPtr(raw.ptr);
        if (ptr < base or ptr - base > source.len or raw.len > source.len - (ptr - base)) return false;
        var line_start = ptr - base;
        while (line_start != 0 and source[line_start - 1] != '\n') line_start -= 1;
        const line_end = std.mem.indexOfScalarPos(u8, source, ptr - base + raw.len, '\n') orelse source.len;
        const line = source[line_start..line_end];
        if (self.body_missing) |tracked| {
            const tracked_base = @intFromPtr(tracked.bytes.ptr);
            const line_ptr = @intFromPtr(line.ptr);
            if (line_ptr < tracked_base or line_ptr - tracked_base > tracked.bytes.len or
                line.len > tracked.bytes.len - (line_ptr - tracked_base)) return false;
            const begin = line_ptr - tracked_base;
            const end = begin + line.len;
            // Unknown elsewhere does not erase known occurrences. Neither the
            // heading delimiters nor its title may borrow missing-template data.
            for (tracked.ranges) |range| if (range.start < end and range.end > begin) return false;
        }
        const heading = headingLineControlled(line, self.behaviorControlMatcher()) orelse return false;
        return heading.title.ptr == raw.ptr and heading.title.len == raw.len;
    }

    // BlockLevelPass tests generated block elements before indent-pre. Prove
    // only one complete Figure token here; the ordinary renderer still owns
    // namespace/options, source provenance, sizing, caption and action checks.
    fn leadingSpaceFigureLine(self: *Renderer, raw: []const u8) bool {
        if (!starts(raw, " ") or !self.interruptedBodyTargetDomain() or
            std.mem.indexOfAny(u8, raw, "\r\n") != null) return false;
        const token_source = std.mem.trim(u8, raw, " \t");
        if (!starts(token_source, "[[")) return false;
        const pair = syntax.balanced(token_source, 0) orelse return false;
        if (pair.end != token_source.len) return false;
        return self.hasFigureBody(token_source);
    }
    fn bodyRawBlock(self: *Renderer, blocks: *std.ArrayList(Block), source: []const u8, raw: []const u8, quotes: *?QuoteBoundaryScan, kind: Kind, path: []const u8, number: []const u8, level: u8) Error!void {
        const previous = self.next_quote_seed;
        self.next_quote_seed = try self.rawBodyQuoteSeed(source, raw, quotes);
        defer self.next_quote_seed = previous;
        if (kind == .heading and self.literalMalformedWikiHeading(source, raw)) {
            const spans = try self.literalBodyDelimiterSpans(raw, self.next_quote_seed);
            try self.appendBlockBudgeted(blocks, .{
                .kind = kind, .text = raw, .spans = spans,
                .depth = @intCast(@min(path.len, 255)),
                .list_path = path[0..@min(path.len, 255)], .number = number, .level = level,
                .relation_note = self.body_formatting_attributes.relation_note,
                .heading_source_offset = self.headingSourceOffset(raw),
            });
            self.fallbacks.literal_markup = true;
            return;
        }
        try self.block(blocks, kind, raw, path, number, level);
    }

    // A single physical list line cannot close a wiki table at its end.
    // Prove the raw tail is ordinary text, not a nested or stripped token.
    // Admit only a complete leading table in this list item's own source
    // slice. Self-closing TemplateStyles has no reading body; other prefixes,
    // paired extension bodies and closers cannot lend a table opening/closing.
    fn leadingListHtmlTableOffset(self: *Renderer, body: []const u8) Error!?usize {
        var offset: usize = 0;
        while (offset < body.len) {
            while (offset < body.len and std.ascii.isWhitespace(body[offset])) : (offset += 1) {}
            if (offset == body.len) return null;
            const tag = (try self.semanticTagAt(body, offset)) orelse return null;
            if (tag.closing) return null;
            // A permissively recovered tag is not proof of a complete grid.
            // Reject an interrupted/unclosed opening attribute quote here.
            var quote: u8 = 0;
            for (tag.attrs) |c| {
                if (quote != 0) {
                    if (c == quote) quote = 0;
                } else if (c == '\'' or c == '"') {
                    quote = c;
                } else if (c == '<' or c == '>') return null;
            }
            if (quote != 0) return null;
            if (tag.is("table")) {
                if (tag.self_closing) return null;
                const pair = syntax.matchingTag(body, tag) orelse return null;
                const close = (try self.semanticTagAt(body, pair.inner_end)) orelse return null;
                if (!close.closing or close.self_closing or !close.is("table") or trim(close.attrs).len != 0) return null;
                return offset;
            }
            if (!tag.is("templatestyles") or !tag.self_closing) return null;
            offset = tag.end;
        }
        return null;
    }

    // A complete trailing grid is a structural continuation of this physical
    // item. Its preceding inline source keeps its existing interpretation;
    // a table inside a link, protected body or formatting owner is not a tail.
    fn trailingWikiListHtmlTableOffset(self: *Renderer, body: []const u8) Error!?usize {
        if (self.pre_block or self.parsed_pre or self.block_formatting.code or self.in_reference or
            self.in_template_literal_scope or self.body_link_target.len != 0 or
            self.explicit_wiki_label != null or self.inline_source_domain != null or
            self.navigation_target_probe != null or self.inline_image_attribute or
            std.mem.indexOfAny(u8, body, "\r\n") != null) return null;
        for ([_]?MissingText{ self.body_missing, self.inline_missing }) |parent| if (parent) |tracked_parent| {
            const tracked = try missingSlice(self.a, tracked_parent, body);
            if (tracked.unknown or tracked.lost_missing_range or tracked.ranges.len != 0 or
                tracked.literal_curly_ranges.len != 0 or tracked.generated_links.len != 0) return null;
        };
        var at: usize = 0;
        var opaque_scan: syntax.OpaqueScan = .{};
        while (at < body.len) {
            if (opaque_scan.protectedEnd(body, at, null)) |end| { at = end; continue; }
            if (starts(body[at..], "{{") or starts(body[at..], "-{")) return null;
            if (starts(body[at..], "[[")) {
                const pair = syntax.balancedWithOpaqueScan(body, at, &opaque_scan) orelse return null;
                at = pair.end;
                continue;
            }
            if (body[at] == '[' and ir.hasExternalProtocol(body[at + 1 ..])) {
                var iterator: ir.InlineIterator = .{ .input = body[at..], .renderer_boundaries = true };
                const token = iterator.next() orelse return null;
                if (token.kind != .external_link) return null;
                at += iterator.cursor;
                continue;
            }
            if (body[at] == '<') {
                const tag = (try self.semanticTagAt(body, at)) orelse return null;
                if (tag.closing or !formattingAngleAttributesBalanced(tag.attrs) or
                    std.mem.indexOfAny(u8, tag.attrs, "<>\r\n") != null) return null;
                if (tag.is("table")) {
                    if (trim(body[0..at]).len == 0 or tag.self_closing) return null;
                    const pair = syntax.matchingTag(body, tag) orelse return null;
                    if (trim(body[pair.end..]).len != 0) return null;
                    if ((try self.leadingListHtmlTableOffset(body[at..])) != @as(?usize, 0)) return null;
                    if (try self.htmlTableInlineDisplay(tag) orelse return null) return null;
                    if (try self.htmlDisplayNone(tag)) return null;
                    return at;
                }
                if (tag.is("br") or tag.is("wbr") or (tag.is("templatestyles") and tag.self_closing)) {
                    at = tag.end;
                    continue;
                }
                if (tag.self_closing or (blockFormattingFlags(tag) == null and !tag.is("span") and !tag.is("div"))) return null;
                const pair = syntax.matchingTagWithOpaqueScan(body, tag, &opaque_scan) orelse return null;
                // An empty source DIV remains on the old inline prefix path.
                // This does not grant list-owned Container geometry.
                if (tag.is("div") and trim(body[tag.end..pair.inner_end]).len != 0) return null;
                at = pair.end;
                continue;
            }
            at += 1;
        }
        return null;
    }

    fn ordinaryWikiListTableTail(raw: []const u8) bool {
        if (std.mem.indexOfAny(u8, raw, "\r\n") != null) return false;
        const tail = std.mem.lastIndexOf(u8, raw, "|}") orelse return false;
        // Closing DIVs are consumed without text by the ordinary inline parser.
        // They do not make an inline list delimiter a physical table closer.
        var suffix = tail + 2;
        while (suffix < raw.len) {
            const tag = syntax.tagAt(raw, suffix) orelse return false;
            if (!tag.is("div") or !tag.closing or tag.self_closing or trim(tag.attrs).len != 0) return false;
            suffix = tag.end;
        }
        var at: usize = 0;
        var opaque_scan: syntax.OpaqueScan = .{};
        var no_more_nowiki_close = false;
        while (at < tail) {
            if (starts(raw[at..], "<!--")) {
                const close = std.mem.indexOfPos(u8, raw, at + 4, "-->") orelse return false;
                if (close + 3 > tail) return false;
                at = close + 3;
                continue;
            }
            if (raw[at] == '<') {
                const tag = opaque_scan.tagAt(raw, at, &no_more_nowiki_close) orelse return false;
                if (tag.html_pre) return false;
                // Even non-opaque handlers such as includeonly can consume an
                // unclosed remainder. Require a complete opening scope here.
                const end = if (!tag.closing)
                    (syntax.matchingTagWithOpaqueScan(raw, tag, &opaque_scan) orelse return false).end
                else
                    tag.end;
                if (end > tail) return false;
                at = end;
                continue;
            }
            if (starts(raw[at..], "[[") or starts(raw[at..], "{{")) {
                const pair = syntax.balancedWithOpaqueScan(raw, at, &opaque_scan) orelse return false;
                if (pair.end > tail) return false;
                at = pair.end;
                continue;
            }
            // Single-bracket action/recovery domains retain their existing rules.
            if (raw[at] == '[') return false;
            at += 1;
        }
        return at == tail;
    }

    fn literalWikiListTableTail(self: *Renderer, blocks: *std.ArrayList(Block), first_block: usize, raw: []const u8) Error!void {
        // An empty rejected link opener at the end of this physical list line
        // emits a marked diagnostic. It does not turn the earlier inline |}
        // into a table close. Protect only that marker, never the suffix/error.
        if (blocks.items.len == first_block + 1 and std.mem.endsWith(u8, raw, "[[")) recovered_tail: {
            if (self.pre_block or self.parsed_pre or self.block_formatting.code or self.in_reference or
                self.in_template_literal_scope or self.body_link_target.len != 0 or
                self.explicit_wiki_label != null or self.inline_source_domain != null or
                self.navigation_target_probe != null or self.inline_image_attribute) break :recovered_tail;
            const tail = std.mem.lastIndexOf(u8, raw, "|}") orelse break :recovered_tail;
            if (tail + 2 > raw.len - 2 or
                std.mem.indexOfAny(u8, raw[0..tail], "<>&{}'\"\r\n") != null or
                std.mem.indexOfAny(u8, raw[tail + 2 .. raw.len - 2], "<>[]{}|&'\"\r\n") != null or
                !ordinaryWikiListTableTail(raw[0 .. tail + 2])) break :recovered_tail;
            // Reuse the ordinary body-source relation. A byte-identical copy,
            // missing/generated range or protected-curly certificate is no proof.
            const body = self.body_missing orelse break :recovered_tail;
            for ([_]?MissingText{ body, self.inline_missing }) |parent| if (parent) |tracked_parent| {
                const tracked = try missingSlice(self.a, tracked_parent, raw);
                if (tracked.unknown or tracked.ranges.len != 0 or tracked.literal_curly_ranges.len != 0 or
                    tracked.generated_links.len != 0) break :recovered_tail;
            };
            const spans = blocks.items[first_block].spans;
            if (spans.len < 2) break :recovered_tail;
            const diagnostic = spans[spans.len - 1];
            const prior = spans[spans.len - 2];
            if (diagnostic.kind != .text or diagnostic.provenance != .parsed or
                diagnostic.target.len != 0 or diagnostic.self_link or diagnostic.image != null or
                diagnostic.generated_link != null or diagnostic.flags.code or !diagnostic.generated_diagnostic or
                !std.mem.eql(u8, diagnostic.text, "[malformed link] ") or
                prior.kind != .text or prior.provenance != .parsed or prior.target.len != 0 or
                prior.self_link or prior.image != null or prior.generated_link != null or
                prior.flags.code or prior.generated_diagnostic) break :recovered_tail;
            const source_tail = raw[tail .. raw.len - 2];
            if (!std.mem.endsWith(u8, prior.text, source_tail)) break :recovered_tail;
            const marker_at = prior.text.len - source_tail.len;
            const prefix_count: usize = @intFromBool(marker_at != 0);
            const suffix_count: usize = @intFromBool(source_tail.len > 2);
            const literal_spans = try self.a.alloc(Span, spans.len + prefix_count + suffix_count);
            @memcpy(literal_spans[0 .. spans.len - 2], spans[0 .. spans.len - 2]);
            var next = spans.len - 2;
            if (prefix_count != 0) {
                literal_spans[next] = prior;
                literal_spans[next].text = prior.text[0..marker_at];
                next += 1;
            }
            literal_spans[next] = prior;
            literal_spans[next].text = prior.text[marker_at .. marker_at + 2];
            literal_spans[next].provenance = .protected_literal;
            next += 1;
            if (suffix_count != 0) {
                literal_spans[next] = prior;
                literal_spans[next].text = prior.text[marker_at + 2 ..];
                next += 1;
            }
            literal_spans[next] = diagnostic;
            blocks.items[first_block].spans = literal_spans;
            return;
        }
        if (blocks.items.len != first_block + 1 or !ordinaryWikiListTableTail(raw)) return;
        const spans = blocks.items[first_block].spans;
        if (spans.len == 0) return;
        const last = spans[spans.len - 1];
        if (last.kind != .text or last.provenance != .parsed or last.target.len != 0 or
            !std.mem.endsWith(u8, last.text, "|}")) return;
        const extra: usize = @intFromBool(last.text.len > 2);
        const literal_spans = try self.a.alloc(Span, spans.len + extra);
        @memcpy(literal_spans[0 .. spans.len - 1], spans[0 .. spans.len - 1]);
        if (extra != 0) {
            literal_spans[spans.len - 1] = last;
            literal_spans[spans.len - 1].text = last.text[0 .. last.text.len - 2];
        }
        const marker = &literal_spans[literal_spans.len - 1];
        marker.* = last;
        marker.text = last.text[last.text.len - 2 ..];
        marker.provenance = .protected_literal;
        blocks.items[first_block].spans = literal_spans;
    }

    // Table parsing precedes the physical wiki-list pass. A non-colon list
    // prefix keeps its following {| visible; it cannot acquire grid semantics.
    // Certify the original local source and protect only those two text bytes.
    fn literalPhysicalWikiListTableOpen(self: *Renderer, blocks: *std.ArrayList(Block), first_block: usize, input: []const u8, line_start: usize, raw: []const u8, path: []const u8) Error!void {
        if (!starts(raw, "{|") or self.body_depth != 1 or self.in_reference or self.pre_block or self.parsed_pre or
            self.in_template_literal_scope or self.block_formatting.code or self.orphan_close_inline_origin or
            self.body_link_target.len != 0 or self.navigation_target_probe != null) return;
        const tracked = self.body_missing orelse return;
        if (tracked.bytes.ptr != input.ptr or tracked.bytes.len != input.len or line_start >= input.len or
            (line_start != 0 and input[line_start - 1] != '\n')) return;
        const offset = std.math.sub(usize, @intFromPtr(raw.ptr), @intFromPtr(input.ptr)) catch return;
        if (offset < line_start or offset > input.len or raw.len > input.len - offset) return;
        const physical_end = std.mem.indexOfScalarPos(u8, input, line_start, '\n') orelse input.len;
        if (raw.len < 2 or offset + raw.len > physical_end) return;
        var prefix_end = line_start;
        var noncolon = false;
        while (prefix_end < offset and std.mem.indexOfScalar(u8, "*#;:", input[prefix_end]) != null) : (prefix_end += 1) {
            noncolon = noncolon or input[prefix_end] != ':';
        }
        if (!noncolon or !std.mem.eql(u8, input[line_start..prefix_end], path)) return;
        if (std.mem.trim(u8, input[prefix_end..offset], " \t").len != 0 or
            std.mem.trim(u8, input[offset + raw.len .. physical_end], " \t\r").len != 0) return;
        // Unknown evidence elsewhere remains unknown. A known local occurrence,
        // literal-source range or generated action cannot lend this certificate.
        for (tracked.ranges) |range| if (range.start < offset + 2 and range.end > line_start) return;
        for (tracked.literal_curly_ranges) |range| if (range.start < offset + 2 and range.end > line_start) return;
        for (tracked.generated_links) |range| if (range.start < offset + 2 and range.end > line_start) return;
        if (blocks.items.len != first_block + 1) return;
        const spans = blocks.items[first_block].spans;
        if (spans.len == 0) return;
        const first = spans[0];
        if (first.kind != .text or first.provenance != .parsed or first.target.len != 0 or first.self_link or first.flags.code or first.generated_diagnostic or
            first.image != null or first.generated_link != null or !starts(first.text, "{|")) return;
        const extra: usize = @intFromBool(first.text.len > 2);
        const literal_spans = try self.a.alloc(Span, spans.len + extra);
        literal_spans[0] = first;
        literal_spans[0].text = first.text[0..2];
        literal_spans[0].provenance = .protected_literal;
        if (extra != 0) {
            literal_spans[1] = first;
            literal_spans[1].text = first.text[2..];
        }
        @memcpy(literal_spans[1 + extra ..], spans[1..]);
        blocks.items[first_block].spans = literal_spans;
    }

    // Table parsing precedes BlockLevelPass. After a wiki list prefix has
    // been consumed, its leading |} is visible item text, not a table close.
    // Isolate only that literal delimiter; the complete suffix stays strict.
    fn literalWikiListTableClose(self: *Renderer, blocks: *std.ArrayList(Block), first_block: usize, raw: []const u8) Error!void {
        if (!starts(raw, "|}")) return self.literalWikiListTableTail(blocks, first_block, raw);
        if (blocks.items.len != first_block + 1) return;
        const spans = blocks.items[first_block].spans;
        if (spans.len == 0) return;
        const first = spans[0];
        if (first.kind != .text or first.provenance != .parsed or !starts(first.text, "|}")) return;
        const extra: usize = @intFromBool(first.text.len > 2);
        const literal_spans = try self.a.alloc(Span, spans.len + extra);
        literal_spans[0] = first;
        literal_spans[0].text = first.text[0..2];
        literal_spans[0].provenance = .protected_literal;
        if (extra != 0) {
            literal_spans[1] = first;
            literal_spans[1].text = first.text[2..];
        }
        @memcpy(literal_spans[1 + extra ..], spans[1..]);
        blocks.items[first_block].spans = literal_spans;
    }

    // Parser.handleTables consumes only the first physical control on a line.
    // A real table completion may expose a repeated footer after DIV closers.
    // The proof lives only in the current root body and never borrows a copied
    // cell, action, reference, protected source or arbitrary display token.
    fn observeCompletedWikiTableClose(self: *Renderer, close: []const u8) void {
        const proof = self.wiki_table_tail_proof orelse return;
        if (proof.source.unknown or self.in_reference or self.pre_block or self.parsed_pre or
            self.body_link_target.len != 0 or self.block_formatting.code or self.in_template_literal_scope) return;
        const base = @intFromPtr(proof.source.bytes.ptr);
        const ptr = @intFromPtr(close.ptr);
        if (close.len != 2 or !std.mem.eql(u8, close, "|}") or ptr < base or
            ptr - base > proof.source.bytes.len or close.len > proof.source.bytes.len - (ptr - base)) return;
        proof.completed_close = ptr - base;
    }
    fn bareDivClosers(source: []const u8) bool {
        var rest = std.mem.trim(u8, source, " \t\r");
        var count: usize = 0;
        while (rest.len != 0) {
            if (count == 16) return false;
            const tag = syntax.tagAt(rest, 0) orelse return false;
            if (!tag.is("div") or !tag.closing or tag.self_closing or trim(tag.attrs).len != 0) return false;
            rest = std.mem.trim(u8, rest[tag.end..], " \t\r");
            count += 1;
        }
        return count != 0;
    }
    fn completedTableCloseTail(self: *const Renderer, input: []const u8, start: usize, physical_end: usize) bool {
        const proof = self.wiki_table_tail_proof orelse return false;
        if (self.body_depth != 1 or self.orphan_close_inline_origin or self.in_reference or
            self.pre_block or self.parsed_pre or self.in_template_literal_scope or self.block_formatting.code or
            self.body_link_target.len != 0 or proof.source.unknown or
            proof.source.bytes.ptr != input.ptr or proof.source.bytes.len != input.len or
            start > physical_end or physical_end > input.len or physical_end - start < 2 or
            !starts(input[start..physical_end], "|}")) return false;
        const first = proof.completed_close orelse return false;
        if (first >= start or start - first < 2 or (first != 0 and input[first - 1] != '\n') or
            !starts(input[first..start], "|}") or
            !bareDivClosers(input[first + 2 .. start]) or !bareDivClosers(input[start + 2 .. physical_end])) return false;
        for (proof.source.ranges) |range| if (range.start < physical_end and range.end > first) return false;
        for (proof.source.literal_curly_ranges) |range| if (range.start < physical_end and range.end > first) return false;
        for (proof.source.generated_links) |range| if (range.start < physical_end and range.end > first) return false;
        return true;
    }

    fn bodyParagraph(self: *Renderer, blocks: *std.ArrayList(Block), raw: []const u8, seed: ?QuoteSeed, pending_join: *?bool) Error!void {
        const first = blocks.items.len;
        try self.paragraphWithQuoteSeed(blocks, raw, seed);
        if (pending_join.*) |separator| {
            pending_join.* = null;
            try self.joinBodyParagraphs(blocks, first, separator);
        }
    }

    fn appendLinkContinuation(self: *Renderer, blocks: *std.ArrayList(Block), raw: []const u8, target: []const u8) Error!void {
        if (raw.len == 0) return;
        const spans = try self.parseBodySpans(raw, if (target.len != 0) try self.wikiLinkStyle(.{}, .{ .target = target }) else .{});
        if (spans.len == 0) return;
        if (blocks.items.len != 0 and blocks.items[blocks.items.len - 1].kind == .paragraph) {
            try self.appendParagraphSpans(blocks, blocks.items.len - 1, spans, false);
        } else try self.appendBlockBudgeted(blocks, .{ .kind = .paragraph, .spans = spans });
    }

    const BodyPre = struct { opening_start: usize, tag: syntax.Tag, pair: ?syntax.Pair };
    // A root paragraph's pre is a block element. Complete inline/cell domains
    // remain with their existing parsers; never discover a page scope inside
    // attributes, a protected body, a link label, or a template argument.
    // The same conservative hint used by Writer admission. Actual body
    // traversal decides whether a later pre is parsed, protected or literal.
    fn bodyPreCandidate(input: []const u8) bool {
        var at: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input, at, '<')) |opening| {
            at = opening + 1;
            if (input.len - at >= 3 and std.ascii.eqlIgnoreCase(input[at .. at + 3], "pre")) return true;
        }
        return false;
    }
    fn htmlHeadingLevel(tag: syntax.Tag) ?u8 {
        if (tag.name.len != 2 or std.ascii.toLower(tag.name[0]) != 'h' or tag.name[1] < '1' or tag.name[1] > '6') return null;
        return tag.name[1] - '0';
    }
    // Promote only existing ordinary block containers after lexical text.
    // Nested accepted tags, protected bodies and link labels keep their owners.
    fn interruptedBodyTargetDomain(self: *const Renderer) bool {
        const inherited: Style = self.body_language_direction orelse .{};
        return !self.pre_block and !self.parsed_pre and !self.in_reference and
            !self.in_template_literal_scope and !self.block_formatting.code and self.body_link_target.len == 0 and
            self.explicit_wiki_label == null and inherited.provenance == .parsed and inherited.kind == .text and
            inherited.target.len == 0 and inherited.self_link_target == null and !inherited.missing_nonaction and
            !inherited.code and !inherited.preserve_whitespace;
    }
    const InlineBodyContainer = struct { at: usize, rejected_opening: ?usize = null, image_map_error: ?ObservedImageMapError = null };
    fn inlineBodyContainerAt(self: *Renderer, input: []const u8, start: usize, line_end: usize) Error!?usize {
        const container = (try self.inlineBodyContainer(input, start, line_end)) orelse return null;
        return container.at;
    }
    // A complete HR is a block boundary even when a following ordinary table
    // shares its physical line. Keep this admission out of inline/action scopes.
    fn ordinaryTableAfterHorizontalRule(self: *Renderer, input: []const u8, start: usize, at: usize, tag: syntax.Tag) Error!bool {
        if (start >= at or at > input.len or tag.end > input.len - at or
            tag.closing or !tag.is("table") or tag.self_closing or
            self.pre_block or self.parsed_pre or self.block_formatting.code or self.in_reference or
            self.in_template_literal_scope or self.body_link_target.len != 0 or
            self.explicit_wiki_label != null or self.inline_source_domain != null or
            self.navigation_target_probe != null or self.inline_image_attribute) return false;
        const prefix = trim(input[start..at]);
        if (prefix.len == 0 or prefix.len > 4096) return false;
        const rule = syntax.tagAt(prefix, 0) orelse return false;
        if (rule.closing or !rule.is("hr") or rule.end != prefix.len or
            !formattingAngleAttributesBalanced(rule.attrs) or
            std.mem.indexOfAny(u8, rule.attrs, "<>[]{}\r\n") != null or
            !formattingAngleAttributesBalanced(tag.attrs) or
            std.mem.indexOfAny(u8, tag.attrs, "<>[]{}\r\n") != null) return false;
        const pair = syntax.matchingTag(input[at..], tag) orelse return false;
        const closing = syntax.tagAt(input[at..], pair.inner_end) orelse return false;
        if (!closing.closing or !closing.is("table") or trim(closing.attrs).len != 0) return false;
        const inline_display = try self.htmlTableInlineDisplay(tag) orelse return false;
        if (inline_display) return false;
        // The prefix and opener must belong to the current ordinary source.
        // Missing/generated/copied-unmapped domains cannot manufacture them.
        for ([_][]const u8{ input[start .. at + tag.end], input[at + pair.inner_end .. at + pair.end] }) |boundary| {
            for ([_]?MissingText{ self.body_missing, self.inline_missing }) |parent| if (parent) |tracked_parent| {
                const tracked = try missingSlice(self.a, tracked_parent, boundary);
                if (tracked.unknown or tracked.ranges.len != 0 or tracked.literal_curly_ranges.len != 0 or
                    tracked.generated_links.len != 0) return false;
            };
        }
        return true;
    }

    fn retainedCellTableDomain(self: *Renderer, input: []const u8, tag: syntax.Tag) Error!bool {
        const source = self.retained_cell_body_source orelse return false;
        const base = @intFromPtr(source.ptr);
        const address = @intFromPtr(input.ptr);
        if (address < base or address - base > source.len or input.len > source.len - (address - base) or
            !tag.is("table") or tag.closing or tag.self_closing or
            self.figure_caption_depth != 0 or !self.interruptedBodyTargetDomain() or
            self.inline_source_domain != null or self.navigation_target_probe != null or self.inline_image_attribute)
            return false;
        // Inline/unknown display keeps the existing span/flow refusal path.
        return !(try self.htmlTableInlineDisplay(tag) orelse return false);
    }

    fn inlineBodyContainer(self: *Renderer, input: []const u8, start: usize, line_end: usize) Error!?InlineBodyContainer {
        const interrupted_target_domain = self.interruptedBodyTargetDomain();
        var rejected_opening: ?usize = null;
        var at = start;
        var opaque_scan: syntax.OpaqueScan = .{};
        while (at < line_end) {
            at += std.mem.indexOfAny(u8, input[at..line_end], "<[{") orelse return null;
            if (input[at] == '<') {
                // A proven extension error is the observed P block at this
                // original interval; all other opaque extensions stay opaque.
                if (rejected_opening == null) if (try self.observedImageMapErrorAt(input, at)) |observed|
                    return .{ .at = at, .image_map_error = observed };
                if (opaque_scan.protectedEnd(input, at, null)) |end| {
                    at = end;
                    continue;
                }
                if (try self.semanticTagAt(input[at..], 0)) |tag| {
                    if (!tag.closing and syntax.pairedHtmlTag(tag.name)) {
                        const pair = (if (tag.is("p")) blockWrapperPair(input[at..], tag, self.behaviorControlMatcher()) else syntax.matchingTag(input[at..], tag)) orelse return null;
                        const item_block = self.html_list_item_flow and oneOf(tag.name, &.{ "ul", "ol", "dl", "table" });
                        const rule_table = tag.is("table") and try self.ordinaryTableAfterHorizontalRule(input, start, at, tag);
                        const cell_table = tag.is("table") and try self.retainedCellTableDomain(input, tag);
                        if (at > start and (item_block or rule_table or cell_table or oneOf(tag.name, &.{ "blockquote", "div", "p", "center" }) or htmlHeadingLevel(tag) != null))
                            return .{ .at = at, .rejected_opening = rejected_opening };
                        at += pair.end;
                    } else at += tag.end;
                    continue;
                }
            } else if (starts(input[at..], "[[") or starts(input[at..], "{{")) {
                if (interrupted_target_domain and htmlInterruptedInternalOpening(input, at)) {
                    // This rejected opener has no label owner. Keep scanning its
                    // ordinary HTML children instead of hiding them in a pair.
                    rejected_opening = at;
                    at += 2;
                    continue;
                }
                if (syntax.balancedWithOpaqueScan(input, at, &opaque_scan)) |pair| {
                    at = pair.end;
                    continue;
                }
                return null;
            } else if (input[at] == '[' and ir.hasExternalProtocol(input[at + 1 ..])) {
                var iterator: ir.InlineIterator = .{ .input = input[at..], .renderer_boundaries = true };
                if (iterator.next()) |token| if (token.kind == .external_link) {
                    at += iterator.cursor;
                    continue;
                };
            }
            at += 1;
        }
        return null;
    }

    fn bodyPreAt(input: []const u8, start: usize, opaque_scan: *syntax.OpaqueScan) ?BodyPre {
        const line_end = std.mem.indexOfScalarPos(u8, input, start, '\n') orelse input.len;
        var nesting: [max_depth][]const u8 = undefined;
        var count: usize = 0;
        var at = start;
        while (at < line_end) {
            if (input[at] == '<') {
                if (opaque_scan.tagAt(input, at, null)) |tag| {
                    if (!tag.closing and !tag.self_closing and tag.is("pre") and count == 0) {
                        const pair = syntax.matchingTagWithOpaqueScan(input, tag, opaque_scan);
                        if (tag.html_pre or pair == null) return .{ .opening_start = at, .tag = tag, .pair = pair };
                        at = pair.?.end;
                        continue;
                    }
                    if (!tag.closing and tag.isOpaque()) {
                        at = if (opaque_scan.pair(input, tag)) |pair| pair.end else tag.end;
                        continue;
                    }
                    if (syntax.pairedHtmlTag(tag.name) or tag.html_pre or oneOf(tag.name, &.{ "li", "dt", "dd" })) {
                        if (tag.closing) {
                            if (count != 0 and std.ascii.eqlIgnoreCase(nesting[count - 1], tag.name)) count -= 1;
                        } else if (!tag.self_closing) {
                            if (count == nesting.len) return null;
                            nesting[count] = tag.name;
                            count += 1;
                        }
                    }
                    at = tag.end;
                    continue;
                }
                if (opaque_scan.protectedEnd(input, at, null)) |end| {
                    at = end;
                    continue;
                }
            }
            if (starts(input[at..], "{{") or starts(input[at..], "[[")) {
                if (syntax.balancedWithOpaqueScan(input, at, opaque_scan)) |pair| {
                    at = pair.end;
                    continue;
                }
            }
            at += 1;
        }
        return null;
    }

    fn behaviorControlMatcher(self: *Renderer) ?syntax.ControlMatcher {
        return if (self.context.behavior_switches) |registry| .{
            .ctx = registry,
            .match = struct {
                fn match(raw: ?*const anyopaque, value: []const u8, at: usize) ?usize {
                    const profile: *const @import("namespace_registry").behavior_switches.Registry = @ptrCast(@alignCast(raw.?));
                    return profile.matchAt(std.heap.page_allocator, value, at) catch null;
                }
            }.match,
            .toc_match = struct {
                fn match(raw: ?*const anyopaque, value: []const u8, at: usize) ?usize {
                    const profile: *const @import("namespace_registry").behavior_switches.Registry = @ptrCast(@alignCast(raw.?));
                    return profile.tocMatchAt(std.heap.page_allocator, value, at) catch null;
                }
            }.match,
        } else null;
    }
    fn renderInlineTableBody(self: *Renderer, source: []const u8) Error![]const Block {
        // Keep existing table/heading parsing unchanged. Only orphan-close
        // recovery needs the lost physical origin of this inline capture.
        return self.renderBodyWithOrphanOrigin(MissingText.untracked(source), true);
    }

    fn renderBodyWithOrphanOrigin(self: *Renderer, source: MissingText, inline_origin: bool) Error![]const Block {
        const previous = self.orphan_close_inline_origin;
        self.orphan_close_inline_origin = inline_origin;
        defer self.orphan_close_inline_origin = previous;
        return self.renderBodyWithMissing(source);
    }

    fn renderBodyWithInlineStart(self: *Renderer, source: []const u8, initial_inline: bool) Error![]const Block {
        return self.renderBodySlice(source, initial_inline, false, null, null);
    }
    const BodyListSeed = struct { path: []const u8, previous_path: []const u8, counts: [32]usize, result: ?*BodyListSeed = null };
    fn renderBodySlice(self: *Renderer, source: []const u8, initial_inline: bool, terminal_inline: bool, source_origin: ?usize, initial_quote: ?QuoteSeed) Error![]const Block {
        return self.renderBodySliceSeeded(source, initial_inline, terminal_inline, source_origin, initial_quote, null);
    }
    fn renderBodySliceSeeded(self: *Renderer, source: []const u8, initial_inline: bool, terminal_inline: bool, source_origin: ?usize, initial_quote: ?QuoteSeed, initial_list: ?BodyListSeed) Error![]const Block {
        try self.checkPageAncestorEffects(if (self.body_missing) |tracked| try missingSlice(self.a, tracked, source) else MissingText.untracked(source));
        const previous_implicit_list = self.figure_implicit_list_context;
        self.figure_implicit_list_context = previous_implicit_list or (if (initial_list) |seed| seed.path.len != 0 else false);
        defer self.figure_implicit_list_context = previous_implicit_list;
        const tracked = if (self.body_missing) |parent| try self.missingSliceWithHeadingSource(parent, source) else MissingText.untracked(source);
        const prepared_missing = try self.prepareUnmatchedOpaqueWithMissing(tracked);
        const input = prepared_missing.bytes;
        const wiki_root_source = self.wikiHeadingRootSource(input);
        const wiki_all_root_offset = self.wikiAllHeadingRootOffset(input);
        const html_root_source = self.page_html_heading_openings != null and self.headingRootSource(input);
        const previous_missing = self.body_missing;
        self.body_missing = prepared_missing;
        defer self.body_missing = previous_missing;
        // An allocated preparation is a different source domain. Do not infer
        // its original offsets; the caller prepares the whole page first.
        const origin = if (input.ptr == source.ptr and input.len == source.len) source_origin else null;
        if (self.pre_scope_observer != null and source_origin != null and origin == null)
            return error.InvalidPreContext;
        if (self.body_depth >= max_depth) {
            self.fallbacks.render_limit = true;
            var fallback: std.ArrayList(Block) = .empty;
            try self.block(&fallback, .preformatted, input, "", "", 0);
            return fallback.toOwnedSlice(self.a);
        }
        var root_table_tail: WikiTableTailProof = .{ .source = prepared_missing };
        const prior_table_tail = self.wiki_table_tail_proof;
        if (self.body_depth == 0) self.wiki_table_tail_proof = if (initial_inline) null else &root_table_tail;
        defer self.wiki_table_tail_proof = prior_table_tail;
        self.body_depth += 1;
        defer self.body_depth -= 1;
        const line_capacity = std.mem.count(u8, input, "\n") + @intFromBool(input.len != 0 and input[input.len - 1] != '\n');
        var blocks: std.ArrayList(Block) = try .initCapacity(self.a, line_capacity);
        var paragraph_join: BodyParagraphJoin = .{};
        const previous_join = self.body_paragraph_join;
        self.body_paragraph_join = &paragraph_join;
        defer self.body_paragraph_join = previous_join;
        var inline_line_end = if (initial_inline) (std.mem.indexOfScalar(u8, input, '\n') orelse input.len) else 0;
        var pos: usize = 0;
        var para: ?usize = null;
        var link_inline_join: ?bool = null;
        var formatting_join_pending = false;
        var counts: [32]usize = if (initial_list) |seed| seed.counts else @splat(0);
        var previous_list_path: []const u8 = if (initial_list) |seed| seed.previous_path else "";
        var line_opaque: syntax.OpaqueScan = .{};
        var body_pre_opaque: syntax.OpaqueScan = .{};
        var body_quotes: ?QuoteBoundaryScan = if (initial_quote != null) QuoteBoundaryScan.initWithContext(input, initial_quote, self.context) else null;
        defer if (body_quotes) |*quotes| quotes.deinit();
        // The later block pass sees a complete admitted label inside its anchor.
        // Wiki list markers and leading spaces stay literal in that raw domain.
        const link_label_scope = if (initial_quote) |seed| seed.label_scope else false;
        // This raw domain is immutable and every local continuation resumes
