        var content = indent;
        while (content < line.len and std.ascii.isWhitespace(line[content])) : (content += 1) {}
        if (!starts(line[content..], "{|")) return null;
        return line[0..indent];
    }
    fn indentTableBlocks(self: *Renderer, blocks: []const Block, path: []const u8) Error![]const Block {
        if (path.len == 0 or blocks.len == 0) return blocks;
        const indented = try self.a.dupe(Block, blocks);
        for (indented) |*b| {
            if (b.container != null) return self.containerUnavailableAt("indented_container_owner", "");
            const composed = try std.fmt.allocPrint(self.a, "{s}{s}", .{ path, b.list_path });
            b.list_path = composed[0..@min(composed.len, 255)];
            b.depth = @intCast(b.list_path.len);
        }
        return indented;
    }
    fn appendTableCaption(self: *Renderer, caption: *std.ArrayList(Span), spans: []const Span) Error!void {
        if (spans.len == 0) return;
        if (caption.items.len != 0 and self.spend())
            try caption.append(self.a, .{ .kind = .line_break, .text = "" });
        try caption.appendSlice(self.a, spans);
    }
    fn captionInlineBlock(self: *Renderer, spans: []const Span) Error!Block {
        if (!self.spend()) return error.RenderLimit;
        const parts = try self.a.alloc(FlowPart, 1);
        parts[0] = .{ .kind = .@"inline", .spans = spans };
        return .{ .kind = .paragraph, .flow = parts };
    }
    fn appendRichTableCaption(self: *Renderer, flat: *std.ArrayList(Span), rich: *std.ArrayList(Block), spans: []const Span, blocks: ?[]const Block) Error!void {
        if (blocks == null and rich.items.len == 0) return self.appendTableCaption(flat, spans);
        if (spans.len == 0 and (if (blocks) |values| values.len == 0 else true)) return;
        if (flat.items.len != 0) try rich.append(self.a, try self.captionInlineBlock(try flat.toOwnedSlice(self.a)));
