    }
    fn cellContentSpans(self: *Renderer, source: []const u8, retained: ?*?[]const Block) Error![]const Span {
        const previous_cell_source = self.retained_cell_body_source;
        // Capture the caller's domain before the cell clears inline targets.
        self.retained_cell_body_source = if (retained != null and self.interruptedBodyTargetDomain() and
            self.figure_caption_depth == 0 and self.inline_source_domain == null and
            self.navigation_target_probe == null and !self.inline_image_attribute) source else null;
        defer self.retained_cell_body_source = previous_cell_source;
        // A caption/span-only caller cannot retain a figure, even if recursive
        // list/table parsing temporarily re-enters the ordinary block renderer.
        const previous_suppression = self.image_block_suppressed;
        self.image_block_suppressed = previous_suppression or retained == null;
        defer self.image_block_suppressed = previous_suppression;
        // Cells are local inline domains. Preserve ordinary cell-opener text,
        // but retain real later headings and rules rather than flattening identity.
        const previous_target = self.body_link_target;
        self.body_link_target = "";
        defer self.body_link_target = previous_target;
        var no_more_nowiki_close = false;
        var has_blocks = false;
        var pos: usize = 0;
        while (pos < source.len) {
            const end = syntax.logicalEndCached(source, pos, &no_more_nowiki_close);
            if (pos != 0 and end != pos and (self.tableCellHeading(source[pos..end]) != null or
                (self.figure_caption_depth == 0 and (source[pos] == ' ' or std.mem.indexOfScalar(u8, "#*:;", source[pos]) != null or starts(source[pos..end], "----"))))) has_blocks = true;
            // Complete cell-local HTML tables need the block route even without
            // a list or heading. The logical-line walk skips protected owners.
            if (retained != null and wikiCellHtmlTableEnd(source, pos) != null) has_blocks = true;
            pos = if (end < source.len) end + 1 else end;
        }
        if (retained != null and (hasContainerBody(source, false) or cellWrappedHtmlTable(source) or hasCellHtmlHeading(source) or try self.hasAlignedBlockScope(source))) has_blocks = true;
        if (!has_blocks and retained != null and try self.cellWholeHtmlListHasBodyBlocks(source)) has_blocks = true;
        // Use the same opaque/link-aware boundary walk as the block renderer.
        // A prefix on the same physical line cannot flatten a real cell table.
        if (!has_blocks and retained != null and try self.inlineBodyContainer(source, 0, source.len) != null) has_blocks = true;
        // File captions undergo link parsing before the page BlockLevelPass;
        // ordinary LF cannot create fresh wiki list/pre/paragraph furniture.
        // Real HTML boxes and the earlier table/heading phases still retain
        // their structural domains. Protected payloads keep their own parser.
        if (retained != null and self.figure_caption_depth != 0 and hasNestedBlockGeometryBox(source)) has_blocks = true;
        if (!has_blocks and std.mem.indexOf(u8, source, "{|") == null) {
            const previous_capture = self.semantic_capture;
            var hints: SemanticHints = if (previous_capture) |value| value.* else .{};
            hints.image_blocks = retained != null;
            hints.figure_blocks = retained != null;
            self.semantic_capture = &hints;
            defer {
                if (previous_capture) |value| value.relation_note = hints.relation_note;
                self.semantic_capture = previous_capture;
            }
            const spans = try self.parseBodySpans(source, .{});
            if (retained) |output| if (hasNonfloatingImage(spans) or hasPendingFigure(spans)) {
                if (!self.spend()) return error.RenderLimit;
                const paragraph_blocks = try self.a.alloc(Block, 1);
                paragraph_blocks[0] = .{ .kind = .paragraph, .spans = spans, .relation_note = hints.relation_note };
                output.* = try self.separateNonfloatingImages(paragraph_blocks);
                return &.{};
            };
            return spans;
        }
        const parent = self.spans;
        self.spans = .empty;
        defer self.spans = parent;
        var body = source;
        var prefix: []const Span = &.{};
        const first_end = syntax.logicalEnd(source, 0);
        if (source.len != 0 and (self.tableCellHeading(source[0..first_end]) != null or
            (self.figure_caption_depth == 0 and (std.mem.indexOfScalar(u8, "#*:;", source[0]) != null or starts(source[0..first_end], "----"))))) {
            prefix = try self.parseBodySpans(source[0..first_end], .{});
            body = source[if (first_end < source.len) first_end + 1 else first_end..];
        }
        const tracked_body = if (self.body_missing) |missing_parent| try self.missingSliceWithHeadingSource(missing_parent, body) else MissingText.untracked(body);
        const body_blocks = try self.renderBodyWithOrphanOrigin(tracked_body, body.ptr == source.ptr);
        const cell_alignment = self.body_formatting_attributes.text_align;
        if (retained) |output| if (blocksNeedCellRetention(body_blocks, cell_alignment) or self.figure_caption_depth != 0) {
            const blocks = try self.relativeCellBlocks(body_blocks, cell_alignment);
            if (prefix.len == 0) {
                output.* = blocks;
            } else {
                const ordered = try self.a.alloc(Block, blocks.len + 1);
                ordered[0] = .{ .kind = .paragraph, .spans = prefix };
                @memcpy(ordered[1..], blocks);
                output.* = ordered;
            }
            return &.{};
        };
        try self.spans.appendSlice(self.a, prefix);
        if (prefix.len != 0 and body.len != 0) try self.lineBreak(.{});
        try self.blocksInline(body_blocks, .{});
        return self.spans.toOwnedSlice(self.a);
    }

    fn resolveZeroRowspans(self: *Renderer, rows: []Row, group_start: usize) Error!void {
        for (rows[group_start..], group_start..) |*row, index| {
            var has_zero = false;
            for (row.cells) |cell| {
                if (cell.rowspan == 0) has_zero = true;
            }
            if (!has_zero) continue;
            // Cells are const slices; copy only rows needing normalization.
            const cells = try self.a.dupe(Cell, row.cells);
            for (cells) |*cell| {
                if (cell.rowspan == 0) cell.rowspan = @intCast(@min(rows.len - index, 100));
            }
            row.cells = cells;
        }
    }
    fn tableSpanAttr(self: *Renderer, tag: syntax.Tag, name: []const u8) Error!u16 {
        const raw = (try self.semanticAttribute(tag, name)) orelse return 1;
        const parsed: u16 = std.fmt.parseInt(u16, raw, 10) catch |err| overflow: {
            if (err != error.Overflow or raw.len == 0) break :overflow 1;
            // Validate the entire positive decimal: overflow may precede junk.
            // Keep parseInt's optional plus and internal underscore grammar.
            const digits = if (raw[0] == '+') raw[1..] else raw;
            if (digits.len == 0 or digits[0] == '_' or digits[digits.len - 1] == '_') break :overflow 1;
            for (digits) |ch| if (ch != '_' and !std.ascii.isDigit(ch)) break :overflow 1;
            break :overflow 100;
        };
        // Zero is build-only: the completed row group resolves it before encoding.
        if (parsed == 0 and std.mem.eql(u8, name, "rowspan")) return 0;
        return @max(1, @min(100, parsed));
    }

    // Root/view includeonly regions are excluded by the preprocessor before
    // table splitting. Keep a complete region together until the existing HTML
    // handler suppresses it; never split its hidden row/cell/attribute markers.
    fn wikiTableProtectedEnd(input: []const u8, at: usize, scan: *syntax.OpaqueScan, no_more_close: ?*bool) ?usize {
        if (scan.protectedEnd(input, at, no_more_close)) |end| return end;
        const tag = scan.tagAt(input, at, no_more_close) orelse return null;
        if (tag.closing or !tag.is("includeonly")) return null;
        if (tag.self_closing) return tag.end;
        // The shared matcher uses the first raw whitespace-only view closer,
        // not nested HTML balancing. Unclosed/malformed cases retain old rules.
        const pair = syntax.matchingTagWithOpaqueScan(input, tag, scan) orelse return null;
        return pair.end;
    }

    fn cellAttributePipe(raw: []const u8) ?usize {
        // Ordinary containers stop at the opening physical line. Earlier strip
        // regions are one opaque token to the table parser, even across lines.
        var end = std.mem.indexOfAny(u8, raw, "\r\n") orelse raw.len;
        const interesting = [_]u8{ '|', '<', '{', '[' };
        var i: usize = 0;
        var opaque_scan: syntax.OpaqueScan = .{};
        while (i < end) {
            const line = raw[0..end];
            i += std.mem.indexOfAny(u8, line[i..], &interesting) orelse return null;
            if (line[i] == '|') return i;
            if (line[i] == '<') {
                if (wikiTableProtectedEnd(raw, i, &opaque_scan, null)) |protected_end| {
                    if (protected_end > end) {
                        // Missing opaque closers fall back to the opening tag's
                        // end. That fallback cannot extend the physical line.
                        if (starts(raw[i..], "<!--")) {
                            if (!std.mem.endsWith(u8, raw[i..protected_end], "-->")) return null;
                        } else {
                            const opening = opaque_scan.tagAt(raw, i, null) orelse return null;
                            if (!opening.self_closing and protected_end <= opening.end) return null;
                        }
                        end = protected_end + (std.mem.indexOfAny(u8, raw[protected_end..], "\r\n") orelse raw[protected_end..].len);
                    }
                    i = protected_end;
                    continue;
                }
                if (syntax.tagAt(line, i)) |tag| {
                    i = tag.end;
                    continue;
                }
            }
            // Parser::handleTables declines cell attributes when a real [[
            // precedes the first delimiter. Earlier opaque/armored tokens were
            // skipped above; their contents cannot supply this source proof.
            if (starts(line[i..], "[[")) return null;
            if (starts(line[i..], "{{")) {
                if (syntax.balanced(line, i)) |pair| {
                    i = pair.end;
                    continue;
                }
                return null;
            }
            i += 1;
        }
        return null;
    }

    // Wiki table cells are split before internal links. Link/template token
    // balancing therefore cannot hide raw table separators. Earlier strip
    // regions stay opaque; allowed HTML attributes are armored by Sanitizer.
    // Earlier strip regions and Sanitizer-armored attributes can contain raw
    // LF in this compiler input. Ordinary link/template/container balancing
    // cannot hide a physical wiki-table marker before the internal-link pass.
    // A complete HTML child belongs to the current wiki cell. Keep its raw
    // rows together, but never skip a physical wiki-table phase boundary.
    fn wikiCellHtmlTableEnd(input: []const u8, start: usize) ?usize {
        if (start >= input.len) return null;
        const bounded = input[start..][0..@min(input.len - start, 1 << 20)];
        const leading = std.mem.trimStart(u8, bounded, " \t");
        const open_at = bounded.len - leading.len;
        const opening = syntax.tagAt(bounded, open_at) orelse return null;
        if (!opening.is("table") or opening.closing or opening.self_closing or
            !formattingAngleAttributesBalanced(opening.attrs)) return null;
        const pair = syntax.matchingTag(bounded, opening) orelse return null;
        const closing = syntax.tagAt(bounded, pair.inner_end) orelse return null;
        if (!closing.is("table") or !closing.closing or closing.self_closing or trim(closing.attrs).len != 0 or closing.end != pair.end) return null;
        var line_end = pair.end;
        while (line_end < bounded.len and (bounded[line_end] == ' ' or bounded[line_end] == '\t' or bounded[line_end] == '\r')) : (line_end += 1) {}
        if (line_end < bounded.len and bounded[line_end] != '\n') return null;
        if (start + line_end < input.len and line_end == bounded.len) return null;
        const source = bounded[0..line_end];
        var pos: usize = 0;
        while (pos < source.len) {
            const end = wikiTableLineEnd(source, pos);
            const line = trim(source[pos..end]);
            if (wikiTableIndent(line) != null or (line.len != 0 and (line[0] == '|' or line[0] == '!'))) return null;
            pos = if (end < source.len) end + 1 else end;
        }
        // The lexical matcher must not borrow a closing token from an
        // unfinished attribute. Opaque bodies use the existing strip boundary.
        var at: usize = open_at;
        var opaque_scan: syntax.OpaqueScan = .{};
        var no_more_nowiki_close = false;
        while (std.mem.indexOfScalarPos(u8, source, at, '<')) |token_at| {
            if (opaque_scan.protectedEnd(source, token_at, &no_more_nowiki_close)) |end| {
                at = end;
                continue;
            }
            const tag = opaque_scan.tagAt(source, token_at, &no_more_nowiki_close) orelse return null;
            if (!formattingAngleAttributesBalanced(tag.attrs)) return null;
            at = tag.end;
        }
        return start + line_end;
    }

    fn wikiTableLineEnd(input: []const u8, start: usize) usize {
        var no_more_nowiki_close = false;
        var opaque_scan: syntax.OpaqueScan = .{};
        return wikiTableLineEndWithScan(input, start, &opaque_scan, &no_more_nowiki_close);
    }

    fn wikiTableLineEndWithScan(input: []const u8, start: usize, opaque_scan: *syntax.OpaqueScan, no_more_nowiki_close: *bool) usize {
        var at = start;
        while (at < input.len) {
            const relative = std.mem.indexOfAny(u8, input[at..], "\n<") orelse return input.len;
            at += relative;
            if (input[at] == '\n') return at;
            if (wikiTableProtectedEnd(input, at, opaque_scan, no_more_nowiki_close)) |end| {
                at = end;
                continue;
            }
            if (opaque_scan.tagAt(input, at, no_more_nowiki_close)) |tag| {
                if (wikiTableArmoredTag(tag)) {
                    at = tag.end;
                    continue;
                }
            }
            at += 1;
        }
        return input.len;
    }
    fn wikiTableArmoredTag(tag: syntax.Tag) bool {
        return oneOf(tag.name, &.{
            "b",      "bdi",  "del",  "i",    "ins",    "u",          "font", "big",  "small", "sub",   "sup",
            "h1",     "h2",   "h3",   "h4",   "h5",     "h6",         "cite", "code", "em",    "s",     "strike",
            "strong", "tt",   "var",  "div",  "center", "blockquote", "ol",   "ul",   "dl",    "table", "caption",
            "pre",    "ruby", "rb",   "rp",   "rt",     "rtc",        "p",    "span", "abbr",  "dfn",   "kbd",
            "samp",   "data", "time", "mark", "br",     "wbr",        "hr",   "li",   "dt",    "dd",    "tr",
            "td",     "th",   "q",    "bdo",
        }) or (tag.is("meta") and tag.attr("itemprop") != null and tag.attr("content") != null) or
            (tag.is("link") and tag.attr("itemprop") != null and tag.attr("href") != null);
    }

    fn wikiCellDelimiter(line: []const u8, needle: []const u8, start: usize) ?usize {
        var no_more_nowiki_close = false;
        var opaque_scan: syntax.OpaqueScan = .{};
        return wikiCellDelimiterWithScan(line, needle, start, &opaque_scan, &no_more_nowiki_close);
    }

    fn wikiCellDelimiterWithScan(line: []const u8, needle: []const u8, start: usize, opaque_scan: *syntax.OpaqueScan, no_more_nowiki_close: *bool) ?usize {
        var i = start;
        while (i < line.len) {
            if (starts(line[i..], needle)) return i;
            if (line[i] == '<') {
                if (wikiTableProtectedEnd(line, i, opaque_scan, no_more_nowiki_close)) |end| {
                    i = end;
                    continue;
                }
                if (opaque_scan.tagAt(line, i, no_more_nowiki_close)) |tag| {
                    if (wikiTableArmoredTag(tag)) {
                        i = tag.end;
                        continue;
                    }
                }
            }
            i += 1;
        }
        return null;
    }

    // Table attributes are interpreted after root-view preprocessing too.
    // Normalize only this derived attribute string; content slices and their
    // MissingText/heading-source coordinates remain in the original domain.
    fn wikiTableViewAttrs(self: *Renderer, raw: []const u8) Error![]const u8 {
        var scan: syntax.OpaqueScan = .{};
        var out: std.ArrayList(u8) = .empty;
        errdefer out.deinit(self.a);
        var copied: usize = 0;
        var at: usize = 0;
        var changed = false;
        while (std.mem.indexOfScalarPos(u8, raw, at, '<')) |open| {
            if (scan.protectedEnd(raw, open, null)) |end| {
                at = end;
                continue;
            }
            const tag = scan.tagAt(raw, open, null) orelse { at = open + 1; continue; };
            if (tag.closing or !tag.is("includeonly")) { at = open + 1; continue; }
            const end = if (tag.self_closing) tag.end else if (syntax.matchingTagWithOpaqueScan(raw, tag, &scan)) |pair| pair.end else {
                at = tag.end;
                continue;
            };
            try out.appendSlice(self.a, raw[copied..open]);
            copied = end;
            at = end;
            changed = true;
        }
        if (!changed) return raw;
        try out.appendSlice(self.a, raw[copied..]);
        return try out.toOwnedSlice(self.a);
    }

    fn cellContent(self: *Renderer, raw: []const u8) Error!CellContent {
        if (cellAttributePipe(raw)) |pipe| {
            const tag: syntax.Tag = .{ .name = "td", .attrs = try self.wikiTableViewAttrs(raw[0..pipe]), .end = 0, .closing = false, .self_closing = false };
            return .{
                .text = trim(raw[pipe + 1 ..]),
                .attrs = tag.attrs,
                .colspan = try self.tableSpanAttr(tag, "colspan"),
                .rowspan = try self.tableSpanAttr(tag, "rowspan"),
                .swatch_color = try self.swatchCssHex(tag, "color"),
            };
        }
        return .{ .text = trim(raw) };
    }

    fn appendTableInlineSpans(self: *Renderer, spans: []const Span, background: ?[]const u8, remaining: *usize) Error!void {
        if (spans.len > remaining.*) return error.RenderLimit;
        remaining.* -= spans.len;
        for (spans) |span| {
            var painted = span;
            if (painted.background == null) painted.background = background;
            try self.spans.append(self.a, painted);
        }
    }
    fn tableInlineWithBudget(self: *Renderer, table: Table, style: Style, leading_row_break: bool, background: ?[]const u8, depth: usize, remaining: *usize) Error!void {
        if (table.caption_blocks != null) return self.figureUnavailableAt("inline_table_caption_blocks", "", 0, 0);
        if (depth >= @import("blob_encoder").presentation_types.max_table_depth or !htmlNestedSpend(remaining)) return error.RenderLimit;
        // A child caption is inside its containing cell but outside its own
        // cells. Structural separators never acquire a cell's paint.
        try self.appendTableInlineSpans(table.caption, background, remaining);
        for (table.rows, 0..) |row, ri| {
            if (!htmlNestedSpend(remaining)) return error.RenderLimit;
            if (leading_row_break or ri != 0 or table.caption.len != 0) try self.lineBreak(style);
            for (row.cells, 0..) |cell, ci| {
                if (!htmlNestedSpend(remaining)) return error.RenderLimit;
                if (ci != 0) try self.text(" · ", style);
                const cell_background = cell.background orelse background;
                if (cell.blocks) |blocks| {
                    try self.cellBlocksInlineWithBudget(blocks, style, cell_background, depth, remaining);
                } else {
                    try self.appendTableInlineSpans(cell.spans, cell_background, remaining);
                    if (cell.nested_table) |child|
                        try self.tableInlineWithBudget(child, style, false, cell_background, depth + 1, remaining);
                }
            }
        }
    }
    fn cellBlocksInlineWithBudget(self: *Renderer, blocks: []const Block, style: Style, background: ?[]const u8, depth: usize, remaining: *usize) Error!void {
        for (blocks, 0..) |block_value, index| {
            if (!htmlNestedSpend(remaining)) return error.RenderLimit;
            if (index != 0) try self.lineBreak(style);
            const label_start = self.spans.items.len;
            if (block_value.list_path.len != 0) switch (block_value.list_path[block_value.list_path.len - 1]) {
                '*' => try self.text("• ", style),
                '#' => if (block_value.number.len != 0) {
                    try self.text(block_value.number, style);
                    try self.text(". ", style);
                },
                else => {},
            };
            for (self.spans.items[label_start..]) |*span| if (span.background == null) {
                span.background = background;
            };
            if (block_value.container != null) return self.containerUnavailableAt("inline_cell_container_block", "");
            if (block_value.figure != null or block_value.flow != null) return self.figureUnavailableAt("inline_cell_structural_block", "", 0, @as(u64, @intFromBool(block_value.figure != null)) | (@as(u64, @intFromBool(block_value.flow != null)) << 1));
            try self.appendTableInlineSpans(block_value.spans, background, remaining);
            if (block_value.table) |child| try self.tableInlineWithBudget(child, style, false, background, depth + 1, remaining);
        }
    }
    fn tableInline(self: *Renderer, table: Table, style: Style, leading_row_break: bool) Error!void {
        var remaining: usize = 1 << 20;
        try self.tableInlineWithBudget(table, style, leading_row_break, null, 0, &remaining);
    }

    // Span-only containment keeps table reading order and explicit row/cell
    // boundaries; its text projection does not recreate table geometry.
    fn blocksInline(self: *Renderer, blocks: []const Block, style: Style) Error!void {
        for (blocks, 0..) |b, index| {
            if (index != 0) try self.lineBreak(style);
            // List labels live on blocks, while DPR2 table cells hold spans.
            // Continuation paths (ending in ':') carry no repeated label.
            if (b.list_path.len != 0) switch (b.list_path[b.list_path.len - 1]) {
                '*' => try self.text("• ", style),
                '#' => if (b.number.len != 0) {
                    try self.text(b.number, style);
                    try self.text(". ", style);
                },
                else => {},
            };
            if (b.container != null) {
                const capture = self.semantic_capture orelse return self.containerUnavailableAt("inline_container_block", "");
                if (!capture.ordinary_paragraph or self.container_handoff_suppressed or !self.interruptedBodyTargetDomain() or self.figure_caption_depth != 0 or
                    self.html_list_item_flow or self.bidi_scope_depth != 0 or self.active_bidi_capture != null or
                    style.provenance != .parsed or style.kind != .text or style.target.len != 0 or style.self_link_target != null or
                    style.code or style.preserve_whitespace or b.kind != .container or b.list_path.len != 0)
                    return self.containerUnavailableAt("inline_container_block", "");
                const pending = try self.a.create(PendingContainer);
                pending.* = .{ .owner = capture, .block = b };
                try self.spans.append(self.a, .{ .text = "", .pending_container = pending });
                continue;
            }
            if (b.figure != null or b.flow != null) return self.figureUnavailableAt("inline_structural_block", "", 0, @as(u64, @intFromBool(b.figure != null)) | (@as(u64, @intFromBool(b.flow != null)) << 1));
            try self.spans.appendSlice(self.a, b.spans);
            if (b.table) |table| try self.tableInline(table, style, false);
        }
    }
};
const Heading = struct { level: u8, title: []const u8 };
fn headingLine(line: []const u8) ?Heading {
    return headingLineControlled(line, null);
}

fn headingLineControlled(line: []const u8, matcher: ?syntax.ControlMatcher) ?Heading {
    const heading = syntax.controlHeading(line, matcher) orelse return null;
    const title = trim(heading.title);
    return .{ .level = heading.level, .title = title };
}
const CellContent = struct { text: []const u8, attrs: ?[]const u8 = null, colspan: u16 = 1, rowspan: u16 = 1, swatch_color: ?[]const u8 = null };

fn flattened(a: A, spans: []const Span) ![]u8 {
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(a);
    for (spans) |s| try out.appendSlice(a, s.text);
    return out.toOwnedSlice(a);
}
test "reference identity fast paths remain exact" {
    try std.testing.expect(referenceStringEqual("", ""));
    try std.testing.expect(referenceStringEqual("r7", "r7"));
    try std.testing.expect(!referenceStringEqual("r7", "r8"));
    try std.testing.expect(referenceStringEqual("abc", "abc"));
    try std.testing.expect(!referenceStringEqual("abc", "abd"));
    try std.testing.expect(referenceStringEqual("abcdefgh", "abcdefgh"));
    try std.testing.expect(!referenceStringEqual("abcdefgh", "abcdxfgh"));
    try std.testing.expect(referenceStringEqual("abcdefghijklmnop", "abcdefghijklmnop"));
    try std.testing.expect(!referenceStringEqual("abcdefghijklmnop", "abcdefxhijklmnop"));
    try std.testing.expect(!referenceStringEqual("same", "same!"));
}

test "renderer resolves Wiktionary definitions links labels and multiline quotations" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var r: Renderer = .{ .a = a, .context = .{ .title = "cat activation noise" } };
