        const linked_input = try std.fmt.allocPrint(a, "[[A|<{s}>&amp; [[X]]</{s}>]] [[B]]", .{ tag, tag });
        const linked = try renderer.parseSpans(linked_input, .{ .bold = true });
        try std.testing.expectEqualStrings("&amp; [[X]] B", try flattened(a, linked));
        var inherited = false;
