    };
    const Case = struct {
        source: []const u8,
        paths: []const []const u8,
        texts: []const []const u8,
        numbers: []const []const u8 = &.{},
        rich: bool = false,
        child_small: bool = false,
        literal_star: bool = false,
        inline_scope: bool = false,
        list_scope: bool = false,
        numbered_scope: bool = false,
    };
    const cases = [_]Case{
        .{ .source = "<ul><li>parent\n ordinary\n* child\n more\n</li></ul>\nafter", .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "parent  ordinary", "child", "more", "after" } },
        .{ .source = "<dl><dd>parent\n ordinary\n* child\n more\n</dd></dl>\nafter", .paths = &.{ ":", ":*", ":", "" }, .texts = &.{ "parent  ordinary", "child", "more", "after" } },
        .{ .source = "<ul lang=fr dir=rtl><li class=note><small>parent\n* [[cat|child]]\n</small>tail\n</li></ul>\nafter", .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "parent", "child", "tail", "after" }, .rich = true, .child_small = true },
        .{ .source = "<ul lang=fr dir=rtl><li class=note><small>parent</small>\n* [[cat|child]]\ntail\n</li></ul>\nafter", .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "parent", "child", "tail", "after" }, .rich = true },
        .{ .source = "<ul lang=fr dir=rtl><li class=note><small>* parent\n* [[cat|child]]\n</small>tail\n</li></ul>\nafter", .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "* parent", "child", "tail", "after" }, .rich = true, .child_small = true, .literal_star = true },
        .{ .source = "<ul lang=fr dir=rtl><li class=note>parent <small>brief</small> <span class=inner lang=de dir=ltr><small>before\n* [[cat|child]]\n</small></span>tail\n</li></ul>\nafter", .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "parent brief before", "child", "tail", "after" }, .rich = true, .child_small = true, .inline_scope = true },
        .{ .source = "<ul lang=fr dir=rtl><li class=note>parent\n* before<small>[[cat|child]]\n continuation</small> tail\n</li></ul>\nafter", .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "parent", "beforechild", "continuation tail", "after" }, .rich = true, .child_small = true, .list_scope = true },
        .{ .source = "<ul><li>parent\n# first\n# second\n# before <small>[[cat|child]]\n# fourth</small>\n# fifth\n tail\n</li></ul>\nafter", .paths = &.{ "*", "*#", "*#", "*#", "*#", "*#", "*:", "" }, .texts = &.{ "parent", "first", "second", "before child", "fourth", "fifth", "tail", "after" }, .numbers = &.{ "", "1", "2", "3", "4", "5", "", "" }, .numbered_scope = true },
        .{ .source = "<ul><li>parent\n<nowiki>\n* literal\n</nowiki>\n* child\n</li></ul>", .paths = &.{ "*", "**" }, .texts = &.{ "parent  * literal", "child" } },
        .{ .source = "<ul><li>parent\n ordinary\n</li></ul>\nafter", .paths = &.{ "*", "" }, .texts = &.{ "parent  ordinary", "after" } },
    };
    var failed_cases: usize = 0;
    for (cases, 0..) |case, case_index| {
        Check.one(a, case) catch |err| {
            std.debug.print("HTML wiki repair case {d}: {s}\n{s}\n", .{ case_index, @errorName(err), case.source });
            failed_cases += 1;
        };
    }
    try std.testing.expectEqual(@as(usize, 0), failed_cases);
}

test "etymology tree branch HTML preserves parent-first relationships through DPR2" {
    const Check = struct {
        fn shape(a: A, blocks: anytype, values: []const []const u8, paths: []const []const u8) !void {
            try std.testing.expectEqual(values.len, blocks.len);
            for (blocks, values, paths) |item, value, path| {
                try std.testing.expect(item.kind == .list_item);
                try std.testing.expectEqualStrings(path, item.list_path);
                try std.testing.expectEqual(@as(u8, @intCast(path.len)), item.depth);
                try std.testing.expectEqualStrings("", item.number);
                try std.testing.expect(item.table == null);
                try std.testing.expectEqualStrings(value, try FormattingScopeTest.text(a, item.spans));
            }
        }
        fn actions(a: A, blocks: anytype) !void {
            try FormattingScopeTest.word(a, blocks, "RootNode", .{ .kind = .link, .target = "R", .classes = "etytree-term" });
            try FormattingScopeTest.word(a, blocks, "AncestorA", .{ .kind = .link, .target = "A", .classes = "etytree-term" });
            try FormattingScopeTest.word(a, blocks, "OldestC", .{ .kind = .link, .target = "C", .language = "la", .direction = "ltr", .italic = true, .classes = "etytree-term" });
            try FormattingScopeTest.word(a, blocks, "AncestorB", .{ .kind = .link, .target = "B", .classes = "etytree-term" });
            try FormattingScopeTest.word(a, blocks, "der.", .{ .kind = .link, .target = "Appendix:Glossary#derived terms", .classes = "etytree-label" });
            try FormattingScopeTest.word(a, blocks, "lbor.", .{ .kind = .link, .target = "Appendix:Glossary#learned borrowing", .classes = "etytree-label" });
        }
        fn effects(a: A, blocks: anytype, notes: anytype, media: anytype) !void {
            try std.testing.expectEqual(@as(usize, 2), blocks.len);
            try std.testing.expectEqualStrings("*", blocks[0].list_path);
            try std.testing.expectEqualStrings("**", blocks[1].list_path);
            try std.testing.expectEqual(@as(usize, 3), notes.len);
            const bodies = [_][]const u8{ "child-note", "caption-note", "root-note" };
            for (notes, bodies) |note, body| try std.testing.expectEqualStrings(body, try FormattingScopeTest.text(a, note.spans));
            const markers = [_][]const u8{ "#reference-3", "#reference-1", "#reference-2" };
            var next: usize = 0;
            for (try FigureProducerTest.bodySpans(a, blocks)) |span| {
                if (span.role != .reference) continue;
                try std.testing.expect(next < markers.len);
                try std.testing.expectEqualStrings(markers[next], span.target);
                next += 1;
            }
            try std.testing.expectEqual(markers.len, next);
            try std.testing.expectEqual(@as(usize, 1), media.len);
            try std.testing.expectEqualStrings("Tree.svg", media[0].file);
            try std.testing.expectEqualStrings("image-caption[2]", media[0].caption);
        }
    };
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // Source-shaped oracle from Module:etymon/tree rev91079116:
    // R has ancestors A and B; A has ancestor C. The DOM is child-first.
    const source = "<div class=\"etytree-body\"><div class=\"etytree-branch-group\"><div class=\"etytree-branch\"><div class=\"etytree-block\"><i lang=\"la\" dir=\"ltr\"><span class=\"etytree-term\">[[C|OldestC]]</span></i></div><span class=\"etytree-connector-vertical\"></span><div class=\"etytree-block\"><span class=\"etytree-term\">[[A|AncestorA]]</span><span class=\"etytree-label-container\"><span class=\"etytree-label\">[[Appendix:Glossary#derived terms|<abbr title=\"edge\">der.</abbr>]]</span></span></div><span class=\"etytree-branch-left\"></span></div><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[B|AncestorB]]</span><span class=\"etytree-label-container\"><span class=\"etytree-label\">[[Appendix:Glossary#learned borrowing|<abbr title=\"edge\">lbor.</abbr>]]</span><abbr class=\"etytree-unc\" title=\"uncertain\">?</abbr></span></div><span class=\"etytree-branch-right\"></span></div></div><span class=\"etytree-connector-vertical\"></span><div class=\"etytree-block\"><span class=\"etytree-term\">[[R|RootNode]]</span></div></div>";
    const values = [_][]const u8{ "RootNode", "AncestorA der.", "OldestC", "AncestorB lbor.?" };
    const paths = [_][]const u8{ "*", "**", "***", "**" };
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const blocks = try renderer.renderBody(source);
    try Check.shape(a, blocks, &values, &paths);
    try Check.actions(a, blocks);
    try std.testing.expect(!renderer.fallbacks.any());
    const decoded = try FormattingScopeTest.encode(a, &renderer, blocks);
    try Check.shape(a, decoded.entry.sections[0].blocks, &values, &paths);
    try Check.actions(a, decoded.entry.sections[0].blocks);

    // A visible group operation belongs between the parent and its terms.
    // The hidden JSON anchor is not a second source of rendered tree content.
    var grouped: Renderer = .{ .a = a, .context = .{} };
    const grouped_blocks = try grouped.renderBody("<div class=\"etytree-body\"><div class=\"etytree-branch-group\"><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[A|GroupA]]</span></div><span class=\"etytree-branch-left\"></span></div><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[B|GroupB]]</span></div><span class=\"etytree-branch-right\"></span></div></div><span class=\"etytree-connector-vertical\"><span class=\"etytree-group-label\"><span class=\"etytree-label\"><abbr title=\"blend\">blend</abbr></span><abbr class=\"etytree-unc\" title=\"uncertain\">?</abbr></span></span><div class=\"etytree-block\"><span class=\"etytree-term\">[[R|RootNode]]</span></div></div><ul class=\"etymonid\" data-ety-tree-json=\"{&quot;term&quot;:&quot;HIDDEN&quot;,&quot;children&quot;:[]}\"></ul>");
    const group_values = [_][]const u8{ "RootNode", "blend?", "GroupA", "GroupB" };
    const group_paths = [_][]const u8{ "*", "**", "***", "***" };
    try Check.shape(a, grouped_blocks, &group_values, &group_paths);
    const grouped_decoded = try FormattingScopeTest.encode(a, &grouped, grouped_blocks);
    try Check.shape(a, grouped_decoded.entry.sections[0].blocks, &group_values, &group_paths);
    try std.testing.expect(!grouped.fallbacks.any());

    // Parse content once in original DOM order, although list nodes are reordered.
    var effects_renderer: Renderer = .{ .a = a, .context = try FigureProducerTest.context(a) };
    const effect_blocks = try effects_renderer.renderBody("<div class=\"etytree-body\"><div class=\"etytree-block\">child<ref>child-note</ref> [[File:Tree.svg|thumb|image-caption<ref>caption-note</ref>]]</div><span class=\"etytree-connector-vertical\"></span><div class=\"etytree-block\">root<ref>root-note</ref></div></div>");
    const references = try effects_renderer.finishReferences();
    try Check.effects(a, effect_blocks, references, effects_renderer.media.items);
    try std.testing.expectEqual(@as(usize, 1), try FigureProducerTest.countFigures(effect_blocks));
    try std.testing.expectEqual(effects_renderer.media.items.len, effects_renderer.media_caption_spans.items.len);
    const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
    const sections = [_]Section{.{ .blocks = effect_blocks }};
    const blob = @import("blob_encoder");
    const encoded = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, references, effects_renderer.media.items);
    const effect_decoded = try blob.presentation_codec.decodeAlloc(a, encoded, "etymology tree", .language, .{ .code = "en", .heading = "English" });
    try Check.effects(a, effect_decoded.entry.sections[0].blocks, effect_decoded.entry.references, effect_decoded.entry.media);
    try std.testing.expectEqual(@as(usize, 1), try FigureProducerTest.countFigures(effect_decoded.entry.sections[0].blocks));
    try std.testing.expectEqualSlices(u8, encoded, try blob.presentation_codec.encodeAlloc(a, effect_decoded));
    try std.testing.expect(!effects_renderer.fallbacks.any());

    // Missing connectors are not evidence of an edge. Validation has no effects,
    // and the ordinary fallback must register each authored reference just once.
    var malformed: Renderer = .{ .a = a, .context = .{} };
    const malformed_blocks = try malformed.renderBody("<div class=\"etytree-body\"><div class=\"etytree-block\">first<ref>first-note</ref></div><div class=\"etytree-block\">second<ref>second-note</ref></div></div>");
    const malformed_refs = try malformed.finishReferences();
    try std.testing.expectEqual(@as(usize, 2), malformed_refs.len);
    try std.testing.expectEqualStrings("first-note", try FormattingScopeTest.text(a, malformed_refs[0].spans));
    try std.testing.expectEqualStrings("second-note", try FormattingScopeTest.text(a, malformed_refs[1].spans));
    for (malformed_blocks) |item| try std.testing.expect(item.kind != .list_item);
    try std.testing.expect(!malformed.fallbacks.any());

    // A duplicate/hidden-ancestry arrow is visible, not invented ancestry.
    var duplicate_renderer: Renderer = .{ .a = a, .context = .{} };
    const duplicate_blocks = try duplicate_renderer.renderBody("<div class=\"etytree-body\"><div class=\"etytree-duplicate-connector\"><div><span class=\"etytree-dup-right\"></span><span class=\"etytree-dup-horiz\"></span><span class=\"etytree-dup-left\"></span><span class=\"etytree-dup-arrow\">▲</span></div></div><div class=\"etytree-block\"><span class=\"etytree-term\">[[R|RootNode]]</span></div></div>");
    try Check.shape(a, duplicate_blocks, &.{"▲ RootNode"}, &.{"*"});
    const duplicate_decoded = try FormattingScopeTest.encode(a, &duplicate_renderer, duplicate_blocks);
    try Check.shape(a, duplicate_decoded.entry.sections[0].blocks, &.{"▲ RootNode"}, &.{"*"});
    try std.testing.expect(!duplicate_renderer.fallbacks.any());

    // Multiple containers can contain a labelled group or an unlabelled forest.
    // No term is invented for the container; the shared outer parent owns it.
    var nested_renderer: Renderer = .{ .a = a, .context = .{} };
    const nested_blocks = try nested_renderer.renderBody("<div class=\"etytree-body\"><div class=\"etytree-branch-group\"><div class=\"etytree-branch\"><div class=\"etytree-branch-group\"><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[A|A]]</span></div><span class=\"etytree-branch-left\"></span></div><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[B|B]]</span></div><span class=\"etytree-branch-right\"></span></div></div><span class=\"etytree-connector-vertical\"><span class=\"etytree-group-label\">blend?</span></span><span class=\"etytree-branch-left\"></span></div><div class=\"etytree-branch\"><div class=\"etytree-branch-group\"><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[C|C]]</span></div><span class=\"etytree-branch-left\"></span></div><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[D|D]]</span></div><span class=\"etytree-branch-right\"></span></div></div><span class=\"etytree-connector-vertical\"></span><span class=\"etytree-connector-vertical-short\"></span><span class=\"etytree-branch-mid\"></span></div><div class=\"etytree-branch\"><div class=\"etytree-block\"><span class=\"etytree-term\">[[E|E]]</span></div><span class=\"etytree-branch-right\"></span></div></div><span class=\"etytree-connector-vertical\"></span><div class=\"etytree-block\"><span class=\"etytree-term\">[[R|R]]</span></div></div>");
    const nested_values = [_][]const u8{ "R", "blend?", "A", "B", "C", "D", "E" };
    const nested_paths = [_][]const u8{ "*", "**", "***", "***", "**", "**", "**" };
    try Check.shape(a, nested_blocks, &nested_values, &nested_paths);
    const nested_decoded = try FormattingScopeTest.encode(a, &nested_renderer, nested_blocks);
    try Check.shape(a, nested_decoded.entry.sections[0].blocks, &nested_values, &nested_paths);
    for ([_][]const u8{ "R", "A", "B", "C", "D", "E" }) |value| {
        try FormattingScopeTest.word(a, nested_blocks, value, .{ .kind = .link, .target = value, .classes = "etytree-term" });
        try FormattingScopeTest.word(a, nested_decoded.entry.sections[0].blocks, value, .{ .kind = .link, .target = value, .classes = "etytree-term" });
    }
    try std.testing.expect(!nested_renderer.fallbacks.any());

    // A rejected geometry check must not resolve effectful class semantics.
    var pure_renderer: Renderer = .{ .a = a, .context = .{} };
    var pure_hints: SemanticHints = .{};
    pure_renderer.semantic_capture = &pure_hints;
    var pure_plan: Renderer.EtymologyTreePlan = .{ .renderer = &pure_renderer };
    try std.testing.expect((try pure_plan.sequence("<div class=\"etytree-block nyms scribunto-error\">first</div><div class=\"etytree-block\">second</div>", &.{}, 0, false)) == null);
    try std.testing.expect(!pure_hints.relation_note);
    try std.testing.expect(!pure_renderer.fallbacks.any());

    // Class hints are captured on the accepted node, without leaking to its
    // parent or a later ordinary paragraph in the same renderer.
    var hinted: Renderer = .{ .a = a, .context = .{} };
    const hinted_blocks = try hinted.renderBody("<div class=\"etytree-body\"><div class=\"etytree-block nyms scribunto-error\">child</div><span class=\"etytree-connector-vertical\"></span><div class=\"etytree-block\">parent</div></div>\n\nplain");
    try std.testing.expectEqual(@as(usize, 3), hinted_blocks.len);
    try std.testing.expect(!hinted_blocks[0].relation_note);
    try std.testing.expect(hinted_blocks[1].relation_note);
    try std.testing.expect(!hinted_blocks[2].relation_note);
    try std.testing.expect(hinted.fallbacks.rendered_lua_error);
    try std.testing.expect(hinted.semantic_capture == null);
}

test "blockquote indentation remains ordinary flow with protected and outside boundaries through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Case = struct { source: []const u8, kinds: []const []const u8, paths: []const []const u8, texts: []const []const u8, rich: bool = false };
    const Check = struct {
        fn shape(alloc: A, blocks: anytype, case: Case) !void {
            try std.testing.expectEqual(case.kinds.len, blocks.len);
            for (blocks, case.kinds, case.paths, case.texts) |value, kind, path, visible| {
                try std.testing.expectEqualStrings(kind, @tagName(value.kind));
                try std.testing.expectEqualStrings(path, value.list_path);
                try std.testing.expectEqualStrings(visible, trim(try FormattingScopeTest.text(alloc, value.spans)));
                try std.testing.expect(value.table == null);
                if (value.kind == .heading) try std.testing.expectEqual(@as(u8, 2), value.level);
                if (value.kind != .preformatted) for (value.spans) |span| {
                    const code = if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code;
                    try std.testing.expect(!code);
                };
            }
            try FormattingScopeTest.word(alloc, blocks, "quoted", if (case.rich) .{ .font_scale = 1.0 / 1.2, .font_scale_set = true, .language = "fr", .direction = "rtl" } else .{});
            try FormattingScopeTest.word(alloc, blocks, "outside", .{ .code = true });
        }
        fn one(alloc: A, case: Case) !void {
            var renderer: Renderer = .{ .a = alloc, .context = .{} };
            const blocks = try renderer.renderBody(case.source);
            try @This().shape(alloc, blocks, case);
            const stored = try FormattingScopeTest.encode(alloc, &renderer, blocks);
            try @This().shape(alloc, stored.entry.sections[0].blocks, case);
            if (@hasField(Renderer, "html_blockquote_flow")) try std.testing.expect(!renderer.html_blockquote_flow);
            try std.testing.expect(!renderer.html_list_item_flow);
            try std.testing.expect(!renderer.fallbacks.any());
        }
    };
    // Nested ordinary containers inherit the quote context. Nested explicit
    // quotes are checked before their closer, without claiming legacy lexical
    // boolean parity for an indented continuation after an inner quote closes.
    const cases = [_]Case{
        .{ .source = "<blockquote>\n quoted\n</blockquote>\n outside", .kinds = &.{ "paragraph", "preformatted" }, .paths = &.{ "", "" }, .texts = &.{ "quoted", "outside" } },
        .{ .source = "<blockquote lang=fr dir=rtl>\n<div><small>\n quoted\n</small></div>\n</blockquote>\n outside", .kinds = &.{ "paragraph", "preformatted" }, .paths = &.{ "", "" }, .texts = &.{ "quoted", "outside" }, .rich = true },
        .{ .source = "<blockquote>\n; term : detail\n: continuation\n quoted\n</blockquote>\n outside", .kinds = &.{ "term", "list_detail", "indent", "paragraph", "preformatted" }, .paths = &.{ ";", ":", ":", "", "" }, .texts = &.{ "term", "detail", "continuation", "quoted", "outside" } },
        .{ .source = "<blockquote>\n <nowiki># quoted <!-- literal --></nowiki>\n\n next\n</blockquote>\n outside", .kinds = &.{ "paragraph", "paragraph", "preformatted" }, .paths = &.{ "", "", "" }, .texts = &.{ "# quoted <!-- literal -->", "next", "outside" } },
        .{ .source = "<blockquote>\n quoted\n\n<pre>* protected</pre>\n</blockquote>\n outside", .kinds = &.{ "paragraph", "preformatted", "preformatted" }, .paths = &.{ "", "", "" }, .texts = &.{ "quoted", "* protected", "outside" } },
        .{ .source = "<blockquote>outer\n\n<blockquote>\n quoted\n</blockquote>\n</blockquote>\n outside", .kinds = &.{ "paragraph", "paragraph", "preformatted" }, .paths = &.{ "", "", "" }, .texts = &.{ "outer", "quoted", "outside" } },
        .{ .source = "<blockquote>\n <nowiki>== literal ==</nowiki>\n\n== Actual ==\n quoted\n</blockquote>\n outside", .kinds = &.{ "paragraph", "heading", "paragraph", "preformatted" }, .paths = &.{ "", "", "", "" }, .texts = &.{ "== literal ==", "Actual", "quoted", "outside" } },
    };
    var failed_cases: usize = 0;
    for (cases, 0..) |case, index| {
        Check.one(a, case) catch |err| {
            std.debug.print("blockquote indent case {d}: {s}\n{s}\n", .{ index, @errorName(err), case.source });
            failed_cases += 1;
        };
    }
    try std.testing.expectEqual(@as(usize, 0), failed_cases);
}

test "inline block containers retain physical list ownership and protected boundaries through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Case = struct { source: []const u8, kinds: []const []const u8, paths: []const []const u8, texts: []const []const u8, rich: bool = false, has_word: bool = false };
    const Check = struct {
        fn shape(alloc: A, values: anytype, case: Case) !void {
            try std.testing.expectEqual(case.kinds.len, values.len);
            var links: usize = 0;
            for (values, case.kinds, case.paths, case.texts) |value, kind, path, visible| {
                try std.testing.expectEqualStrings(kind, @tagName(value.kind));
                try std.testing.expectEqualStrings(path, value.list_path);
                try std.testing.expectEqualStrings(visible, trim(try FormattingScopeTest.text(alloc, value.spans)));
                if (value.kind == .definition) try std.testing.expectEqualStrings("1", value.number);
                for (value.spans) |span| {
                    const code = if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code;
                    try std.testing.expectEqual(value.kind == .preformatted, code);
                }
                for (value.spans) |span| if (span.kind == .link) {
                    links += 1;
                    try std.testing.expectEqualStrings("cat", span.target);
                    try std.testing.expectEqualStrings("word", span.text);
                };
            }
            try std.testing.expectEqual(@as(usize, @intFromBool(case.has_word)), links);
            if (case.has_word) try FormattingScopeTest.word(alloc, values, "word", if (case.rich) .{ .kind = .link, .target = "cat", .language = "fr", .direction = "rtl" } else .{ .kind = .link, .target = "cat" });
            if (case.rich) {
                try FormattingScopeTest.word(alloc, values, "brief", .{ .font_scale = 1.0 / 1.2, .font_scale_set = true });
                try FormattingScopeTest.word(alloc, values, "after", .{});
            }
        }
        fn one(alloc: A, case: Case) !void {
            var renderer: Renderer = .{ .a = alloc, .context = .{} };
            const values = try renderer.renderBody(case.source);
            try @This().shape(alloc, values, case);
            const stored = try FormattingScopeTest.encode(alloc, &renderer, values);
            try @This().shape(alloc, stored.entry.sections[0].blocks, case);
            try std.testing.expect(!renderer.html_blockquote_flow and !renderer.html_list_item_flow);
            try std.testing.expect(!renderer.fallbacks.any());
        }
    };
    const cases = [_]Case{
        .{ .source = "before<blockquote>\n# [[cat|word]]\n</blockquote>suffix\n# outside", .kinds = &.{ "paragraph", "definition", "paragraph", "definition" }, .paths = &.{ "", "#", "", "#" }, .texts = &.{ "before", "word", "suffix", "outside" }, .has_word = true },
        .{ .source = "before<blockquote># literal opener\n# real\n</blockquote># literal suffix\n# outside", .kinds = &.{ "paragraph", "paragraph", "definition", "paragraph", "definition" }, .paths = &.{ "", "", "#", "", "#" }, .texts = &.{ "before", "# literal opener", "real", "# literal suffix", "outside" } },
        .{ .source = "before<blockquote>\n<nowiki># literal</nowiki>\n# real\n</blockquote>after", .kinds = &.{ "paragraph", "paragraph", "definition", "paragraph" }, .paths = &.{ "", "", "#", "" }, .texts = &.{ "before", "# literal", "real", "after" } },
        .{ .source = "<nowiki><blockquote># literal</blockquote></nowiki>\n# outside", .kinds = &.{ "paragraph", "definition" }, .paths = &.{ "", "#" }, .texts = &.{ "<blockquote># literal</blockquote>", "outside" } },
        .{ .source = "before<blockquote>\n quoted\n</blockquote>\n outside", .kinds = &.{ "paragraph", "paragraph", "preformatted" }, .paths = &.{ "", "", "" }, .texts = &.{ "before", "quoted", "outside" } },
        .{ .source = "before <small>brief</small><blockquote lang=fr dir=rtl>\n# [[cat|word]]\n</blockquote>after", .kinds = &.{ "paragraph", "definition", "paragraph" }, .paths = &.{ "", "#", "" }, .texts = &.{ "before brief", "word", "after" }, .rich = true, .has_word = true },
        .{ .source = "<blockquote>outer\n<blockquote>inner</blockquote>\n continuation\n</blockquote>\n outside", .kinds = &.{ "paragraph", "paragraph", "preformatted", "preformatted" }, .paths = &.{ "", "", "", "" }, .texts = &.{ "outer", "inner", "continuation", "outside" } },
        .{ .source = "<blockquote>outer\n<div><blockquote>inner</blockquote></div>\n continuation\n</blockquote>\n outside", .kinds = &.{ "paragraph", "paragraph", "preformatted", "preformatted" }, .paths = &.{ "", "", "", "" }, .texts = &.{ "outer", "inner", "continuation", "outside" } },
        .{ .source = "<blockquote>outer<blockquote>inner</blockquote>\n continuation\n</blockquote>\n outside", .kinds = &.{ "paragraph", "paragraph", "preformatted", "preformatted" }, .paths = &.{ "", "", "", "" }, .texts = &.{ "outer", "inner", "continuation", "outside" } },
        .{ .source = "before<blockquote>quote</blockquote>after", .kinds = &.{ "paragraph", "paragraph", "paragraph" }, .paths = &.{ "", "", "" }, .texts = &.{ "before", "quote", "after" } },
        .{ .source = "before<div>\n# [[cat|word]]\n</div>suffix\n# outside", .kinds = &.{ "paragraph", "definition", "paragraph", "definition" }, .paths = &.{ "", "#", "", "#" }, .texts = &.{ "before", "word", "suffix", "outside" }, .has_word = true },
        .{ .source = "before<div>division</div>after", .kinds = &.{ "paragraph", "paragraph", "paragraph" }, .paths = &.{ "", "", "" }, .texts = &.{ "before", "division", "after" } },
        .{ .source = "before<p>paragraph</p>after", .kinds = &.{ "paragraph", "paragraph", "paragraph" }, .paths = &.{ "", "", "" }, .texts = &.{ "before", "paragraph", "after" } },
        .{ .source = "before<center>centered</center>after", .kinds = &.{ "paragraph", "paragraph", "paragraph" }, .paths = &.{ "", "", "" }, .texts = &.{ "before", "centered", "after" } },
        .{ .source = "<nowiki><div># literal</div></nowiki>\n# outside", .kinds = &.{ "paragraph", "definition" }, .paths = &.{ "", "#" }, .texts = &.{ "<div># literal</div>", "outside" } },
        .{ .source = "before <small>brief</small><div lang=fr dir=rtl>\n# [[cat|word]]\n</div>after", .kinds = &.{ "paragraph", "definition", "paragraph" }, .paths = &.{ "", "#", "" }, .texts = &.{ "before brief", "word", "after" }, .rich = true, .has_word = true },
    };
    var failed_cases: usize = 0;
    for (cases, 0..) |case, index| {
        Check.one(a, case) catch |err| {
            std.debug.print("inline block container case {d}: {s}\n{s}\n", .{ index, @errorName(err), case.source });
            failed_cases += 1;
        };
    }
    try std.testing.expectEqual(@as(usize, 0), failed_cases);
}

test "matched HTML headings preserve typed levels links styles and same-line suffix through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    for (1..7) |level| {
        const source = try std.fmt.allocPrint(a, "alpha<h{d} class=note lang=fr dir=rtl>[[A|beta]]</h{d}>gamma", .{ level, level });
        var r: Renderer = .{ .a = a, .context = .{} };
        const blocks = try r.renderBody(source);
        const saved = try FormattingScopeTest.encode(a, &r, blocks);
        inline for (.{ blocks, saved.entry.sections[0].blocks }) |actual| {
            try std.testing.expectEqual(@as(usize, 3), actual.len);
            try std.testing.expectEqualStrings("paragraph", @tagName(actual[0].kind));
            try std.testing.expectEqualStrings("heading", @tagName(actual[1].kind));
            try std.testing.expectEqualStrings("paragraph", @tagName(actual[2].kind));
            try std.testing.expectEqual(@as(u8, @intCast(level)), actual[1].level);
            try std.testing.expectEqualStrings("alpha", try FormattingScopeTest.text(a, actual[0].spans));
            try std.testing.expectEqualStrings("beta", try FormattingScopeTest.text(a, actual[1].spans));
            try std.testing.expectEqualStrings("gamma", try FormattingScopeTest.text(a, actual[2].spans));
            try FormattingScopeTest.word(a, actual, "beta", .{ .kind = .link, .target = "A", .classes = "note", .language = "fr", .direction = "rtl" });
            try FormattingScopeTest.word(a, actual, "alpha", .{});
            try FormattingScopeTest.word(a, actual, "gamma", .{});
        }
        try std.testing.expect(!r.fallbacks.any());
    }
    // Ordinary physical newlines inside HTML headings stay in the same
    // supported heading domain. This does not assert colon/list semantics.
    for (1..7) |level| {
        const source = try std.fmt.allocPrint(a, "alpha<h{d} class=note lang=fr dir=rtl>[[A|beta]]\n''[[B|delta]]''</h{d}>gamma", .{ level, level });
        var r: Renderer = .{ .a = a, .context = .{} };
        const blocks = try r.renderBody(source);
        const saved = try FormattingScopeTest.encode(a, &r, blocks);
        inline for (.{ blocks, saved.entry.sections[0].blocks }) |actual| {
            try std.testing.expectEqual(@as(usize, 3), actual.len);
            try std.testing.expectEqualStrings("paragraph", @tagName(actual[0].kind));
            try std.testing.expectEqualStrings("heading", @tagName(actual[1].kind));
            try std.testing.expectEqualStrings("paragraph", @tagName(actual[2].kind));
            try std.testing.expectEqual(@as(u8, @intCast(level)), actual[1].level);
            try std.testing.expectEqualStrings("alpha", try FormattingScopeTest.text(a, actual[0].spans));
            try std.testing.expectEqualStrings("beta delta", try FormattingScopeTest.text(a, actual[1].spans));
            try std.testing.expectEqualStrings("gamma", try FormattingScopeTest.text(a, actual[2].spans));
            try FormattingScopeTest.word(a, actual, "beta", .{ .kind = .link, .target = "A", .classes = "note", .language = "fr", .direction = "rtl" });
            try FormattingScopeTest.word(a, actual, "delta", .{ .kind = .link, .target = "B", .classes = "note", .language = "fr", .direction = "rtl", .italic = true });
            try FormattingScopeTest.word(a, actual, "alpha", .{});
            try FormattingScopeTest.word(a, actual, "gamma", .{});
        }
        try std.testing.expect(!r.fallbacks.any());
    }
    const suffixes = [_][]const u8{ "* tail", "==tail==", "{| tail" };
    for (suffixes) |suffix| {
        const source = try std.fmt.allocPrint(a, "<H3>[[A|beta]]</H3>{s}", .{suffix});
        var r: Renderer = .{ .a = a, .context = .{} };
        const blocks = try r.renderBody(source);
        const saved = try FormattingScopeTest.encode(a, &r, blocks);
        inline for (.{ blocks, saved.entry.sections[0].blocks }) |actual| {
            try std.testing.expectEqual(@as(usize, 2), actual.len);
            try std.testing.expectEqualStrings("heading", @tagName(actual[0].kind));
            try std.testing.expectEqual(@as(u8, 3), actual[0].level);
            try std.testing.expectEqualStrings("paragraph", @tagName(actual[1].kind));
            try std.testing.expectEqualStrings(suffix, try FormattingScopeTest.text(a, actual[1].spans));
            try FormattingScopeTest.word(a, actual, "beta", .{ .kind = .link, .target = "A" });
        }
        try std.testing.expect(!r.fallbacks.any());
    }
}

test "HTML headings stay within protected and link-label owners through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const sources = [_][]const u8{
        "<nowiki><h3>literal</h3></nowiki>",
        "<pre><h3>literal</h3></pre>",
        "[[A|<h3>label</h3>]]",
        "[https://example.org <h3>label</h3>]",
        "<div><h2>[[A|beta]]</h2>gamma</div>",
    };
    for (sources, 0..) |source, index| {
        var r: Renderer = .{ .a = a, .context = .{} };
        const blocks = try r.renderBody(source);
        const saved = try FormattingScopeTest.encode(a, &r, blocks);
        inline for (.{ blocks, saved.entry.sections[0].blocks }) |actual| {
            var headings: usize = 0;
            for (actual) |block_value| {
                if (std.mem.eql(u8, @tagName(block_value.kind), "heading")) {
                    headings += 1;
                    try std.testing.expectEqual(@as(u8, 2), block_value.level);
                    try std.testing.expectEqualStrings("beta", try FormattingScopeTest.text(a, block_value.spans));
                }
            }
            try std.testing.expectEqual(@as(usize, if (index == 4) 1 else 0), headings);
            if (index < 2) try std.testing.expectEqualStrings("<h3>literal</h3>", try FormattingScopeTest.text(a, actual[0].spans));
            if (index == 2) try FormattingScopeTest.word(a, actual, "label", .{ .kind = .link, .target = "A" });
            if (index == 3) try FormattingScopeTest.word(a, actual, "label", .{ .kind = .external_link, .target = "https://example.org" });
        }
        try std.testing.expect(!r.fallbacks.any());
    }
}

test "HTML item ordinary containers retain nested wiki lists and protected ownership through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Case = struct { source: []const u8, kinds: []const []const u8, paths: []const []const u8, texts: []const []const u8, numbers: []const []const u8 = &.{}, rich: bool = false, external: bool = false, literal_markup: bool = false };
    const Check = struct {
        fn shape(alloc: A, values: anytype, case: Case) !void {
            try std.testing.expectEqual(case.kinds.len, values.len);
            var links: usize = 0;
            for (values, case.kinds, case.paths, case.texts, 0..) |value, kind, path, visible, index| {
                try std.testing.expectEqualStrings(kind, @tagName(value.kind));
                try std.testing.expectEqualStrings(path, value.list_path);
                try std.testing.expectEqual(@as(u8, @intCast(path.len)), value.depth);
                try std.testing.expectEqualStrings(if (case.numbers.len == 0) "" else case.numbers[index], value.number);
                try std.testing.expectEqualStrings(visible, trim(try FormattingScopeTest.text(alloc, value.spans)));
                try std.testing.expect(value.table == null);
                for (value.spans) |span| {
                    const code = if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code;
                    try std.testing.expect(!code);
                    if (span.kind == .link or span.kind == .external_link) {
                        links += 1;
                        try std.testing.expectEqualStrings(if (case.external) "external_link" else "link", @tagName(span.kind));
                        try std.testing.expectEqualStrings(if (case.external) "https://example.org" else "cat", span.target);
                        try std.testing.expectEqualStrings(if (case.external) "https://example.org" else "child", span.text);
                    }
                }
            }
            try std.testing.expectEqual(@as(usize, @intFromBool(case.rich or case.external)), links);
            if (case.rich) {
                try FormattingScopeTest.word(alloc, values, "parent", .{ .language = "fr", .direction = "rtl", .classes = "note" });
                try FormattingScopeTest.word(alloc, values, "child", .{ .kind = .link, .target = "cat", .font_scale = 1.0 / 1.2, .font_scale_set = true, .language = "de", .direction = "ltr", .classes = "note" });
                try FormattingScopeTest.word(alloc, values, "tail", .{ .language = "fr", .direction = "rtl", .classes = "note" });
                try FormattingScopeTest.word(alloc, values, "after", .{});
            }
        }
        fn one(alloc: A, case: Case) !void {
            var renderer: Renderer = .{ .a = alloc, .context = .{} };
            var check_stage: []const u8 = "render";
            errdefer std.debug.print("nested item assertion stage={s} fallback_flags={any}\n", .{ check_stage, renderer.fallbacks });
            const values = try renderer.renderBody(case.source);
            check_stage = "native shape";
            try @This().shape(alloc, values, case);
            check_stage = "encode";
            const stored = try FormattingScopeTest.encode(alloc, &renderer, values);
            check_stage = "decoded shape";
            try @This().shape(alloc, stored.entry.sections[0].blocks, case);
            check_stage = "exact fallback flags";
            try std.testing.expectEqualDeep(@as(@TypeOf(renderer.fallbacks), .{ .literal_markup = case.literal_markup }), renderer.fallbacks);
            check_stage = "restored state";
            try std.testing.expect(!renderer.html_list_item_flow and !renderer.html_blockquote_flow);
            try std.testing.expectEqualStrings("", renderer.body_formatting_attributes.classes);
            try std.testing.expect(renderer.body_language_direction == null);
            try std.testing.expectEqual(@as(u8, 0), @as(u8, @bitCast(renderer.block_formatting)));
        }
        fn protectedShape(alloc: A, values: anytype, visible: []const u8) !void {
            try std.testing.expectEqual(@as(usize, 2), values.len);
            try std.testing.expectEqualStrings("list_item", @tagName(values[0].kind));
            try std.testing.expectEqualStrings("*", values[0].list_path);
            // Soft line breaks inside a literal are not a list boundary.
            var words = std.mem.tokenizeAny(u8, try FormattingScopeTest.text(alloc, values[0].spans), " \t\r\n");
            var normalized: std.ArrayList(u8) = .empty;
            while (words.next()) |word| {
                if (normalized.items.len != 0) try normalized.append(alloc, ' ');
                try normalized.appendSlice(alloc, word);
            }
            try std.testing.expectEqualStrings(visible, normalized.items);
            try std.testing.expectEqualStrings("paragraph", @tagName(values[1].kind));
            try std.testing.expectEqualStrings("after", trim(try FormattingScopeTest.text(alloc, values[1].spans)));
            for (values) |value| for (value.spans) |span| try std.testing.expect(span.kind != .link);
        }
        fn protectedOne(alloc: A, source: []const u8, visible: []const u8) !void {
            var renderer: Renderer = .{ .a = alloc, .context = .{} };
            const values = try renderer.renderBody(source);
            try @This().protectedShape(alloc, values, visible);
            const stored = try FormattingScopeTest.encode(alloc, &renderer, values);
            try @This().protectedShape(alloc, stored.entry.sections[0].blocks, visible);
            try std.testing.expect(!renderer.fallbacks.any());
        }
    };
    var failed_cases: usize = 0;
    var case_index: usize = 0;
    // The same physical-line admission must work in every supported ordinary
    // container and under unordered, ordered and definition-detail ownership.
    for ([_][]const u8{ "div", "blockquote", "p", "center" }) |tag| {
        const cases = [_]Case{
            .{ .source = try std.fmt.allocPrint(a, "<ul><li>parent<{s}>\n* child\n</{s}>tail</li></ul>\nafter", .{ tag, tag }), .kinds = &.{ "list_item", "list_item", "list_detail", "paragraph" }, .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "parent", "child", "tail", "after" } },
            .{ .source = try std.fmt.allocPrint(a, "<ol><li>parent<{s}>\n# first\n# second\n</{s}>tail</li></ol>\nafter", .{ tag, tag }), .kinds = &.{ "list_item", "definition", "definition", "list_detail", "paragraph" }, .paths = &.{ "#", "##", "##", "#:", "" }, .texts = &.{ "parent", "first", "second", "tail", "after" }, .numbers = &.{ "1", "1", "2", "", "" } },
            .{ .source = try std.fmt.allocPrint(a, "<dl><dt>term</dt><dd>parent<{s}>\n* child\n</{s}>tail</dd><dd>nextdetail</dd></dl>\nafter", .{ tag, tag }), .kinds = &.{ "term", "list_detail", "list_item", "list_detail", "list_detail", "paragraph" }, .paths = &.{ ";", ":", ":*", ":", ":", "" }, .texts = &.{ "term", "parent", "child", "tail", "nextdetail", "after" } },
        };
        for (cases) |case| {
            Check.one(a, case) catch |err| {
                std.debug.print("nested item container case {d}: {s}\n{s}\n", .{ case_index, @errorName(err), case.source });
                failed_cases += 1;
            };
            case_index += 1;
        }
    }
    const edges = [_]Case{
        .{ .source = "<ul><li>parent<div>[https://example.org label\n* fake]</div>tail</li></ul>\nafter", .kinds = &.{ "list_item", "list_detail", "list_item", "list_detail", "paragraph" }, .paths = &.{ "*", "*:", "**", "*:", "" }, .texts = &.{ "parent", "[https://example.org label", "fake]", "tail", "after" }, .external = true, .literal_markup = true },
        .{ .source = "<ul><li>parent<div>* literal opener\n* child\n</div>tail</li></ul>\nafter", .kinds = &.{ "list_item", "list_detail", "list_item", "list_detail", "paragraph" }, .paths = &.{ "*", "*:", "**", "*:", "" }, .texts = &.{ "parent", "* literal opener", "child", "tail", "after" } },
        .{ .source = "<ul><li>parent<div>brief</div><center>\n* child\n</center>tail</li></ul>\nafter", .kinds = &.{ "list_item", "list_detail", "list_item", "list_detail", "paragraph" }, .paths = &.{ "*", "*:", "**", "*:", "" }, .texts = &.{ "parent", "brief", "child", "tail", "after" } },
        .{ .source = "<ul><li>parent<div><!--\n* hidden\n-->\n* child\n</div>tail</li></ul>\nafter", .kinds = &.{ "list_item", "list_item", "list_detail", "paragraph" }, .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "parent", "child", "tail", "after" } },
        .{ .source = "<ul lang=fr dir=rtl><li class=note>parent<div lang=de dir=ltr><small>\n* [[cat|child]]\n</small></div>tail</li></ul>\nafter", .kinds = &.{ "list_item", "list_item", "list_detail", "paragraph" }, .paths = &.{ "*", "**", "*:", "" }, .texts = &.{ "parent", "child", "tail", "after" }, .rich = true },
    };
    for (edges) |case| {
        Check.one(a, case) catch |err| {
            std.debug.print("nested item container case {d}: {s}\n{s}\n", .{ case_index, @errorName(err), case.source });
            failed_cases += 1;
        };
        case_index += 1;
    }
    const protected_cases = .{
        .{ "<ul><li>parent<div><nowiki>\n* [[cat|literal]]\n</nowiki></div>tail</li></ul>\nafter", "parent * [[cat|literal]] tail" },
        .{ "<ul><li>parent<div><!--\n* hidden\n--></div>tail</li></ul>\nafter", "parent tail" },
    };
    inline for (protected_cases) |case| {
        Check.protectedOne(a, case[0], case[1]) catch |err| {
            std.debug.print("nested item protected case {d}: {s}\n{s}\n", .{ case_index, @errorName(err), case[0] });
            failed_cases += 1;
        };
        case_index += 1;
    }
    // Protected/link owners retain their internal markers. An external LF
    // ends bracketed-label ownership, as the pinned official fixture shows.
    for ([_][]const u8{
        "parent<div><nowiki>\n* fake\n</nowiki></div>tail",
        "parent<div><pre>\n* fake\n</pre></div>tail",
        "parent<div><!--\n* fake\n--></div>tail",
        "parent<div>[[cat|label\n* fake]]</div>tail",
        "parent<div>[https://example.org label\n* fake]</div>tail",
        "parent<div>{{template|\n* fake}}</div>tail",
        "parent<div><ul><li>\n* independently owned\n</li></ul></div>tail",
        "parent<div>* literal same line</div>tail",
    }, 0..) |input, index| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const admitted = try renderer.htmlListItemHasBodyBlocks(input);
        if (admitted != (index == 4)) {
            std.debug.print("unexpected nested item admission {d}: {s}\n", .{ case_index, input });
            failed_cases += 1;
        }
        case_index += 1;
    }
    try std.testing.expectEqual(@as(usize, 27), case_index);
    try std.testing.expectEqual(@as(usize, 0), failed_cases);
}

test "unresolved external action destinations retain clean labels and reject bare source" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    for ([_][]const u8{
        "https://dsal.uchicago.edu/cgi-bin/app/caturvedi_query.py?page={{{page=}}}",
        "https://hindwidictionary.com/search?keyword={{#urlencode:शारदा}}",
        "https://example.test/?q={{missing}}",
    }) |target| {
        var r: Renderer = .{ .a = a, .context = .{} };
        try r.link("<b>page <i>741</i></b>", target, .{ .kind = .link, .target = "old-parent", .language = "hi", .direction = "rtl", .small = true, .role = .example }, 0, true);
        try std.testing.expectEqualStrings("page 741", try plainText(a, r.spans.items));
        for (r.spans.items) |span| {
            try std.testing.expectEqual(ir.InlineKind.text, span.kind);
            try std.testing.expectEqualStrings("", span.target);
            try std.testing.expect(span.flags.bold and span.flags.small);
            try std.testing.expectEqualStrings("hi", span.language);
            try std.testing.expectEqualStrings("rtl", span.direction);
            try std.testing.expect(span.role == .example);
            if (std.mem.eql(u8, span.text, "741")) try std.testing.expect(span.flags.italic);
        }
        try std.testing.expect(r.fallbacks.rejected_external_target);
        try std.testing.expectEqual(@as(usize, 0), r.unresolved_templates);
        var bare: Renderer = .{ .a = a, .context = .{} };
        try std.testing.expectError(error.UncompiledTemplate, bare.link(target, target, .{}, 0, true));
    }
    for ([_][]const u8{ "<nowiki>{{literal}}</nowiki>", "<code>&#123;&#123;literal&#125;&#125;</code>" }) |label| {
        var r: Renderer = .{ .a = a, .context = .{} };
        try r.link(label, "https://example.test/?q={{missing}}", .{}, 0, true);
        try std.testing.expectEqualStrings("{{literal}}", try plainText(a, r.spans.items));
        for (r.spans.items) |span| {
            try std.testing.expectEqual(ir.InlineKind.text, span.kind);
            try std.testing.expectEqualStrings("", span.target);
            if (std.mem.indexOfAny(u8, span.text, "{}") != null)
                try std.testing.expect(span.provenance != .parsed);
            if (starts(label, "<code>")) try std.testing.expect(span.flags.code);
        }
    }
    var prior: Renderer = .{ .a = a, .context = .{} };
    try prior.text("see ", .{});
    const prior_count = prior.spans.items.len;
    const prior_span = prior.spans.items[0];
    try prior.link("{{unclosed", "https://example.test/?q={{missing}}", .{}, 0, true);
    try std.testing.expectEqualDeep(prior_span, prior.spans.items[0]);
    try std.testing.expectEqualStrings("see [malformed template]", try plainText(a, prior.spans.items));
    try std.testing.expect(prior.fallbacks.rejected_external_target and prior.fallbacks.literal_markup);
    try std.testing.expectEqual(@as(usize, 0), prior.unresolved_templates);
    for (prior.spans.items[prior_count..]) |span| {
        try std.testing.expect(span.kind == .text and span.target.len == 0 and !span.self_link);
        try std.testing.expectEqualStrings("[malformed template]", span.text);
        try std.testing.expect(span.generated_diagnostic and span.provenance == .parsed);
    }
    var newline: Renderer = .{ .a = a, .context = .{} };
    try newline.link("{<br>{example}", "https://example.test/?q={{missing}}", .{}, 0, true);
    try std.testing.expectEqualStrings("{\n{example}", try plainText(a, newline.spans.items));
    var boundary: Renderer = .{ .a = a, .context = .{} };
    try boundary.link("{<nowiki>{example}</nowiki>", "https://example.test/?q={{missing}}", .{}, 0, true);
    try std.testing.expectEqualStrings("{{example}", try plainText(a, boundary.spans.items));
    var supported: Renderer = .{ .a = a, .context = .{} };
    try supported.link("{{small|word}}", "https://example.test/?q={{missing}}", .{}, 0, true);
    try std.testing.expectEqualStrings("word", try plainText(a, supported.spans.items));
    for (supported.spans.items) |span| {
        try std.testing.expect(span.flags.small);
        try std.testing.expectEqual(ir.InlineKind.text, span.kind);
        try std.testing.expectEqualStrings("", span.target);
    }
    var unresolved_label: Renderer = .{ .a = a, .context = .{} };
    try unresolved_label.link("{{unclosed", "https://example.test/?q={{missing}}", .{ .small = true }, 0, true);
    try std.testing.expectEqualStrings("[malformed template]", try plainText(a, unresolved_label.spans.items));
    try std.testing.expect(unresolved_label.fallbacks.rejected_external_target and unresolved_label.fallbacks.literal_markup);
    try std.testing.expectEqual(@as(usize, 0), unresolved_label.unresolved_templates);
    for (unresolved_label.spans.items) |span| {
        try std.testing.expect(span.kind == .text and span.target.len == 0 and !span.self_link);
        try std.testing.expectEqualStrings("[malformed template]", span.text);
        try std.testing.expect(span.generated_diagnostic and span.provenance == .parsed and span.flags.small);
    }
    const controls = [_]struct { input: []const u8, expected: []const u8 }{
        .{ .input = "https://example.test/?q={literal}", .expected = "https://example.test/?q={literal}" },
        .{ .input = "https://example.test/?q=%7B%7Bmissing%7D%7D", .expected = "https://example.test/?q=%7B%7Bmissing%7D%7D" },
        .{ .input = "https://example.test/शारदा?a=1&amp;b=2", .expected = "https://example.test/शारदा?a=1&b=2" },
        .{ .input = "https://example.test/?q=&amp;#123;literal&amp;#125;", .expected = "https://example.test/?q=&#123;literal&#125;" },
    };
    for (controls) |item| {
        var r: Renderer = .{ .a = a, .context = .{} };
        try r.link("valid label", item.input, .{}, 0, true);
        try std.testing.expectEqualStrings("valid label", try plainText(a, r.spans.items));
        for (r.spans.items) |span| {
            try std.testing.expectEqual(ir.InlineKind.external_link, span.kind);
            try std.testing.expectEqualStrings(item.expected, span.target);
        }
        try std.testing.expect(!r.fallbacks.rejected_external_target);
    }
    for ([_][]const u8{ "[[{{missing}}|clean label]]", "[[{{{arg}}}|clean label]]", "[[&#123;&#123;missing&#125;&#125;|clean label]]" }) |source| {
        var r: Renderer = .{ .a = a, .context = .{} };
        const spans = try r.parseSpans(source, .{});
        for (spans) |span| try std.testing.expect(span.kind != .link and span.kind != .external_link);
        try std.testing.expect(r.fallbacks.literal_markup);
    }
}

const ExternalNumberingFixture = struct {
    const Expected = struct { target: []const u8, label: []const u8, bold: ?bool = null, code: ?bool = null };
    fn spans(values: anytype, wanted: Expected, count: *usize) !void {
        for (values) |span| if (span.kind == .external_link and std.mem.eql(u8, span.target, wanted.target)) {
            count.* += 1;
            try std.testing.expectEqualStrings(wanted.label, span.text);
            if (wanted.bold) |flag| try std.testing.expectEqual(flag, if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold);
            if (wanted.code) |flag| try std.testing.expectEqual(flag, if (@hasField(@TypeOf(span), "flags")) span.flags.code else span.code);
        };
    }
    fn actions(a: A, blocks: anytype, refs: anytype, wanted: Expected) !void {
        var count: usize = 0;
        try spans(try FigureProducerTest.bodySpans(a, blocks), wanted, &count);
        for (refs) |ref| {
            if (ref.blocks) |reference_blocks| try spans(try FigureProducerTest.bodySpans(a, reference_blocks), wanted, &count) else try spans(ref.spans, wanted, &count);
        }
        if (count == 0) std.debug.print("missing numbered target {s}\n", .{wanted.target});
        try std.testing.expect(count != 0);
    }
    fn roundtrip(a: A, r: *Renderer, blocks: []const Block, expected: []const Expected) !void {
        const refs = try r.finishReferences();
        for (expected) |wanted| try actions(a, blocks, refs, wanted);
        const stored = try FormattingScopeTest.encode(a, r, blocks);
        for (expected) |wanted| try actions(a, stored.entry.sections[0].blocks, stored.entry.references, wanted);
        const codec = @import("blob_encoder").presentation_codec;
        const bytes = try CenteredImageTest.encoded(a, r, blocks);
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, try codec.decodeAlloc(a, bytes, "numbering", .language, .{ .code = "en", .heading = "English" })));
    }
};

