        .{ .text = "forced", .bold = true },   .{ .text = "plain", .bold = false },
        .{ .text = "strong", .bold = true },   .{ .text = "Default", .bold = true },
        .{ .text = "reset", .bold = false },   .{ .text = "nested", .bold = false },
        .{ .text = "after", .bold = false },
    };
    for (expected) |wanted| {
        var count: usize = 0;
