        .{ .source = "[[:en:Other ]]", .label = "en:Other ", .target = "https://en.wiktionary.org/wiki/Other", .kind = .external_link },
        .{ .source = "[[Page ]]", .label = "Page ", .target = "", .kind = .text, .bold = true },
