            }
            try std.testing.expect(case.linked);
            try std.testing.expectEqual(case.italic, span.flags.italic);
            if (std.mem.eql(u8, span.target, "A")) {
                try std.testing.expectEqualStrings("one", span.text);
                try std.testing.expect(two_links == 0);
                one_links += 1;
            } else {
                try std.testing.expectEqualStrings("B", span.target);
                try std.testing.expectEqualStrings("two", span.text);
                two_links += 1;
            }
        }
        try std.testing.expectEqual(@as(usize, if (case.linked) 1 else 0), one_links);
        try std.testing.expectEqual(@as(usize, if (case.linked) 1 else 0), two_links);
        try std.testing.expect(!renderer.fallbacks.malformed_table and !renderer.fallbacks.literal_markup);
        const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
        const blob = @import("blob_encoder");
        const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &[_]Section{.{ .blocks = blocks }}, blob.presentation_types.Layout{}, renderer.refs.items, renderer.media.items);
        const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "empty caption list boundary", .language, .{ .code = "en", .heading = "English" });
        try std.testing.expectEqualSlices(u8, bytes, try blob.presentation_codec.encodeAlloc(a, decoded));
        const decoded_blocks = decoded.entry.sections[0].blocks;
        try std.testing.expectEqual(@as(usize, 1), decoded_blocks.len);
        try std.testing.expectEqual(blob.presentation_types.BlockKind.table, decoded_blocks[0].kind);
        const decoded_table = decoded_blocks[0].table.?;
        try std.testing.expectEqual(@as(usize, 0), decoded_table.rows.len);
        var visible: std.ArrayList(u8) = .empty;
        defer visible.deinit(a);
        one_links = 0;
        two_links = 0;
        for (decoded_table.caption) |span| {
            if (span.kind == .line_break) try visible.append(a, '\n') else try visible.appendSlice(a, span.text);
            if (span.kind != .link) {
                try std.testing.expectEqualStrings("", span.target);
                continue;
            }
            try std.testing.expect(case.linked);
            try std.testing.expectEqual(case.italic, span.italic);
            if (std.mem.eql(u8, span.target, "A")) {
                try std.testing.expectEqualStrings("one", span.text);
                try std.testing.expect(two_links == 0);
                one_links += 1;
            } else {
                try std.testing.expectEqualStrings("B", span.target);
                try std.testing.expectEqualStrings("two", span.text);
                two_links += 1;
            }
        }
        try std.testing.expectEqualStrings(case.visible, visible.items);
        try std.testing.expectEqual(@as(usize, if (case.linked) 1 else 0), one_links);
        try std.testing.expectEqual(@as(usize, if (case.linked) 1 else 0), two_links);
    }
}

test "matched inline HTML preserves source-isolated closing bracket provenance" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const document = @import("presentation_document.zig");
    const codec = @import("blob_encoder").presentation_codec;
    const source = "[<span style='font-style:italic'>IPA]</span>] tail [[Target|label]]";
    var report: document.Fallbacks = .{};
    const encoded = try document.compileReportedAlloc(a, "entry", .language, "English", "en", source, null, &report);
    try std.testing.expect(!report.literal_markup);
    const stored = try codec.decodeAlloc(a, encoded, "entry", .language, .{ .code = "en", .heading = "English" });
    try std.testing.expectEqual(@as(usize, 1), stored.entry.sections[0].blocks.len);
    var visible: std.ArrayList(u8) = .empty;
    defer visible.deinit(a);
    var actions: usize = 0;
    var ipa_italic = false;
    var outer_bracket = false;
    for (stored.entry.sections[0].blocks[0].spans) |span| {
        try visible.appendSlice(a, span.text);
        if (std.mem.eql(u8, span.text, "IPA]")) ipa_italic = span.italic and span.target.len == 0;
        if (std.mem.eql(u8, span.text, "]")) outer_bracket = !span.italic and span.target.len == 0;
        if (span.kind == .link) {
            actions += 1;
            try std.testing.expectEqualStrings("Target", span.target);
            try std.testing.expectEqualStrings("label", span.text);
        }
    }
    try std.testing.expectEqualStrings("[IPA]] tail label", visible.items);
    try std.testing.expect(ipa_italic and outer_bracket);
    try std.testing.expectEqual(@as(usize, 1), actions);
    var linked: Renderer = .{ .a = a, .context = .{} };
    const link_spans = try linked.parseSpans("[[A|<span>x]</span>]]", .{});
    try std.testing.expectEqualStrings("x]", try flattened(a, link_spans));
    try std.testing.expect(!linked.fallbacks.literal_markup);
    for (link_spans) |span| {
        try std.testing.expectEqual(ir.InlineKind.link, span.kind);
        try std.testing.expectEqualStrings("A", span.target);
    }
    var terminal: Renderer = .{ .a = a, .context = .{} };
    const terminal_spans = try terminal.parseSpans("[<span>x]</span>]", .{});
    try std.testing.expectEqualStrings("[x]]", try flattened(a, terminal_spans));
    try std.testing.expect(!terminal.fallbacks.literal_markup);
    try std.testing.expectEqual(Provenance.protected_literal, terminal_spans[terminal_spans.len - 1].provenance);
    // Candidate-free authored closes are literal source under the ordinary
    // malformed-body policy; assembled closes still have no source proof.
    for ([_]struct { source: []const u8, visible: []const u8 }{
        .{ .source = "word]]tail", .visible = "word]]tail" },
        .{ .source = "<span>x</span>]]", .visible = "x]]" },
    }) |case| {
        errdefer std.debug.print("authored closing pair source={s}\n", .{case.source});
        var literal: Renderer = .{ .a = a, .context = .{} };
        const spans = try literal.parseSpans(case.source, .{});
        try std.testing.expectEqualStrings(case.visible, try flattened(a, spans));
        var closes: usize = 0;
        for (spans) |span| {
            try std.testing.expect(span.kind == .text and span.target.len == 0 and !span.generated_diagnostic);
            if (std.mem.indexOfScalar(u8, span.text, ']') != null) {
                closes += 1;
                try std.testing.expectEqualStrings("]]", span.text);
                try std.testing.expectEqual(Provenance.protected_literal, span.provenance);
            }
        }
        try std.testing.expectEqual(@as(usize, 1), closes);
        try std.testing.expect(literal.fallbacks.literal_markup);
        try std.testing.expectError(error.UncompiledPresentation, requireCompiledText(try flattened(a, spans)));
        var literal_report: document.Fallbacks = .{};
        const payload = try document.compileReportedAlloc(a, "entry", .language, "English", "en", case.source, null, &literal_report);
        const decoded = try codec.decodeAlloc(a, payload, "entry", .language, .{ .code = "en", .heading = "English" });
        try std.testing.expectEqualSlices(u8, payload, try codec.encodeAlloc(a, decoded));
        try std.testing.expect(literal_report.literal_markup);
    }
    {
        const raw = "<span>x</span>]__NOTOC__]";
        var negative: Renderer = .{ .a = a, .context = .{} };
        const spans = try negative.parseSpans(raw, .{});
        for (spans) |span| if (std.mem.indexOfScalar(u8, span.text, ']') != null)
            try std.testing.expect(span.provenance == .parsed);
        var raw_report: document.Fallbacks = .{};
        try std.testing.expectError(error.UncompiledPresentation, document.compileReportedAlloc(a, "entry", .language, "English", "en", raw, null, &raw_report));
        try std.testing.expect(raw_report.literal_markup);
    }
    // Comments are removed in the expansion phase. Direct compiler callers
    // must not acquire a literal exemption across that same empty boundary.
    for ([_][]const u8{ "<span>x</span>]<!--comment-->]", "<span>x</span>]<!--comment-->__NOTOC__]" }) |raw| {
        var raw_report: document.Fallbacks = .{};
        try std.testing.expectError(error.UncompiledPresentation, document.compileReportedAlloc(a, "entry", .language, "English", "en", raw, null, &raw_report));
        try std.testing.expect(raw_report.literal_markup);
    }
    var linked_pair: Renderer = .{ .a = a, .context = .{} };
    const linked_pair_spans = try linked_pair.parseSpans("[[A|[<span>x]</span>] tail]]", .{});
    try std.testing.expectEqualStrings("[x]] tail", try flattened(a, linked_pair_spans));
    try std.testing.expect(!linked_pair.fallbacks.literal_markup);
    for (linked_pair_spans) |span| {
        try std.testing.expectEqual(ir.InlineKind.link, span.kind);
        try std.testing.expectEqualStrings("A", span.target);
    }
    // An arbitrary fragment boundary has no matched HTML proof.
    var fragments: Renderer = .{ .a = a, .context = .{} };
    try fragments.inlineText("]", .{}, 0);
    try fragments.inlineText("]", .{}, 0);
    try std.testing.expectEqualStrings("]]", try flattened(a, fragments.spans.items));
    for (fragments.spans.items) |span| try std.testing.expectEqual(Provenance.parsed, span.provenance);
}

test "captured dottir wiki tables retain authored cellpadding beside CSS through codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const fragments = [_][]const u8{ "{| style=\"float:right; margin-left:0.5em; margin-bottom:0.5em; border: 1px solid #AAAAAA; border-collapse:collapse;\" cellpadding=\"3\" rules=\"all\"\n! width=\"65\" bgcolor=\"#F4F4F4\" | [[hulp:naamval|Naamval]]\n! bgcolor=\"#FFFFE0\" colspan=\"2\" | [[hulp:enkelvoud|Enkelvoud]]\n! bgcolor=\"#FFFFE0\" colspan=\"2\" | [[hulp:meervoud|Meervoud]]\n|- align=\"center\"\n!\n! bgcolor=\"#FFFFE0\" | [[hulp:onbepaald|Onbepaald]]\n! bgcolor=\"#FFFFE0\" | [[hulp:bepaald|Bepaald]]\n! bgcolor=\"#FFFFE0\" | [[hulp:onbepaald|Onbepaald]]\n! bgcolor=\"#FFFFE0\" | [[hulp:bepaald|Bepaald]]\n|- align=\"center\"\n| bgcolor=\"#F4F4F4\" | '''[[hulp:nominatief|Nominatief]]'''\n| dóttir [[vroulik|<abbr title=\"Vroulik\" style=\"background-color: #f8f9fa;border-radius: 2px;border: 1px solid #c8ccd1;padding: 0 0.2em 0 0.1em;font-style: italic\">v</abbr>]] || dóttirin || døtur || døturnar\n|- align=\"center\"\n| bgcolor=\"#F4F4F4\" | '''[[hulp:genitief|Genitief]]'''\n| dóttur || dótturinnar || døtra || døtranna\n|- align=\"center\"\n| bgcolor=\"#F4F4F4\" | '''[[Hulp:datief|Datief]]'''\n| dóttur || dóttrini || døtrum || døtrunum\n|- align=\"center\"\n| bgcolor=\"#F4F4F4\" | '''[[hulp:akkusatief|Akkusatief]]'''\n| dóttur || dóttrina || døtur || døturnar\n|}\n", "{| style=\"float:right; margin-left:0.5em; margin-bottom:0.5em; border: 1px solid #AAAAAA; border-collapse:collapse;\" cellpadding=\"3\" rules=\"all\"\n! width=\"65\" bgcolor=\"#F4F4F4\" | [[hulp:naamval|Naamval]]\n! bgcolor=\"#FFFFE0\" colspan=\"2\" | [[hulp:enkelvoud|Enkelvoud]]\n! bgcolor=\"#FFFFE0\" colspan=\"2\" | [[hulp:meervoud|Meervoud]]\n|-\n!\n! bgcolor=\"#FFFFE0\" | [[hulp:onbepaald|Onbepaald]]\n! bgcolor=\"#FFFFE0\" | [[hulp:bepaald|Bepaald]]\n! bgcolor=\"#FFFFE0\" | [[hulp:onbepaald|Onbepaald]]\n! bgcolor=\"#FFFFE0\" | [[hulp:bepaald|Bepaald]]\n|- \n| bgcolor=\"#F4F4F4\" | '''[[hulp:nominatief|Nominatief]]'''\n| dóttir [[vroulik|<abbr title=\"Vroulik\" style=\"background-color: #f8f9fa;border-radius: 2px;border: 1px solid #c8ccd1;padding: 0 0.2em 0 0.1em;font-style: italic\">v</abbr>]] || dóttirin || dœtr || dœtrnar\n|-\n| bgcolor=\"#F4F4F4\" | '''[[hulp:genitief|Genitief]]'''\n| dóttur || dótturinnar || dœtra || dœtranna\n|-\n| bgcolor=\"#F4F4F4\" | '''[[Hulp:datief|Datief]]'''\n| dóttur || dótturinni || dœtrum || dœtrunum\n|-\n| bgcolor=\"#F4F4F4\" | '''[[hulp:akkusatief|Akkusatief]]'''\n| dóttur || dótturina || dœtr || dœtrnar\n|}\n", "{| style=\"float:right; margin-left:0.5em; margin-bottom:0.5em; border: 1px solid #AAAAAA; border-collapse:collapse;\" cellpadding=\"3\" rules=\"all\"\n! width=\"65\" bgcolor=\"#F4F4F4\" | [[hulp:naamval|Naamval]]\n! bgcolor=\"#FFFFE0\" colspan=\"2\" | [[hulp:enkelvoud|Enkelvoud]]\n! bgcolor=\"#FFFFE0\" colspan=\"2\" | [[hulp:meervoud|Meervoud]]\n|-\n!\n! bgcolor=\"#FFFFE0\" | [[hulp:onbepaald|Onbepaald]]\n! bgcolor=\"#FFFFE0\" | [[hulp:bepaald|Bepaald]]\n! bgcolor=\"#FFFFE0\" | [[hulp:onbepaald|Onbepaald]]\n! bgcolor=\"#FFFFE0\" | [[hulp:bepaald|Bepaald]]\n|- \n| bgcolor=\"#F4F4F4\" | '''[[hulp:nominatief|Nominatief]]'''\n| dóttir [[vroulik|<abbr title=\"Vroulik\" style=\"background-color: #f8f9fa;border-radius: 2px;border: 1px solid #c8ccd1;padding: 0 0.2em 0 0.1em;font-style: italic\">v</abbr>]] || dóttirin || dætur || dæturnar\n|-\n| bgcolor=\"#F4F4F4\" | '''[[hulp:genitief|Genitief]]'''\n| dóttur || dótturinnar || dætra || dætranna\n|-\n| bgcolor=\"#F4F4F4\" | '''[[Hulp:datief|Datief]]'''\n| dóttur || dótturinni || dætrum || dætrunum\n|-\n| bgcolor=\"#F4F4F4\" | '''[[hulp:akkusatief|Akkusatief]]'''\n| dóttur || dótturina || dætur || dæturnar\n|}\n" };
    const blob = @import("blob_encoder");
    const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
    for (fragments) |source| {
        var renderer: Renderer = .{ .a = a, .context = .{ .title = "dóttir" } };
        const blocks = try renderer.renderBody(source);
        try std.testing.expectEqual(@as(usize, 1), blocks.len);
        const table_value = blocks[0].table.?;
        try std.testing.expect(table_value.geometry != null);
        const geometry = table_value.geometry.?;
        try std.testing.expectEqual(@as(?u16, 3), geometry.cell_padding);
        // The authored CSS border/float is not a legacy border/width value.
        try std.testing.expect(geometry.border == null and geometry.cell_spacing == null and geometry.width == null);
        try std.testing.expectEqual(@as(usize, 6), table_value.rows.len);
        try std.testing.expectEqual(@as(usize, 3), table_value.rows[0].cells.len);
        try std.testing.expectEqual(@as(u16, 2), table_value.rows[0].cells[1].colspan);
        try std.testing.expectEqualStrings("Naamval", table_value.rows[0].cells[0].spans[0].text);
        try std.testing.expect(table_value.rows[0].cells[0].spans[0].kind == .link);
        const encoded = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &[_]Section{.{ .blocks = blocks }}, blob.presentation_types.Layout{}, renderer.refs.items, renderer.media.items);
        const stored = try blob.presentation_codec.decodeAlloc(a, encoded, "dóttir", .language, .{ .code = "af", .heading = "Afrikaans" });
        const saved_table = stored.entry.sections[0].blocks[0].table.?;
        try std.testing.expect(saved_table.geometry != null);
        try std.testing.expectEqual(@as(?u16, 3), saved_table.geometry.?.cell_padding);
        try std.testing.expect(saved_table.geometry.?.border == null and saved_table.geometry.?.cell_spacing == null and saved_table.geometry.?.width == null);
        try std.testing.expectEqual(table_value.rows.len, saved_table.rows.len);
        try std.testing.expectEqualStrings(table_value.rows[0].cells[0].spans[0].target, saved_table.rows[0].cells[0].spans[0].target);
        try std.testing.expectEqualStrings("Naamval", saved_table.rows[0].cells[0].spans[0].text);
    }
}

test "wiki opener geometry preserves zero units nesting and absent or invalid controls" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const cases = [_]struct { attrs: []const u8, present: bool }{
        .{ .attrs = "", .present = false },
        .{ .attrs = " class='ordinary' style='border:1px solid red' rules='all'", .present = false },
        .{ .attrs = " cellpadding='-1'", .present = false },
        .{ .attrs = " cellpadding='1.5'", .present = false },
        .{ .attrs = " cellpadding='3px'", .present = false },
        .{ .attrs = " cellpadding='65536'", .present = false },
        .{ .attrs = " cellpadding=' 3 '", .present = false },
        .{ .attrs = " width='101%'", .present = false },
        .{ .attrs = " border='0' cellspacing='0' cellpadding='0' width='50%' class='ordinary'", .present = true },
    };
    for (cases) |case| {
        const source = try std.fmt.allocPrint(a, "{{|{s}\n| [[X|body]] || second\n|}}", .{case.attrs});
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(source);
        const table_value = blocks[0].table.?;
        try std.testing.expectEqual(@as(usize, 2), table_value.rows[0].cells.len);
        try std.testing.expectEqual(case.present, table_value.geometry != null);
        try std.testing.expectEqualStrings("body", table_value.rows[0].cells[0].spans[0].text);
        try std.testing.expectEqualStrings("X", table_value.rows[0].cells[0].spans[0].target);
        if (table_value.geometry) |geometry| {
            try std.testing.expectEqual(@as(?u16, 0), geometry.border);
            try std.testing.expectEqual(@as(?u16, 0), geometry.cell_spacing);
            try std.testing.expectEqual(@as(?u16, 0), geometry.cell_padding);
            try std.testing.expect(geometry.width.?.unit == .percent);
            try std.testing.expectEqual(@as(u32, 50), geometry.width.?.value);
        }
    }
    var nested: Renderer = .{ .a = a, .context = .{} };
    const nested_blocks = try nested.renderBody("{| cellpadding=3\n| lead\n{| cellpadding=0 width=20px\n| inner || second\n|}\n|}suffix");
    const parent_table = nested_blocks[0].table.?;
    try std.testing.expect(parent_table.geometry != null);
    try std.testing.expectEqual(@as(?u16, 3), parent_table.geometry.?.cell_padding);
    const child_table = parent_table.rows[0].cells[0].blocks.?[1].table.?;
    try std.testing.expect(child_table.geometry != null);
    try std.testing.expectEqual(@as(?u16, 0), child_table.geometry.?.cell_padding);
    try std.testing.expect(child_table.geometry.?.width.?.unit == .px);
    try std.testing.expectEqual(@as(u32, 20), child_table.geometry.?.width.?.value);
    try std.testing.expectEqualStrings("suffix", try flattened(a, nested_blocks[1].spans));
    // HTML nested-grid admission keeps its original unrelated-attribute refusal.
    const strict_html: syntax.Tag = .{ .name = "table", .attrs = " cellpadding=3 class=ordinary", .end = 0, .closing = false, .self_closing = false };
    try std.testing.expect(Renderer.htmlNestedGeometry(strict_html) == null);
}

test "Cite external labels follow joined bodies reverse group flushes and orphan ordering" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source = "[https://example.org/body]\n<ref group=a name=n>[https://example.org/ap]</ref><ref group=b name=n>[https://example.org/bp]</ref><ref group=a follow=n>[https://example.org/af]</ref><ref group=b follow=n>[https://example.org/bf]</ref><references group=b/><references group=a/>";
    const prepared = try preparePageExternalLinksAlloc(a, source, .{});
    var r: Renderer = .{ .a = a, .context = .{ .citations = prepared.citations, .poem_phase = prepared.poem_phase, .external_links_prepared = true } };
    const blocks = try r.renderBody(prepared.source);
    try ExternalNumberingFixture.roundtrip(a, &r, blocks, &.{
        .{ .target = "https://example.org/bp", .label = "[1]" },
        .{ .target = "https://example.org/bf", .label = "[2]" },
        .{ .target = "https://example.org/ap", .label = "[3]" },
        .{ .target = "https://example.org/af", .label = "[4]" },
        .{ .target = "https://example.org/body", .label = "[5]" },
    });
    const orphan = try preparePageExternalLinksAlloc(a, "<ref name=first>[https://example.org/first]</ref><ref follow=later>[https://example.org/orphan]</ref><ref name=later>[https://example.org/later]</ref><references/>", .{});
    const plan = orphan.citations.?;
    try std.testing.expect(std.mem.indexOf(u8, plan.items.items[1].body.?.bytes, "https://example.org/orphan <nowiki>[1]</nowiki>") != null);
    try std.testing.expect(std.mem.indexOf(u8, plan.items.items[0].body.?.bytes, "https://example.org/first <nowiki>[2]</nowiki>") != null);
    try std.testing.expect(std.mem.indexOf(u8, plan.items.items[2].body.?.bytes, "https://example.org/later <nowiki>[3]</nowiki>") != null);
}

test "Cite footer shares extension phase across items and reuses numbered recovery prefix" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const prepared = try preparePageExternalLinksAlloc(a, "<ref name=a>[https://example.org/ordinary]</ref><ref name=b><poem>[https://example.org/poem]</poem></ref><references/>", .{});
    try std.testing.expect(std.mem.indexOf(u8, prepared.citations.?.items.items[0].body.?.bytes, "https://example.org/ordinary <nowiki>[2]</nowiki>") != null);
    try std.testing.expect(std.mem.indexOf(u8, prepared.citations.?.items.items[1].body.?.bytes, "https://example.org/poem <nowiki>[1]</nowiki>") != null);
    const recovery = try preparePageExternalLinksAlloc(a, "<references><ref name=n>[https://example.org/recovered]</ref></references><ref name=n/><ref follow=n>[https://example.org/tail]</ref><references/>[https://example.org/body]", .{});
    const body = recovery.citations.?.items.items[0].body.?.bytes;
    try std.testing.expect(std.mem.indexOf(u8, body, "https://example.org/recovered <nowiki>[1]</nowiki>") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, "https://example.org/tail <nowiki>[2]</nowiki>") != null);
    try std.testing.expect(std.mem.indexOf(u8, recovery.source, "https://example.org/body <nowiki>[3]</nowiki>") != null);
    const copied = try a.dupe(u8, recovery.source);
    const again = try preparePageExternalLinksAlloc(a, copied, .{ .citations = recovery.citations, .poem_phase = recovery.poem_phase });
    try std.testing.expectEqualStrings(copied, again.source);
    try std.testing.expect(again.citations == recovery.citations);
    try std.testing.expectEqualStrings(body, again.citations.?.items.items[0].body.?.bytes);
}

test "Cite private attributes avoid authored collisions and ignore protected tags" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source = "<!-- DATA-WIKIDICT-CITE-0 --><nowiki><ref follow=missing>literal</ref></nowiki><includeonly><ref>hidden</ref></includeonly><ref name=n>visible</ref><references/>";
    const prepared = try preparePageExternalLinksAlloc(a, source, .{});
    const plan = prepared.citations.?;
    try std.testing.expectEqualStrings("data-wikidict-cite-1", plan.attribute);
    try std.testing.expectEqual(@as(usize, 2), plan.events.items.len);
    try std.testing.expectEqual(@as(usize, 1), plan.items.items.len);
    try std.testing.expectEqualStrings("visible", plan.items.items[0].body.?.bytes);
    try std.testing.expect(std.mem.indexOf(u8, prepared.source, "<nowiki><ref follow=missing>literal</ref></nowiki>") != null);
    var r: Renderer = .{ .a = a, .context = .{ .citations = plan, .external_links_prepared = true } };
    const forged = try std.fmt.allocPrint(a, "<ref {s}=\"999999\"/>", .{plan.attribute});
    try std.testing.expectError(error.InvalidPreContext, r.renderBody(forged));
}

