    const tracked: MissingText = .{ .bytes = source, .ranges = &.{.{ .start = @intCast(b_at), .end = @intCast(b_at + 1), .occurrence = 1 }} };
    const prepared = try preparePageExternalLinksWithMissingAlloc(a, tracked, .{});
