}


test "orphan gallery close protects only its ordinary opening delimiter" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    for ([_][]const u8{ "</gallery>", "</Gallery>", "</GALLERY>" }) |closer| {
        var r: Renderer = .{ .a = a, .context = .{} };
        const source = try std.fmt.allocPrint(a, "''{s}'' [[Tail|suffix]]", .{closer});
        const spans = try r.parseSpans(source, .{});
        try std.testing.expectEqualStrings(try std.fmt.allocPrint(a, "{s} suffix", .{closer}), try flattened(a, spans));
        var protected_openings: usize = 0;
        var actions: usize = 0;
        for (spans) |span| {
            if (std.mem.eql(u8, span.text, "<")) {
                protected_openings += 1;
                try std.testing.expect(span.provenance == .protected_literal and span.flags.italic);
                try std.testing.expect(span.kind == .text and span.target.len == 0);
            }
            if (std.mem.eql(u8, span.text, closer[1..])) {
                try std.testing.expect(span.provenance == .parsed and span.flags.italic);
            }
            if (span.kind == .link) {
                actions += 1;
                try std.testing.expectEqualStrings("Tail", span.target);
                try std.testing.expectEqualStrings("suffix", span.text);
                try std.testing.expect(!span.flags.italic);
            }
        }
        try std.testing.expect(protected_openings == 1 and actions == 1 and r.fallbacks.literal_markup);
    }
    // The opening scope owns its real closer and retains gallery media.
    const matched = "<Gallery>\nFile:Cat.jpg|caption\n</Gallery>";
    var owned: Renderer = .{ .a = a, .context = .{} };
    _ = try owned.parseSpans(matched, .{});
    try std.testing.expect(owned.media.items.len == 1 and !owned.fallbacks.literal_markup);
    var orphan: Renderer = .{ .a = a, .context = .{} };
    const both = try orphan.parseSpans(try std.fmt.allocPrint(a, "{s}</Gallery>", .{matched}), .{});
    try std.testing.expectEqualDeep(owned.media.items, orphan.media.items);
    try std.testing.expect(std.mem.endsWith(u8, try flattened(a, both), "</Gallery>"));
    try std.testing.expect(orphan.fallbacks.literal_markup);
    for ([_][]const u8{ "<nowiki></Gallery></nowiki>", "&lt;/Gallery>" }) |source| {
        var protected: Renderer = .{ .a = a, .context = .{} };
        try std.testing.expectEqualStrings("</Gallery>", try flattened(a, try protected.parseSpans(source, .{})));
        try std.testing.expect(!protected.fallbacks.literal_markup);
    }
    // Attribute-bearing, malformed, other extension and action domains do
    // not acquire this proof. The test inspects provenance, not a fallback.
    for ([_][]const u8{ "</gallery x>", "</gallery/>", "</ref>", "</gallery" }) |source| {
        var r: Renderer = .{ .a = a, .context = .{} };
        const spans = try r.parseSpans(source, .{});
        for (spans) |span| try std.testing.expect(!(std.mem.eql(u8, span.text, "<") and span.provenance == .protected_literal));
    }
    for ([_]Style{
        .{ .kind = .link, .target = "Target" },
        .{ .kind = .external_link, .target = "https://example.test" },
        .{ .self_link_target = "entry" },
    }) |style| {
        var r: Renderer = .{ .a = a, .context = .{} };
        const spans = try r.parseSpans("</Gallery>", style);
        for (spans) |span| try std.testing.expect(span.provenance == .parsed);
        try std.testing.expect(!r.fallbacks.literal_markup);
    }
    try std.testing.expectError(error.UncompiledPresentation, requireCompiledText("</Gallery>"));
}

test "Cite collection resumes after malformed invocation before same-cell and later-table notes" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    for ([_][]const u8{ "{{trad|fr|mettre} des bottes}", "{{{parameter des bottes" }) |malformed| {
        for ([_]bool{ false, true }) |later_table| {
            const separation = if (later_table) "\n|}\n{|\n| " else " ";
            const source = try std.mem.concat(a, u8, &.{
                "<h2>Heading</h2>\n{|\n| before<ref group=N name=before>first [[First|one]]</ref><references group=N/>\n|}\n{|\n| ",
                malformed, separation,
                "after<ref group=N name=after>''later'' [[Later|two]]</ref>\n|}\n<references group=N/>",
            });
            const original = try a.dupe(u8, source);
            const prepared = try preparePageExternalLinksAlloc(a, source, .{});
            try std.testing.expectEqualStrings(original, source);
            const plan = prepared.citations orelse return error.TestUnexpectedResult;
            try std.testing.expectEqual(@as(usize, 4), plan.events.items.len);
            try std.testing.expectEqual(@as(usize, 2), plan.items.items.len);
            const after_tag = try std.fmt.allocPrint(a, "<ref {s}=\"2\" group=N name=after>", .{plan.attribute});
            try std.testing.expect(std.mem.indexOf(u8, prepared.source, after_tag) != null);
            try std.testing.expect(std.mem.indexOf(u8, prepared.source, malformed) != null);
            // Reusing immutable annotated input must neither renumber nor append.
            const copied = try a.dupe(u8, prepared.source);
            const again = try preparePageExternalLinksAlloc(a, copied, .{ .citations = plan });
            try std.testing.expect(again.citations == plan);
            try std.testing.expectEqualStrings(copied, again.source);
            var renderer: Renderer = .{ .a = a, .context = .{ .citations = plan, .external_links_prepared = true } };
            _ = try renderer.renderBody(prepared.source);
            const refs = try renderer.finishReferences();
            try std.testing.expectEqual(@as(usize, 2), refs.len);
            try std.testing.expectEqualStrings("before", refs[0].name);
            try std.testing.expectEqualStrings("after", refs[1].name);
            try std.testing.expectEqualStrings("N", refs[0].group);
            try std.testing.expectEqualStrings("N", refs[1].group);
            try std.testing.expectEqualStrings("first one", try flattened(a, refs[0].spans));
            try std.testing.expectEqualStrings("later two", try flattened(a, refs[1].spans));
            var first_action = false;
            var later_action = false;
            var later_italic = false;
            for (refs[0].spans) |span| if (span.kind == .link and std.mem.eql(u8, span.target, "First")) { first_action = true; };
            for (refs[1].spans) |span| {
                if (span.kind == .link and std.mem.eql(u8, span.target, "Later")) later_action = true;
                if (span.flags.italic and std.mem.eql(u8, span.text, "later")) later_italic = true;
            }
            try std.testing.expect(first_action and later_action and later_italic);
            var missing: Renderer = .{ .a = a, .context = .{ .citations = plan, .external_links_prepared = true } };
            try std.testing.expectError(error.InvalidPreContext, missing.renderBody("<ref group=N>unannotated</ref>"));
            var forged: Renderer = .{ .a = a, .context = .{ .citations = plan, .external_links_prepared = true } };
            const invalid = try std.fmt.allocPrint(a, "<ref {s}=\"999999\"/>", .{plan.attribute});
            try std.testing.expectError(error.InvalidPreContext, forged.renderBody(invalid));
        }
    }
    // Protected and balanced invocation domains are not newly traversed.
    const protected_source = "<nowiki>{{broken <ref>hidden</ref></nowiki><!-- {{broken <ref>hidden</ref> --><ref name=n>visible</ref><references/>";
    const protected = try preparePageExternalLinksAlloc(a, protected_source, .{});
    try std.testing.expectEqual(@as(usize, 2), protected.citations.?.events.items.len);
    try std.testing.expectEqual(@as(usize, 1), protected.citations.?.items.items.len);
    const balanced = try preparePageExternalLinksAlloc(a, "{{unexpanded|<ref>hidden</ref>}}<ref name=n>visible</ref><references/>", .{});
    try std.testing.expectEqual(@as(usize, 2), balanced.citations.?.events.items.len);
    try std.testing.expectEqualStrings("visible", balanced.citations.?.items.items[0].body.?.bytes);
    // A bare URL in the discarded contiguous prefix is not an auto-numbered
    // bracketed action; the later visible bracketed URL still receives [1].
    const url_source = "{{https://hidden.example/path later [https://visible.example/path]<ref>note</ref><references/>";
    const numbered = try preparePageExternalLinksAlloc(a, url_source, .{});
    try std.testing.expect(std.mem.indexOf(u8, numbered.source, "{{https://hidden.example/path later ") != null);
    try std.testing.expect(std.mem.indexOf(u8, numbered.source, "https://visible.example/path <nowiki>[1]</nowiki>") != null);
    try std.testing.expect(std.mem.indexOf(u8, numbered.source, "<nowiki>[2]</nowiki>") == null);
    try std.testing.expectEqual(@as(usize, 2), numbered.citations.?.events.items.len);
}

test "terminal dot abbreviation proof is confined to parsed nonaction text" {
    var hr_dot_arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer hr_dot_arena.deinit();
    const hr_dot_a = hr_dot_arena.allocator();
    for ([_][]const u8{ "<Sv.>", "<Vol.>", "<Etc.>" }) |hr_dot_source|
        try std.testing.expectEqual(@as(?usize, hr_dot_source.len), Renderer.terminalDotUnregisteredHtmlNameEnd(hr_dot_source, 0));
    for ([_][]const u8{
        "", "<", "<S", "<Sv.", "<.>", "<Sv..>", "<Sv.x>", "<Sv-xyz.>", "<Sv2.>",
        "</Sv.>", "<Sv./>", "<Sv. >", "<Sv.\n>", "<Sv. title='x'>", "<Sv.[[Child]]>",
        "<a.>", "<img.>", "<B.>", "<div.>", "<ref.>", "<math.>", "<script.>",
        "<http.>", "<https://example.test>", "&lt;Sv.&gt;",
    }) |hr_dot_source|
        try std.testing.expect(Renderer.terminalDotUnregisteredHtmlNameEnd(hr_dot_source, 0) == null);
    try std.testing.expect(Renderer.terminalDotUnregisteredHtmlNameEnd("<<Sv.>>", 1) == null);
    try std.testing.expect(Renderer.terminalDotUnregisteredHtmlNameEnd("<broken <Sv.>", 8) == null);
    // The pre-quote atomic handler leaves this ordinary-nonaction domain alone.
    try std.testing.expect(Renderer.completeUnknownHtmlTokenEnd("<a.>", 0) == null);
    var hr_dot_renderer: Renderer = .{ .a = hr_dot_a, .context = .{} };
    const hr_dot_spans = try hr_dot_renderer.parseSpans("''(<Sv.> 4.)'' [[Child|kept]]", .{});
    try std.testing.expectEqualStrings("(<Sv.> 4.) kept", try flattened(hr_dot_a, hr_dot_spans));
    var hr_dot_openings: usize = 0;
    for (hr_dot_spans) |hr_dot_span| {
        if (hr_dot_span.provenance == .protected_literal) {
            hr_dot_openings += 1;
            try std.testing.expectEqualStrings("<", hr_dot_span.text);
            try std.testing.expect(hr_dot_span.kind == .text and hr_dot_span.target.len == 0 and hr_dot_span.flags.italic);
        }
        if (hr_dot_span.kind == .link) {
            try std.testing.expectEqualStrings("Child", hr_dot_span.target);
            try std.testing.expectEqualStrings("kept", hr_dot_span.text);
            try std.testing.expectEqual(Provenance.parsed, hr_dot_span.provenance);
        }
    }
    try std.testing.expectEqual(@as(usize, 1), hr_dot_openings);
    try std.testing.expect(hr_dot_renderer.fallbacks.literal_markup);
    // Inherited action labels and self-link displays are outside this proof.
    for ([_]Style{
        .{ .kind = .link, .target = "Target" },
        .{ .kind = .external_link, .target = "https://example.test" },
        .{ .self_link_target = "Target" },
    }) |hr_dot_style| {
        var hr_dot_action: Renderer = .{ .a = hr_dot_a, .context = .{} };
        const hr_dot_action_spans = try hr_dot_action.parseSpans("<Sv.>", hr_dot_style);
        for (hr_dot_action_spans) |hr_dot_span| try std.testing.expect(hr_dot_span.provenance != .protected_literal);
    }
    var hr_dot_protected: Renderer = .{ .a = hr_dot_a, .context = .{} };
    try std.testing.expectEqualStrings("<Sv.>", try flattened(hr_dot_a, try hr_dot_protected.parseSpans("<nowiki><Sv.></nowiki>", .{})));
    try std.testing.expect(!hr_dot_protected.fallbacks.literal_markup);
    var hr_dot_entity: Renderer = .{ .a = hr_dot_a, .context = .{} };
    try std.testing.expectEqualStrings("<Sv.>", try flattened(hr_dot_a, try hr_dot_entity.parseSpans("&lt;Sv.&gt;", .{})));
    try std.testing.expect(!hr_dot_entity.fallbacks.literal_markup);
    var hr_dot_supported: Renderer = .{ .a = hr_dot_a, .context = .{} };
    const hr_dot_supported_spans = try hr_dot_supported.parseSpans("<b>kept</b>", .{});
    try std.testing.expectEqualStrings("kept", try flattened(hr_dot_a, hr_dot_supported_spans));
    for (hr_dot_supported_spans) |hr_dot_span| try std.testing.expect(hr_dot_span.flags.bold);
    try std.testing.expectError(error.UncompiledPresentation, requireCompiledText("<Sv.>"));
}


test "ordinary list tail table marker has exact source and nonaction provenance" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    for ([_][]const u8{
        "before|}",
        "[[Keep|kept]] <span class='label'>tail</span>|}",
        "<nowiki>literal</nowiki> [[Keep]]:|}",
        "<!-- hidden -->[[Keep]]|}",
    }) |raw| try std.testing.expect(Renderer.ordinaryWikiListTableTail(raw));
    for ([_][]const u8{
        "before |} after",
        "before\n|}",
        "before\r|}",
        "[[Keep|label|}",
        "{{unclosed|}",
        "[https://example.test label|}",
        "<span title='unfinished |}",
        "before |}<!--hidden |}",
        "<nowiki>unclosed |}",
        "<source>unclosed |}",
        "<ref>unclosed |}",
        "before |}<includeonly>hidden |}",
        "before |}<span style='display:none'>hidden |}",
        "<span title='|}'>after",
    }) |raw| try std.testing.expect(!Renderer.ordinaryWikiListTableTail(raw));

    var renderer: Renderer = .{ .a = a, .context = .{} };
    const blocks = try renderer.renderBody("* [[Keep|kept]] <i>tail</i>|}\n");
    try std.testing.expectEqual(@as(usize, 1), blocks.len);
    try std.testing.expectEqual(Kind.list_item, blocks[0].kind);
    try std.testing.expectEqualStrings("*", blocks[0].list_path);
    var link = false;
    var italic = false;
    var marker: usize = 0;
    for (blocks[0].spans) |span| {
        if (span.kind == .link and std.mem.eql(u8, span.target, "Keep") and std.mem.eql(u8, span.text, "kept")) link = true;
        if (std.mem.eql(u8, span.text, "tail") and span.flags.italic) italic = true;
        if (std.mem.eql(u8, span.text, "|}")) {
            marker += 1;
            try std.testing.expect(span.kind == .text and span.target.len == 0);
            try std.testing.expectEqual(Provenance.protected_literal, span.provenance);
            try std.testing.expect(!span.generated_diagnostic and !span.flags.italic);
        }
    }
    try std.testing.expect(link and italic);
    try std.testing.expectEqual(@as(usize, 1), marker);
    try std.testing.expect(!renderer.fallbacks.malformed_table);
    try std.testing.expectError(error.UncompiledPresentation, requireCompiledText("|}"));

    // A nested action cannot acquire literal authority from its label's suffix.
    var action: Renderer = .{ .a = a, .context = .{} };
    const action_spans = try action.parseSpans("[[Target|label |}]]", .{});
    var parsed_action_marker = false;
    for (action_spans) |span| {
        if (std.mem.indexOf(u8, span.text, "|}") != null) {
            parsed_action_marker = span.kind == .link and std.mem.eql(u8, span.target, "Target") and span.provenance == .parsed;
        }
    }
    try std.testing.expect(parsed_action_marker);
}


test "underscore short unknown tags preserve literal angles and independent inline actions" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Check = struct {
        fn at(spans: []const Span, offset: usize) !Span {
            var position: usize = 0;
            for (spans) |span| {
                if (offset >= position and offset - position < span.text.len) return span;
                position += span.text.len;
            }
            return error.TestUnexpectedResult;
        }
    };
    const cases = [_]struct { source: []const u8, escaped: []const u8 }{
        .{ .source = "<ref_ଅଜନ୍ତା ଓଡ଼ିଆ ଅଭିଧାନ ପୃଷ୍ଟା ୫୫୩=\"\"/>", .escaped = "&lt;ref_ଅଜନ୍ତା ଓଡ଼ିଆ ଅଭିଧାନ ପୃଷ୍ଟା ୫୫୩=\"\"/&gt;" },
        .{ .source = "<custom_name note=\"[[Target|''word'']]\"/> tail", .escaped = "&lt;custom_name note=\"[[Target|''word'']]\"/&gt; tail" },
        .{ .source = "''before<ref_custom note=\"''\"/>after", .escaped = "''before&lt;ref_custom note=\"''\"/&gt;after" },
    };
    for (cases) |case| {
        var actual: Renderer = .{ .a = a, .context = .{} };
        var oracle: Renderer = .{ .a = a, .context = .{} };
        const spans = try actual.parseSpans(case.source, .{});
        const expected = try oracle.parseSpans(case.escaped, .{});
        const visible = try flattened(a, spans);
        try std.testing.expectEqualStrings(try flattened(a, expected), visible);
        for (visible, 0..) |byte, offset| {
            const got = try Check.at(spans, offset);
            const want = try Check.at(expected, offset);
            try std.testing.expectEqual(want.kind, got.kind);
            try std.testing.expectEqual(want.flags, got.flags);
            try std.testing.expectEqual(want.provenance, got.provenance);
            try std.testing.expectEqualStrings(want.target, got.target);
            if (byte == '<' or byte == '>') try std.testing.expect(got.provenance == .entity_literal);
        }
        try std.testing.expect(actual.fallbacks.literal_markup);
        try std.testing.expect(!oracle.fallbacks.literal_markup);
    }
    var linked: Renderer = .{ .a = a, .context = .{} };
    const spans = try linked.parseSpans(cases[1].source, .{});
    var found = false;
    for (spans) |span| if (span.kind == .link) {
        try std.testing.expectEqualStrings("Target", span.target);
        try std.testing.expectEqualStrings("word", span.text);
        try std.testing.expect(span.flags.italic);
        found = true;
    };
    try std.testing.expect(found);
}

test "underscore short name proof excludes real references incomplete tokens and nested angles" {
    for ([_][]const u8{
        "<ref name=n/>", "<ref>note</ref>", "<nowiki/>", "<script/>",
        "<ref_custom", "<ref_custom\n/>",
        "<ref_custom note=<span>/>", "<ref_custom\x00/>", "<ref_\xff/>",
        "<ref_\xe2\x80\x8b/>", "<https://example.test/>",
    }) |source| try std.testing.expect(Renderer.completeUnknownHtmlTokenEnd(source, 0) == null);
    for ([_][]const u8{ "<x_name/>", "<ref_/>", "<ref_custom>", "</ref_custom>", "<ref_custom:other/>" }) |source|
        try std.testing.expectEqual(@as(?usize, source.len), Renderer.completeUnknownHtmlTokenEnd(source, 0));
    // A valid supported reference and protected text retain their own semantics.
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var protected: Renderer = .{ .a = arena.allocator(), .context = .{} };
