        try std.testing.expect(Renderer.literalBareParameterName(name));
    for ([_][]const u8{ "-{{{РОД|x}}}", "-{{{РОД}}}|argument", "{{{РОД}}}", "-{{{}}}", "-{{{РОД}}", "-{{{x\xff}}}", "префикс:{{{x}}}" }) |body|
        try std.testing.expect(!Renderer.literalUnboundTemplateName(body));
