    try FormattingScopeTest.shapes(a, protected_stored.entry.sections[0].blocks, &.{"paragraph"}, &.{"[[Bad<ref>literal</ref>|label]]"});
    const planned = try preparePageExternalLinksAlloc(a, "<ref>planned</ref>", .{});
