        try std.testing.expectEqualStrings(label, action.text);
        try std.testing.expectEqual(if (index == 0) ir.InlineKind.external_link else .link, action.kind);
        if (index == 1 or index == 2) {
            try std.testing.expect(action.flags.italic);
            try std.testing.expectEqualStrings(if (index == 1) "oka" else "col", action.language);
        }
    }
    try std.testing.expect(renderer.fallbacks.literal_markup and renderer.unresolved_templates == 0);
    var reference: Renderer = .{ .a = a, .context = context };
    try fixture.sameStored(a, &renderer, blocks, &reference, try reference.renderBody(fixture.reference));
}

test "HTML interrupted target preserves nonempty table contents styling references and sibling scope" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source = "* [[w:<div class=NavFrame>\n<div class=NavContent>\n{| border=0\n|-\n| bgcolor=#ffffe0 | [[A|first]]\n|}</div></div>|<div class=NavFrame>\n<div class=NavContent>\n{| border=0\n|-\n| bgcolor=#ffffe0 | ''[[B|second]]''\n|}</div></div>]] [[Tail]]<ref>retained reference</ref>";
    // As in the retained JA reference, the empty first NavFrame contributes
    // no body or table ancestor; do not create an inline block line break.
    const reference_source = "* <nowiki>[[</nowiki>w:\n<div class=NavContent>\n{| border=0\n|-\n| bgcolor=#ffffe0 | [[A|first]]\n|}</div><p>|</p><div class=NavFrame>\n<div class=NavContent>\n{| border=0\n|-\n| bgcolor=#ffffe0 | ''[[B|second]]''\n|}</div></div><p><nowiki>]]</nowiki> [[Tail]]<ref>retained reference</ref></p>";
    var profile = try table_style_profile.parseAlloc(a, ".NavFrame td { background:inherit; }");
    defer profile.deinit();
    const context: Context = .{ .table_styles = &profile };
    var renderer: Renderer = .{ .a = a, .context = context };
    const blocks = try renderer.renderBody(source);
    try JaHtmlInterruptedLinkFixture.tables(a, blocks, "first", "second");
    var count: usize = 0;
    for (blocks) |block_value| if (block_value.table) |value| {
        const cell = value.rows[0].cells[0];
        if (count == 0) try std.testing.expectEqualStrings("#ffffe0", cell.background.?) else try std.testing.expect(cell.background == null);
        try std.testing.expectEqual(@as(usize, 1), cell.spans.len);
        try std.testing.expectEqual(ir.InlineKind.link, cell.spans[0].kind);
        try std.testing.expectEqualStrings(if (count == 0) "A" else "B", cell.spans[0].target);
        try std.testing.expectEqual(count == 1, cell.spans[0].flags.italic);
        count += 1;
    };
    const references = try renderer.finishReferences();
    try std.testing.expectEqual(@as(usize, 1), references.len);
    try std.testing.expectEqualStrings("retained reference", try flattened(a, references[0].spans));
    try std.testing.expectEqualStrings("", renderer.table_css_ancestor_classes);
    var reference: Renderer = .{ .a = a, .context = context };
    try JaHtmlInterruptedLinkFixture.sameStored(a, &renderer, blocks, &reference, try reference.renderBody(reference_source));
}

test "HTML interrupted target proof excludes labels protected text and unresolved source" {
    for ([_][]const u8{ "[[w:<div class=NavFrame>", "[[x<b>body</b>]]", "[[<SPAN>body</SPAN>]]" }) |source|
        try std.testing.expect(htmlInterruptedInternalOpening(source, 0));
    for ([_][]const u8{
        "[[Target|<div>label</div>]]", "[[x&lt;div&gt;]]", "[[x<nowiki>literal</nowiki>]]", "[[x<pre>literal</pre>]]",
        "[[x<ref>reference</ref>]]", "[[x<unknown>body</unknown>]]", "[[x<div", "[[x</div>]]", "[[x\n<div>body</div>]]",
        "[[{{missing}}<div>body</div>]]", "[[x[<div>body</div>]]", "[[x|label<div>body</div>]]",
    }) |source| try std.testing.expect(!htmlInterruptedInternalOpening(source, 0));
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var label: Renderer = .{ .a = a, .context = .{} };
    const linked = try label.parseSpans("[[Target|<i>kept</i>]]", .{});
    try std.testing.expectEqual(@as(usize, 1), linked.len);
    try std.testing.expectEqualStrings("Target", linked[0].target);
    try std.testing.expect(linked[0].flags.italic and !label.fallbacks.literal_markup);
    for ([_][]const u8{ "<nowiki>[[w:<div>literal</div>]]</nowiki>", "<pre>[[w:<div>literal</div>]]</pre>", "<span title='[[w:&lt;div&gt;'>kept</span>" }) |source| {
        var protected: Renderer = .{ .a = a, .context = .{} };
        const body = try protected.renderBody(source);
        try std.testing.expect(!protected.fallbacks.literal_markup);
        for (body) |block_value| for (block_value.spans) |span| try std.testing.expect(span.target.len == 0 and !span.generated_diagnostic);
    }
    var unresolved: Renderer = .{ .a = a, .context = .{} };
    _ = try unresolved.parseSpans("[[w:<span>{{missing|body}}</span>]]", .{});
    try std.testing.expectEqual(@as(usize, 1), unresolved.unresolved_templates);
    for ([_][]const u8{ "[[", "]]", "{{missing}}", "<div>source</div>" }) |source|
        try std.testing.expectError(error.UncompiledPresentation, requireCompiledText(source));
}

test "parsed defaultless HTTP query literals preserve exact href label style and source proof" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const url = "http://www.perseus.tufts.edu/hopper/morph?l={{{1}}}&la=greek#lexicon";
    const source = "[" ++ url ++ " " ++ url ++ "]";
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const spans = try renderer.parseSpans(source, .{ .italic = true, .foreground = "#123456", .foreground_set = true });
    var label: std.ArrayList(u8) = .empty;
    var literal: usize = 0;
    for (spans) |span| {
        try std.testing.expectEqual(ir.InlineKind.external_link, span.kind);
        try std.testing.expectEqualStrings(url, span.target);
        try std.testing.expect(hasCompiledExternalLiteralParameterTarget(span));
        try std.testing.expect(span.flags.italic);
        try std.testing.expectEqualStrings("#123456", span.foreground.?);
        try label.appendSlice(a, span.text);
        if (std.mem.eql(u8, span.text, "{{{1}}}")) {
            literal += 1;
            try std.testing.expectEqual(Provenance.protected_literal, span.provenance);
        }
    }
    try std.testing.expectEqualStrings(url, label.items);
    try std.testing.expectEqual(@as(usize, 1), literal);
    // Two distinct authored occurrences: query destination and displayed label.
    try std.testing.expectEqual(@as(usize, 2), renderer.unresolved_templates);
    try std.testing.expect(renderer.fallbacks.missing_template);
    try std.testing.expect(unresolvedExternalActionTarget(url));
    // Neither the public action helper nor generic display provenance grants a proof.
    var direct: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expectError(error.UncompiledTemplate, direct.link(url, url, .{}, 0, true));
    for (spans) |span| {
        var copied = span;
        copied.target = try a.dupe(u8, span.target);
        try std.testing.expect(!hasCompiledExternalLiteralParameterTarget(copied));
        var changed = span;
        changed.target = span.target[0 .. span.target.len - 1];
        try std.testing.expect(!hasCompiledExternalLiteralParameterTarget(changed));
        var detached = span;
        detached.external_literal_parameter = .{ .token = try a.dupe(u8, span.external_literal_parameter.?.token), .target = span.target };
        try std.testing.expect(!hasCompiledExternalLiteralParameterTarget(detached));
    }
}

test "literal query proof excludes unparsed domains entities defaults children and other URL components" {
    for ([_][]const u8{
        "http://example.test/?q={{{x|default}}}", "http://example.test/?q={{{x|}}}",
        "http://example.test/?q={{missing}}", "http://example.test/?q={{{}}}",
        "http://example.test/?q={{{bad name}}}", "http://example.test/?q={{{x\xff}}}",
        "http://example.test/?q={{{x}}", "http://example.test/?q={{{x}}}}",
        "http://example.test/?q={{{{x}}}}", "http://example.test/?q={{{x}}}{{missing}}",
        "http://{{{host}}}/?q=x", "http://example.test/{{{path}}}?q=x",
        "http://example.test/?q=x#{{{fragment}}}", "http://example.test/?{{{key}}}=value",
        "http://example.test/?q=&#123;&#123;&#123;x&#125;&#125;&#125;",
        "http://example.test/?q={{{x}}}&amp;lang=grc", "http://example.test/&quest;q={{{x}}}",
        "http://example.test/?q={{{x}}}#&num;fragment", "http://example.test/?q={{{x}}}&bare",
        "http://example.test/?q={{{x}}}\\tail", "ftp://example.test/?q={{{x}}}",
        "//example.test/?q={{{x}}}", "javascript:alert({{{x}}})",
    }) |target| {
        errdefer std.debug.print("unexpected literal query admission target={s}\n", .{target});
        try std.testing.expect(Renderer.literalDefaultlessExternalQuery(target) == null);
    }
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const url = "https://example.test/?q={{{x}}}";
    for ([_][]const u8{
        "<nowiki>[" ++ url ++ " " ++ url ++ "]</nowiki>",
        "<pre>[" ++ url ++ " " ++ url ++ "]</pre>",
        "<span title=\"[" ++ url ++ " " ++ url ++ "]\">attribute only</span>",
    }) |source| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(source);
        for (blocks) |block| for (block.spans) |span| {
            try std.testing.expect(span.kind != .external_link);
            try std.testing.expect(span.external_literal_parameter == null);
        };
    }
    // Even complete URL bytes cannot create a proof outside a parsed bracketed token.
    var bare: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expectError(error.UncompiledTemplate, bare.link(url, url, .{ .code = true }, 0, true));
}

test "image border preserves occurrence dimensions actions and none geometry" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    for ([_]struct { source: []const u8, kind: ir.InlineKind, target: []const u8 }{
        .{ .source = "[[File:Flag of Poland.svg|40px|border]]", .kind = .link, .target = "File:Flag of Poland.svg" },
        .{ .source = "[[File:Flag of Poland.svg|border|40px|border|link=]]", .kind = .text, .target = "" },
        .{ .source = "[[File:Flag of Poland.svg|border|40px|link=Polacco]]", .kind = .link, .target = "Polacco" },
        .{ .source = "[[File:Flag of Poland.svg|40px|border|link=https://example.test/]]", .kind = .external_link, .target = "https://example.test/" },
    }) |case| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const spans = try renderer.parseSpans(case.source, .{});
        try std.testing.expectEqual(@as(usize, 1), spans.len);
        const span = spans[0];
        const image = span.image orelse return error.TestUnexpectedResult;
        try std.testing.expect(image.border and span.image_fields_compiled);
        try std.testing.expectEqualStrings("Flag of Poland.svg", image.file);
        try std.testing.expectEqual(@as(?u32, 40), image.width_px);
        try std.testing.expect(image.height_px == null and image.alt == null and image.tooltip == null);
        try std.testing.expectEqual(case.kind, span.kind);
        try std.testing.expectEqualStrings(case.target, span.target);
        try std.testing.expectEqualStrings("", span.text);
        // Trail belongs to the stored wire span, not the compiler's Span.
        const saved = try FormattingScopeTest.encode(a, &renderer, &.{.{ .kind = .paragraph, .spans = spans }});
        const saved_spans = saved.entry.sections[0].blocks[0].spans;
        try std.testing.expectEqual(@as(usize, 1), saved_spans.len);
        const retained = saved_spans[0];
        try std.testing.expectEqualStrings("", retained.text);
        try std.testing.expectEqualStrings("", retained.trail);
        try std.testing.expectEqualStrings(@tagName(case.kind), @tagName(retained.kind));
        try std.testing.expectEqualStrings(case.target, retained.target);
        try std.testing.expectEqualDeep(image, retained.image.?);
    }
    var block_renderer: Renderer = .{ .a = a, .context = .{} };
    const blocks = try block_renderer.renderBody("before[[File:X.svg|none|border|x40px|alt=|link=]]after");
    try std.testing.expectEqual(@as(usize, 3), blocks.len);
    const span = try NonfloatingImageTest.occurrence(blocks[1], "X.svg", 40);
    try std.testing.expect(span.image.?.border);
    try std.testing.expectEqualStrings("", span.image.?.alt.?);
    try std.testing.expectEqualStrings("before", try plainText(a, blocks[0].spans));
    try std.testing.expectEqualStrings("after", try plainText(a, blocks[2].spans));
}

test "image border authority retains unsupported formats raw markup and local option scopes" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const ns = @import("namespace_registry");
    var options = try ns.image_options.Registry.init(a, image_option_test_identity ++
        "img_border\t1\t\"bordo\"\nimg_width\t1\t\"$1px\"\n",
        "dewiktionary", "20261001", "de", @splat(0), @splat(0));
    defer options.deinit();
    var localized: Renderer = .{ .a = a, .context = .{ .image_options = &options } };
    const admitted = try localized.parseSpans("[[File:X.svg|bordo|40px]]", .{});
    try std.testing.expect(admitted[0].image.?.border);
    const caption = try localized.parseSpans("[[File:X.svg|border|40px]]", .{});
    try std.testing.expect(!caption[0].image.?.border);
    try std.testing.expectEqualStrings("border", caption[0].image.?.tooltip.?);
    for ([_][]const u8{
        "[[File:X.svg|border|thumb|40px]]", "[[File:X.svg|frame|border|40px]]",
        "[[File:X.svg|border|frameless|40px]]", "[[File:X.svg|border|right|40px]]",
        "<nowiki>[[File:X.svg|border|40px]]</nowiki>",
    }) |source| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        if (std.mem.indexOf(u8, source, "|thumb|") != null or std.mem.indexOf(u8, source, "|frame|") != null) {
            try std.testing.expectError(error.UncompiledPresentation, renderer.parseSpans(source, .{}));
            try std.testing.expect(renderer.fallbacks.unrepresented_figure);
        } else {
            const spans = try renderer.parseSpans(source, .{});
            for (spans) |span| try std.testing.expect(span.image == null);
        }
    }
    for ([_][]const u8{ "[[File:X.svg|border|thumb|40px]]", "[[File:X.svg|frame|border|40px]]" }, 0..) |source, index| {
        var owned: Renderer = .{ .a = a, .context = try FigureProducerTest.context(a) };
        const body = try owned.renderBody(source); const figure = try FigureProducerTest.find(body);
        try std.testing.expectEqual(if (index == 0) presentation_types.FigureFormat.thumbnail else presentation_types.FigureFormat.framed, figure.format);
        try std.testing.expectEqual(if (index == 0) presentation_types.FigureSizingPolicy.requested_fit else presentation_types.FigureSizingPolicy.intrinsic, figure.content.image.sizing);
        try std.testing.expectEqualStrings("X.svg", figure.content.image.span.image.?.file);
        try std.testing.expectEqual(@as(?u32, 40), figure.content.image.span.image.?.width_px);
        try std.testing.expect(figure.content.image.span.image.?.border);
        try std.testing.expectEqualStrings("File:X.svg", figure.content.image.span.target);
        try std.testing.expectEqual(@as(usize, 1), owned.media.items.len);
        try FigureProducerTest.roundtrip(a, &owned, body);
    }
    var renderer: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expectError(error.UncompiledTemplate, renderer.parseSpans("[[File:X.svg|border|alt={{Missing}}]]", .{}));
    try std.testing.expectError(error.UncompiledPresentation, requireCompiledText("<img src='X.svg' border='1'>"));
    const legacy = try renderer.parseSpans("[[File:X.svg|40px]]", .{});
    try std.testing.expect(!legacy[0].image.?.border);
}


test "static stylesheet display obeys own element selectors cascade and uncertainty" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const cases = [_]struct { css: []const u8, tag: []const u8 = "tr", attrs: []const u8 = "class='omit'", hidden: bool, unresolved: bool = false }{
        .{ .css = ".omit { display:none; }", .hidden = true },
        .{ .css = ".omit, .other { display:none; }", .hidden = true },
        .{ .css = ".omit, .other. { display:none; }", .hidden = false, .unresolved = true },
        .{ .css = ".omit, .other:unknown-pseudo { display:none; }", .hidden = false, .unresolved = true },
        .{ .css = ".- { display:none; }", .attrs = "class='-'", .hidden = false, .unresolved = true },
        .{ .css = ".-1 { display:none; }", .attrs = "class='-1'", .hidden = false, .unresolved = true },
        .{ .css = "#-1 { display:none; }", .attrs = "id='-1'", .hidden = false, .unresolved = true },
        .{ .css = ".-ok { display:none; }", .attrs = "class='-ok'", .hidden = true },
        .{ .css = ".--1 { display:none; }", .attrs = "class='--1'", .hidden = true },
        .{ .css = "tr.omit { display:none; }", .hidden = true },
        .{ .css = "tr.omit { display:none; }", .tag = "td", .hidden = false },
        .{ .css = ".omit { display:none; }", .attrs = "class='omit-extra'", .hidden = false },
        .{ .css = ".omit.extra { display:none; }", .hidden = false },
        .{ .css = ".omit.extra { display:none; }", .attrs = "class='extra omit'", .hidden = true },
        .{ .css = ".omit { display:none; } .omit { display:table-row; }", .hidden = false },
        .{ .css = "tr.omit { display:none; } .omit { display:table-row; }", .hidden = true },
        .{ .css = "#chosen { display:block; } .omit { display:none; }", .attrs = "id=chosen class=omit", .hidden = false },
        .{ .css = "#chosen { display:block; } .omit.omit.omit.omit.omit.omit.omit.omit.omit.omit.omit { display:none; }", .attrs = "id=chosen class=omit", .hidden = false },
        .{ .css = ".omit { display:none; } tr.omit { display:table-row; }", .hidden = false },
        .{ .css = ".omit { display:none; }", .attrs = "class=omit style='display:table-row'", .hidden = false },
        .{ .css = ".omit { display:none!important; }", .attrs = "class=omit style='display:table-row'", .hidden = true },
        .{ .css = ".omit { display:none!important; }", .attrs = "class=omit style='display:table-row!important'", .hidden = false },
        .{ .css = ".omit { display:none; display:invalid; }", .hidden = true },
        .{ .css = ".omit { display:none; all:initial; }", .hidden = false },
        .{ .css = ".omit { display:none; display:var(--choice); }", .hidden = false, .unresolved = true },
        .{ .css = ".omit { display:none; } @media print { .omit { display:table-row; } }", .hidden = false, .unresolved = true },
        .{ .css = "@media print { .other { display:none; } } .omit { display:none; }", .hidden = true },
        .{ .css = ".omit { display:none; } table .omit { display:table-row; }", .hidden = false, .unresolved = true },
        .{ .css = ".omit { display:none; } table td { display:block; }", .hidden = true },
        .{ .css = ".omit { display:none; } .omit:hover { display:block; }", .hidden = false, .unresolved = true },
        .{ .css = ".omit { display:none; } :not(.other) { display:block; }", .hidden = false, .unresolved = true },
        .{ .css = ".omit { display:none; } tr[data-x] { display:block; }", .hidden = false, .unresolved = true },
        .{ .css = ".omit { display:none; } tr.other[data-x] { display:block; }", .hidden = true },
        .{ .css = ".omit { display:none; } tr/* x*/.omit { display:block; }", .hidden = false, .unresolved = true },
        .{ .css = ".omit. { display:none; }", .hidden = false, .unresolved = true },
        .{ .css = ".omit { display:none; } t\\72 { display:block; }", .hidden = false, .unresolved = true },
        .{ .css = ".omit { display:none; } .x\x00 { display:block; }", .attrs = "class='omit x\u{fffd}'", .hidden = false, .unresolved = true },
        .{ .css = ".omit { display:none; } svg|tr { display:block; }", .hidden = false, .unresolved = true },
        .{ .css = ".omit { display:none; d\\69splay:block; }", .hidden = false, .unresolved = true },
        .{ .css = "@import 'missing.css'; .omit { display:none; }", .hidden = false, .unresolved = true },
        .{ .css = "@import 'missing.css'; .omit { display:none; }", .attrs = "class=omit style='display:none'", .hidden = false, .unresolved = true },
        .{ .css = "@import 'missing.css'; .omit { display:none; }", .attrs = "class=omit style='display:none!important'", .hidden = true },
    };
    for (cases) |case| {
        errdefer std.debug.print("display css={s} tag={s} attrs={s}\n", .{case.css, case.tag, case.attrs});
        var profile = try table_style_profile.parseAlloc(a, case.css);
        defer profile.deinit();
        var renderer: Renderer = .{ .a = a, .context = .{ .table_styles = &profile } };
        const tag: syntax.Tag = .{ .name = case.tag, .attrs = case.attrs, .end = 0, .closing = false, .self_closing = false };
        try std.testing.expectEqual(case.hidden, try renderer.htmlDisplayNone(tag));
        try std.testing.expectEqual(case.unresolved, renderer.fallbacks.unsupported_element);
        if (std.mem.eql(u8, case.tag, "tr")) {
            var body_renderer: Renderer = .{ .a = a, .context = .{ .table_styles = &profile } };
            const source = try std.fmt.allocPrint(a, "{{|\n|- {s}\n| candidate\n|-\n| retained\n|}}", .{case.attrs});
            const blocks = try body_renderer.renderBody(source);
            const rows = blocks[0].table.?.rows;
            try std.testing.expectEqual(@as(usize, if (case.hidden) 1 else 2), rows.len);
            if (!case.hidden) try std.testing.expectEqualStrings("candidate", try plainText(a, rows[0].cells[0].spans));
            try std.testing.expectEqualStrings("retained", try plainText(a, rows[rows.len - 1].cells[0].spans));
        }
    }
}

test "static class visibility never inherits a table class as a row own class" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var profile = try table_style_profile.parseAlloc(a, "tr.omit { display:none; } table.paint { background:#abcdef; }");
    defer profile.deinit();
    var renderer: Renderer = .{ .a = a, .context = .{ .table_styles = &profile } };
    const blocks = try renderer.renderBody("{| class='omit paint'\n| first\n|- class=omit\n| hidden\n|-\n| retained [[Visible|action]]\n|}");
    const rows = blocks[0].table.?.rows;
    try std.testing.expectEqual(@as(usize, 2), rows.len);
    try std.testing.expectEqualStrings("first", try plainText(a, rows[0].cells[0].spans));
    try std.testing.expectEqualStrings("retained action", try plainText(a, rows[1].cells[0].spans));
    var actions: usize = 0;
