        const retained = try r.parseSpans(try std.fmt.allocPrint(a, "lead{s}<tr><td>[[Target|word]]</td></tr></table>tail", .{opening}), .{});
        try std.testing.expectEqualStrings("lead\nword\ntail", try plainText(a, retained));
        var actions: usize = 0;
