    for ([_][]const u8{ "<code>" ++ source ++ "</code>", "[[Target|" ++ source ++ "]]", "<span title='" ++ source ++ "'>" }) |parent| {
        const offset = std.mem.indexOf(u8, parent, source).?;
        const child = parent[offset .. offset + source.len];
