    const a = arena.allocator(); const codec = @import("blob_encoder").presentation_codec;
    const base = "[[<h1>English</h1>\n''body'' [[Target|label]]\n{|\n| bgcolor=#ffeeaa|cell\n|}\n]]\nafter";
    for ([_][]const u8{ "\n", "\r\n" }) |newline| {
