        .{ .code = true, .preserve_whitespace = true, .kind = .external_link, .target = "https://example.test" },
        .{ .code = true, .preserve_whitespace = true, .self_link_target = "self" },
        .{ .code = true, .preserve_whitespace = true, .missing_nonaction = true },
