        try std.testing.expect(refused.source.bytes.ptr == multiline.ptr and refused.angles.len == 0);
    }
    for ([_][]const u8{
        "<span title='\n" ++ line ++ "'>body</span>",
        "<span title='>\n" ++ line ++ "'>body</span>",
        "<div\n" ++ line, "<code>\n" ++ line ++ "</code>",
