    for ([_][]const u8{
        "{{bad name|text=<b>x</b>\n|field=|}", "{{x|bad field=<b>x</b>\n|field=|}",
        "{{x|text=<b>x\n</b>|field=|}", "{{x|text=<b>x</b>\n\n|field=|}",
