    const reference = "&lt;<i class=\"Latn mention\" lang=\"en\">[[:Feb#Bahasa&#95;Inggeris|Feb]]</i>> atau &lt;<i class=\"Latn mention\" lang=\"en\">[[:Feb.#Bahasa&#95;Inggeris|Feb.]]</i>>. [[Tail]]";
    var renderer: Renderer = .{ .a = a, .context = .{} };
