        .{ .bytes = source, .literal_curly_ranges = &.{.{ .start = open_curly, .end = open_curly + 1 }} },
    }) |tracked| try std.testing.expect(!r.entityOpenedCodeExample(tracked, at, body, .{}));
    const suffix: u32 = @intCast(pair.end + 1);
