    for ([_][]const u8{ "-{}-", "-{open", "-{a -{b}-}-", "-{H|x}-", "-{sr:x;sr-el:y}-", "-{a=>b}-", "-{[[Target]]}-", "-{<b>x</b>}-", "-{''x''}-", "-{&amp;}-", "-{x\ny}-", "-{x\ty}-", "-{x\x7fy}-", "-{x\xffy}-" }) |source| {
