    try std.testing.expectEqual(@as(usize, 0), prepared.ranges.len);
    try std.testing.expectEqual(@as(usize, 0), prepared.literal_curly_ranges.len);
    try std.testing.expectEqual(@as(usize, 0), prepared.generated_links.len);
